-- load saved theme choice (chosen in Settings tab, applied on next load)
if isfile and readfile and isfile("Islands trading hub/config.json") then
    pcall(function()
        local data = game:GetService("HttpService"):JSONDecode(readfile("Islands trading hub/config.json"))
        if type(data) == "table" and data.theme and Themes[data.theme] then
            ActiveTheme = data.theme
        end
    end)
end

-- Build yielder: the whole UI is created synchronously. Under a heavy obfuscation VM
-- that can exceed the executor's no-yield watchdog ("Script timeout: exhausted allowed
-- execution time") and freeze the game. Yielding every few instance creations resets
-- the watchdog so the build spreads over a handful of frames instead of one long stall.
do
    local n = 0
    function IVM_BuildTick()
        n += 1
        if n % 8 == 0 then task.wait() end
    end
end

-- UI library
do
Library, UI, Create,
UserInputService, CoreGui, TweenService, RunService, Players =
{},
{
    Colors   = Themes[ActiveTheme] or Themes["Dark Red"],
    Themes   = Themes,
    Font     = Enum.Font.GothamBold,
    FontBold = Enum.Font.GothamBold,
},
(function(Class, Props)
    local Inst = Instance.new(Class)
    local Parent = Props.Parent
    for i, v in pairs(Props) do if i ~= "Parent" then Inst[i] = v end end
    if Parent then Inst.Parent = Parent end
    IVM_BuildTick()
    return Inst
end),
game:GetService("UserInputService"),
game:GetService("CoreGui"),
game:GetService("TweenService"),
game:GetService("RunService"),
game:GetService("Players")
game:GetService("ReplicatedStorage")
game:GetService("HttpService")
