-- random helper functions
local function safedestroy(obj)
    if type(obj) ~= "table" and type(obj) ~= "userdata" then return end
    pcall(function()
        if obj.Destroy    then obj:Destroy()
        elseif obj.Disconnect then obj:Disconnect()
        elseif obj.Stop   then obj:Stop() end
    end)
end

local function addconn(c) table.insert(Cache.Connections, c); return c end
-- Backpack and Character, skipping whichever is missing. ipairs over the literal
-- {backpack, character} stops at a nil first entry, so a respawn with no Backpack yet
-- hid the tools you were holding.
function Cache.toolContainers()
    local out = {}
    local bp = LocalPlayer:FindFirstChild("Backpack")
    if bp then out[#out + 1] = bp end
    if LocalPlayer.Character then out[#out + 1] = LocalPlayer.Character end
    return out
end
local function addloop(t) table.insert(Cache.Loops, t); return t end

-- cache to save memory
local function makeboundedcache(maxSize)
    local store, count = {}, 0
    return {
        get = function(key) return store[key] end,
        set = function(key, val)
            if not store[key] then
                if count >= maxSize then
                    local keys = {}
                    for k in pairs(store) do table.insert(keys, k) end
                    store[keys[1]] = nil
                    count -= 1
                end
                count += 1
            end
            store[key] = val
        end,
        clear = function() store = {}; count = 0 end,
        raw   = function() return store end,
    }
end

local FixNameCache  = makeboundedcache(500)
local ItemNameCache = makeboundedcache(200)

-- makes names look nice
-- DIGITS ARE WORD BOUNDARIES TOO, and a name that starts with one still has a first
-- letter. The game's furniture is named 2cabinet, 3rug1, 4tableUmbrella, and this used
-- to split only the camelCase hump and then uppercase character one -- so "2cabinet"
-- came back as "2cabinet", because :upper() on "2" is "2" and the c was never reached.
-- A market export full of 1table and 3bed1 reads as raw data rather than as a shop's
-- stock, which is what it was reported as.
local function fixname(s)
    local cached = FixNameCache.get(s)
    if cached then return cached end
    local n = s:gsub("(%l)(%u)", "%1 %2")      -- goldAxe   -> gold Axe
        :gsub("(%a)(%d)", "%1 %2")             -- rug1      -> rug 1
        :gsub("(%d)(%a)", "%1 %2")             -- 2cabinet  -> 2 cabinet
        :gsub("_", " ")
    -- the first LETTER, wherever it is, not the first character
    local result = n:gsub("^(%A*)(%a)", function(pre, c) return pre .. c:upper() end)
    FixNameCache.set(s, result)
    return result
end

-- AN ID IS NOT A NAME. Islands stores an island's owner as a GUID on an attribute
-- called `Owner`, and anything reading that key for a display name gets 36 characters
-- of hex -- which is what filled the Owner column of the market export. Whatever else
-- it is, it is not something to show a person.
function Cache.looksLikeGuid(v)
    return type(v) == "string"
        and v:match("^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$") ~= nil
end

-- AN ISLAND'S OWN NAME IS AN ID TOO. When an island carries no owner field the scanner
-- can read, the shop is keyed on the island's name -- "<guid>-island" -- and that is
-- what the Price Book's shop picker showed: four rows of hex, one per shop. Anything
-- this answers yes to is a key, not a name a person would recognise.
function Cache.looksLikeShopId(v)
    if type(v) ~= "string" then return false end
    if Cache.looksLikeGuid(v) then return true end
    local g = v:match("^(.+)%-island$")
    return g ~= nil and Cache.looksLikeGuid(g)
end

-- makes numbers shorter
local function shortnum(n)
    if n >= 1e12 then return string.format("%.1fT", n * 1e-12)
    elseif n >= 1e9  then return string.format("%.1fB", n * 1e-9)
    elseif n >= 1e6  then return string.format("%.1fM", n * 1e-6)
    elseif n >= 1e3  then return string.format("%.1fK", n * 1e-3)
    else return tostring(math.floor(n)) end
end

-- turns text like "1B" or "500K" into actual numbers
-- THE SUFFIX MOVES THE DECIMAL POINT; IT IS NOT A MULTIPLICATION. This used to be
-- math.floor(tonumber(num) * 1e6), and a typed decimal is not exact in binary: 4.1 * 1e6
-- is 4099999.9999..., so "4.1M" priced a vend at 4,099,999 (and 8.2M, 2.01B, ...), and
-- as a Min Price floor let a price one below it through. Shifting the typed digits
-- never goes through a fraction at all. What falls below a coin is dropped, as the floor
-- always dropped it. tests/parsenum.test.lua.
local function parsenum(txt)
    txt = tostring(txt or ""):upper():gsub("%s", "")
    local ip, fp, suf = txt:match("^(%d*)%.?(%d*)([KMBT]?)$")
    if not ip or (ip == "" and fp == "") then return nil end
    local shift = (suf == "K" and 3) or (suf == "M" and 6) or (suf == "B" and 9) or (suf == "T" and 12) or 0
    fp = fp .. string.rep("0", shift)
    return tonumber(ip .. fp:sub(1, shift)) or 0
end

local function regitem(name, arg)
    local display = name
    local tools = ReplicatedStorage:FindFirstChild("Tools")
    if tools then
        local t = tools:FindFirstChild(name)
        if t then
            local dn = t:FindFirstChild("DisplayName")
            if dn and dn:IsA("StringValue") then display = dn.Value end
        end
    end
    local amt = 0
    if type(arg) == "number" then
        amt = arg
    elseif typeof(arg) == "Instance" then
        local v = arg:FindFirstChild("Amount") or arg:FindFirstChild("Value")
        amt = (v and (v:IsA("IntValue") or v:IsA("NumberValue"))) and v.Value or 1
    end
    local base = display
    if amt > 1 then display = display .. " (" .. shortnum(amt) .. ")" end
    Cache.ItemNameMap[display] = name
    Cache.ItemNameMap[base]    = name
    return display
end

-- gets items display name
local function getinternalname(input)
    if not input then return "" end
    local val = type(input) == "table" and (input[1] or input[1] == nil and "") or input
    if type(val) ~= "string" then return tostring(val) end
    if val == "" then return "" end
    local low = val:lower()
    local cached = ItemNameCache.get(low)
    if cached then return cached end
    for d, i in pairs(Cache.ItemNameMap) do
        if d:lower() == low or i:lower() == low then
            ItemNameCache.set(low, i)
            return i
        end
    end
    return val
end

-- A NAME SOMEONE TYPED, AS THE ITEM THEY HOLD. getinternalname answers a display name
-- or an id in any case, but only for names an inventory list has already shown; what
-- it has not seen is checked against what is held (`counts`, internal name -> amount),
-- case-insensitively. A name that matches nothing held is returned as typed, trimmed,
-- so a message about it still names what was asked for. tests/held_item.test.lua.
function Cache.resolveHeldItem(typed, counts)
    if type(typed) ~= "string" then return nil end
    typed = typed:gsub("^%s+", ""):gsub("%s+$", "")
    if typed == "" then return nil end
    counts = type(counts) == "table" and counts or {}
    local id = getinternalname(typed)
    if counts[id] then return id end
    local low = tostring(id):lower()
    for k in pairs(counts) do
        if type(k) == "string" and k:lower() == low then return k end
    end
    return id
end

-- tool list with 30s cache
local AllToolsCache = { data = nil, time = 0, ttl = 30 }
local function getalltools()
    local now = tick()
    if AllToolsCache.data and (now - AllToolsCache.time) < AllToolsCache.ttl then
        return AllToolsCache.data
    end
    local items, tools = {}, ReplicatedStorage:FindFirstChild("Tools")
    if tools then
        for _, tool in ipairs(tools:GetChildren()) do
            local display = tool.Name
            local dn = tool:FindFirstChild("DisplayName")
            if dn and dn:IsA("StringValue") then display = dn.Value end
            Cache.ItemNameMap[display] = tool.Name
            table.insert(items, display)
        end
    end
    table.sort(items)
    AllToolsCache.data = #items > 0 and items or {"Empty"}
    AllToolsCache.time = now
    return AllToolsCache.data
end

-- fuzzy search
local SearchCache = makeboundedcache(100)
local SEARCH_TTL  = 5

local function fuzzysearch(items, query)
    if not query or query == "" then return items, nil end
    query = query:lower():gsub("%s+", " "):gsub("^%s*", ""):gsub("%s*$", "")
    if query == "" then return items, nil end

    -- KEY ON THE LIST'S CONTENTS, NOT JUST ITS LENGTH. Two dropdowns feed this (the
    -- vend-selectable items and the inventory), and `query .. #items` collides
    -- whenever they happen to be the same length: the second one is served the first
    -- one's results. The everyday version is subtler -- inventory labels carry stack
    -- counts ("Wood (1.2K)"), so the SAME list re-queried inside the 5s window comes
    -- back with the amounts as they were, not as they are. Fingerprinting the ends and
    -- the middle costs three concatenations and separates all of those.
    local n = #items
    local cacheKey = query .. "#" .. n .. "#" .. tostring(items[1]) ..
        "#" .. tostring(items[(n // 2) + 1]) .. "#" .. tostring(items[n])
    local cached = SearchCache.get(cacheKey)
    if cached and (tick() - cached.time) < SEARCH_TTL then
        return cached.results, cached.bestMatch
    end

    local filtered, bestMatch, bestScore = {}, nil, 999
    local queryWords = {}
    for word in query:gmatch("%S+") do table.insert(queryWords, word) end

    -- ONE FRAME'S WORTH OF WORK BETWEEN YIELDS, NOT FIVE STRING COMPARES.
    -- task.wait() surrenders the REST OF THE FRAME (~16ms), and this yielded every
    -- fifth item for a body that lowercases a string and runs a plain find. On the
    -- tool list -- every child of ReplicatedStorage.Tools, hundreds of entries -- that
    -- was over a hundred frames, so roughly two seconds of stale dropdown after every
    -- keystroke, for a few milliseconds of actual filtering. Time-budgeted instead:
    -- a short list never yields at all, and a huge one still stays responsive.
    local sliceEnd = os.clock() + 0.004
    for _, item in ipairs(items) do
        if os.clock() >= sliceEnd then task.wait(); sliceEnd = os.clock() + 0.004 end
        local itemLow = item:lower()
        local score, matches = 999, 0

        if itemLow == query then
            score = 0; matches = #queryWords
        elseif itemLow:find(query, 1, true) == 1 then
            score = 1; matches = #queryWords
        else
            local allMatch = true
            for _, word in ipairs(queryWords) do
                if itemLow:find(word, 1, true) then matches += 1
                else allMatch = false end
            end
            score = allMatch and 2 or (matches > 0 and 3 or 999)
        end

        if matches > 0 then
            table.insert(filtered, item)
            if score < bestScore then bestScore = score; bestMatch = item end
        end
    end

    SearchCache.set(cacheKey, { results = filtered, bestMatch = bestMatch, time = tick() })
    return filtered, bestMatch
end

-- shared helpers. Defined on Cache inside a do-block (not as chunk-level locals)
-- because this file runs close to Luau's 200-local-per-scope limit.
do
    -- Count Backpack + currently-held tool into an internalName -> total map, reading
    -- the Amount/Value child the same way the rest of the script does.
    function Cache.countInventory()
        local counts = {}
        local bp = LocalPlayer:FindFirstChild("Backpack")
        if bp then
            for _, item in ipairs(bp:GetChildren()) do
                local v = item:FindFirstChild("Amount") or item:FindFirstChild("Value")
                local a = (v and (v:IsA("IntValue") or v:IsA("NumberValue"))) and v.Value or 1
                counts[item.Name] = (counts[item.Name] or 0) + a
            end
        end
        local char = LocalPlayer.Character
        local held = char and char:FindFirstChildWhichIsA("Tool")
        if held then
            local v = held:FindFirstChild("Amount") or held:FindFirstChild("Value")
            local a = (v and (v:IsA("IntValue") or v:IsA("NumberValue"))) and v.Value or 1
            counts[held.Name] = (counts[held.Name] or 0) + a
        end
        return counts
    end

    -- WHY A BLOCK PICKER CAME BACK EMPTY, in words rather than "no blocks found".
    -- Every picker in the script reads LocalPlayer.Backpack -- Block Fill's, the sign's,
    -- the QR's -- and getbackpackblocks lists EVERY child of it with no filtering at
    -- all. So an empty list never means "you have no blocks", it means the Backpack
    -- itself was empty, and the three ways that happens want three different answers.
    -- Saying "no blocks in your inventory" when the real answer is "they are in your
    -- inventory and not on your hotbar" is how someone concludes the feature is broken.
    function Cache.emptyPickerReason()
        local bp = LocalPlayer:FindFirstChild("Backpack")
        if not bp then
            return "Your character has no Backpack yet — it is probably still loading. Wait a moment and press it again."
        end
        local n = #bp:GetChildren()
        local held = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildWhichIsA("Tool")
        if n == 0 and not held then
            return "Your Backpack is empty as far as the game is concerned. This reads the HOTBAR, not the inventory screen — if your blocks are sitting in inventory or in a chest, move a stack onto the hotbar and press it again."
        end
        return string.format("Read %d item(s) but none of them came back with a usable name. That is not a normal state; say so if you see it.", n + (held and 1 or 0))
    end

    -- Resolve the representative BasePart of an instance/model. Matches the common
    -- "(x is BasePart) or first descendant BasePart or model.PrimaryPart" pattern.
    function Cache.getPart(inst)
        if not inst then return nil end
        if inst:IsA("BasePart") then return inst end
        return inst:FindFirstChildWhichIsA("BasePart")
            or (inst:IsA("Model") and inst.PrimaryPart) or nil
    end

    -- Display name -> internal item name via ItemNameMap (strips a trailing " (1.2K)").
    function Cache.toInternal(val)
        if type(val) == "table" then val = val[1] end
        if type(val) ~= "string" then return val end
        return Cache.ItemNameMap[val]
            or Cache.ItemNameMap[val:gsub(" %([%d%.]+[KMB]?%)$", "")]
            or val
    end

    -- Does an opener's internal name match the selected opener-type dropdown value?
    local openerKinds = {
        Cauldron = "cauldron", ["Treasure Chest"] = "treasureChest",
        ["Dungeon Chest"] = "dungeonChest", ["Serpent Egg"] = "serpentEgg",
        ["Dragon Egg"] = "dragonEgg",
    }
    function Cache.openerMatches(name, selType)
        if selType == "All" then return true end
        local key = openerKinds[selType]
        return key ~= nil and name:find(key) ~= nil
    end

    -- Resolve the opener ITEM to mass-place from inventory. "Auto" picks the matching
    -- opener you hold the most of. Returns name, count (nil when none held).
    -- NOTE: does not route "Auto" through openerMatches — its "All" branch matches
    -- everything in the inventory, not just openers.
    function Cache.openerItemName(selType)
        local bestName, bestCount
        for name, cnt in pairs(Cache.countInventory()) do
            local matched = false
            if selType == nil or selType == "Auto" then
                for _, key in pairs(openerKinds) do
                    if name:find(key) then matched = true; break end
                end
            else
                local key = openerKinds[selType]
                matched = key ~= nil and name:find(key) ~= nil
            end
            if matched and (bestCount == nil or cnt > bestCount) then bestName, bestCount = name, cnt end
        end
        return bestName, bestCount
    end

    -- Cancel a loop thread and drop it from Cache.Loops. Returns nil so callers can
    -- write `Thread = Cache.stoploop(Thread)`.
    function Cache.stoploop(t)
        if t then
            pcall(function() task.cancel(t) end)
            for i = #Cache.Loops, 1, -1 do
                if Cache.Loops[i] == t then table.remove(Cache.Loops, i); break end
            end
        end
        return nil
    end
end

-- inventory
local function getinv()
    local now = tick()
    if Cache.InvCache and (now - Cache.InvLastUpdate) < 0.5 then return Cache.InvCache end

    local counts = Cache.countInventory()

    local allItems = {}
    for name, count in pairs(counts) do table.insert(allItems, regitem(name, count)) end
    table.sort(allItems)

    Cache.InvCache      = #allItems > 0 and allItems or {"Empty"}
    Cache.InvLastUpdate = now
    return Cache.InvCache
end

-- ---- vends: finding them and their mode -----------------------------------
-- A vend's current mode: 0 sells, 1 buys, nil when it cannot be read. The game has
-- carried it as an attribute and as a value child under two spellings; one reader.
function Cache.vendMode(v)
    local mode = v:GetAttribute("mode") or v:GetAttribute("Mode")
    if mode == nil then
        local mc = v:FindFirstChild("mode") or v:FindFirstChild("Mode")
        if mc then mode = mc.Value end
    end
    return mode
end

-- nearby vending machines
-- ignoreModeFilter: repricing YOUR OWN shop should hit both sell AND buy vends
-- regardless of the "Only Act On" (Sell/Buy) targeting filter, which is meant
-- for actions AGAINST other people's vends — not your own shop maintenance.
local function getvendings(ignoreModeFilter)
    local list = {}
    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return list end
    local hrpPos = hrp.Position
    local radSq  = Settings.VendingRadius * Settings.VendingRadius

    for _, data in pairs(Cache.VendingMachines) do
        local v, part = data.v, data.part
        if not (v and v.Parent and part and part.Parent) then continue end
        if not ignoreModeFilter and State.TargetVendingMode ~= "All" then
            local mode = Cache.vendMode(v)
            if mode == nil then continue end
            if State.TargetVendingMode == "Sell" and mode ~= 0 then continue end
            if State.TargetVendingMode == "Buy"  and mode ~= 1 then continue end
        end
        if State.SelectionModeEnabled and not Cache.SelectedVendings[v] then continue end
        local d = part.Position - hrpPos
        if Settings.IgnoreRadius or (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= radSq then
            table.insert(list, v)
        end
    end
    return list
end

-- nearby chests
local function getchests()
    local list = {}
    local char = LocalPlayer.Character
    local hrp  = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return list end
    local hrpPos = hrp.Position
    local radSq  = Settings.VendingRadius * Settings.VendingRadius
    local targetInternal = Cache.ChestMap[State.SelectedChestType] or "All"

    for _, data in pairs(Cache.Chests) do
        local v, part = data.v, data.part
        if not (v and v.Parent and part and part.Parent) then continue end
        if targetInternal ~= "All" and v.Name ~= targetInternal then continue end
        local d = part.Position - hrpPos
        if Settings.IgnoreRadius or (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= radSq then
            table.insert(list, v)
        end
    end
    return list
end

-- functions to open and close vending machines
local function openVending(guid, v)
    -- pcall so a nil/renamed remote (these are resolved via FindFirstChild, so a game
    -- update can turn them nil) can't crash the caller's batch loop; a failed open
    -- just skips that machine instead of killing the whole feature thread.
    pcall(function()
        Remotes.VendingOpen:FireServer(guid, {{vendingMachine = v}})
        Remotes.VendingEdit:FireServer(guid, {{vendingMachine = v}})
    end)
end
local function closeVending(v)
    pcall(function() Remotes.VendingClose:FireServer({vendingMachine = v}) end)
end

-- Set ONE vend's mode + price: open it, fire, close it. The server only accepts the
-- change while the machine is open, and a nil price means "we couldn't read one" --
-- the machine is still opened and closed so the caller's pacing is unchanged.
-- Returns true when the change was actually sent.
function Cache.applyVendMode(v, newMode, price)
    local guid = HttpService:GenerateGUID(false)
    openVending(guid, v)
    task.wait(Delay.VendingAction)
    local sent = false
    if price then
        -- REPORT WHAT THE PCALL SAID, not the fact that we reached this line. These
        -- remotes are resolved with FindFirstChild, so a game update renaming one
        -- turns every fire into a throw the pcall eats -- and `sent = true` then told
        -- the caller it worked. The visible result was "Set 30 vend(s) to Sell mode"
        -- with not one price changed, which sends you hunting for a server problem
        -- that isn't there instead of re-capturing the remote.
        sent = pcall(function() Remotes.VendingMode:FireServer(guid, {{
            mode = newMode, vendingMachine = v,
            player_tracking_category = "join_from_web", transactionPrice = price,
        }}) end)
    end
    closeVending(v); task.wait(Delay.VendingAction)
    return sent
end

-- ---- items in and out of a vend -------------------------------------------
-- vending manager
-- itemName = nil means EVERY item in the vend (that is how "Withdraw All Items"
-- works). Returns how many vends were emptied and how many items came out, so the
-- button can report it instead of finishing in silence.
local function withdrawitems(customAmt, gen, itemName)
    if gen and gen ~= State.ItemLoopGen then return 0, 0 end
    local vendsHit, moved = 0, 0
    for _, v in ipairs(getvendings()) do
        if gen and gen ~= State.ItemLoopGen then break end
        if State.IsCleaningUp then break end
        local contents = v:FindFirstChild("SellingContents"); if not contents then continue end
        local items = {}
        if itemName then
            local it = contents:FindFirstChild(itemName)
            if it then
                local a = it:FindFirstChild("Amount")
                if a and a.Value > 0 then
                    table.insert(items, { tool = it, amount = customAmt and math.min(customAmt, a.Value) or a.Value })
                end
            end
        else
            for _, child in ipairs(contents:GetChildren()) do
                local a = child:FindFirstChild("Amount")
                if a and a.Value > 0 then
                    table.insert(items, { tool = child, amount = customAmt and math.min(customAmt, a.Value) or a.Value })
                end
            end
        end
        if #items == 0 then continue end
        vendsHit += 1
        local guid = HttpService:GenerateGUID(false)
        openVending(guid, v)
        task.wait(Delay.VendingAction)
        for _, entry in ipairs(items) do
            if State.IsCleaningUp then break end
            -- count it AFTER the send says it went, not before: a renamed remote
            -- throws inside the pcall and the total would still claim the items came out
            if pcall(function()
                Remotes.VendingTrans:FireServer(guid, {{
                    player_tracking_category = "join_from_web",
                    vendingMachine = v, action = "withdraw",
                    tool = entry.tool, amount = entry.amount,
                }})
            end) then moved += entry.amount end
            task.wait(Delay.VendingAction)
        end
        closeVending(v); task.wait(Delay.VendingAction)
    end
    return vendsHit, moved
end

-- Deposit up to `amount` of one item into ONE vend: open, fire, close. The tool is
-- re-found after the open because the instance can be replaced while the vend
-- opens. Returns how many were actually sent (0 if the item vanished on us).
function Cache.depositToVend(v, itemName, amount)
    local function findTool()
        local bp = LocalPlayer:FindFirstChild("Backpack")
        local t = bp and bp:FindFirstChild(itemName)
        if not t and LocalPlayer.Character then t = LocalPlayer.Character:FindFirstChild(itemName) end
        return t
    end
    if not findTool() then return 0 end
    local guid = HttpService:GenerateGUID(false)
    openVending(guid, v)
    -- THE SAME ONE-FRAME GAP EVERY OTHER VEND ACTION USES. Open and deposit go out on
    -- different remotes, so a wait is needed -- Roblox only orders calls within one
    -- remote -- but this was the one place that hardcoded 0.05 where applyVendMode,
    -- withdrawitems and both coin paths use Delay.VendingAction. At 60fps a 0.05 wait
    -- rounds up to four frames, and two of them per vend made depositing three to four
    -- times slower than withdrawing the same items back out, for no reason anyone ever
    -- wrote down. Raise Delay.VendingAction if a future server rejects the pace.
    task.wait(Delay.VendingAction)
    local sent = 0
    local tool = findTool()
    if tool then
        local va = tool:FindFirstChild("Amount") or tool:FindFirstChild("Value")
        local cur = va and va.Value or 1
        local final = math.min(amount, cur)
        if final > 0 then
            -- only report a deposit the fire actually accepted (see applyVendMode)
            if pcall(function()
                Remotes.VendingTrans:FireServer(guid, {{
                    player_tracking_category = "join_from_web",
                    vendingMachine = v, action = "deposit",
                    tool = tool, amount = final,
                }})
            end) then sent = final end
        end
    end
    closeVending(v); task.wait(Delay.VendingAction)
    return sent
end

-- TAKE ONE ITEM OUT OF ONE VEND. The mirror of depositToVend above, and it exists for
-- the same reason that one does: withdrawitems walks EVERY vend in range, which is what
-- "Withdraw All Items" wants and the exact opposite of what rearranging a wall wants --
-- there the whole job is to empty this vend and not its neighbour.
--
-- The item instance is re-found after the open, like the deposit does, because the vend
-- replaces its contents while it opens and the one you looked at first is stale by then.
-- Returns how many actually came out, counted after the fire is accepted rather than
-- before it is sent, so a renamed remote reports nothing moved instead of lying.
function Cache.withdrawFromVend(v, itemName, amount)
    if not (v and v.Parent and itemName) then return 0 end
    local guid = HttpService:GenerateGUID(false)
    openVending(guid, v)
    task.wait(Delay.VendingAction)
    local took = 0
    local contents = v:FindFirstChild("SellingContents")
    local tool = contents and contents:FindFirstChild(itemName)
    if tool then
        local a = tool:FindFirstChild("Amount")
        local have = (a and a.Value) or 0
        local final = math.min(tonumber(amount) or have, have)
        if final > 0 then
            if pcall(function()
                Remotes.VendingTrans:FireServer(guid, {{
                    player_tracking_category = "join_from_web",
                    vendingMachine = v, action = "withdraw",
                    tool = tool, amount = final,
                }})
            end) then took = final end
        end
    end
    closeVending(v); task.wait(Delay.VendingAction)
    return took
end

-- ---- REARRANGING A WALL THAT IS ALREADY FULL ---------------------------------
-- The Shop Organizer lays a buy/sell pattern over the vends and prices them. What it
-- never did is look at WHAT is in them: a wall built up over a month has swords next
-- to dirt next to a trophy, in whatever order things happened to get stocked, and the
-- only way to tidy it was to empty the whole thing by hand and start again.
--
-- This plans the tidy-up. Stacks are treated as ATOMIC -- a vend holding 4000 gears is
-- one thing that moves to one place, never split across vends -- so the wall's contents
-- are a permutation of themselves and nothing can be lost by arithmetic.
--
-- WHAT DOES NOT MOVE MATTERS MORE THAN WHAT DOES. Every move is a withdraw and a
-- deposit, so it costs two remote calls and a round trip through your inventory; a
-- plan that re-seats an item that was already in the right place is paying that for
-- nothing. So a slot whose ITEM already matches what should be there is left alone,
-- compared on the item and not the amount -- two vends of stone are interchangeable,
-- and shuffling them to equalise the piles would be work with no result.
--
-- Protected vends are fixed points: they keep what they hold and take no part in the
-- permutation, which is what "protected" has to mean if it means anything.
--   slots { { item = <name or nil>, amount =, protected = }, ... } in wall order
--   opts  { order = "section" (default, groups by Cache.itemCategory) | "name" }
-- returns a plan: target per slot, the two phases, and what it decided not to touch.
function Cache.planShopReorder(slots, opts)
    opts = opts or {}
    local order = opts.order or "section"
    local rep = { unchanged = 0, protected = 0, buyVends = 0, emptySlots = 0,
                  stacks = 0, mixed = 0 }
    local movable, stacks = {}, {}
    -- ONE STACK PER VEND IS THE TARGET, NOT THE ASSUMPTION. The rest of the shop puts
    -- one item type in a vend -- Stock The Shop does, Auto Restock tops up the one that
    -- is there -- so the first version of this read the first stocked item and stopped.
    -- A vend holding two is then INVISIBLE in its second half: the plan pulls one stack,
    -- deposits something new on top of the leftover, and the wall ends up worse than it
    -- started with an item silently stranded. A mixed vend is a mess to be fixed, not a
    -- shape to be assumed away, so every stack is read and each becomes a stack looking
    -- for a slot of its own.
    for i, sl in ipairs(slots or {}) do
        if type(sl) == "table" then
            local held = {}
            if type(sl.items) == "table" then
                for _, e in ipairs(sl.items) do
                    local amt = math.floor(tonumber(e.amount) or 0)
                    if type(e.item) == "string" and e.item ~= "" and amt > 0 then
                        held[#held + 1] = { item = e.item, amount = amt }
                    end
                end
            else
                local amt = math.floor(tonumber(sl.amount) or 0)
                if type(sl.item) == "string" and sl.item ~= "" and amt > 0 then
                    held[1] = { item = sl.item, amount = amt }
                end
            end
            sl._held = held
            if #held > 1 then rep.mixed = rep.mixed + 1 end
            -- A BUY VEND IS NOT A SHELF. It collects what other people sell you, which
            -- is why the stocker skips one too -- and unlike a sell vend its contents
            -- are takings rather than stock, so they are not ours to rearrange. Fixed
            -- point, the same as a protected vend, and for a better reason.
            if sl.protected then
                rep.protected = rep.protected + 1
            elseif sl.mode == 1 then
                rep.buyVends = rep.buyVends + 1
            else
                movable[#movable + 1] = i
                for _, st in ipairs(held) do stacks[#stacks + 1] = st end
            end
        end
    end
    rep.stacks = #stacks
    local rank = {}
    for i, c in ipairs(Cache.ItemCategories or {}) do rank[c] = i end
    local function sectionOf(item) return Cache.itemCategory(item) end
    table.sort(stacks, function(a, b)
        if order == "section" then
            local ra = rank[sectionOf(a.item)] or 98
            local rb = rank[sectionOf(b.item)] or 98
            if ra ~= rb then return ra < rb end
        end
        if a.item ~= b.item then return a.item < b.item end
        return a.amount > b.amount
    end)

    -- WHERE EACH STACK LANDS. Packed end to end by default. With rowBreak, a section
    -- starts at the beginning of a row and the rest of its last row is left empty --
    -- which is what makes a wall read as sections from across the island instead of as
    -- one long sorted list that happens to wrap. A section longer than a row simply
    -- runs on; the next one still starts fresh. If the rows run out the remainder packs
    -- continuously, because leaving stock on the floor to preserve a layout would be
    -- the wrong way round.
    local target = {}
    if order == "section" and opts.rowBreak and #movable > 0 then
        local byRow, rowOrder = {}, {}
        for _, idx in ipairs(movable) do
            local r = slots[idx].row or 1
            if not byRow[r] then byRow[r] = {}; rowOrder[#rowOrder + 1] = r end
            byRow[r][#byRow[r] + 1] = idx
        end
        table.sort(rowOrder)
        local ri, ci, placed = 1, 1, 0
        local lastSection
        for _, st in ipairs(stacks) do
            local sec = sectionOf(st.item)
            if lastSection and sec ~= lastSection and ri <= #rowOrder then
                ri, ci = ri + 1, 1          -- new section, new row
            end
            lastSection = sec
            while ri <= #rowOrder and ci > #byRow[rowOrder[ri]] do ri, ci = ri + 1, 1 end
            if ri > #rowOrder then break end
            target[byRow[rowOrder[ri]][ci]] = st
            ci, placed = ci + 1, placed + 1
        end
        -- anything the row layout could not seat packs into whatever is still free
        if placed < #stacks then
            local free = {}
            for _, idx in ipairs(movable) do if not target[idx] then free[#free + 1] = idx end end
            for k = placed + 1, #stacks do
                if not free[k - placed] then break end
                target[free[k - placed]] = stacks[k]
            end
        end
    else
        for k, idx in ipairs(movable) do target[idx] = stacks[k] end
    end

    local takeOut, putIn = {}, {}
    for _, idx in ipairs(movable) do
        local held = slots[idx]._held
        local want = target[idx]
        -- unchanged only when the vend holds exactly ONE stack and it is the right one.
        -- Two stacks is never right, however good the first one looks.
        local settled = (#held == 1) and want and held[1].item == want.item
        if settled then
            rep.unchanged = rep.unchanged + 1
        elseif #held == 0 and not want then
            rep.unchanged = rep.unchanged + 1
            rep.emptySlots = rep.emptySlots + 1
        else
            for _, st in ipairs(held) do
                takeOut[#takeOut + 1] = { slot = idx, item = st.item, amount = st.amount }
            end
            if want then
                putIn[#putIn + 1] = { slot = idx, item = want.item, amount = want.amount }
            else
                rep.emptySlots = rep.emptySlots + 1
            end
        end
    end
    return { target = target, takeOut = takeOut, putIn = putIn, report = rep }
end

-- Returns vends filled and items moved, like withdrawitems, so the button can say
-- what it did. It used to return nothing at all: you pressed 'Perform Item Action',
-- the thread went away for as long as it took, and the only way to know whether it had
-- worked -- or was still going -- was to open a vend and look.
local function deposititems(itemName, amount, gen)
    if gen and gen ~= State.ItemLoopGen then return 0, 0 end
    local bp = LocalPlayer:FindFirstChild("Backpack")
    local function FindTool()
        local t = bp and bp:FindFirstChild(itemName)
        if not t and LocalPlayer.Character then t = LocalPlayer.Character:FindFirstChild(itemName) end
        return t
    end
    if not FindTool() then return 0, 0 end
    local vendsHit, moved = 0, 0
    for _, v in ipairs(getvendings()) do
        if gen and gen ~= State.ItemLoopGen then break end
        if State.IsCleaningUp then break end
        local contents = v:FindFirstChild("SellingContents")
        local total, existing, skip = 0, 0, false
        if contents then
            for _, it in ipairs(contents:GetChildren()) do
                local a = it:FindFirstChild("Amount")
                if a and a.Value > 0 then
                    total += a.Value
                    if it.Name ~= itemName then skip = true; break end
                    existing += a.Value
                end
            end
        end
        if skip or total >= 1000 then continue end
        -- EVERY amount is capped to the room left, not just the blank one. A vend holds
        -- 1000; blank already worked that out ('1 - existing' was a typo that deposited
        -- 0 into any vend already holding stock), but 'Deposit (Max)' asked for
        -- 999999999 and depositToVend happily offered your entire stack to the first
        -- vend it found. Whatever the server does with an over-cap offer, it cannot put
        -- 2,500 into a 1,000 slot -- so one press moved one vend's worth and you pressed
        -- it again, and again. Capped, the stack spreads across as many vends as it
        -- needs in a single press, which is what Max meant.
        local room = math.max(0, 1000 - existing)
        local depositAmt = (amount and amount > 0) and math.min(amount, room) or room
        if depositAmt <= 0 then continue end
        local sent = Cache.depositToVend(v, itemName, depositAmt)
        if sent > 0 then vendsHit += 1; moved += sent end
        -- STOP WHEN THE STACK IS SPENT. 'Deposit (Max)' empties your stack into as many
        -- vends as it takes, and the loop then walked every remaining vend to be told
        -- there was nothing left to give -- a couple of frames each, times however many
        -- vends you own, spent proving the obvious.
        local left = FindTool()
        local la = left and (left:FindFirstChild("Amount") or left:FindFirstChild("Value"))
        if not left or (la and la.Value <= 0) then break end
    end
    return vendsHit, moved
end

-- ---- coins: withdraw, and the deposit planner -----------------------------
-- WHICH VEND GIVES UP HOW MANY COINS, decided before any of them is opened. Pure, the
-- way planCoinDeposit is, so both directions of the same idea are proved the same way
-- (tests/coins.test.lua) instead of one of them being arithmetic buried in a loop.
--
-- Amount used to mean "this much from EACH vend", and nothing clamped it to what the
-- vend held: asking 80B of a wall of five took 80B from every one, and a vend holding
-- 2B was still counted as 80B withdrawn -- a summary reporting coins that could not
-- have existed.
--
--   "Withdraw"              a TOTAL, taken in the order given, each vend capped at what
--                           it holds, stopping when the budget is spent
--   "Withdraw (Max)"        everything, every vend
--   "Drain Each To Amount"  each vend brought DOWN to amount, fullest first -- the true
--                           mirror of "Fill Each To Amount", which fills each vend UP to
--                           one. Fullest first so the wall levels off from the top.
--
-- vends: { {v=, balance=}, ... }. Returns the sends { {v=, amount=}, ... } and a
-- summary: want (what the mode asked for), short (asked for and not there) and empty
-- (vends holding nothing, skipped).
function Cache.planCoinWithdraw(mode, amount, vends)
    local sum = { want = 0, short = 0, empty = 0 }
    local cands = {}
    for i, e in ipairs(vends) do
        local bal = math.max(0, math.floor(tonumber(e.balance) or 0))
        if bal <= 0 then sum.empty += 1
        else cands[#cands + 1] = { v = e.v, balance = bal, order = i } end
    end
    local sends = {}
    local function take(c, n)
        n = math.floor(math.min(n, c.balance))
        if n > 0 then sends[#sends + 1] = { v = c.v, amount = n }; return n end
        return 0
    end
    if mode == "Drain Each To Amount" then
        local target = math.max(0, math.floor(tonumber(amount) or 0))
        table.sort(cands, function(a, b)
            if a.balance ~= b.balance then return a.balance > b.balance end
            return a.order < b.order
        end)
        for _, c in ipairs(cands) do
            local need = math.max(0, c.balance - target)
            sum.want += need
            sum.short += need - take(c, need)
        end
    elseif mode == "Withdraw (Max)" then
        for _, c in ipairs(cands) do
            sum.want += c.balance
            take(c, c.balance)
        end
    else                                        -- "Withdraw": one budget across the wall
        local left = math.max(0, math.floor(tonumber(amount) or 0))
        sum.want = left
        for _, c in ipairs(cands) do
            if left <= 0 then break end
            left -= take(c, math.min(left, c.balance))
        end
        sum.short = left
    end
    return sends, sum
end

-- Carries the plan out. Mirrors the deposit executor, including the re-clamp: the plan
-- was made against one reading of the balances, so each send is trimmed to what the
-- vend actually holds when its turn comes.
local function withdrawcoins(amount, gen, mode)
    if gen and gen ~= State.CoinLoopGen then return 0, 0 end
    if State.CoinActionInProgress then return 0, 0 end
    State.CoinActionInProgress = true
    mode = mode or (amount and "Withdraw" or "Withdraw (Max)")
    local vendsHit, moved = 0, 0
    local sum = { want = 0, short = 0, empty = 0 }
    -- pcall the whole batch so a thrown FireServer (e.g. a nil/renamed remote) can never
    -- leave CoinActionInProgress stuck true, which would permanently block every future
    -- coin action via the guard above.
    pcall(function()
        local list = {}
        for _, v in ipairs(getvendings()) do
            local cb = v:FindFirstChild("CoinBalance")
            list[#list + 1] = { v = v, balance = cb and cb.Value or 0 }
        end
        local sends
        sends, sum = Cache.planCoinWithdraw(mode, amount, list)
        for _, s in ipairs(sends) do
            if gen and gen ~= State.CoinLoopGen then break end
            if State.IsCleaningUp then break end
            local guid = HttpService:GenerateGUID(false)
            openVending(guid, s.v)
            task.wait(Delay.VendingAction)
            local cb = s.v:FindFirstChild("CoinBalance")
            local wa = math.floor(math.min(s.amount, cb and cb.Value or s.amount))
            if wa > 0 then
                -- COUNT IT AFTER IT LEAVES. The batch pcall above exists so a throwing
                -- FireServer can't wedge CoinActionInProgress -- but the totals were
                -- added BEFORE the fire, so that same throw aborted the loop and still
                -- reported the coins as withdrawn. You are told 5M came out of three
                -- vends and the balances have not moved.
                Remotes.VendingCoinsWithdraw:FireServer(guid, {{
                    vendingMachine = s.v, player_tracking_category = "join_from_web", amount = wa,
                }})
                vendsHit += 1; moved += wa
            end
            closeVending(s.v); task.wait(Delay.VendingAction)
        end
    end)
    State.CoinActionInProgress = false
    return vendsHit, moved, sum.short, sum
end

-- WHICH VEND GETS HOW MANY COINS, decided before any of them is opened. Pure: it is
-- handed what the vends hold and what the pocket holds and returns the sends in the
-- order to make them, so it is tested without a vend in sight (tests/coins.test.lua).
--
-- The old loop had one rule, "amount into each vend as it comes", and "Max" meant the
-- whole pocket into whichever vend the scan listed first. Neither is what a shop
-- owner topping up a wall of buy vends means: 'Deposit 50M' onto a vend already
-- holding 30M made it 80M, and Max funded one vend and left the rest dry.
--
--   "Deposit"              amount into each vend, in the order given
--   "Deposit (Max)"        the whole pocket, emptiest vend first
--   "Fill Each To Amount"  each vend brought up to amount, emptiest first, so the
--                          driest vends are funded before the pocket runs out
--   "Spread Evenly"        the pocket split evenly, no vend past its space (what one
--                          cannot hold is shared out among the rest)
--
-- vends: { {v=, balance=, mode=}, ... } with mode 0 selling, 1 buying, nil unread.
-- skipSell leaves mode-0 vends out: a sell vend has no use for coins. Returns the
-- sends { {v=, amount=}, ... } and a summary: want (what the mode asked for), short
-- (asked for and the pocket did not have), leftover (pocket no vend had room for),
-- skippedSell, and full (already at the cap).
Cache.VendCoinCap = 5_000_000_000
-- ---- stocking an empty shop -----------------------------------------------
-- WHAT RESTOCK CANNOT DO. Auto Restock refills each vend with the item it already
-- sells; an EMPTY vend has nothing to tell it, so a wall of fresh machines stays a
-- wall of fresh machines. Filling them by hand is: pick item, pick amount, walk to
-- the next machine, forty times.
--
-- This is the other half: what you are carrying, spread one type per vend. The pile
-- you have most of goes in the first vend, so the wall reads biggest-first and the
-- item you brought a stack of is not the one that runs out of machines. An item you
-- hold a handful of never takes a vend at all (`minHave`) -- a shop wall is worth
-- more than a slot holding three of something.
--
-- ---- WHAT KIND OF THING IS THIS ----------------------------------------------
-- A shop wall is built in sections: the weapon wall, the ore wall, the trophy case.
-- Stocking one meant picking the right items out of a full inventory by hand, which
-- is the part nobody does twice. This sorts what you are carrying into the section
-- it belongs in, so "stock the weapons wall" is a dropdown and not forty decisions.
--
-- BY NAME, like every other classifier here (the tool picker in 034, the sickle
-- finder in 050). No item ids: the game adds items faster than a hardcoded list can
-- be updated, and a name test still works on the ones it has never seen.
--
-- ORDER IS THE WHOLE TRICK, because these words overlap. "swordRuby" holds "ruby"
-- and "diamondSword" holds "diamond" -- both are weapons, and both would read as
-- materials if materials were tested first. So the most specific bucket goes first
-- and the catch-all material words go last. Same reason 034 tests "pickaxe" before
-- "axe". Anything that matches nothing is "Other", which is a section too: it is
-- where you find the item the script has not learned yet.
-- THE SECTIONS, IN THE ORDER THEY ARE TESTED. First bucket with a matching whole word
-- wins, so this list is ordered most specific to most general, and every entry earns
-- its place from the game's own registry rather than from anyone's idea of a shop: the
-- counts beside each are how many of this game's 2202 item names land there.
--
-- Trophies first because a trophy is a trophy whatever it is made of and whatever it
-- depicts -- festivalFishTrophy is not a fish. Blocks & Materials last because it is
-- what "placeable, and nothing more specific claimed it" means.
Cache.ItemCategories = {
    "Trophies", "Blueprints", "Tools & Weapons", "Machines & Storage",
    "Food & Drink", "Crops & Seeds", "Furniture & Decor", "Blocks & Materials", "Other",
}
Cache.ItemCategoryWords = {
    { "Trophies", { "trophy", "trophies", "medal", "award", "ribbon" } },
    -- its own behaviour script in the game, and 51 items wearing it
    { "Blueprints", { "blueprint", "blueprints" } },
    { "Tools & Weapons", {
        "sword", "scythe", "sickle", "katana", "rapier", "cutlass", "dagger", "blade",
        "spear", "halberd", "glaive", "lance", "mace", "club", "hammer", "mallet",
        "pickaxe", "axe", "shovel", "spade", "mattock", "chisel", "drill", "saw",
        "bow", "crossbow", "sling", "arrow", "staff", "wand", "scepter", "dao", "fan",
        "whip", "rod", "net", "bucket", "shears", "torch", "armor", "helmet",
        "chestplate", "boots", "shield", "gauntlet",
        "spellbook", "grimoire", "tome", "scroll", "orb", "talisman", "amulet", "rune",
        -- straight off the game's own type list, not words anybody thought up
        "hoe", "tool", "watering", "clippers", "pesticide", "spray", "spreader",
        "rageblade", "quill", "throwable", "tap", "tube",
    } },
    -- A wall of machines is a shop section people actually build, and the game has the
    -- vocabulary for it: smelterIndustrial, washingStationIndustrial, vendingMachine1.
    -- Storage belongs with them rather than with furniture -- a chest is a thing you
    -- put things in, not a thing you sit on. It is tested before Food so that a crate
    -- of lemons is filed as a crate, the way the thing in your hand actually is.
    { "Machines & Storage", {
        "machine", "station", "smelter", "furnace", "forge", "anvil", "industrial",
        "extractor", "collector", "generator", "reactor", "refinery", "mill", "press",
        "workbench", "bench", "cauldron", "chest", "crate", "barrel", "silo", "tank",
        "vending", "storage", "pallet", "conveyor", "hopper",
    } },
    { "Food & Drink", {
        "food", "jar", "jam", "juice", "drink", "soda", "tea", "coffee", "milk",
        "bread", "dough", "cake", "pie", "pancake", "syrup", "soup", "stew", "salad",
        "sandwich", "cookie", "candy", "chocolate", "honey", "sugar", "salt", "meal",
        "potion", "elixir", "brew", "cooked", "roasted", "grilled", "fried",
        -- the catch, once it has been cut: cutSalmon and cutTuna are dinner, not fish
        -- you are still holding by the tail. Named one by one rather than by "cut",
        -- which on its own says nothing about what was cut.
        "carp", "catfish", "eel", "snapper", "salmon", "trout", "tuna",
        "sushi", "pizza", "truffle", "jug",
    } },
    { "Crops & Seeds", {
        "seed", "seeds", "sapling", "crop", "harvested", "wheat", "carrot", "potato",
        "tomato", "pumpkin", "corn", "cabbage", "lettuce", "onion", "pepper", "melon",
        "berry", "blueberry", "grape", "apple", "banana", "coconut", "lemon", "lime",
        "orange", "pineapple", "starfruit", "avocado", "kiwi", "spinach", "beans",
        "cactus", "mushroom", "flower", "rose", "tulip", "daisy", "lily", "sunflower",
        "orchid", "wool", "hay", "fruit", "vegetable", "fish", "fertile", "bush",
        "fertilizer",
    } },
    -- 152 item names carry the word "furniture" alone. Lamps, banners, ornaments and
    -- the seasonal decorations sit here too: they are all bought for the same reason.
    { "Furniture & Decor", {
        "furniture", "chair", "table", "bed", "stool", "sofa", "couch", "bench",
        "cabinet", "bookshelf", "shelf", "dresser", "wardrobe", "desk", "rug", "carpet",
        "curtain", "lamp", "lantern", "chandelier", "candle", "banner", "ornament",
        "painting", "portrait", "statue", "vase", "mirror", "clock", "fountain",
        "chimney", "fence", "gate", "door", "window", "sign", "disk", "instrument",
        "instruments", "firework", "sparkler", "confetti", "present", "wreath",
    } },
    { "Blocks & Materials", {
        "crystal", "iron", "gold", "diamond", "emerald", "ruby", "sapphire", "amethyst",
        "ore", "ingot", "bar", "nugget", "dust", "shard", "scrap", "plate", "block",
        "stone", "cobble", "rock", "marble", "slate", "granite", "obsidian", "basalt",
        "brick", "clay", "glass", "concrete", "sand", "dirt", "grass", "gravel", "mud",
        "snow", "ice", "wood", "plank", "log", "timber", "bamboo", "coal", "copper",
        "silver", "platinum", "titanium", "mithril", "steel", "leather", "cloth",
        "string", "fiber", "slime", "bone", "fossil", "essence", "fragment",
        "metal", "yarn", "slab", "stair", "pillar", "tile", "panel", "beam",
        "gear", "gearbox", "cog", "propeller", "piston", "spring", "bolt", "screw",
        "wire", "circuit", "motor", "engine", "turbine", "pipe", "valve", "gasket",
        "battery", "magnet", "fuel", "oil", "petroleum", "resin", "rubber", "plastic",
        -- gems and creature drops: what is left of the registry once everything with a
        -- purpose has been claimed, and all of it is something you sell by the stack
        "opal", "pearl", "aquamarine", "electrite", "feather", "leaves", "sap",
        "fang", "scale", "tooth", "flame",
    } },
}
-- WORDS, NOT SUBSTRINGS. The first cut of this tested `ln:find(word)` and was wrong
-- on a whole class of real names, because these words live inside other words:
-- "garnet" and "magnet" end in "net", "rice" and "juice" contain "ice", "barley"
-- contains "bar", "sawdust" starts with "saw". Every one of those came back as a
-- weapon or a material with a straight face. Ordering the buckets cannot help -- the
-- match itself is the bug. So the name is split into words the way fixname splits it
-- for display (camelCase boundary, then anything that is not a letter) and a bucket
-- claims the item only when one of those WHOLE words is in its list. "goldAxe" is
-- still {gold, axe} and still a tool; "garnet" is one word that is not "net".
-- Wrapped in a do-block, not left at file level: the two locals below (the splitter
-- and the prebuilt word sets) would be two of the main chunk's 200 registers, and
-- the ceiling has started to bite. Cache.itemCategory is a table field, so it is
-- still visible to every later part -- only its working parts are shut in here.
do
    local function itemWords(name)
        local s = tostring(name or "")
            :gsub("(%l)(%u)", "%1 %2")      -- goldAxe   -> gold Axe
            :gsub("(%u)(%u%l)", "%1 %2")    -- TNTBlock  -> TNT Block
            :gsub("[^%a]+", " "):lower()
        local out = {}
        for w in s:gmatch("%a+") do out[#out + 1] = w end
        return out
    end
    -- published so the combat weapon test below splits names the SAME way. A second
    -- splitter written beside this one would drift from it, and the whole point of
    -- the word rule is that every list matches whole words the same way.
    Cache.itemWords = itemWords
    -- built once: bucket name -> { word = true }, so a lookup is a hash hit per word
    local ItemCategorySets = {}
    for _, entry in ipairs(Cache.ItemCategoryWords) do
        local set = {}
        for _, word in ipairs(entry[2]) do set[word] = true end
        ItemCategorySets[entry[1]] = set
    end
    -- ITEMS WHOSE NAME LIES ABOUT THEM. "spikeCactus" is a weapon -- it is in this file's
    -- own WeaponPriority list further down -- and reads as a crop to any word test, because
    -- the word really is "cactus". No rule fixes that; it is a fact about one item, so it
    -- is written down as one. Add a name here when the words are right and the item is not.
    Cache.ItemCategoryNames = {
        spikeCactus = "Tools & Weapons",
    }
    -- THE WORD HALF ON ITS OWN. Split out from the lookup below so a caller can ask
    -- what the LISTS think, without the game's block folder answering for them. The
    -- report uses it to tell a word match apart from a rescue: an item that reached
    -- Blocks & Materials on a word is one the list already knows, and an item that got
    -- there only because the game has a template for it is a word worth adding. On
    -- screen those two look identical, and only one of them is a thing to fix.
    --
    -- Exact overrides first, then the buckets in order: first bucket with a matching
    -- whole word wins, and a plural still matches its word.
    function Cache.itemCategoryByWords(name)
        local raw = tostring(name or "")
        if raw == "" then return "Other" end
        local override = Cache.ItemCategoryNames[raw]
        if override then return override end
        local toks = itemWords(raw)
        for _, entry in ipairs(Cache.ItemCategoryWords) do
            local set = ItemCategorySets[entry[1]]
            for _, t in ipairs(toks) do
                if set[t]
                or (#t > 1 and t:sub(-1) == "s" and set[t:sub(1, -2)])
                or (#t > 2 and t:sub(-2) == "es" and set[t:sub(1, -3)]) then
                    return entry[1]
                end
            end
        end
        return "Other"
    end

    -- NOT EVERY BEHAVIOUR IS A TYPE. "block-place" is on 1439 of this game's 2202
    -- items -- every block, every piece of furniture, every machine, every trophy --
    -- and all it says is that you can place the thing. Asked as a type it is a
    -- bulldozer: the first cut of this asked the behaviour first and sent all 39
    -- trophies to the materials wall, because a trophy is placeable and "block-place"
    -- splits to {block, place}. Trophies went from 22 to nought, which is the section
    -- this feature was asked for first.
    --
    -- So placement behaviours are listed and deliberately NOT treated as an answer.
    -- They still decide the fallback at the end -- placeable really does mean material
    -- once nothing else has claimed it -- they just do not get to speak before the
    -- words that can tell a trophy from a stone.
    Cache.ItemPlacementBehaviours = { ["block-place"] = true, ["multiplace"] = true }

    -- Which section an item belongs in.
    --
    -- Cache.itemBehaviour (034) returns the name of the item's behaviour script, which
    -- for everything except the two above is the game's own word for what the item IS:
    -- "axe", "bow", "sword", "sickle", "blueprint", "food". That beats the item's own
    -- name, because it is a type rather than a label -- voidMattock says nothing any
    -- word list will ever catch, and its script says "axe".
    --
    -- The order that falls out of those two facts: a REAL type first, then the words,
    -- then placement, then nothing. A type the lists do not recognise falls through to
    -- the item's own name rather than swallowing the item -- the game offered an
    -- answer, the lists did not know it, and the next thing to try is what we did
    -- before. It goes through the same matcher as any other name, so
    -- "grimoire-spellbook" splits to {grimoire, spellbook} and hits a bucket without
    -- needing a mechanism of its own.
    function Cache.itemCategory(name)
        local raw = tostring(name or "")
        if raw == "" then return "Other" end
        local override = Cache.ItemCategoryNames[raw]
        if override then return override end
        local behaviour = Cache.itemBehaviour and Cache.itemBehaviour(raw) or nil
        local placeable = behaviour ~= nil and Cache.ItemPlacementBehaviours[behaviour] == true
        if behaviour and not placeable then
            local byType = Cache.itemCategoryByWords(behaviour)
            if byType ~= "Other" then return byType end
        end
        local byWords = Cache.itemCategoryByWords(raw)
        if byWords ~= "Other" then return byWords end
        if placeable then return "Blocks & Materials" end
        -- LAST, AND ONLY LAST: ask the game instead of guessing. Anything the Blocks
        -- folder holds a template for is something you can place, and a thing you place
        -- is a material -- which is how "garnet" and "barrel" reach the materials wall
        -- without anyone adding a word for them. It runs after every bucket because a
        -- seed and a trophy are placeable too, and asking first would flatten every
        -- section into this one.
        --
        -- Asked through Cache and only if it is there: Cache.isPlaceableBlock is defined
        -- in 034 and this part loads first, so at load time there is nothing to call. It
        -- is also what keeps this function pure under tests/run_tests.py, which loads
        -- this part without 034 -- see the note on the definition.
        if raw ~= "" and Cache.isPlaceableBlock and Cache.isPlaceableBlock(raw) then
            return "Blocks & Materials"
        end
        return "Other"
    end
end

-- WHAT THE PANEL SAYS, WORKED OUT WITHOUT A PANEL. 121 draws the window; this decides
-- every line in it. The split is the same one 064/065 have from 214-216 and for the
-- same reason: a part with UI at file level cannot be loaded by tests/run_tests.py, so
-- anything worth proving has to live on this side of the line. What is worth proving
-- here is the ORDER -- sections in Cache.ItemCategories order, and inside a section
-- biggest pile first with ties by name, which is exactly how planShopStock orders its
-- pool. If those two ever drift, the panel is lying about the wall it claims to preview.
--   inv   name -> count, as Cache.countInventory() returns it
--   opts  { floor = the minHave the planner would use, want = picked section, filter = search }
-- returns the lines, and how many item types it saw at all (0 = nothing to draw)
function Cache.itemSectionLines(inv, opts)
    opts = opts or {}
    local floor  = math.max(1, math.floor(tonumber(opts.floor) or 50))
    local want   = tostring(opts.want or "All")
    local filter = tostring(opts.filter or ""):lower()
    local buckets, counted = {}, 0
    for _, c in ipairs(Cache.ItemCategories) do buckets[c] = {} end
    for name, n in pairs(inv or {}) do
        local have = math.floor(tonumber(n) or 0)
        if type(name) == "string" and name ~= "" and have > 0 then
            local b = buckets[Cache.itemCategory(name)] or buckets.Other
            b[#b + 1] = { name = name, have = have }
            counted = counted + 1
        end
    end
    if counted == 0 then return {}, 0 end
    local lines = {}
    lines[#lines + 1] = (want == "All")
        and "Stocking: every section, grouped by kind."
        or  ("Stocking: " .. want .. " only -- the rest stays in your pockets.")
    lines[#lines + 1] = ""
    for _, c in ipairs(Cache.ItemCategories) do
        local b = buckets[c]
        table.sort(b, function(x, y)
            if x.have ~= y.have then return x.have > y.have end
            return x.name < y.name
        end)
        local shown = {}
        for _, e in ipairs(b) do
            if filter == "" or fixname(e.name):lower():find(filter, 1, true) then
                shown[#shown + 1] = string.format("   %s   %s%s", shortnum(e.have), fixname(e.name),
                    e.have < floor and "   (under the floor)" or "")
            end
        end
        if #shown > 0 then
            lines[#lines + 1] = string.format("-- %s --   %d type(s)%s", c:upper(), #b,
                (want ~= "All" and c == want) and "   << stocking this" or "")
            for _, l in ipairs(shown) do lines[#lines + 1] = l end
            lines[#lines + 1] = ""
        end
    end
    if #buckets.Other > 0 and filter == "" then
        lines[#lines + 1] = "OTHER is what matched no name word and that the game's own"
        lines[#lines + 1] = "block list did not claim either. It still stocks -- pick Other"
        lines[#lines + 1] = "as the section -- but anything in there that plainly belongs"
        lines[#lines + 1] = "elsewhere is a word worth adding."
    end
    return lines, counted
end

-- THE SAME THING AS TEXT, FOR SENDING TO SOMEONE. The panel is for reading; this is
-- for pasting. The word lists in Cache.ItemCategoryWords are a guess at what this game
-- calls things -- only a handful of real names are known here for certain, the ones in
-- WeaponPriority below -- so the fastest way to make the sorter right is for someone
-- holding the actual items to send the actual names back.
--
-- It reports INTERNAL names, not display names, because those are what the classifier
-- and the Blocks folder are keyed on -- "Gold Trophy" is not something you can add to
-- a word list, "goldTrophy" is.
--
-- AND IT MARKS THE ONES THAT GOT THERE WITHOUT A WORD. An item on the materials wall
-- because a word matched and an item there because the game happens to have a block
-- for it look identical on screen, and only the second is a word worth adding. So the
-- second is flagged. Between that and the Other group, every line that wants doing
-- something about says so, and every other line is just confirmation.
--
-- OTHER GOES FIRST. It is the section that needs the reply, so it is the part nobody
-- has to scroll for.
function Cache.itemSectionReport(inv)
    local rows, n = {}, 0
    for name, count in pairs(inv or {}) do
        local have = math.floor(tonumber(count) or 0)
        if type(name) == "string" and name ~= "" and have > 0 then
            n = n + 1
            local cat = Cache.itemCategory(name)
            rows[#rows + 1] = {
                name = name, have = have, cat = cat,
                -- the flag that matters: this item is on the materials wall only
                -- because the game has a template for it, not because any word in
                -- the list matched. Those are exactly the words worth adding.
                rescued = (cat == "Blocks & Materials"
                           and Cache.itemCategoryByWords(name) == "Other"),
            }
        end
    end
    if n == 0 then return "No items -- the inventory read back empty." end
    local order = {}
    for i, c in ipairs(Cache.ItemCategories) do order[c] = i end
    order.Other = 0   -- the one that needs answering, at the top
    table.sort(rows, function(a, b)
        local ra, rb = order[a.cat] or 98, order[b.cat] or 98
        if ra ~= rb then return ra < rb end
        if a.have ~= b.have then return a.have > b.have end
        return a.name < b.name
    end)
    local out = { "Islands Trading Hub -- item sections", n .. " item type(s)", "" }
    local seen
    for _, r in ipairs(rows) do
        if r.cat ~= seen then
            seen = r.cat
            out[#out + 1] = "-- " .. r.cat:upper() .. " --"
                .. (r.cat == "Other" and "   (nothing recognised these)" or "")
        end
        out[#out + 1] = string.format("%s  x%d%s", r.name, r.have,
            r.rescued and "  [no word -- placeable]" or "")
    end
    return table.concat(out, "\n")
end

-- Pure: it is handed what you have and what is standing, and returns what to put
-- where. Depositing it, and setting the price after, is the caller's job.
--   items { {name=, have=}, ... }
--   vends { {v=, stocked=<item name or nil>, mode=<1 is Buy>, protected=}, ... } in wall order
--   opts  { perVend, minHave, oneVendPerItem, includeBuy, category }
function Cache.planShopStock(items, vends, opts)
    opts = opts or {}
    local perVend = math.max(1, math.floor(tonumber(opts.perVend) or Cache.VendStackCap or 1000))
    local minHave = math.max(1, math.floor(tonumber(opts.minHave) or 1))
    local onePer  = opts.oneVendPerItem ~= false
    -- nil / "All" = take everything, which is what it did before this existed
    local want = opts.category
    if want == "All" or want == "" then want = nil end
    -- ONE ITEM, WHEN THAT IS WHAT YOU MEAN. The section picker narrows to a kind of
    -- thing; this narrows to a thing. A wall of nothing but gears is an ordinary shop,
    -- and until this the only way to get one was to go and put everything else in a
    -- chest first.
    --
    -- IT WINS OVER THE SECTION when both are set, rather than being ANDed with it. A
    -- named item is already the complete answer to "which items", so also requiring it
    -- to sit in the picked section could do exactly one thing that matters: turn a
    -- deliberate pick into an empty plan, for a reason the panel would struggle to
    -- explain ("you asked for gears, and gears are not Trophies").
    local only = opts.onlyItem
    if only == "" or only == "All" then only = nil end
    local rep = { protected = 0, buySkipped = 0, alreadySelling = 0,
                  vendsUsed = 0, vendsLeftEmpty = 0, itemsLeftOut = 0, moved = 0,
                  wrongCategory = 0, notPicked = 0 }
    local pool = {}
    for _, it in ipairs(items or {}) do
        local name = type(it) == "table" and it.name or nil
        local have = math.floor(tonumber(type(it) == "table" and it.have) or 0)
        if type(name) == "string" and name ~= "" and have >= minHave then
            local cat = Cache.itemCategory(name)
            if only then
                -- a named item answers the question on its own; the section is not
                -- consulted, so a pick can never come back empty for a reason the
                -- person who made it would not expect
                if name ~= only then rep.notPicked = rep.notPicked + 1
                else pool[#pool + 1] = { name = name, have = have, cat = cat } end
            elseif want and cat ~= want then
                -- counted, not silently dropped: "nothing to do" with a section
                -- picked is a question ("is my stuff in the wrong bucket?"), and
                -- the skip line is where that gets answered
                rep.wrongCategory = rep.wrongCategory + 1
            else
                pool[#pool + 1] = { name = name, have = have, cat = cat }
            end
        end
    end
    -- SECTION FIRST, THEN BIGGEST PILE. Grouping by category before size is what makes
    -- a mixed wall come out sorted -- every sword next to every other sword -- instead
    -- of ordered by how much of each thing you happen to be carrying. Within a section
    -- it is still biggest-first, so the pile you brought a stack of is not the one that
    -- runs out of machines, and ties still break by name: the same inventory always
    -- lays out the same wall, which is what makes a preview worth reading.
    local catRank = {}
    for i, c in ipairs(Cache.ItemCategories) do catRank[c] = i end
    table.sort(pool, function(a, b)
        local ra, rb = catRank[a.cat] or 99, catRank[b.cat] or 99
        if ra ~= rb then return ra < rb end
        if a.have ~= b.have then return a.have > b.have end
        return a.name < b.name
    end)
    local plan, pi = {}, 1
    for _, e in ipairs(vends or {}) do
        if type(e) == "table" and e.v ~= nil then
            if e.protected then
                rep.protected = rep.protected + 1
            elseif e.mode == 1 and not opts.includeBuy then
                -- a Buy vend collects items FROM sellers; stocking one is meaningless
                rep.buySkipped = rep.buySkipped + 1
            elseif e.stocked then
                rep.alreadySelling = rep.alreadySelling + 1
            else
                while pi <= #pool and pool[pi].have < minHave do pi = pi + 1 end
                if pi > #pool then
                    rep.vendsLeftEmpty = rep.vendsLeftEmpty + 1
                else
                    local it = pool[pi]
                    local amount = math.min(perVend, it.have)
                    plan[#plan + 1] = { v = e.v, name = it.name, amount = amount }
                    it.have = it.have - amount
                    rep.vendsUsed = rep.vendsUsed + 1
                    rep.moved = rep.moved + amount
                    -- one vend per type unless you asked for the whole pile spread
                    if onePer or it.have < minHave then pi = pi + 1 end
                end
            end
        end
    end
    for i = pi, #pool do
        if pool[i].have >= minHave then rep.itemsLeftOut = rep.itemsLeftOut + 1 end
    end
    return plan, rep
end

function Cache.planCoinDeposit(mode, amount, pocket, vends, skipSell)
    local cap = Cache.VendCoinCap
    local sum = { want = 0, short = 0, leftover = 0, skippedSell = 0, full = 0 }
    local cands = {}
    for i, e in ipairs(vends) do
        local bal = tonumber(e.balance) or 0
        if skipSell and e.mode == 0 then sum.skippedSell += 1
        elseif bal >= cap then sum.full += 1
        else cands[#cands + 1] = { v = e.v, balance = bal, space = cap - bal, order = i } end
    end
    local sends = {}
    local left = math.max(0, math.floor(tonumber(pocket) or 0))
    local function give(c, n)
        n = math.floor(math.min(n, c.space, left))
        if n > 0 then sends[#sends + 1] = { v = c.v, amount = n }; left -= n end
        return n
    end
    local function emptiestFirst(a, b)
        if a.balance ~= b.balance then return a.balance < b.balance end
        return a.order < b.order
    end
    if mode == "Fill Each To Amount" then
        local target = math.max(0, math.floor(tonumber(amount) or 0))
        table.sort(cands, emptiestFirst)
        for _, c in ipairs(cands) do
            local need = math.max(0, math.min(target - c.balance, c.space))
            sum.want += need
            sum.short += need - give(c, need)
        end
    elseif mode == "Spread Evenly" then
        -- water-filling: the vend with the least room goes first and takes its equal
        -- share or all it can hold; whatever it could not take raises everyone's share
        table.sort(cands, function(a, b)
            if a.space ~= b.space then return a.space < b.space end
            return a.order < b.order
        end)
        sum.want = left
        local n = #cands
        for _, c in ipairs(cands) do
            give(c, math.floor(left / n))
            n -= 1
        end
        sum.leftover = left
    elseif mode == "Deposit (Max)" then
        table.sort(cands, emptiestFirst)
        sum.want = left
        for _, c in ipairs(cands) do give(c, c.space) end
        sum.leftover = left
    else                                       -- "Deposit": a fixed amount into each
        local each = math.max(0, math.floor(tonumber(amount) or 0))
        for _, c in ipairs(cands) do
            local need = math.min(each, c.space)
            sum.want += need
            sum.short += need - give(c, need)
        end
    end
    return sends, sum
end

local function depositcoins(mode, amount, gen)
    if gen and gen ~= State.CoinLoopGen then return 0, 0 end
    if State.CoinActionInProgress then return 0, 0 end
    State.CoinActionInProgress = true
    mode = mode or "Deposit"
    local vendsHit, moved, balanceUnknown = 0, 0, false
    local sum = { want = 0, short = 0, leftover = 0, skippedSell = 0, full = 0 }
    -- pcall the whole batch so a thrown FireServer can never leave
    -- CoinActionInProgress stuck true (which would block all future coin actions).
    pcall(function()
        local list = {}
        for _, v in ipairs(getvendings()) do
            local cb = v:FindFirstChild("CoinBalance")
            list[#list + 1] = { v = v, balance = cb and cb.Value or 0, mode = Cache.vendMode(v) }
        end
        local pocket = Cache.playerCoins()
        if not pocket then
            -- balance unreadable: a fixed amount can still be sent and judged by the
            -- server, so it is; the modes that divide the pocket have nothing to
            -- divide and are reported instead of quietly doing nothing
            balanceUnknown = true
            if mode ~= "Deposit" then return end
            pocket = math.huge
        end
        -- the sell-vend skip is a deposit-side default; a deliberate 'Only Act On:
        -- Sell' or 'Buy' is a choice already made and is respected as it stands
        local sends
        sends, sum = Cache.planCoinDeposit(mode, amount, pocket, list,
            State.CoinSkipSell and State.TargetVendingMode == "All")
        for _, s in ipairs(sends) do
            if gen and gen ~= State.CoinLoopGen then break end
            if State.IsCleaningUp then break end
            local guid = HttpService:GenerateGUID(false)
            openVending(guid, s.v)
            task.wait(Delay.VendingAction)
            -- the plan was made against one reading of the pocket; each send is
            -- clamped to what is actually in it now
            local live = Cache.playerCoins()
            local dep = live and math.min(s.amount, live) or s.amount
            if dep > 0 then
                -- count it after it leaves, for the reason withdrawcoins gives
                Remotes.VendingCoinsDeposit:FireServer(guid, {{
                    vendingMachine = s.v, player_tracking_category = "join_from_web", amount = dep,
                }})
                vendsHit += 1; moved += dep
                -- sent on purpose: not a loss to the Coin Tripwire (049)
                if Cache.tripwireSpent then Cache.tripwireSpent(dep) end
            end
            closeVending(s.v); task.wait(Delay.VendingAction)
        end
    end)
    State.CoinActionInProgress = false
    return vendsHit, moved, balanceUnknown, sum
end

-- ---- prices and the ATM ---------------------------------------------------
-- Shared guard: Select Vends Mode on but nothing picked means every vend action would
-- filter down to zero and silently do nothing (looks broken). Warn + signal to bail.
function Cache.selEmpty(title)
    if State.SelectionModeEnabled and not next(Cache.SelectedVendings) then
        Cache.notify({Title = title or "Vending", Content = "'Select Vends Mode' is ON but no vends are selected — Alt+Click your vend(s), or turn it off to target all nearby.", Duration = 7})
        return true
    end
    return false
end

local function setprice(amount)
    if Cache.selEmpty("Vending") then return end
    -- Item filter: only touch vends whose SellingContents holds the selected item, so
    -- you can reprice just your diamond vends without changing the whole shop.
    local wantItem = State.SelectedVendItem
    local itemOnly = State.SetPriceItemOnly and wantItem and wantItem ~= "" and wantItem ~= "Empty"
    if State.SetPriceItemOnly and not itemOnly then
        Cache.notify({Title="Vending", Content="'Only Vends Selling Selected Item' is ON but no item is picked — choose one in 'Select Item' first.", Duration=7})
        return
    end
    local newMode = State.SelectedVendMode
    local changed, skipped, wrongItem = 0, 0, 0
    local buyNoItem, flipKeepPrice, noPrice = 0, 0, 0
    for _, v in ipairs(getvendings()) do
        if State.IsCleaningUp then break end
        if Cache.VendWhitelist and Cache.VendWhitelist[v] then skipped += 1; continue end  -- protected shop vend
        if itemOnly then
            local sc = v:FindFirstChild("SellingContents")
            if not (sc and sc:FindFirstChild(wantItem)) then wrongItem += 1; continue end
        end
        -- current mode, to spot a Sell<->Buy flip that reuses the old (opposite-meaning) price
        local curMode = Cache.vendMode(v)
        -- a Buy vend with nothing stocked has nothing to buy (VendingMode carries no item;
        -- the buy target is whatever item already sits in the vend's SellingContents)
        if newMode == 1 then
            local sc = v:FindFirstChild("SellingContents")
            if not (sc and #sc:GetChildren() > 0) then buyNoItem += 1 end
        end
        local price = amount
        if not price then
            price = Cache.vendCurrentPrice(v)
            if price and curMode ~= nil and curMode ~= newMode then flipKeepPrice += 1 end
        end
        if Cache.applyVendMode(v, newMode, price) then changed += 1 else noPrice += 1 end
    end
    -- feedback: the old version was silent, so a working call felt "broken"
    local modeName = newMode == 1 and "Buy" or "Sell"
    if changed > 0 then
        local extra = ""
        if skipped > 0 then extra = extra .. " " .. skipped .. " protected skipped." end
        if itemOnly and wrongItem > 0 then extra = extra .. " " .. wrongItem .. " not selling " .. fixname(wantItem) .. "." end
        if flipKeepPrice > 0 then extra = extra .. " WARNING: " .. flipKeepPrice .. " kept their old price across a Sell<->Buy flip — that price now means the OPPOSITE; set an explicit price." end
        if buyNoItem > 0 then extra = extra .. " NOTE: " .. buyNoItem .. " Buy vend(s) have no item stocked — a Buy vend buys whatever item is deposited in it, so deposit the target item first (Item Actions)." end
        Cache.notify({Title="Vending", Content=string.format("Set %d vend(s) to %s mode%s.%s",
            changed, modeName, amount and (" @ " .. shortnum(amount)) or " (price kept)", extra), Duration=9})
    elseif skipped > 0 and wrongItem == 0 then
        Cache.notify({Title="Vending", Content="No vends changed — all " .. skipped
            .. " nearby/selected vend(s) are protected. Un-protect them (Protect Vends) to change them.", Duration=7})
    else
        Cache.notify({Title="Vending", Content="No vends changed — "
            .. (itemOnly and ("no " .. (State.SelectionModeEnabled and "selected" or "nearby") .. " vend sells " .. fixname(wantItem))
                or ("no vends " .. (State.SelectionModeEnabled and "selected" or "in range")))
            .. (noPrice > 0 and (" (" .. noPrice .. " had no readable price)") or "")
            .. ". Walk closer / widen radius / check your filters.", Duration=7})
    end
end

-- functions for ATMS and chests
local function doatm()
    local amount = parsenum(State.ATMInputValue)
    if not (amount and amount > 0) then return end
    local transferType = State.AtmMode == "Withdraw" and "WITHDRAWAL" or "DEPOSIT"
    if transferType == "DEPOSIT" then
        -- clamp to pocket balance: "Deposit 1B" with only 10M now deposits the 10M
        -- instead of firing an unaffordable amount the server rejects. Same balance
        -- read the sniper/coin-deposit paths use. WITHDRAWAL stays unclamped — the
        -- bank balance isn't client-readable anywhere.
        -- nil = unreadable, which must not be treated as "you have none": the
        -- deposit goes through unclamped and the server decides.
        local pocket = Cache.playerCoins()
        if pocket and pocket <= 0 then
            Cache.notify({Title="ATM", Content="No coins in your pocket to deposit.", Duration=3}); return
        end
        if pocket and amount > pocket then
            amount = pocket
            Cache.notify({Title="ATM", Content="Depositing your whole pocket: " .. shortnum(amount), Duration=3})
        end
    end
    -- AtmRemote is resolved via FindFirstChild and can be nil; pcall so a nil/renamed
    -- remote doesn't crash the ATM loop thread.
    pcall(function()
        Remotes.AtmRemote:FireServer(HttpService:GenerateGUID(false), {{
            accountType  = State.AtmAccount == "Shared" and "SHARED" or "PERSONAL",
            transferType = transferType,
            amount       = amount,
        }})
    end)
    -- a deposit leaves the pocket on purpose: not a loss to the Coin Tripwire (049)
    if transferType == "DEPOSIT" and Cache.tripwireSpent then Cache.tripwireSpent(amount) end
end

-- ---- chests ---------------------------------------------------------------
local function dochest(gen)
    if gen and gen ~= State.ChestLoopGen then return end
    local amount = parsenum(State.ChestItemAmountValue) or 1
    local tool
    if State.UseHeldItemChest then
        local char = LocalPlayer.Character; tool = char and char:FindFirstChildWhichIsA("Tool")
    else
        local bp = LocalPlayer:FindFirstChild("Backpack")
        tool = (bp and bp:FindFirstChild(State.SelectedChestItem))
            or (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(State.SelectedChestItem))
    end
    if not tool then return end
    local ao = tool:FindFirstChild("Amount")
    local dep = math.min(amount, ao and ao.Value or 1)
    if dep <= 0 then return end
    for _, chest in ipairs(getchests()) do
        if gen and gen ~= State.ChestLoopGen then break end
        if State.IsCleaningUp then break end
        Cache.fireInvoke(Remotes.ChestTrans, {
            chest = chest, player_tracking_category = "join_from_web",
            amount = dep, tool = tool, action = "deposit",
        })
        task.wait(0.05)
    end
end

-- WITHDRAW / auto-loot from chests & cauldrons. Field capture confirmed the
-- shape: CLIENT_CHEST_TRANSACTION{ chest, tool=<the item inside>, amount,
-- action="withdraw" }. The `tool` is the content instance sitting in the
-- chest's storage folder — we reference each one directly and pull its stack.
Cache.ChestContentFolders = { "Contents", "Items", "Storage", "Content", "SellingContents" }
-- WHAT A CHEST HOLDS, READ ONCE, THE SAME WAY EVERYWHERE. The content folder is the
-- first of ChestContentFolders the chest has; each child is one stack, its Amount
-- value the count (1 when there is none). Six parts walked those two loops for
-- themselves -- the withdraw below, the chest restock (128), the forecast's reserve
-- (126), the materials check (195), the pull (196) and the self-test (252) -- and a
-- game update that moves the folder or the Amount would have been six fixes. Returns
-- the folder (nil when the chest shows nothing) and the stacks, each { ref = <the
-- content instance the withdraw names>, item = <internal name>, amount = <count> }.
function Cache.chestStacks(chest)
    local sc
    for _, fn in ipairs(Cache.ChestContentFolders) do
        sc = chest:FindFirstChild(fn); if sc then break end
    end
    local stacks = {}
    if sc then
        for _, it in ipairs(sc:GetChildren()) do
            local a = it:FindFirstChild("Amount")
            stacks[#stacks + 1] = { ref = it, item = it.Name, amount = (a and tonumber(a.Value)) or 1 }
        end
    end
    return sc, stacks
end
function Cache.dochestwithdraw(gen)
    if gen and gen ~= State.ChestWithdrawGen then return end
    local want = State.SelectedChestItem  -- optional filter ("Empty"/nil = all)
    local filter = want and want ~= "" and want ~= "Empty" and getinternalname and getinternalname(want) or nil
    local perStack = parsenum(State.ChestItemAmountValue)  -- nil/0 = whole stack
    local pulled, chestsHit = 0, 0
    for _, chest in ipairs(getchests()) do
        if gen and gen ~= State.ChestWithdrawGen then break end
        if State.IsCleaningUp then break end
        local sc, stacks = Cache.chestStacks(chest)
        if sc then
            local anyThisChest = false
            for _, s in ipairs(stacks) do
                if gen and gen ~= State.ChestWithdrawGen then break end
                if not filter or s.item == filter then
                    local have = s.amount
                    local amt = (perStack and perStack > 0) and math.min(perStack, have) or have
                    if amt > 0 then
                        Cache.fireInvoke(Remotes.ChestTrans, {
                            chest = chest, player_tracking_category = "join_from_web",
                            amount = amt, tool = s.ref, action = "withdraw",
                        })
                        pulled += 1; anyThisChest = true
                        task.wait(Delay.VendingAction or 0.05)
                    end
                end
            end
            if anyThisChest then chestsHit += 1 end
        end
    end
    if not (gen and gen ~= State.ChestWithdrawGen) then
        Cache.notify({Title="Withdraw", Content=pulled > 0
            and string.format("Pulled %d stack(s) from %d chest/cauldron(s).", pulled, chestsHit)
            or "Nothing to withdraw (no matching items in range — scan chests / widen radius).", Duration=5})
    end
end

