    local function normkey(s)
        return (tostring(s):lower():gsub("[^a-z0-9]+", ""))
    end
    Cache.ItemDisplayNames = {}
    for line in DUMP:gmatch("[^\n]+") do
        local k = normkey(line)
        if k ~= "" then Cache.ItemDisplayNames[k] = line end
    end

    -- fixname with EVERY word capitalised, for an item the dump has no name for.
    -- Not a change to fixname: that stays as it is, pinned, because the dropdowns
    -- read better its way. This is the spreadsheet's answer to the same string.
    function Cache.titleName(raw)
        if type(raw) ~= "string" or raw == "" then return tostring(raw) end
        local n = fixname(raw)
        return (n:gsub("(%a[%w']*)", function(w) return w:sub(1, 1):upper() .. w:sub(2) end))
    end

    -- What the game calls this item, else the best name we can build from the id.
    function Cache.displayName(raw)
        if type(raw) ~= "string" or raw == "" then return tostring(raw) end
        local hit = Cache.ItemDisplayNames[normkey(raw)]
        if hit then return hit end
        return Cache.titleName(raw)
    end
end
