-- making things draggable and handling color changes
local IsHoveringElement = false

local function makedraggable(frame, handle)
    local dg, ds, dp = false, nil, nil
    handle.InputBegan:Connect(function(i, gp)
        if gp or IsHoveringElement then return end
        if i.UserInputType == Enum.UserInputType.MouseButton1
        or i.UserInputType == Enum.UserInputType.Touch then
            dg = true; ds = i.Position; dp = frame.Position
        end
    end)
    addconn(UserInputService.InputChanged:Connect(function(i)
        if not dg then return end
        if i.UserInputType == Enum.UserInputType.MouseMovement
        or i.UserInputType == Enum.UserInputType.Touch then
            local d = i.Position - ds
            frame.Position = UDim2.new(dp.X.Scale, dp.X.Offset + d.X, dp.Y.Scale, dp.Y.Offset + d.Y)
        end
    end))
    addconn(UserInputService.InputEnded:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1
        or i.UserInputType == Enum.UserInputType.Touch then dg = false end
    end))
end

local function smoothcolorchange(obj, color, duration)
    TweenService:Create(obj, TweenInfo.new(duration or 0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
        { BackgroundColor3 = color }):Play()
end

local function makeholdablebutton(btn, callback)
    local held, holdThread, clicked = false, nil, false
    local nc  = Color3.fromRGB(40,40,48)
    local hov = Color3.fromRGB(55,55,65)
    local prs = Color3.fromRGB(70,70,85)

    btn.MouseButton1Down:Connect(function()
        held = true; clicked = false; smoothcolorchange(btn, prs, 0.1)
        holdThread = task.delay(0.15, function()
            if not held then if not clicked then clicked = true; callback() end; return end
            clicked = true   -- the hold already stepped; release must not add one more
            callback()
            local d = 0.1
            while held do task.wait(d); if not held then break end; callback(); d = math.max(d * 0.9, 0.025) end
        end)
    end)
    btn.MouseButton1Up:Connect(function()
        held = false
        if holdThread then task.cancel(holdThread); holdThread = nil end
        if not clicked then clicked = true; callback() end
        smoothcolorchange(btn, hov, 0.1)
    end)
    -- MouseButton1Up only fires when the release is OVER the button: press, drag off
    -- and let go, and the repeat ran on until the button was clicked again. Stop on
    -- leaving it and on any release anywhere.
    local function releaseAway()
        if not held then return end
        -- clicked is left alone: this can run BEFORE MouseButton1Up on a normal quick
        -- click, and that one still has to step once
        held = false
        if holdThread then task.cancel(holdThread); holdThread = nil end
        smoothcolorchange(btn, nc, 0.1)
    end
    addconn(UserInputService.InputEnded:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1
        or i.UserInputType == Enum.UserInputType.Touch then releaseAway() end
    end))
    btn.MouseEnter:Connect(function() if not held then smoothcolorchange(btn, hov, 0.1) end end)
    btn.MouseLeave:Connect(function() if held then releaseAway() else smoothcolorchange(btn, nc, 0.1) end end)
    smoothcolorchange(btn, nc, 0)
end

-- ---- every floating panel in the window's colours ----------------------------------
-- The window is the UI library's (020) palette and type; the panels were written in
-- greys and Gotham of their own. buildFrameBase hands each panel to this pass, which
-- asks 053's Cache.panelTone what every grey stands for and paints the theme's tone
-- instead -- now, for whatever is added later, and again whenever a panel repaints a
-- colour (a hover, a status line), so nothing slips back to grey. Colours with a hue
-- are left alone. Panels that SHOW block colours (a preview you scan, a thumbnail, a
-- damage map) get the frame and title only, because a grey stone block turned navy
-- would make the preview lie. Pure rules: 053; this is the plumbing.
do
    Cache.PanelThemeSkip = {
        IVM_SignPreview = true, IVM_QRPreview = true, IVM_PixelPreview = true,
        IVM_TerrainPreview = true, IVM_RepairMap = true, IVM_BlueprintLibrary = true,
    }
    local PROPS = { BackgroundColor3 = "bg", TextColor3 = "text", PlaceholderColor3 = "text", Color = "stroke" }
    local function themeTone(name)
        local T = Library and Library.Theme
        if not T then return nil end
        if name == "Faint" then
            local a, b = T.Muted, T.Surface
            if not (a and b) then return nil end
            local ok, c = pcall(function()
                return Color3.new(a.R + (b.R - a.R) * 0.35, a.G + (b.G - a.G) * 0.35, a.B + (b.B - a.B) * 0.35)
            end)
            return ok and c or a
        end
        return T[name]
    end
    local GOTHAM = { [Enum.Font.Gotham] = "Regular", [Enum.Font.GothamMedium] = "Medium",
                     [Enum.Font.GothamBold] = "Bold", [Enum.Font.GothamBlack] = "Bold" }
    local function apply(inst)
        for prop, kind in pairs(PROPS) do
            local ok, c = pcall(function() return inst[prop] end)
            if ok and typeof(c) == "Color3" then
                local f = math.floor
                local name = Cache.panelTone(f(c.R * 255 + 0.5), f(c.G * 255 + 0.5), f(c.B * 255 + 0.5), kind)
                local t = name and themeTone(name)
                if t and t ~= c then pcall(function() inst[prop] = t end) end
            end
        end
        -- the window's type: Builder Sans at the weight the Gotham was
        local F = Library and Library.Fonts
        if F then
            local ok, f = pcall(function() return inst.Font end)
            local w = ok and GOTHAM[f]
            if w and F[w] then pcall(function() inst.FontFace = F[w] end) end
        end
    end
    local function hook(inst)
        local okC, cls = pcall(function() return inst.ClassName end)
        if not okC then return end
        if cls == "ImageLabel" or cls == "ImageButton" or cls == "ViewportFrame" then return end
        if not (cls == "UIStroke" or inst:IsA("GuiObject")) then return end
        apply(inst)
        local busy = false
        pcall(function()
            inst.Changed:Connect(function(prop)
                if busy or not (PROPS[prop] or prop == "Font") then return end
                busy = true; apply(inst); busy = false
            end)
        end)
    end
    -- root: a panel's frame. Hooks what is there and everything added later.
    function Cache.themePanel(root)
        if not (root and Cache.panelTone and Library and Library.Theme) then return end
        for _, d in ipairs(root:GetDescendants()) do hook(d) end
        pcall(function()
            root.DescendantAdded:Connect(function(d) task.defer(hook, d) end)
        end)
    end
end

-- the UI for showing required blocks
local function buildFrameBase(guiName, frameSize, framePos)
    local ui = Instance.new("ScreenGui")
    ui.Name = guiName; ui.Parent = gethui and gethui() or CoreGui; ui.ResetOnSpawn = false
    local frame = Instance.new("Frame"); frame.Name = "MainFrame"
    frame.Size = frameSize; frame.Position = framePos
    local TH = Library and Library.Theme or {}
    frame.BackgroundColor3 = TH.Background or Color3.fromRGB(20,20,25); frame.BorderSizePixel = 0; frame.Parent = ui
    local stroke = Instance.new("UIStroke", frame); stroke.Color = TH.Stroke or Color3.fromRGB(60,60,70)
    stroke.Thickness = TH.Stroke and 1 or 1.5
    local corner = Instance.new("UICorner", frame); corner.CornerRadius = UDim.new(0,10)
    local shadow = Instance.new("ImageLabel", frame); shadow.Name = "Shadow"
    shadow.AnchorPoint = Vector2.new(0.5,0.5); shadow.Position = UDim2.new(0.5,0,0.5,0)
    shadow.Size = UDim2.new(1,20,1,20); shadow.BackgroundTransparency = 1
    shadow.Image = "rbxassetid://131604521937076"; shadow.ImageColor3 = Color3.fromRGB(0,0,0)
    shadow.ImageTransparency = 0.6; shadow.ScaleType = Enum.ScaleType.Slice
    shadow.SliceCenter = Rect.new(20,20,80,80); shadow.ZIndex = -1
    -- the panel's own greys become the window's tones (see the theme pass above);
    -- a panel that shows block colours keeps them
    if not Cache.PanelThemeSkip[guiName] then task.defer(Cache.themePanel, frame) end
    return ui, frame
end

-- toggleName: the switch that shows this panel. Given one, the bar gets a close
-- button that turns THAT switch off, so the panel and its switch never disagree.
local function addTitleBar(frame, titleText, bgColor, toggleName)
    local titleBar = Instance.new("Frame"); titleBar.Name = "TitleBar"
    -- THE WINDOW'S TITLE BAR, whatever colour the caller asked for: the panels each
    -- passed their own grey (or purple), and the bar is the one place every panel
    -- shares -- so it is the theme's background, a hairline under it, and the title
    -- in the window's type. bgColor is still honoured where there is no theme.
    local TH = Library and Library.Theme or {}
    titleBar.Size = UDim2.new(1,0,0,35); titleBar.BackgroundColor3 = TH.Background or bgColor
    titleBar.BorderSizePixel = 0; titleBar.Parent = frame
    Instance.new("UICorner", titleBar).CornerRadius = UDim.new(0,8)
    if TH.Stroke then
        local rule = Instance.new("Frame"); rule.Name = "Rule"
        rule.Size = UDim2.new(1,0,0,1); rule.Position = UDim2.new(0,0,1,0)
        rule.BackgroundColor3 = TH.Stroke; rule.BorderSizePixel = 0; rule.Parent = titleBar
    end
    local title = Instance.new("TextLabel"); title.Name = "Title"
    title.Size = UDim2.new(1,-40,1,0); title.Position = UDim2.new(0,12,0,0)
    title.BackgroundTransparency = 1; title.Text = titleText
    title.TextColor3 = TH.Text or Color3.fromRGB(230,230,230); title.Font = Enum.Font.GothamBold
    pcall(function() if Library and Library.Fonts then title.FontFace = Library.Fonts.Bold end end)
    title.TextSize = 15; title.TextXAlignment = Enum.TextXAlignment.Left
    title.TextStrokeTransparency = 1; title.Parent = titleBar
    if toggleName then
        local close = Instance.new("TextButton"); close.Name = "Close"
        close.Size = UDim2.new(0,28,0,28); close.Position = UDim2.new(1,-32,0,3)
        close.BackgroundTransparency = 1; close.Text = "×"
        local idle = TH.Muted or Color3.fromRGB(200,200,210)
        close.TextColor3 = idle; close.Font = Enum.Font.GothamBold
        close.TextSize = 20; close.AutoButtonColor = false; close.Parent = titleBar
        close.MouseEnter:Connect(function() close.TextColor3 = TH.Error or Color3.fromRGB(255,110,110) end)
        close.MouseLeave:Connect(function() close.TextColor3 = idle end)
        close.MouseButton1Click:Connect(function()
            local tf = Cache.ToggleFunctions and Cache.ToggleFunctions[toggleName]
            if not (tf and pcall(tf, false)) then frame.Visible = false end
        end)
    end
    return titleBar
end

-- required blocks UI
-- THE CLIPBOARD, WHATEVER THE EXECUTOR CALLS IT. setclipboard on most, toclipboard
-- on some, syn.write_clipboard on the old Synapse; each is tried, and false comes
-- back when none took the text so the caller can say so. Read through the function
-- environment rather than by name, because a name the executor does not define is
-- an unknown global to tools/ast_globals.py. The Blueprint Library (219) used to
-- keep its own copy of this; it reads this one now.
function Cache.copyText(text)
    local env = getfenv(0)
    local syn = rawget(env, "syn")
    for _, fn in ipairs({ rawget(env, "setclipboard"), rawget(env, "toclipboard"),
                          type(syn) == "table" and syn.write_clipboard or nil }) do
        if type(fn) == "function" and pcall(fn, tostring(text)) then return true end
    end
    return false
end

local function createrequiredblocksui()
    if Cache.RequiredBlocksUI then pcall(function() Cache.RequiredBlocksUI:Destroy() end) end
    if Cache.RequiredBlocksUI then Cache.RequiredBlocksUI:Destroy() end
    local ui, frame = buildFrameBase("IVM_RequiredBlocks",
        UDim2.new(0,320,0,350), UDim2.new(0,10,0.5,-175))
    frame.Visible = State.ShowRequiredBlocksUI

    local titleBar = addTitleBar(frame, "Required Blocks", Color3.fromRGB(35,35,42), "Show Required Blocks UI")
    makedraggable(frame, titleBar)
    -- COPY, because every report the hub writes ends up in this one box -- materials,
    -- the queue's time and cost, the self-test, what the chests gave -- and the next
    -- thing the owner does with most of them is paste them somewhere.
    local copy = Instance.new("TextButton"); copy.Name = "Copy"
    copy.Size = UDim2.new(0,56,0,24); copy.Position = UDim2.new(1,-96,0,5)
    copy.BackgroundColor3 = Color3.fromRGB(50,50,60); copy.BorderSizePixel = 0
    copy.Text = "Copy"; copy.TextSize = 12; copy.Font = Enum.Font.GothamBold
    copy.TextColor3 = Color3.fromRGB(220,220,225); copy.Parent = titleBar
    Instance.new("UICorner", copy).CornerRadius = UDim.new(0,6)
    copy.MouseButton1Click:Connect(function()
        local txt = RequiredBlocksLabel and RequiredBlocksLabel.Text or ""
        if Cache.copyText(txt) then
            Cache.notify({Title="Copied", Content=string.format("%d line(s) of the Required Blocks panel are on your clipboard.", select(2, txt:gsub("\n", "")) + 1), Duration=3})
        else
            Cache.notify({Title="Copy", Content="Your executor offers no clipboard function. The last report is also in its own file under Islands trading hub.", Duration=6})
        end
    end)

    local scroll = Instance.new("ScrollingFrame"); scroll.Name = "Scroll"
    scroll.Size = UDim2.new(1,-16,1,-50); scroll.Position = UDim2.new(0,8,0,42)
    scroll.BackgroundColor3 = Color3.fromRGB(25,25,30); scroll.BorderSizePixel = 0
    scroll.ScrollBarThickness = 6; scroll.ScrollBarImageColor3 = Color3.fromRGB(80,80,90)
    scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y; scroll.Parent = frame
    Instance.new("UICorner", scroll).CornerRadius = UDim.new(0,6)

    local list = Instance.new("TextLabel"); list.Name = "List"
    list.Size = UDim2.new(1,-12,0,0); list.Position = UDim2.new(0,8,0,8)
    list.BackgroundTransparency = 1; list.Text = "No blueprint loaded."
    list.TextColor3 = Color3.fromRGB(190,190,190); list.Font = Enum.Font.GothamBold
    list.TextSize = 13; list.TextXAlignment = Enum.TextXAlignment.Left
    list.TextYAlignment = Enum.TextYAlignment.Top; list.TextStrokeTransparency = 1
    list.TextWrapped = true   -- wrap long block names instead of clipping them at the panel edge
    list.AutomaticSize = Enum.AutomaticSize.Y; list.Parent = scroll

    Cache.RequiredBlocksUI = ui
    RequiredBlocksLabel = list
    return ui
end
Cache.createRequiredBlocksUI = createrequiredblocksui
-- ONE DOOR TO THE PANEL. The Required Blocks panel is the script's one scrolling text
-- box, and eleven callers filled it the same five-line way: build it if it is not
-- there (RequiredBlocksLabel is nil until then), set the text, show the frame, set
-- the State flag, and move the tab's 'Show Required Blocks UI' switch so it stays
-- honest. Eleven copies of one idea is ten places for the next change to miss, so
-- this is the idea, once. text=nil shows the panel without touching what is in it.
-- Returns whether the frame exists (callers say "in the panel" or "in the file").
function Cache.showRequiredBlocks(text)
    if not (Cache.RequiredBlocksUI and Cache.RequiredBlocksUI.Parent) then
        pcall(Cache.createRequiredBlocksUI)
    end
    if RequiredBlocksLabel and text ~= nil then RequiredBlocksLabel.Text = text end
    local mf = Cache.RequiredBlocksUI and Cache.RequiredBlocksUI:FindFirstChild("MainFrame")
    if mf then mf.Visible = true end
    State.ShowRequiredBlocksUI = true
    local tf = Cache.ToggleFunctions and Cache.ToggleFunctions["Show Required Blocks UI"]
    if tf then pcall(tf, true) end
    return mf ~= nil
end

-- movement UI
-- THE PANEL HAS TO BE REBUILDABLE. It used to be created once, in a deferred thread
-- at start-up, and never again. But DoFullCleanup runs on TELEPORT -- a slot switch,
-- an island hop, even a teleport that fails to start -- and it destroys this panel
-- while the script keeps running. From then on the toggle read ON with nothing on
-- screen and no way to say why. Both toggles below rebuild on demand instead.
local function createmovementui()
    -- the ScreenGui, so a rebuild replaces the old one instead of stacking another
    -- invisible copy in gethui() every time
    if Cache.MovementUI then pcall(function() Cache.MovementUI:Destroy() end) end
    local ui, frame = buildFrameBase("IVM_Movement",
        UDim2.new(0,220,0,350), UDim2.new(1,-230,0.5,-175))
    frame.Visible = State.ShowMovementUI

    local titleBar = addTitleBar(frame, "Blueprint Movement", Color3.fromRGB(30,30,38), "Show Movement UI")
    makedraggable(frame, titleBar)

    local content = Instance.new("Frame"); content.Name = "Content"
    content.Size = UDim2.new(1,-16,1,-50); content.Position = UDim2.new(0,8,0,42)
    content.BackgroundColor3 = Color3.fromRGB(25,25,30); content.BorderSizePixel = 0
    content.Parent = frame
    Instance.new("UICorner", content).CornerRadius = UDim.new(0,8)

    local function makebtn(text, pos, callback, once)
        local btn = Instance.new("TextButton"); btn.Name = text
        btn.Size = UDim2.new(0,90,0,36); btn.Position = pos
        btn.BackgroundColor3 = Color3.fromRGB(40,40,48); btn.Text = text
        btn.TextColor3 = Color3.fromRGB(210,210,210); btn.Font = Enum.Font.GothamBold
        btn.TextSize = 13; btn.TextStrokeTransparency = 1; btn.AutoButtonColor = false
        btn.Parent = content
        Instance.new("UICorner", btn).CornerRadius = UDim.new(0,8)
        btn.MouseEnter:Connect(function() TweenService:Create(btn, TweenInfo.new(0.15), { BackgroundColor3 = Color3.fromRGB(55,55,65) }):Play() end)
        btn.MouseLeave:Connect(function() TweenService:Create(btn, TweenInfo.new(0.15), { BackgroundColor3 = Color3.fromRGB(40,40,48) }):Play() end)
        -- HOLD-TO-REPEAT IS FOR NUDGING, NOT FOR TURNING. A held nudge walks the build
        -- across the ground, which is the point; a held ROTATE spun it through a full
        -- turn about every tenth of a second, and every one of those turns throws the
        -- whole preview away and rebuilds it -- thousands of parts, forty times a
        -- second, on a build big enough to want turning. One press, one quarter turn.
        if once then
            btn.MouseButton1Click:Connect(callback)
            btn.MouseButton1Down:Connect(function() smoothcolorchange(btn, Color3.fromRGB(70,70,85), 0.1) end)
            btn.MouseButton1Up:Connect(function() smoothcolorchange(btn, Color3.fromRGB(55,55,65), 0.1) end)
        else
            makeholdablebutton(btn, callback)
        end
        return btn
    end

    local function moveRelative(direction)
        -- +rotation, not -rotation. The preview is drawn as CFrame.new(pos) *
        -- CFrame.Angles(0, rotY, 0), so a step along the BUILD's own X is that step
        -- rotated by +rotY. Negating it sent Left/Right (and Forward/Back) the wrong
        -- way the moment the build was rotated 90 or 270 degrees, which is how nudging
        -- it into place walks it further out instead of onto the blocks.
        local rotated = CFrame.Angles(0, State.BlueprintPreviewRotationY, 0):PointToWorldSpace(direction)
        -- keep the offset on whole cells: a rotation by math.pi/2 leaves ~1e-16 dust on
        -- the axis that should be zero, and enough nudges of that accumulate into a
        -- visible sub-stud drift of the whole build.
        State.BlueprintPreviewOffset += Vector3.new(
            math.floor(rotated.X / 3 + 0.5) * 3,
            math.floor(rotated.Y / 3 + 0.5) * 3,
            math.floor(rotated.Z / 3 + 0.5) * 3)
    end
    makebtn("Left",    UDim2.new(0,10,  0,10),  function() moveRelative(Vector3.new(-3,0,0)) end)
    makebtn("Right",   UDim2.new(0,106, 0,10),  function() moveRelative(Vector3.new(3,0,0)) end)
    makebtn("Up",      UDim2.new(0,10,  0,50),  function() State.BlueprintPreviewOffset += Vector3.new(0,3,0) end)
    makebtn("Down",    UDim2.new(0,106, 0,50),  function() State.BlueprintPreviewOffset -= Vector3.new(0,3,0) end)
    makebtn("Forward", UDim2.new(0,10,  0,90),  function() moveRelative(Vector3.new(0,0,-3)) end)
    makebtn("Back",    UDim2.new(0,106, 0,90),  function() moveRelative(Vector3.new(0,0,3)) end)
    -- TURNING IT, BOTH WAYS. There was one Rotate button and it only went one way, so
    -- getting back a quarter turn meant three more -- three full preview rebuilds --
    -- and nothing on screen said which way the build was facing. Both directions, and
    -- the angle written down.
    --
    -- Counted in QUARTER TURNS rather than added in radians: adding math.pi/2 four
    -- times leaves a build facing 6.283185307179586 instead of 0, and every later
    -- reader has to round it back. Rounding to the nearest quarter first also pulls a
    -- rotation that came from somewhere else -- the aligner, a queue entry -- onto a
    -- quarter turn before it is turned again.
    local function turn(steps)
        local q = math.floor((State.BlueprintPreviewRotationY or 0) / (math.pi / 2) + 0.5)
        State.BlueprintPreviewRotationY = ((q + steps) % 4) * (math.pi / 2)
        if Cache.paintMovementRotation then Cache.paintMovementRotation() end
    end
    makebtn("Rotate -90°", UDim2.new(0,10,  0,130), function() turn(-1) end, true)
    makebtn("Rotate +90°", UDim2.new(0,106, 0,130), function() turn(1) end, true)

    local rotLabel = Instance.new("TextLabel"); rotLabel.Name = "Facing"
    rotLabel.Size = UDim2.new(1,-20,0,18); rotLabel.Position = UDim2.new(0,10,0,170)
    rotLabel.BackgroundTransparency = 1; rotLabel.Text = "Facing: 0°"
    rotLabel.TextColor3 = Color3.fromRGB(170,180,205); rotLabel.Font = Enum.Font.GothamBold
    rotLabel.TextSize = 12; rotLabel.TextXAlignment = Enum.TextXAlignment.Center
    rotLabel.TextStrokeTransparency = 1; rotLabel.Parent = content
    -- repainted from the heartbeat while the panel is up, not only when a button here
    -- is pressed: the aligner and a queue entry both set the rotation from elsewhere,
    -- and a readout that lies is worse than no readout
    local function paintRot()
        if not rotLabel.Parent then return end
        local q = math.floor((State.BlueprintPreviewRotationY or 0) / (math.pi / 2) + 0.5) % 4
        local txt = string.format("Facing: %d°", q * 90)
        -- said here rather than on the button, because the mirror is a property of the
        -- blueprint that is loaded, not of the last press: it survives a rotate, a
        -- Reset and a panel rebuild, and it is gone the moment another blueprint loads
        if State.BlueprintPreviewFlipped then txt = txt .. " · Flipped" end
        if rotLabel.Text ~= txt then rotLabel.Text = txt end
    end
    Cache.paintMovementRotation = paintRot
    paintRot()

    -- FLIPPING IT. Turning is a number the preview and the engines already read;
    -- mirroring is not one, so this rewrites the loaded blocks (see the flip in the
    -- blueprint core for why, and for why one axis is enough next to the two rotate
    -- buttons above). One press, one flip -- it walks the whole blueprint and throws
    -- the preview away, so hold-to-repeat is the last thing it wants.
    local flipBtn = makebtn("Flip", UDim2.new(0,10, 0,194), function()
        local ok, msg = Cache.flipLoadedBlueprint()
        paintRot()
        Window:Notify({Title = ok and "Blueprint Flipped" or "Flip",
            Content = msg, Duration = ok and 6 or 8})
    end, true)
    flipBtn.Size = UDim2.new(1,-20,0,32)

    local resetBtn = makebtn("Reset", UDim2.new(0,10, 0,232), function()
        State.BlueprintPreviewOffset = Vector3.new(0,0,0)
        State.BlueprintPreviewRotationY = 0
        Cache.BlueprintAnchor = nil; Cache.BlueprintAnchorLocked = false
        paintRot()
        Window:Notify({Title="Preview", Content="Position reset.", Duration=2})
    end, true)
    resetBtn.Size = UDim2.new(1,-20,0,32)

    local hint = Instance.new("TextLabel"); hint.Name = "Hint"
    hint.Size = UDim2.new(1,-10,0,20); hint.Position = UDim2.new(0,5,1,-25)
    hint.BackgroundTransparency = 1; hint.Text = "3 studs = 1 block"
    hint.TextColor3 = Color3.fromRGB(130,130,130); hint.Font = Enum.Font.GothamBold
    hint.TextSize = 11; hint.TextXAlignment = Enum.TextXAlignment.Center
    hint.TextStrokeTransparency = 1; hint.Parent = content

    Cache.MovementUI = ui; Cache.MovementFrame = frame
    return ui
end
Cache.createMovementUI = createmovementui

-- Built up front so they are ready, but a failure here is no longer fatal to the
-- feature: both toggles rebuild on demand, so this is an optimisation, not the only
-- chance to exist.
task.defer(function() pcall(createrequiredblocksui) end)
task.defer(function() pcall(createmovementui) end)

