local FarmingTab  = Window:CreateTab("Farming",  GetIcon("sprout"), 70)
local OpeningTab  = Window:CreateTab("Opening",  GetIcon("package-open"), 80)
local MiscTab     = Window:CreateTab("Misc",     GetIcon("wrench"), 90)
local SettingsTab = Window:CreateTab("Settings", GetIcon("settings"), 100)

-- a dropdown menu where u can pick multiple things
local function CreateMultiDropdown(tabObj, props)
    -- Drawn by hand, so it has to be told what the window looks like: Library.Theme is
    -- the live UI library's palette, and UI.Colors is the one the old library left
    -- behind in bootstrap -- a different theme, in different colours, under the same
    -- names. Falling back to it keeps this working if the theme ever goes away again.
    local T = Library.Theme or {}
    local C = {
        Element = T.Surface2 or UI.Colors.Element,
        Row     = T.Surface  or UI.Colors.Sidebar,
        Text    = T.Text     or UI.Colors.Text,
        Dim     = T.Muted    or UI.Colors.TextDim,
        Accent  = T.Accent   or UI.Colors.Accent,
        OnAccent= T.AccentDark or Color3.fromRGB(235,235,245),
    }
    local SelectedSet, SelectedList = {}, {}
    for _, v in ipairs(props.CurrentOption or {}) do SelectedSet[v] = true; table.insert(SelectedList, v) end

    local dropFrame = Create("Frame", {
        Size = UDim2.new(1,0,0,42), BackgroundColor3 = C.Element,
        BorderSizePixel = 0, ClipsDescendants = true,
        LayoutOrder = tabObj.NextOrder and tabObj:NextOrder() or 0, Parent = tabObj.Page,
    })
    Create("UICorner", { CornerRadius = UDim.new(0,6), Parent = dropFrame })
    local Header = Create("TextButton", { Size = UDim2.new(1,0,0,42), BackgroundTransparency = 1, BorderSizePixel = 0, Text = "", Parent = dropFrame })
    Create("TextLabel", {
        Size = UDim2.new(1,-40,1,0), Position = UDim2.new(0,10,0,0),
        BackgroundTransparency = 1, Text = props.Name,
        TextColor3 = C.Text, Font = UI.Font, TextSize = 14,
        TextXAlignment = Enum.TextXAlignment.Left, Parent = Header,
    })
    dropFrame.MouseEnter:Connect(function() IsHoveringElement = true end)
    dropFrame.MouseLeave:Connect(function() IsHoveringElement = false end)

    local SelectedLabel = Create("TextLabel", {
        Size = UDim2.new(1,-40,1,0), Position = UDim2.new(0,10,0,0),
        BackgroundTransparency = 1, Text = table.concat(SelectedList, ", "),
        TextColor3 = C.Accent, Font = UI.Font, TextSize = 14,
        TextXAlignment = Enum.TextXAlignment.Right, Parent = Header,
    })
    local Arrow = Create("ImageLabel", {
        Size = UDim2.new(0,16,0,16), Position = UDim2.new(1,-26,0.5,-8),
        BackgroundTransparency = 1, Image = "rbxassetid://6031091004",
        ImageColor3 = C.Dim, Parent = Header,
    })
    local Container = Create("ScrollingFrame", {
        Size = UDim2.new(1,-10,0,150), Position = UDim2.new(0,5,0,45),
        BackgroundTransparency = 1, ScrollBarThickness = 2,
        ScrollBarImageColor3 = Color3.fromRGB(60,60,65), BorderSizePixel = 0, Parent = dropFrame,
    })
    Create("UIListLayout", { Padding = UDim.new(0,2), SortOrder = Enum.SortOrder.LayoutOrder, Parent = Container })

    local Open    = false
    local Options = props.Options or {}
    local DropObj = { CurrentOption = SelectedList }
    local ButtonPool = {}

    local function UpdateLabel()
        SelectedList = {}
        for _, opt in ipairs(Options) do if SelectedSet[opt] then table.insert(SelectedList, opt) end end
        DropObj.CurrentOption = SelectedList
        local display
        if     SelectedSet["All"] then display = "All"
        elseif #SelectedList == 0 then display = "None"
        elseif #SelectedList <= 2 then display = table.concat(SelectedList, ", ")
        else   display = SelectedList[1] .. ", " .. SelectedList[2] .. " (+" .. (#SelectedList - 2) .. ")" end
        SelectedLabel.Text = display
    end

    -- WHAT ROW i CURRENTLY SHOWS. The pooled buttons are created once and repainted on
    -- every Refresh, but their click/hover closures captured the option string they
    -- were BORN with -- and Refresh replaces the option list without rebuilding them.
    -- So after "Remove These Types" was refreshed from its placeholder to a real
    -- blueprint's types, row 1 read `stone x4321` and toggled "Load blueprint first".
    -- Where old and new lists overlapped it silently ticked the WRONG block type for
    -- removal, which is a build quietly omitting blocks you never chose. Reading the
    -- option out of this table at click time means a repaint is enough to rebind.
    local ButtonOpt = {}

    local function RefreshList()
        for i, opt in ipairs(Options) do
            local isSel = SelectedSet[opt]
            local optBtn = ButtonPool[i]
            ButtonOpt[i] = opt
            if not optBtn then
                optBtn = Create("TextButton", {
                    BorderSizePixel = 0, Size = UDim2.new(1,0,0,30),
                    BackgroundColor3 = isSel and C.Accent or C.Row,
                    TextColor3 = isSel and C.OnAccent or C.Dim,
                    AutoButtonColor = false, Text = opt, Font = UI.Font, TextSize = 13, Parent = Container,
                })
                Create("UICorner", { CornerRadius = UDim.new(0,4), Parent = optBtn })
                optBtn.MouseEnter:Connect(function()
                    if not SelectedSet[ButtonOpt[i]] then TweenService:Create(optBtn, TweenInfo.new(0.2), { BackgroundColor3 = Color3.fromRGB(28,28,34) }):Play() end
                end)
                optBtn.MouseLeave:Connect(function()
                    if not SelectedSet[ButtonOpt[i]] then TweenService:Create(optBtn, TweenInfo.new(0.2), { BackgroundColor3 = C.Row }):Play() end
                end)
                optBtn.MouseButton1Down:Connect(function()
                    TweenService:Create(optBtn, TweenInfo.new(0.1), { BackgroundColor3 = C.Accent, TextColor3 = Color3.fromRGB(235,235,245) }):Play()
                end)
                optBtn.MouseButton1Click:Connect(function()
                    local cur = ButtonOpt[i]
                    if cur == nil then return end
                    if cur == "All" then
                        if SelectedSet["All"] then SelectedSet = {}
                        else SelectedSet = {}; for _, o in ipairs(Options) do SelectedSet[o] = true end end
                    else
                        SelectedSet["All"] = nil
                        if SelectedSet[cur] then SelectedSet[cur] = nil else SelectedSet[cur] = true end
                    end
                    UpdateLabel(); RefreshList()
                    task.spawn(props.Callback, DropObj.CurrentOption)
                end)
                ButtonPool[i] = optBtn
            else
                optBtn.Text = opt
                optBtn.BackgroundColor3 = isSel and C.Accent or C.Row
                optBtn.TextColor3 = isSel and C.OnAccent or C.Dim
                -- ...and BACK ON. A shorter list hides the surplus rows below, and
                -- nothing ever re-showed them: refresh from a 3-type blueprint to a
                -- 20-type one and rows 4+ were updated but stayed invisible, so most
                -- of the blueprint's types could not be seen or ticked at all.
                optBtn.Visible = true
            end
        end
        for i = #Options + 1, #ButtonPool do ButtonPool[i].Visible = false; ButtonOpt[i] = nil end
        Container.CanvasSize = UDim2.new(0,0,0, #Options * 32)
    end

    Header.MouseButton1Click:Connect(function()
        Open = not Open
        if Open then
            RefreshList()
            TweenService:Create(dropFrame, TweenInfo.new(0.3, Enum.EasingStyle.Quart),
                { Size = UDim2.new(1,0,0, math.min(#Options * 32 + 50, 200)) }):Play()
            TweenService:Create(Arrow, TweenInfo.new(0.3), { Rotation = 180 }):Play()
        else
            TweenService:Create(dropFrame, TweenInfo.new(0.3, Enum.EasingStyle.Quart),
                { Size = UDim2.new(1,0,0,42) }):Play()
            TweenService:Create(Arrow, TweenInfo.new(0.3), { Rotation = 0 }):Play()
        end
    end)

    function DropObj:Refresh(newOptions, defaults)
        Options = newOptions; SelectedSet = {}
        if defaults then
            if type(defaults) == "table" then for _, d in ipairs(defaults) do SelectedSet[d] = true end
            else SelectedSet[defaults] = true end
        end
        UpdateLabel()
        if Open then
            RefreshList()
            TweenService:Create(dropFrame, TweenInfo.new(0.3, Enum.EasingStyle.Quart),
                { Size = UDim2.new(1,0,0, math.min(#Options * 34 + 54, 200)) }):Play()
        end
    end
    return DropObj
end

-- search bars
-- debounced search
local function makeSearchInput(tabObj, getListFn, dropdownRef, stateKey)
    local debounce = nil
    tabObj:CreateInput({ Name = "Search Item", PlaceholderText = "Type to filter...", Callback = function(text)
        if debounce then task.cancel(debounce) end
        debounce = task.delay(0.3, function()
            debounce = nil
            text = text:gsub("^%s*",""):gsub("%s*$","")
            local inv = getListFn()
            local filtered, best = fuzzysearch(inv, text)
            if #filtered == 0 then filtered = {"Empty"} end
            local dd = dropdownRef()
            if dd then
                dd:Refresh(filtered, best or filtered[1])
                if best and stateKey then
                    State[stateKey] = Cache.toInternal(best)
                end
            end
        end)
    end})
end

-- Detailed vending scanner: searchable panel of every vend's item / mode / price /
-- stock across the island, with per-row quick Buy (VendingBuyDirect) and Sell
-- (VendingTrans deposit). Only uses remotes the script already exercises. Defined on
-- Cache; the row/action closures live inside the function (not chunk-level locals).
-- Best-effort shop owner for an island, WITHOUT any network call (kept fast for the
-- scan). Tries the usual attribute/child names; falls back to the island's name. A
-- numeric result (a UserId) is resolved to a username later, at export time. If your
-- game stores the owner under a different field, "Dump Shop Fields" reveals it.
function Cache.islandOwnerRaw(island)
    if not island then return "unknown" end
    -- A GUID UNDER A NAME KEY IS STILL AN ID. `Owner` holds a 36-character GUID in
    -- this game, and taking the first non-empty string meant the export's Owner column
    -- was hex -- while the publisher column two over held the actual player name. Skip
    -- it here and the later keys, or the ObjectValue below, get their turn.
    for _, key in ipairs({"OwnerName","Owner_Name","ownerName","DisplayName","Owner","owner"}) do
        local a = island:GetAttribute(key)
        if type(a) == "string" and a ~= "" and not Cache.looksLikeGuid(a) then return a end
        if type(a) == "number" and a > 0 then return tostring(a) end
    end
    for _, key in ipairs({"OwnerUserId","OwnerId","ownerId","UserId","userId"}) do
        local a = island:GetAttribute(key)
        if type(a) == "number" and a > 0 then return tostring(a) end
        if type(a) == "string" and a ~= "" then return a end
    end
    local ov = island:FindFirstChild("Owner") or island:FindFirstChild("owner")
    if ov then
        if ov:IsA("ObjectValue") and ov.Value then return ov.Value.Name end
        if ov:IsA("StringValue") and ov.Value ~= "" then return ov.Value end
        if (ov:IsA("IntValue") or ov:IsA("NumberValue")) and ov.Value > 0 then return tostring(ov.Value) end
    end
    return island.Name or "unknown"
end

-- The island the player actually OWNS (by owner match), NOT the nearest one.
-- myIslandModel() is proximity-based, so on a shop server it returns the SHOP —
-- which made the Price Book exclude the very vends you were trying to scan
-- ("Saved 0" everywhere you visit). Ownership is stable no matter where you stand.
function Cache.myOwnedIslandModel()
    local islands = Workspace:FindFirstChild("Islands")
    if not islands then return nil end
    local uid = tostring(LocalPlayer.UserId)
    local name = (LocalPlayer.Name or ""):lower()
    local dname = (LocalPlayer.DisplayName or ""):lower()
    for _, isl in ipairs(islands:GetChildren()) do
        local o = tostring(Cache.islandOwnerRaw(isl))
        local ol = o:lower()
        if o == uid or (name ~= "" and ol == name) or (dname ~= "" and ol == dname) then
            return isl
        end
    end
    return nil
end

-- THE island every build operation must read: the one you own. Everything in the
-- build stack (the block index the alignment search runs against, the origin a saved
-- anchor is rebased onto, the streaming check, the block budget) used the
-- proximity-based myIslandModel, which answers "whichever island Base is nearest in
-- X/Z". Stand on an outlying platform — or have a build that floats clear of the
-- island it belongs to — and that resolves to a NEIGHBOUR. The search then indexes
-- the wrong Blocks folder, finds none of your blueprint, declines the snap, and the
-- resume calmly starts a second copy. Ownership doesn't care where you stand.
-- Memoised while the model stays parented; proximity remains the fallback for
-- servers where ownership can't be read (visiting, unowned wilderness).
function Cache.buildIslandModel()
    local m = Cache.BuildIslandMemo
    if m and m.Parent then return m end
    local owned = Cache.myOwnedIslandModel and Cache.myOwnedIslandModel()
    Cache.BuildIslandMemo = owned
    return owned or Cache.myIslandModel()
end

-- THE ISLAND'S CAP, AND WHAT IS ALREADY AGAINST IT. Islands allows 80,000 blocks per
-- island, and the cap is per ISLAND, not per build -- so the only question that
-- matters before generating anything large is how much of it is still free. This
-- lived in the .schem importer, which is not in every tier; the sign and the QR
-- generator need it in tiers that have no importer, and the number is a fact about
-- the game either way. It sits here because Cache.buildIslandModel is what it counts.
Cache.ISLAND_BLOCK_LIMIT = 80000
function Cache.islandBlocksUsed()
    local isl = Cache.buildIslandModel()
    local blocks = isl and isl:FindFirstChild("Blocks")
    if not blocks then return nil end   -- unreadable, not empty: islandBlocksFree maps this to nil
    return #blocks:GetChildren()
end

-- How many blocks are left, or nil when the island cannot be read -- which is a real
-- answer and not zero: "no room" and "cannot tell" must not look the same to a caller.
function Cache.islandBlocksFree()
    local ok, used = pcall(Cache.islandBlocksUsed)
    if not ok or type(used) ~= "number" then return nil end
    return math.max(0, Cache.ISLAND_BLOCK_LIMIT - used), used
end

-- Resolve a UserId string to a username (cached; yields on first lookup). Non-numeric
-- input is returned unchanged, so it's safe to call on any ownerRaw value.
function Cache.resolveOwner(raw)
    local id = tonumber(raw)
    if not id then return raw or "unknown" end
    Cache.OwnerNameCache = Cache.OwnerNameCache or {}
    if Cache.OwnerNameCache[id] then return Cache.OwnerNameCache[id] end
    local ok, name = pcall(function() return Players:GetNameFromUserIdAsync(id) end)
    if ok and type(name) == "string" and name ~= "" then Cache.OwnerNameCache[id] = name; return name end
    return raw
end

-- WHO OWNS AN ISLAND WHOSE OWNER FIELD IS AN ID? Only answerable while the owner is on
-- the server, and only by matching the id against something the player carries: an
-- attribute on the Player holding the island's GUID (or its "<guid>-island" name), or
-- an attribute on the island holding a player's UserId or name. Generic on purpose --
-- which field Islands uses is not known from outside the game, and a guess at one name
-- would be a guess. No network call; nil when nobody here matches.
function Cache.islandOwnerByPlayers(island)
    if not island then return nil end
    local ids = {}
    local n = tostring(island.Name or "")
    ids[n] = true
    local g = n:match("^(.+)%-island$")
    if g then ids[g] = true end
    pcall(function()
        for _, key in ipairs({ "Owner", "owner", "OwnerId", "OwnerGuid", "IslandId" }) do
            local a = island:GetAttribute(key)
            if type(a) == "string" and a ~= "" then ids[a] = true end
        end
    end)
    local islandAttrs = {}
    pcall(function() islandAttrs = island:GetAttributes() end)
    for _, p in ipairs(Players:GetPlayers()) do
        local found = false
        pcall(function()
            for _, v in pairs(p:GetAttributes()) do
                if type(v) == "string" and ids[v] then found = true; break end
            end
        end)
        if not found then
            local uname = tostring(p.Name):lower()
            for _, v in pairs(islandAttrs) do
                if (type(v) == "number" and v == p.UserId)
                    or (type(v) == "string" and v:lower() == uname) then found = true; break end
            end
        end
        if found then return p.Name end
    end
    return nil
end

function Cache.buildVendScanData()
    local data = {}
    local islands = Workspace:FindFirstChild("Islands")
    if not islands then return data end
    for _, island in ipairs(islands:GetChildren()) do
        local blocks = island:FindFirstChild("Blocks")
        if blocks then
            local owner = Cache.islandOwnerRaw(island)  -- once per island, not per vend
            -- an id-keyed shop: learn its name now, while its owner may be here
            -- (090 keeps it; the key itself is left alone so the rows still group)
            if Cache.learnShopName and Cache.looksLikeShopId(tostring(owner))
                and not (Cache.ShopNames and Cache.ShopNames[tostring(owner)]) then
                local nm = Cache.islandOwnerByPlayers(island)
                if nm then Cache.learnShopName(owner, nm) end
            end
            for _, v in ipairs(blocks:GetChildren()) do
                local n = v.Name
                if n == "vendingMachine1" or n == "vendingMachine" or n == "vendingMachineIndustrial" then
                    local mode = v:GetAttribute("mode") or v:GetAttribute("Mode")
                    if mode == nil then local mc = v:FindFirstChild("mode") or v:FindFirstChild("Mode"); if mc then mode = mc.Value end end
                    local price = v:GetAttribute("Price") or v:GetAttribute("TransactionPrice")
                    if price == nil then local pc = v:FindFirstChild("Price") or v:FindFirstChild("TransactionPrice"); if pc then price = pc.Value end end
                    price = tonumber(price)  -- a single string price would crash the scanner's sort
                    local sc = v:FindFirstChild("SellingContents")
                    if sc then
                        for _, it in ipairs(sc:GetChildren()) do
                            local a = it:FindFirstChild("Amount")
                            local stock = (a and a.Value) or 0
                            data[#data + 1] = { vend = v, item = it.Name, mode = mode, price = price or 0, stock = stock, owner = owner }
                        end
                    end
                end
            end
        end
    end
    table.sort(data, function(a, b) return a.price < b.price end)
    return data
end

function Cache.showVendScanner()
    if Cache.VendScanUI then
        pcall(function()
            local f = Cache.VendScanUI:FindFirstChild("MainFrame")
            if f then Cache.VendScanLastPos = f.Position end
            Cache.VendScanUI:Destroy()
        end)
        Cache.VendScanUI = nil
    end
    -- spawn at the right edge, NOT screen-center: centered it sat glued on top of the
    -- main hub window. Reopening restores wherever the user last dragged it.
    local ui, frame = buildFrameBase("IVM_VendScan", UDim2.new(0,380,0,440),
        Cache.VendScanLastPos or UDim2.new(1,-396,0.5,-220))
    frame.Visible = true
    Cache.VendScanUI = ui
    local titleBar = addTitleBar(frame, "Vending Scanner", Color3.fromRGB(35,35,42))
    makedraggable(frame, titleBar)

    local closeBtn = Instance.new("TextButton")
    closeBtn.Size = UDim2.new(0,26,0,26); closeBtn.Position = UDim2.new(1,-32,0,4)
    closeBtn.BackgroundColor3 = Color3.fromRGB(60,32,34); closeBtn.Text = "X"
    closeBtn.TextColor3 = Color3.fromRGB(235,200,200); closeBtn.Font = Enum.Font.GothamBold
    closeBtn.TextSize = 14; closeBtn.ZIndex = 5; closeBtn.Parent = titleBar
    Instance.new("UICorner", closeBtn).CornerRadius = UDim.new(0,6)
    closeBtn.MouseButton1Click:Connect(function()
        if Cache.VendScanUI then
            Cache.VendScanLastPos = frame.Position
            pcall(function() Cache.VendScanUI:Destroy() end)
            Cache.VendScanUI = nil
        end
    end)

    local search = Instance.new("TextBox")
    search.Size = UDim2.new(1,-184,0,26); search.Position = UDim2.new(0,8,0,42)
    search.BackgroundColor3 = Color3.fromRGB(25,25,30); search.BorderSizePixel = 0
    search.TextColor3 = Color3.fromRGB(230,230,230); search.PlaceholderText = "Search item..."
    search.PlaceholderColor3 = Color3.fromRGB(120,120,130); search.Font = Enum.Font.Gotham
    search.TextSize = 13; search.Text = ""; search.ClearTextOnFocus = false; search.Parent = frame
    Instance.new("UICorner", search).CornerRadius = UDim.new(0,6)

    local savePrices = Instance.new("TextButton")
    savePrices.Size = UDim2.new(0,78,0,26); savePrices.Position = UDim2.new(1,-170,0,42)
    savePrices.BackgroundColor3 = Color3.fromRGB(40,60,44); savePrices.Text = "Save Prices"
    savePrices.TextColor3 = Color3.fromRGB(220,235,222); savePrices.Font = Enum.Font.GothamBold
    savePrices.TextSize = 11; savePrices.Parent = frame
    Instance.new("UICorner", savePrices).CornerRadius = UDim.new(0,6)
    savePrices.MouseButton1Click:Connect(function()
        local n = Cache.capturePricesToBook(Cache.VendScanData)
        Window:Notify({Title="Price Book", Content="Saved " .. n .. " item price(s) from this scan.", Duration=3})
    end)

    local rescan = Instance.new("TextButton")
    rescan.Size = UDim2.new(0,78,0,26); rescan.Position = UDim2.new(1,-86,0,42)
    rescan.BackgroundColor3 = Color3.fromRGB(40,44,60); rescan.Text = "Rescan"
    rescan.TextColor3 = Color3.fromRGB(220,220,235); rescan.Font = Enum.Font.GothamBold
    rescan.TextSize = 13; rescan.Parent = frame
    Instance.new("UICorner", rescan).CornerRadius = UDim.new(0,6)

    local list = Instance.new("ScrollingFrame")
    list.Size = UDim2.new(1,-16,1,-84); list.Position = UDim2.new(0,8,0,76)
    list.BackgroundColor3 = Color3.fromRGB(22,22,27); list.BorderSizePixel = 0
    list.ScrollBarThickness = 5; list.ScrollBarImageColor3 = Color3.fromRGB(80,80,90)
    list.CanvasSize = UDim2.new(0,0,0,0); list.Parent = frame
    Instance.new("UICorner", list).CornerRadius = UDim.new(0,6)
    local layout = Instance.new("UIListLayout"); layout.Padding = UDim.new(0,4)
    layout.SortOrder = Enum.SortOrder.LayoutOrder; layout.Parent = list

    local function quickBuy(entry)
        task.spawn(function()
            local v = entry.vend; if not (v and v.Parent) then return end
            -- can only BUY from a SELL-mode vend. Clicking Buy on a [Buy]-mode row used
            -- to fire the remotes anyway: the server no-ops the purchase, the machine
            -- flickers open, and a false "Bought N" toast appeared ("it just glitches").
            local liveMode = v:GetAttribute("mode") or v:GetAttribute("Mode")
            if liveMode == nil then local mc = v:FindFirstChild("mode") or v:FindFirstChild("Mode"); if mc then liveMode = mc.Value end end
            if (liveMode or entry.mode) ~= 0 then
                Window:Notify({Title="Buy", Content="That vend is in BUY mode (it buys FROM players) — you can only buy from Sell vends. Use its row's Sell button to sell to it instead.", Duration=6})
                return
            end
            local sc = v:FindFirstChild("SellingContents"); local it = sc and sc:FindFirstChild(entry.item)
            if not it then Window:Notify({Title="Buy", Content="That item is no longer stocked in this vend.", Duration=3}); return end
            local a = it:FindFirstChild("Amount"); local stock = (a and a.Value) or 0
            local coins = Cache.playerCoins()
            -- re-read the LIVE price: the scan-time price can be minutes old, and a
            -- raised price would make the affordability clamp buy far more than shown
            local livePrice = tonumber(it and v:GetAttribute("Price") or nil) or tonumber(v:GetAttribute("TransactionPrice"))
            if livePrice == nil then
                local pc = v:FindFirstChild("Price") or v:FindFirstChild("TransactionPrice")
                livePrice = pc and tonumber(pc.Value) or nil
            end
            livePrice = livePrice or tonumber(entry.price) or 0
            local amt = stock
            -- only clamp when the balance is actually readable; nil would otherwise
            -- floor every buy to zero and the button would do nothing, silently
            if livePrice > 0 and coins then amt = math.min(amt, math.floor(coins / livePrice)) end
            if amt <= 0 then Window:Notify({Title="Buy", Content="Can't afford or no stock.", Duration=2}); return end
            local guid = HttpService:GenerateGUID(false)
            -- fire VendingOpen ONLY — openVending() also fires VendingEdit, which
            -- requests an owner-level EDIT session. That's right for managing your own
            -- vends but wrong for buying: on a shop vend it desyncs the session (the
            -- buy gets dropped), and CloseSniper never closes an edit session, leaving
            -- the machine stuck "in use" — the visible glitch. The proven sniper buy
            -- path opens without the edit remote; do the same here.
            pcall(function() Remotes.VendingOpen:FireServer(guid, {{vendingMachine = v}}) end)
            task.wait(0.05)
            pcall(function() Remotes.VendingBuyDirect:FireServer(guid, {{ vendingMachine = v,
                player_tracking_category = "join_from_web", tool = it, amount = amt }}) end)
            task.wait(0.05)
            pcall(function() Remotes.VendingCloseSniper:FireServer({vendingMachine = v}) end)
            -- honest feedback: verify by re-reading the coin balance instead of
            -- unconditionally claiming success
            task.wait(0.3)
            local after = Cache.playerCoins()
            if coins and after and after < coins then
                Window:Notify({Title="Buy", Content="Bought " .. amt .. " " .. fixname(entry.item) .. " (spent " .. shortnum(coins - after) .. ")", Duration=3})
            else
                Window:Notify({Title="Buy", Content="Buy request sent for " .. amt .. " " .. fixname(entry.item) .. " — coins unchanged, it may not have gone through.", Duration=4})
            end
        end)
    end
    local function quickSell(entry)
        task.spawn(function()
            local v = entry.vend; if not (v and v.Parent) then return end
            local bp = LocalPlayer:FindFirstChild("Backpack")
            local tool = (bp and bp:FindFirstChild(entry.item))
                or (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(entry.item))
            if not tool then Window:Notify({Title="Sell", Content="You don't hold " .. fixname(entry.item), Duration=2}); return end
            local a = tool:FindFirstChild("Amount") or tool:FindFirstChild("Value")
            local amt = (a and a.Value) or 1
            if amt <= 0 then return end
            local coins = Cache.playerCoins()
            local guid = HttpService:GenerateGUID(false)
            openVending(guid, v); task.wait(0.05)
            pcall(function() Remotes.VendingTrans:FireServer(guid, {{ player_tracking_category = "join_from_web",
                vendingMachine = v, action = "deposit", tool = tool, amount = amt }}) end)
            closeVending(v)
            -- honest feedback, as quickBuy does: a sale shows up as coins, not as a request sent
            task.wait(0.3)
            local after = Cache.playerCoins()
            if coins and after and after > coins then
                Window:Notify({Title="Sell", Content="Sold " .. amt .. " " .. fixname(entry.item) .. " (+" .. shortnum(after - coins) .. ")", Duration=3})
            else
                Window:Notify({Title="Sell", Content="Sell request sent for " .. amt .. " " .. fixname(entry.item) .. " — coins unchanged, it may not have gone through.", Duration=4})
            end
        end)
    end

    local function makeRow(entry)
        local row = Instance.new("Frame")
        row.Size = UDim2.new(1,-6,0,44); row.BackgroundColor3 = Color3.fromRGB(30,30,36)
        row.BorderSizePixel = 0; row.Parent = list
        Instance.new("UICorner", row).CornerRadius = UDim.new(0,6)
        local info = Instance.new("TextLabel")
        info.Size = UDim2.new(1,-110,1,0); info.Position = UDim2.new(0,8,0,0)
        info.BackgroundTransparency = 1; info.Font = Enum.Font.Gotham; info.TextSize = 12
        info.TextXAlignment = Enum.TextXAlignment.Left; info.TextColor3 = Color3.fromRGB(225,225,230)
        info.TextWrapped = true
        local modeStr = entry.mode == 0 and "Sell" or (entry.mode == 1 and "Buy" or "?")
        info.Text = string.format("%s  [%s]\nPrice: %s   Stock: %s", fixname(entry.item), modeStr,
            shortnum(entry.price or 0), shortnum(entry.stock or 0))
        info.Parent = row
        local buyBtn = Instance.new("TextButton")
        buyBtn.Size = UDim2.new(0,46,0,20); buyBtn.Position = UDim2.new(1,-100,0.5,-21)
        buyBtn.BackgroundColor3 = Color3.fromRGB(40,90,60); buyBtn.Text = "Buy"
        buyBtn.TextColor3 = Color3.fromRGB(220,255,230); buyBtn.Font = Enum.Font.GothamBold
        buyBtn.TextSize = 12; buyBtn.Parent = row
        Instance.new("UICorner", buyBtn).CornerRadius = UDim.new(0,5)
        buyBtn.MouseButton1Click:Connect(function() quickBuy(entry) end)
        local sellBtn = Instance.new("TextButton")
        sellBtn.Size = UDim2.new(0,46,0,20); sellBtn.Position = UDim2.new(1,-100,0.5,1)
        sellBtn.BackgroundColor3 = Color3.fromRGB(90,60,40); sellBtn.Text = "Sell"
        sellBtn.TextColor3 = Color3.fromRGB(255,235,220); sellBtn.Font = Enum.Font.GothamBold
        sellBtn.TextSize = 12; sellBtn.Parent = row
        Instance.new("UICorner", sellBtn).CornerRadius = UDim.new(0,5)
        sellBtn.MouseButton1Click:Connect(function() quickSell(entry) end)
    end

    local function render(filter)
        for _, c in ipairs(list:GetChildren()) do if c:IsA("Frame") then c:Destroy() end end
        filter = (filter or ""):lower()
        local data = Cache.VendScanData or {}
        local shown = 0
        for _, e in ipairs(data) do
            if filter == "" or fixname(e.item):lower():find(filter, 1, true) then
                shown += 1
                if shown > 150 then break end
                makeRow(e)
            end
        end
        list.CanvasSize = UDim2.new(0,0,0, shown * 48 + 4)
    end

    local function doScan()
        rescan.Text = "..."
        task.spawn(function()
            Cache.VendScanData = Cache.buildVendScanData()
            render(search.Text)
            rescan.Text = "Rescan"
        end)
    end

    rescan.MouseButton1Click:Connect(doScan)
    search:GetPropertyChangedSignal("Text"):Connect(function() render(search.Text) end)
    doScan()
    return ui
end

-- ==================== COMMAND LINE: THE PARSER (and Mobile Mode's arithmetic) ====================
-- The command line in 231 lets you type "fish on" instead of finding the Fishing tab,
-- scrolling to the switch and clicking it. This half is pure so tests/command.test.lua
-- can prove it: the tokenizer, the fuzzy matcher, and the step that turns a typed line
-- into ONE action (or into "which of these did you mean?"). 231 does the doing.
-- Nothing in here touches the game. In every tier.
--
-- NO FEATURE NAME IS WRITTEN HERE. The switches and sliders a command can reach are
-- handed in at call time from this build's own registries (ToggleFunctions,
-- SliderFunctions), so a tier that cut a feature simply has nothing for "fish on" to
-- match, and says so -- rather than carrying a list of premium names that build.py's
-- FORBIDDEN_STRINGS would (rightly) refuse to ship in the trial.
do
    -- LOWER CASE, LETTERS AND DIGITS ONLY, split into words. "Don't Move My Character
    -- (I'll walk)" is {dont, move, my, character, ill, walk}; apostrophes vanish rather
    -- than split, because "dont" is what anyone types and "don t" is not.
    function Cache.cmdWords(s)
        s = string.lower(tostring(s or ""))
        s = string.gsub(string.gsub(s, "\u{2019}", ""), "'", "")
        local out = {}
        for w in string.gmatch(s, "[%w]+") do out[#out + 1] = w end
        return out
    end

    -- the same thing with the spaces gone, so "auto build" and "autobuild" are one key
    -- (and the same fold 073's overviewKey uses, apart from the apostrophe)
    function Cache.cmdFold(s)
        return table.concat(Cache.cmdWords(s))
    end

    -- THE TOKENIZER keeps what the matcher throws away: a number keeps its sign and its
    -- decimal point ("set flight speed -1.5" must not become "1" and "5"), and a
    -- "quoted name" stays one token so a name that ends in a word like "on" can be said
    -- exactly. Everything else is whitespace-separated and lower-cased.
    function Cache.cmdTokenize(line)
        line = tostring(line or "")
        local toks, i, n = {}, 1, #line
        while i <= n do
            local c = string.sub(line, i, i)
            if string.match(c, "%s") then
                i += 1
            elseif c == '"' then
                local j = string.find(line, '"', i + 1, true) or (n + 1)
                toks[#toks + 1] = { text = string.lower(string.sub(line, i + 1, j - 1)), quoted = true }
                i = j + 1
            else
                local j = string.find(line, "%s", i) or (n + 1)
                toks[#toks + 1] = { text = string.lower(string.sub(line, i, j - 1)) }
                i = j
            end
        end
        return toks
    end

    -- THE SCORE, in fixed tiers so an ordering between them is a rule and not a sum:
    --   400 exact            the whole name, ignoring case, spaces and punctuation
    --   300 prefix           "auto build" -> "Auto Build Blueprint"
    --   250 whole words      every typed word IS a word of the name, in order: "fish"
    --                        -> "Auto Fish"
    --   200 word prefixes    every typed word STARTS a word of the name, in order:
    --                        "harv" -> "Auto Harvest"
    --   100 substring        anywhere in the folded name
    --     0 no match
    -- Whole words sit above word prefixes because "fish" should mean "Auto Fish" and not
    -- a switch with "fishing" in it: the typed word being a word of the name is better
    -- evidence than it being the start of one. That is a sub-rank of the word tier, not
    -- a fifth rule -- the order exact > prefix > word > substring still holds.
    function Cache.cmdScore(query, name)
        local qw = type(query) == "table" and query or Cache.cmdWords(query)
        local qf = table.concat(qw)
        if qf == "" then return 0 end
        local nw = Cache.cmdWords(name)
        local nf = table.concat(nw)
        if nf == qf then return 400 end
        if string.sub(nf, 1, #qf) == qf then return 300 end
        local j, whole = 1, true
        for _, q in ipairs(qw) do
            local found = false
            while j <= #nw do
                local w = nw[j]; j += 1
                if w == q then found = true; break end
                if string.sub(w, 1, #q) == q then found = true; whole = false; break end
            end
            if not found then whole = nil; break end
        end
        if whole ~= nil then return whole and 250 or 200 end
        if string.find(nf, qf, 1, true) then return 100 end
        return 0
    end

    -- THE SEARCH BOX'S MATCH (020's sidebar search, and 'find' below). Looser than a
    -- command's on purpose: a command acts, so "farm on" must not guess, but a search
    -- only SHOWS -- and a row shown that you did not want costs nothing, where a row
    -- hidden that you did makes you think the feature is gone. So on top of cmdScore:
    --   150 every typed word starts a word of the name, in ANY order: "speed build"
    --       finds 'Build Speed'
    --    50 every typed word of three letters or more is somewhere in the folded name
    -- The old box matched the typed text as one substring, so "build speed" found it
    -- and "speed build" or "autobuild" found nothing at all.
    function Cache.searchScore(query, name)
        local qw = type(query) == "table" and query or Cache.cmdWords(query)
        if #qw == 0 or name == nil then return 0 end
        local s = Cache.cmdScore(qw, name)
        -- cmdScore's substring tier takes any piece of a word; for a box that filters
        -- as you type, a two-letter piece ("ee") would light up half the hub
        if s > 100 or (s == 100 and #table.concat(qw) >= 3) then return s end
        local nw = Cache.cmdWords(name)
        local all = true
        for _, q in ipairs(qw) do
            local found = false
            for _, w in ipairs(nw) do
                if string.sub(w, 1, #q) == q then found = true; break end
            end
            if not found then all = false; break end
        end
        if all then return 150 end
        local nf = table.concat(nw)
        for _, q in ipairs(qw) do
            if #q < 3 or not string.find(nf, q, 1, true) then return 0 end
        end
        return 50
    end

    -- WHAT ONE TAB SHOWS FOR A SEARCH. rows: the tab's rows in their order, each
    -- { kind = "Section" | "Note" | anything else (a control), name = text or nil }.
    -- Returns { show = { [i] = bool }, count = controls shown, score = the tab's rank }.
    --   * a section whose heading matches shows whole, notes and all
    --   * a control that matches shows, and brings its section heading with it
    --   * a note is prose: never a match on its own, shown only with a whole section
    --   * a row with no name (a divider) shows only inside a whole section
    -- 020 walks the instances, hands their kinds and names here, and sets Visible.
    function Cache.searchPlan(query, rows, scoreFn)
        scoreFn = scoreFn or Cache.searchScore
        local show, count, total = {}, 0, 0
        local head, members = nil, {}
        local function flush()
            local hs = head and rows[head].name and scoreFn(query, rows[head].name) or 0
            local any = false
            for _, i in ipairs(members) do
                local r = rows[i]
                local control = r.kind ~= "Note" and r.name ~= nil
                local rs = control and scoreFn(query, r.name) or 0
                show[i] = hs > 0 or rs > 0
                if show[i] and control then count += 1; total += math.max(rs, 1) end
                if rs > 0 then any = true end
            end
            if head then
                show[head] = hs > 0 or any
                total += hs
            end
        end
        for i, r in ipairs(rows or {}) do
            if r.kind == "Section" then
                flush(); head, members = i, {}
            else
                members[#members + 1] = i
            end
        end
        flush()
        return { show = show, count = count, score = total }
    end

    -- PICK ONE NAME, OR SAY WHY NOT. Returns
    --   { ok = name }                                    one clear best
    --   { ambiguous = {names...}, score = s }            a tie at the top tier
    --   { none = true }                                  nothing matched at all
    -- A TIE IS NEVER BROKEN BY GUESSING. "farm on" with three farms is a question
    -- back to you, because the cost of the wrong guess is a farm running that you did
    -- not ask for. `prefer` (optional) narrows the field first: for on/off the command
    -- line prefers switches that RUN something (073's filter), so "harvest toggle"
    -- means Auto Harvest and not a reach modifier that merely starts with "harvest".
    -- The narrowing only applies when the preferred field has a word-level match or
    -- better, and an EXACT name always wins from the whole field -- so every switch
    -- stays reachable by typing its name.
    function Cache.cmdPick(query, names, prefer)
        local qw = type(query) == "table" and query or Cache.cmdWords(query)
        local all, exact = {}, {}
        for _, name in ipairs(names or {}) do
            local s = Cache.cmdScore(qw, name)
            if s > 0 then
                all[#all + 1] = { name = name, s = s }
                if s == 400 then exact[#exact + 1] = name end
            end
        end
        if #exact == 1 then return { ok = exact[1] } end
        local pool = all
        if prefer and #exact == 0 then
            local pref, best = {}, 0
            for _, e in ipairs(all) do
                if prefer(e.name) then pref[#pref + 1] = e; if e.s > best then best = e.s end end
            end
            if best >= 200 then pool = pref end
        end
        local best = 0
        for _, e in ipairs(pool) do if e.s > best then best = e.s end end
        if best == 0 then return { none = true } end
        local top = {}
        for _, e in ipairs(pool) do if e.s == best then top[#top + 1] = e.name end end
        table.sort(top)
        if #top == 1 then return { ok = top[1] } end
        return { ambiguous = top, score = best }
    end

    -- the words that say what to do with a switch, wherever they stand in the line
    local MODES = {
        on = "on", enable = "on", start = "on", ["true"] = "on", ["1"] = "on",
        off = "off", disable = "off", stop = "off", ["false"] = "off", ["0"] = "off",
        toggle = "toggle", flip = "toggle", switch = "toggle",
    }
    Cache.CmdModes = MODES

    local function joinTexts(toks, a, b)
        local t = {}
        for i = a, b do t[#t + 1] = toks[i].text end
        return table.concat(t, " ")
    end

    -- ONE LINE -> ONE ACTION. `ctx` = { toggles = {names}, sliders = {names},
    -- prefer = function(name) -> bool }. The result is a plain table with `kind`:
    --   empty | help | panic | status | stopall | restock | pause | resume
    --   find    { query }  -- show the matching controls in the hub
    --   toggle  { name, mode = "on"|"off"|"toggle" }
    --   set     { name, value }
    --   ambiguous { what = "switch"|"slider", query, candidates, mode?/value? }
    --   unknown   { what = "switch"|"slider"|"command", query, hint? }
    --   bad       { msg }  -- understood, but malformed ("set x" with no number)
    -- The fixed words are checked before any name matching, so a switch that happens
    -- to be called "Status" can never swallow the status command.
    function Cache.cmdResolve(line, ctx)
        ctx = ctx or {}
        local toks = Cache.cmdTokenize(line)
        local n = #toks
        if n == 0 then return { kind = "empty" } end
        local w1 = toks[1].text
        local w2 = n >= 2 and toks[2].text or nil
        local rest = joinTexts(toks, 1, n)
        local folded = Cache.cmdFold(rest)
        -- ALIASES FIRST, by their exact folded name, so "night" runs the alias called
        -- night before any switch called Night-something could claim it -- and the
        -- alias commands themselves before any name matching, like the fixed words.
        local al = Cache.cmdAliasParse(line)
        if al then return al end
        local aliases = ctx.aliases
        if aliases and aliases[folded] and not ctx.inAlias then
            return { kind = "alias-run", name = folded, lines = aliases[folded] }
        end
        if folded == "help" or rest == "?" or folded == "commands" then return { kind = "help" } end
        if folded == "panic" then return { kind = "panic" } end
        if folded == "status" or folded == "running" or folded == "whatsrunning" then return { kind = "status" } end
        if folded == "stopall" or folded == "alloff" or folded == "stopeverything" then return { kind = "stopall" } end
        if folded == "restock" or folded == "restocknow" then return { kind = "restock" } end
        if folded == "pause" or folded == "pausebuild" then return { kind = "pause" } end
        if folded == "resume" or folded == "resumebuild" or folded == "unpause" or folded == "unpausebuild" then
            return { kind = "resume" }
        end
        -- find <words>: open the hub with its search box showing what matches
        if (w1 == "find" or w1 == "search" or w1 == "where" or w1 == "goto") and n >= 2 then
            return { kind = "find", query = joinTexts(toks, 2, n) }
        end

        -- set <slider> [to|=] <number>
        if w1 == "set" then
            -- "set flight speed=60" and "set flight speed = 60" are the same line
            toks = Cache.cmdTokenize((string.gsub(tostring(line), "=", " = ")))
            n = #toks
            local v = tonumber(toks[n].text)
            if v == nil or v ~= v then
                return { kind = "bad", msg = "Give a number at the end, e.g. set flight speed 60." }
            end
            local stop = n - 1
            while stop >= 2 and (toks[stop].text == "to" or toks[stop].text == "=") do stop -= 1 end
            if stop < 2 then return { kind = "bad", msg = "Name a slider, e.g. set flight speed 60." } end
            local q = joinTexts(toks, 2, stop)
            local pick = Cache.cmdPick(q, ctx.sliders)
            if pick.ok then return { kind = "set", name = pick.ok, value = v } end
            if pick.ambiguous then
                return { kind = "ambiguous", what = "slider", query = q, candidates = pick.ambiguous, value = v }
            end
            return { kind = "unknown", what = "slider", query = q }
        end

        -- <name> on|off|toggle, or on|off|toggle <name> (also "turn on <name>")
        local mode, a, b = nil, 1, n
        if not toks[n].quoted and MODES[toks[n].text] and n >= 2 then
            mode, b = MODES[toks[n].text], n - 1
        elseif w1 == "turn" and w2 and MODES[w2] and n >= 3 then
            mode, a = MODES[w2], 3
        elseif not toks[1].quoted and MODES[w1] and n >= 2 then
            mode, a = MODES[w1], 2
        end
        if mode then
            local q = joinTexts(toks, a, b)
            local pick = Cache.cmdPick(q, ctx.toggles, ctx.prefer)
            if pick.ok then return { kind = "toggle", name = pick.ok, mode = mode } end
            if pick.ambiguous then
                return { kind = "ambiguous", what = "switch", query = q, candidates = pick.ambiguous, mode = mode }
            end
            return { kind = "unknown", what = "switch", query = q }
        end

        -- A BARE NAME IS NOT A COMMAND. It could mean on, off or flip, and flipping a
        -- farm you meant to check on is exactly the wrong guess -- so it says how.
        local pick = Cache.cmdPick(rest, ctx.toggles, ctx.prefer)
        if pick.ok then
            return { kind = "unknown", what = "command", query = rest, hint = pick.ok }
        end
        return { kind = "unknown", what = "command", query = rest }
    end

    -- "A, B, C and 4 more": an ambiguous answer names what it can without a wall of text
    function Cache.cmdListNames(names, max)
        max = max or 6
        local shown = {}
        for i = 1, math.min(#names, max) do shown[i] = names[i] end
        local s = table.concat(shown, ", ")
        if #names > max then s = s .. string.format(" and %d more", #names - max) end
        return s
    end

    -- ALIASES: one word for a routine of presses. "alias night = auto harvest on, loop
    -- restock on" keeps the two commands under "night"; typing "night" runs them in
    -- order. The grammar, pure, so tests/command.test.lua can pin it:
    --   alias                      -> { kind = "alias-list" }
    --   alias NAME = A, B; C       -> { kind = "alias-set", name, lines = {A, B, C} }
    --   alias NAME: A, B           -> the same (a colon is a sign too)
    --   alias NAME                 -> { kind = "alias-show", name }
    --   alias NAME =  /  unalias NAME -> { kind = "alias-del", name }
    -- A name is letters, digits, _ and -, at most 24 long, never one of the fixed
    -- words (an alias called "panic" would shadow the real one). The body is split on
    -- commas and semicolons, at most 12 lines, each non-empty. An alias may name
    -- another alias, whose lines then run as plain commands: that is one level deep
    -- (cmdResolve's inAlias is set by 231 at the second level), so an alias that
    -- names itself, or two that name each other, cannot loop.
    -- Returns nil for a line that is not about aliases; { kind = "bad", msg } for one
    -- that is but is malformed.
    Cache.CMD_FIXED = { help = true, commands = true, panic = true, status = true, running = true,
        whatsrunning = true, stopall = true, alloff = true, stopeverything = true, restock = true,
        restocknow = true, pause = true, pausebuild = true, resume = true, resumebuild = true,
        unpause = true, unpausebuild = true, alias = true, aliases = true, unalias = true,
        set = true, find = true, search = true, where = true, goto = true, turn = true,
        on = true, off = true, toggle = true, flip = true }
    function Cache.cmdAliasParse(line)
        line = tostring(line or "")
        local head, rest = string.match(line, "^%s*(%a+)%s*(.-)%s*$")
        if not head then return nil end
        head = string.lower(head)
        if head ~= "alias" and head ~= "aliases" and head ~= "unalias" then return nil end
        if head == "aliases" or (head == "alias" and rest == "") then return { kind = "alias-list" } end
        local name, sep, body = string.match(rest, "^([^=:%s]+)%s*([=:]?)%s*(.-)%s*$")
        if not name or name == "" then
            return { kind = "bad", msg = "Name the alias, e.g. alias night = auto harvest on, loop restock on." }
        end
        name = string.lower(name)
        if #name > 24 or not string.match(name, "^[%w_%-]+$") then
            return { kind = "bad", msg = "An alias name is letters, digits, _ or -, up to 24 long: " .. name }
        end
        if Cache.CMD_FIXED[Cache.cmdFold(name)] then
            return { kind = "bad", msg = "\u{201C}" .. name .. "\u{201D} is a command of its own and cannot be an alias." }
        end
        -- FOLDED ONCE, HERE, so parse, store, load and run all hold the same key:
        -- "build-night" is typed back as build-night, buildnight or Build Night, and
        -- the resolver looks it up by the folded line. Stored unfolded, the alias ran
        -- only after a reload (231 folds on load) and alias-show never found it.
        name = Cache.cmdFold(name)
        if head == "unalias" then return { kind = "alias-del", name = name } end
        if sep == "" then
            if body ~= "" then
                return { kind = "bad", msg = "Put = between the name and the commands: alias " .. name .. " = " .. body }
            end
            return { kind = "alias-show", name = name }
        end
        if body == "" then return { kind = "alias-del", name = name } end
        local lines = {}
        for piece in string.gmatch(body, "[^,;]+") do
            piece = string.match(piece, "^%s*(.-)%s*$")
            if piece ~= "" then lines[#lines + 1] = piece end
        end
        if #lines == 0 then return { kind = "alias-del", name = name } end
        if #lines > 12 then return { kind = "bad", msg = "An alias holds at most 12 commands; this one has " .. #lines .. "." } end
        return { kind = "alias-set", name = name, lines = lines }
    end

    -- "night = auto harvest on, loop restock on" -- one alias, the way it is listed
    function Cache.cmdAliasLine(name, lines)
        return tostring(name) .. " = " .. table.concat(lines or {}, ", ")
    end

    function Cache.cmdHelpText()
        return table.concat({
            "<switch> on | off | toggle   (e.g. auto farm on, tree aura toggle)",
            "alias NAME = A, B   keep commands under one word; type NAME to run them (alias lists them, unalias NAME forgets one)",
            "stop all   every automation off; settings such as Anti AFK stay",
            "panic   every switch off",
            "status   what is running",
            "set <slider> <number>   (e.g. set flight speed 60)",
            "restock   refill your vends now",
            "pause build / resume build",
            "find <words>   open the hub at every control that matches (e.g. find repair)",
            "Names can be partial; if more than one fits you are shown the choices.",
        }, "\n")
    end

    -- HISTORY: the last `max` distinct lines, walked with up and down like a shell.
    -- `pos` past the end means "not browsing": up from there is the newest line, and
    -- down off the end hands back an empty box rather than sticking on the newest.
    function Cache.cmdHistoryNew(max)
        return { items = {}, pos = 1, max = max or 20 }
    end
    function Cache.cmdHistoryPush(h, line)
        line = tostring(line or "")
        if string.match(line, "^%s*$") then h.pos = #h.items + 1; return h end
        if h.items[#h.items] ~= line then table.insert(h.items, line) end
        while #h.items > h.max do table.remove(h.items, 1) end
        h.pos = #h.items + 1
        return h
    end
    -- dir -1 = older (up arrow), +1 = newer (down arrow); returns the text to show
    function Cache.cmdHistoryStep(h, dir)
        local n = #h.items
        if n == 0 then return nil end
        if dir < 0 then
            h.pos = math.max(1, h.pos - 1)
            return h.items[h.pos]
        end
        h.pos = math.min(n + 1, h.pos + 1)
        return h.items[h.pos] or ""
    end

    -- ==== MOBILE MODE'S ARITHMETIC (232 applies it) ====
    -- The library's own fit (Airflow `_fitToScreen`) only ever SHRINKS: it scales a
    -- 720x470 window down until it fits, so on a 390-point-tall phone every control
    -- comes out at ~0.78 of its size -- the opposite of what a thumb needs. Mobile Mode
    -- instead shrinks the WINDOW (its offset size, down to the library's own resize
    -- minimum of 480x320) so the content does not have to shrink, and then lets the
    -- scale go up to `want` (the Mobile UI Scale slider) where the screen has room.
    -- Returns width, height, scale and whether the sidebar should narrow.
    Cache.MobileBase = { w = 720, h = 470, minW = 480, minH = 320, margin = 24, floor = 0.45 }
    function Cache.mobileWindowLayout(sx, sy, want)
        local B = Cache.MobileBase
        want = math.clamp(tonumber(want) or 1, 0.6, 1.6)
        sx, sy = tonumber(sx) or 0, tonumber(sy) or 0
        if sx <= 0 or sy <= 0 then return B.w, B.h, 1, false end
        local availX, availY = math.max(sx - B.margin, 1), math.max(sy - B.margin, 1)
        -- the scale first: as much as was asked for, but no more than lets the
        -- SMALLEST window fit -- then the window grows back into whatever room that
        -- scale leaves, so a height-bound phone still gets the full width
        local s = math.max(B.floor, math.min(want, availX / B.minW, availY / B.minH))
        local w = math.floor(math.clamp(availX / s, B.minW, B.w))
        local h = math.floor(math.clamp(availY / s, B.minH, B.h))
        local scale = math.max(B.floor, math.min(s, availX / w, availY / h))
        -- the 190-pixel sidebar is a third of a 480-wide window; below 600 it narrows
        return w, h, scale, w < 600
    end

    -- A FLOATING PANEL (Required Blocks, What's Running, the previews...) is built for
    -- a desktop: 340-380 wide and 400-470 tall, which on a phone covers the game. It
    -- starts scaled to fit in 60% of the width and below the menu pill, and docked to
    -- the right edge, cascading so two panels opened together do not sit exactly on top
    -- of each other. The owner can still drag it anywhere afterwards.
    function Cache.mobilePanelPlacement(sx, sy, w, h, index)
        sx, sy = tonumber(sx) or 0, tonumber(sy) or 0
        w, h = math.max(tonumber(w) or 1, 1), math.max(tonumber(h) or 1, 1)
        local top = 64
        local s = math.clamp(math.min(1, (sy - top - 8) / h, (sx * 0.6) / w), 0.5, 1)
        local step = ((tonumber(index) or 0) % 5) * 28
        local x = math.max(8, sx - w * s - 8 - step)
        local y = top + step
        if y + h * s > sy - 8 then y = math.max(8, sy - 8 - h * s) end
        return s, math.floor(x), math.floor(y)
    end
end
-- ==== end of COMMAND LINE: THE PARSER =======================================
-- ==== BLUEPRINT EXTRAS: upgrades and machine contents (pure) ================
-- A blueprint used to be block types and positions and nothing else, so a max-upgraded
-- farm saved and rebuilt came back as a level-0 farm, and a gold-block farm came back
-- with empty machines. This part is the pure half of carrying that across:
--
--   * what a placed block holds beyond its type -- `extra` on the blueprint entry:
--       attrs    = every attribute whose value is a number, string or bool
--       values   = ValueBase children, one level deep, plus those inside a child
--                  "Config"/"Configuration" folder (keyed "Config/<name>")
--       contents = child items that look like stored items: { name, amount }
--     It is GENERIC on purpose: nobody here has read a copper farm's or a mold
--     machine's instance tree, so nothing is keyed on a guessed name. Whatever the
--     block really carries is what gets saved, and the apply side acts only on the
--     two shapes it understands (a "<Path>Level" number, and a stored item stack).
--   * the plan: saved vs what stands now -> an ordered list of actions, with the
--     inventory checked before anything is sent.
--   * the recorder's classifiers: turn one call you made by hand into a template
--     that can be replayed against a different block.
--
-- `extra` is OPTIONAL on every entry. An old blueprint has none, an old reader never
-- looks for it, and the engines only ever read blockType and cframe -- so a file
-- written with extras loads and builds exactly as before in any version.
--
-- 189_bp_extras_ui.lua is the half that touches the game. Everything here is loadable
-- by tests/bp_extras.test.lua.
do
    local BPX = {
        MAX_ATTRS = 24,       -- per block; a totem has three paths, a machine a handful
        MAX_VALUES = 24,
        MAX_CONTENTS = 16,    -- stacks per block
        MAX_STR = 80,         -- a string attribute longer than this is not a level or a name
        MAX_LEVEL = 1000,     -- a saved level above this is corrupt, not ambition
        MAX_EXTRAS = 20000,   -- per blueprint file: a whole-island save must stay loadable
    }
    Cache.BPX = BPX

    local VALUE_CLASSES = { "IntValue", "NumberValue", "StringValue", "BoolValue" }
    local CONFIG_NAMES = { "Config", "Configuration", "config", "configuration" }
    -- the chest withdraw's folder list (033's Cache.ChestContentFolders) plus the names
    -- a machine slot is likely to use. A folder that is not there costs one lookup.
    local CONTENT_FOLDERS = { "Contents", "Items", "Storage", "Content", "Inventory",
        "Slot", "Slots", "Input", "Inputs", "Mold", "Molds" }
    -- STORAGE IS NOT A MACHINE. A chest wall's contents are your savings, not part of
    -- the build: "applying" a saved chest would try to move thousands of items out of
    -- your inventory into it. Such blocks keep their attrs but never record contents.
    local STORAGE_WORDS = { "chest", "vending", "crate", "barrel", "storage", "silo", "cauldron" }
    -- stems that end in "Level" but name a cap or a requirement, not a path you buy
    local NOT_A_PATH = { max = true, min = true, base = true, required = true, unlock = true, cap = true }

    local function isStorage(name)
        local l = tostring(name or ""):lower()
        for _, w in ipairs(STORAGE_WORDS) do
            if l:find(w, 1, true) then return true end
        end
        return false
    end
    Cache.bpxIsStorage = isStorage

    -- JSON-safe primitive or nil. NaN and infinities are refused: JSONEncode turns
    -- them into something the decoder then chokes on, and one bad attribute must not
    -- make a whole blueprint file unreadable.
    local function prim(v)
        local t = type(v)
        if t == "boolean" then return v end
        if t == "number" then
            if v ~= v or v == math.huge or v == -math.huge then return nil end
            return v
        end
        if t == "string" then
            if #v > BPX.MAX_STR then return nil end
            return v
        end
        return nil
    end

    local function sortedKeys(t)
        local ks = {}
        for k in pairs(t) do if type(k) == "string" then ks[#ks + 1] = k end end
        table.sort(ks)
        return ks
    end

    local function copyMap(src, cap)
        local out, n = {}, 0
        if type(src) ~= "table" then return out, 0 end
        for _, k in ipairs(sortedKeys(src)) do
            local v = prim(src[k])
            if v ~= nil and #k <= BPX.MAX_STR then
                if n >= cap then break end
                out[k] = v; n += 1
            end
        end
        return out, n
    end

    -- The one gate every extra goes through, on save AND on load: a hand-edited or
    -- truncated file cannot put a table where a number belongs and crash the apply.
    -- Returns nil when nothing is left, which is how "skip blocks with nothing" works.
    -- ==== BLUEPRINT MERGE ==========================================================
    -- Two blueprints into one file at an offset: the house AND its sign AND the fence
    -- as one queue entry, one share code, one library card. Positions are the twelve
    -- numbers each file already stores, relative to its own origin; b's are moved by
    -- offset (studs, a multiple of 3 keeps the lattice) and the two lists are joined.
    -- Where a cell is in both, rule decides: "later" (b wins), "first" (a wins) or
    -- "refuse" (nil and the count, nothing written). The result is re-based so its
    -- lowest cell sits at 1.5 on every axis -- the corner Save Selection and Block Fill
    -- use -- shifted by a multiple of 3, so a block on the lattice stays on it.
    -- Returns blocks, { a, b, overlaps, total } or nil, info.
    -- ON THE CELL, NOT ON ITS EDGE. Cells sit at 1.5 + 3k (the corner this function
    -- re-bases onto), so c/3 + 0.5 is k + 1 exactly -- the rounding boundary itself --
    -- and float noise in a scanned file (4.49997) sent a block to the neighbour's key:
    -- a false overlap that dropped a real block, or a real one missed. (c - 1.5)/3 is
    -- k exactly, and rounding it is safe from noise either way.
    local function cellKey(c)
        return string.format("%d,%d,%d", math.floor((c[1] - 1.5) / 3 + 0.5),
            math.floor((c[2] - 1.5) / 3 + 0.5), math.floor((c[3] - 1.5) / 3 + 0.5))
    end
    function Cache.bpMerge(a, b, offset, rule)
        rule = rule or "later"
        offset = offset or { 0, 0, 0 }
        local out, at, info = {}, {}, { a = 0, b = 0, overlaps = 0, total = 0 }
        for _, bd in ipairs(a or {}) do
            if type(bd) == "table" and type(bd.cframe) == "table" and bd.cframe[1] then
                local copy = { blockType = bd.blockType, cframe = table.clone(bd.cframe) }
                for k, v in pairs(bd) do if k ~= "blockType" and k ~= "cframe" then copy[k] = v end end
                out[#out + 1] = copy
                at[cellKey(copy.cframe)] = #out
                info.a += 1
            end
        end
        for _, bd in ipairs(b or {}) do
            if type(bd) == "table" and type(bd.cframe) == "table" and bd.cframe[1] then
                local copy = { blockType = bd.blockType, cframe = table.clone(bd.cframe) }
                for k, v in pairs(bd) do if k ~= "blockType" and k ~= "cframe" then copy[k] = v end end
                copy.cframe[1] += offset[1] or 0; copy.cframe[2] += offset[2] or 0; copy.cframe[3] += offset[3] or 0
                info.b += 1
                local key = cellKey(copy.cframe)
                local idx = at[key]
                if idx then
                    info.overlaps += 1
                    if rule == "refuse" then return nil, info end
                    if rule == "later" then out[idx] = copy end
                else
                    out[#out + 1] = copy
                    at[key] = #out
                end
            end
        end
        -- re-base to the low corner, by whole cells
        if #out > 0 then
            local mn = { math.huge, math.huge, math.huge }
            for _, bd in ipairs(out) do for i = 1, 3 do if bd.cframe[i] < mn[i] then mn[i] = bd.cframe[i] end end end
            local shift = {}
            for i = 1, 3 do shift[i] = math.floor((1.5 - mn[i]) / 3 + 0.5) * 3 end
            for _, bd in ipairs(out) do for i = 1, 3 do bd.cframe[i] += shift[i] end end
        end
        info.total = #out
        return out, info
    end

    -- "10,0,-4" (blocks) -> { 30, 0, -12 } (studs), or nil and why
    function Cache.bpMergeOffset(text)
        local parts = {}
        for n in tostring(text or ""):gmatch("[^,%s]+") do parts[#parts + 1] = tonumber(n) end
        if #parts == 0 then return { 0, 0, 0 } end
        if #parts ~= 3 then return nil, "write three numbers, x,y,z in blocks (e.g. 10,0,-4), or leave it empty" end
        for i = 1, 3 do
            if parts[i] ~= parts[i] or parts[i] ~= math.floor(parts[i]) then return nil, "whole blocks only" end
        end
        return { parts[1] * 3, parts[2] * 3, parts[3] * 3 }
    end

    function Cache.bpxSanitizeExtra(raw)
        if type(raw) ~= "table" then return nil end
        local attrs, na = copyMap(raw.attrs, BPX.MAX_ATTRS)
        local values, nv = copyMap(raw.values, BPX.MAX_VALUES)
        local contents = {}
        if type(raw.contents) == "table" then
            for _, c in ipairs(raw.contents) do
                if #contents >= BPX.MAX_CONTENTS then break end
                if type(c) == "table" and type(c.name) == "string" and c.name ~= ""
                    and #c.name <= BPX.MAX_STR then
                    local a = tonumber(c.amount) or 1
                    a = math.floor(a)
                    if a > 0 and a == a and a < 1e9 then
                        contents[#contents + 1] = { name = c.name, amount = a }
                    end
                end
            end
        end
        if na == 0 and nv == 0 and #contents == 0 then return nil end
        local out = {}
        if na > 0 then out.attrs = attrs end
        if nv > 0 then out.values = values end
        if #contents > 0 then out.contents = contents end
        return out
    end

    local function isValue(obj)
        for _, c in ipairs(VALUE_CLASSES) do
            if obj:IsA(c) then return true end
        end
        return false
    end

    local function stackAmount(item)
        local a = item:FindFirstChild("Amount") or item:FindFirstChild("Value")
        if a and (a:IsA("IntValue") or a:IsA("NumberValue")) then return a.Value, true end
        local at = item:GetAttribute("Amount")
        if type(at) == "number" then return at, true end
        return 1, false
    end

    -- Read one placed block. Duck-typed (GetAttributes, GetChildren, IsA) so the tests
    -- can hand it a stub; every read is pcall'd because a block can be destroyed under
    -- a whole-island save and one dead instance must not abort the file.
    function Cache.bpxCaptureExtra(block)
        if not block then return nil end
        local raw = { attrs = {}, values = {}, contents = {} }
        pcall(function()
            for k, v in pairs(block:GetAttributes()) do raw.attrs[k] = v end
        end)
        pcall(function()
            for _, ch in ipairs(block:GetChildren()) do
                if isValue(ch) then
                    raw.values[ch.Name] = ch.Value
                end
            end
            for _, cn in ipairs(CONFIG_NAMES) do
                local cfg = block:FindFirstChild(cn)
                if cfg then
                    for _, ch in ipairs(cfg:GetChildren()) do
                        if isValue(ch) then raw.values["Config/" .. ch.Name] = ch.Value end
                    end
                    -- attributes on the folder count too: the totem reader in 168 looks
                    -- for a level on a Configuration child, and a folder is as likely a
                    -- home for an attribute as for a value object
                    pcall(function()
                        for k, v in pairs(cfg:GetAttributes()) do raw.values["Config/" .. k] = v end
                    end)
                    break
                end
            end
        end)
        if not isStorage(block.Name) then
            pcall(function()
                for _, fn in ipairs(CONTENT_FOLDERS) do
                    local f = block:FindFirstChild(fn)
                    if f then
                        for _, it in ipairs(f:GetChildren()) do
                            -- an item stack carries an Amount; a bare part or a script
                            -- inside the folder does not, and is not an item
                            local a, isStack = stackAmount(it)
                            if isStack then raw.contents[#raw.contents + 1] = { name = it.Name, amount = a } end
                        end
                    end
                end
            end)
        end
        return Cache.bpxSanitizeExtra(raw)
    end

    -- THE SAVE PATHS' ONE ENTRY POINT (210's Save Selection and Save Island). Adds
    -- `extra` to a blueprint entry when the block carries anything, and stops adding
    -- once a file holds BPX.MAX_EXTRAS of them -- the blocks still save, only their
    -- extras stop, so a whole-island save can never become unloadable because of this.
    -- `budget` is one table per save ({ n = 0 }). Returns the entry either way.
    function Cache.bpxAttach(entry, block, budget)
        if type(entry) ~= "table" then return entry end
        budget = budget or {}
        budget.n = budget.n or 0
        if budget.n >= BPX.MAX_EXTRAS then budget.capped = true; return entry end
        local ok, ex = pcall(Cache.bpxCaptureExtra, block)
        if ok and ex then
            entry.extra = ex
            budget.n += 1
        end
        return entry
    end

    -- "QualityLevel" / "qualityLevel" / "Config/QualityLevel" -> "quality".
    -- The Totem Upgrader (168) reads "<Path>Level" with the path capitalised and fires
    -- UpgradeBlock with the lowercase path, so the lowercase stem is the name the
    -- server knows. A bare "Level" has no path and is not acted on: there is no known
    -- call that raises "the" level of a block.
    function Cache.bpxLevelPath(key)
        if type(key) ~= "string" then return nil end
        local leaf = key:match("[^/]+$") or key
        local stem = leaf:match("^(%a+)Level$")
        if not stem or stem == "" then return nil end
        stem = stem:sub(1, 1):lower() .. stem:sub(2)
        if NOT_A_PATH[stem:lower()] then return nil end
        return stem
    end

    local function levelNumber(v)
        if type(v) == "string" then v = tonumber(v) end
        if type(v) ~= "number" or v ~= v then return nil end
        v = math.floor(v)
        if v < 0 or v > BPX.MAX_LEVEL then return nil end
        return v
    end

    -- path -> level. An attribute wins over a value object of the same path, the same
    -- precedence 168's getTotemPathLevel uses.
    function Cache.bpxLevels(extra)
        local out = {}
        if type(extra) ~= "table" then return out end
        -- attrs last = attrs win. Indexed by hand, not ipairs over { values, attrs }:
        -- with no values that list starts with a nil and ipairs sees nothing at all.
        local srcs = { extra.values or false, extra.attrs or false }
        for i = 1, 2 do
            local src = srcs[i]
            if type(src) == "table" then
                for _, k in ipairs(sortedKeys(src)) do
                    local p = Cache.bpxLevelPath(k)
                    local lv = p and levelNumber(src[k])
                    if lv then out[p] = lv end
                end
            end
        end
        return out
    end

    -- 168's classification, repeated: it is a local inside that part's do-block, and
    -- this must fire the SAME second argument the Totem Upgrader fires or the server
    -- refuses it (coal fired as totem_crop was rejected every time -- see 168).
    local ORE_WORDS = { "iron", "gold", "rock", "ore", "coal", "copper", "emerald", "ruby",
        "diamond", "obsidian", "crystal", "stone" }
    function Cache.bpxTotemType(name)
        local l = tostring(name or ""):lower()
        if not l:find("totem", 1, true) then return nil end
        for _, w in ipairs(ORE_WORDS) do
            if l:find(w, 1, true) then return "totem_rock" end
        end
        return "totem_crop"
    end

    local function aggregate(list)
        local m = {}
        for _, c in ipairs(list or {}) do m[c.name] = (m[c.name] or 0) + (c.amount or 1) end
        return m
    end

    -- THE PLAN. entries[i] = { key, blockType, saved = extra, current = extra|nil,
    -- found = bool }. inv = item -> count you are carrying. opts.canUpgrade(blockType)
    -- says whether any known call can raise that block's levels (the totem call, or a
    -- recorded one); levels on a block it says no to are reported, never sent.
    --
    -- Order: every level first, then every insert. Upgrades are what the owner asked
    -- for first, and they spend coins/materials rather than the items an insert needs,
    -- so doing them first cannot starve an insert of anything it counted on.
    -- Contents are allocated from the inventory in that order and an insert is cut
    -- down to what you actually carry; the shortfall is reported, not attempted.
    function Cache.bpxPlan(entries, inv, opts)
        opts = opts or {}
        local canUpgrade = opts.canUpgrade or function() return false end
        local plan = {
            actions = {}, withExtras = 0, missingBlocks = 0, missingByType = {},
            upToDate = 0, perType = {}, need = {}, short = {}, noCall = {},
            levelSteps = 0, insertCount = 0,
        }
        local levels, inserts = {}, {}
        local function pt(bt)
            local r = plan.perType[bt]
            if not r then r = { blocks = 0, levels = 0, items = {} }; plan.perType[bt] = r end
            return r
        end
        for _, e in ipairs(entries or {}) do
            local saved = Cache.bpxSanitizeExtra(e.saved)
            if not saved then continue end
            plan.withExtras += 1
            local bt = tostring(e.blockType or "?")
            if not e.found then
                plan.missingBlocks += 1
                plan.missingByType[bt] = (plan.missingByType[bt] or 0) + 1
                continue
            end
            local did = false
            local sL, cL = Cache.bpxLevels(saved), Cache.bpxLevels(e.current)
            for _, path in ipairs(sortedKeys(sL)) do
                local to, from = sL[path], cL[path] or 0
                if from < to then
                    did = true
                    if canUpgrade(bt, path) then
                        levels[#levels + 1] = { kind = "level", key = e.key, blockType = bt,
                            path = path, from = from, to = to }
                        pt(bt).levels += to - from
                        plan.levelSteps += to - from
                    else
                        plan.noCall[bt] = (plan.noCall[bt] or 0) + (to - from)
                    end
                end
            end
            local sC, cC = aggregate(saved.contents), aggregate(e.current and e.current.contents)
            local names = {}
            for n in pairs(sC) do names[#names + 1] = n end
            table.sort(names)
            for _, n in ipairs(names) do
                local want = sC[n] - (cC[n] or 0)
                if want > 0 then
                    did = true
                    plan.need[n] = (plan.need[n] or 0) + want
                    inserts[#inserts + 1] = { kind = "insert", key = e.key, blockType = bt,
                        item = n, want = want }
                end
            end
            if did then pt(bt).blocks += 1 else plan.upToDate += 1 end
        end
        for _, a in ipairs(levels) do plan.actions[#plan.actions + 1] = a end
        local left = {}
        for k, v in pairs(inv or {}) do left[k] = v end
        for _, a in ipairs(inserts) do
            local have = left[a.item] or 0
            local give = math.min(have, a.want)
            left[a.item] = have - give
            if give < a.want then plan.short[a.item] = (plan.short[a.item] or 0) + (a.want - give) end
            if give > 0 then
                a.amount = give
                plan.actions[#plan.actions + 1] = a
                plan.insertCount += 1
                local it = pt(a.blockType).items
                it[a.item] = (it[a.item] or 0) + give
            end
        end
        return plan
    end

    local function sortedPairs(m)
        local ks = {}
        for k in pairs(m) do ks[#ks + 1] = k end
        table.sort(ks)
        return ks
    end

    -- The preview's text. label(name) prettifies an internal name (fixname in the
    -- script, identity in tests). Says outright that nothing is free: the upgrade
    -- call is the one a hand makes, and the server charges it the same.
    function Cache.bpxReportLines(plan, opts)
        opts = opts or {}
        local label = opts.label or function(s) return s end
        local L = {}
        L[#L + 1] = opts.title or "UPGRADES & CONTENTS"
        L[#L + 1] = "The game charges for every upgrade and insert exactly as it would by hand. Nothing here is free."
        if plan.withExtras == 0 then
            L[#L + 1] = "This blueprint has no saved upgrades or contents. Save it again (after this update) to record them."
            return L
        end
        L[#L + 1] = string.format("%d block(s) carry saved extras: %d already match, %d not standing yet.",
            plan.withExtras, plan.upToDate, plan.missingBlocks)
        L[#L + 1] = string.format("Would send: %d upgrade level(s), %d insert(s).", plan.levelSteps, plan.insertCount)
        local types = sortedPairs(plan.perType)
        if #types > 0 then L[#L + 1] = "" ; L[#L + 1] = "PER BLOCK TYPE" end
        for _, bt in ipairs(types) do
            local r = plan.perType[bt]
            local items = {}
            for _, n in ipairs(sortedPairs(r.items)) do items[#items + 1] = label(n) .. " x" .. r.items[n] end
            L[#L + 1] = string.format("  %s: %d block(s), %d level(s)%s", label(bt), r.blocks, r.levels,
                #items > 0 and (", items " .. table.concat(items, ", ")) or "")
        end
        local short = sortedPairs(plan.short)
        if #short > 0 then
            L[#L + 1] = ""; L[#L + 1] = "MISSING FROM YOUR INVENTORY (these inserts are skipped)"
            for _, n in ipairs(short) do L[#L + 1] = string.format("  %s x%d", label(n), plan.short[n]) end
        end
        local nc = sortedPairs(plan.noCall)
        if #nc > 0 then
            L[#L + 1] = ""; L[#L + 1] = "LEVELS SAVED BUT NO KNOWN UPGRADE CALL (not sent; record one by hand)"
            for _, bt in ipairs(nc) do L[#L + 1] = string.format("  %s: %d level(s)", label(bt), plan.noCall[bt]) end
        end
        local mb = sortedPairs(plan.missingByType)
        if #mb > 0 then
            L[#L + 1] = ""; L[#L + 1] = "NOT STANDING YET (build first)"
            for _, bt in ipairs(mb) do L[#L + 1] = string.format("  %s x%d", label(bt), plan.missingByType[bt]) end
        end
        return L
    end

    -- ---- the recorder: one call made by hand -> a replayable template ------------
    -- The spy (200) snapshots arguments with Instances as { __inst = "<full path>" }.
    -- A call is recognised by SHAPE, the way classifyBlockPlace and classifyMobHit do:
    -- which leaf is the block, which is the item, which is the number. Everything else
    -- is kept verbatim, so a token the server wants rides along without being
    -- understood. Slot positions are key paths (e.g. {1, "chest"}), so JSON keeps them.
    local function walk(v, path, visit)
        if type(v) ~= "table" then visit(path, v); return end
        if type(v.__inst) == "string" then visit(path, v); return end
        local ks = {}
        for k in pairs(v) do ks[#ks + 1] = k end
        table.sort(ks, function(a, b) return tostring(a) < tostring(b) end)
        for _, k in ipairs(ks) do
            local p = {}
            for i, x in ipairs(path) do p[i] = x end
            p[#p + 1] = k
            walk(v[k], p, visit)
        end
    end

    local function isBlockPath(s)
        return s:find("%.Blocks%.") ~= nil or s:find("%.Entities%.") ~= nil
    end
    local function isToolPath(s, playerName)
        if s:find("^Players%.[^%.]+%.Backpack%.[^%.]+$") then return true end
        if playerName then
            local esc = playerName:gsub("%p", "%%%0")
            if s:find("^Workspace%." .. esc .. "%.[^%.]+$") then return true end
        end
        return false
    end

    -- An insert: one block leaf, one leaf that is an item you carry, and (optionally)
    -- a number under a key that reads like an amount. The chest deposit this script
    -- already knows (033: { chest, tool, amount, action = "deposit" }) has exactly this
    -- shape, so if a machine takes items the same way, a recording finds it.
    function Cache.bpxClassifyInsert(entry, playerName)
        if type(entry) ~= "table" or type(entry.args) ~= "table" or type(entry.path) ~= "string" then return nil end
        local machine, tool, amount, itemName
        walk(entry.args, {}, function(path, v)
            if type(v) == "table" and type(v.__inst) == "string" then
                if not machine and isBlockPath(v.__inst) then machine = path
                elseif not tool and isToolPath(v.__inst, playerName) then
                    tool = path; itemName = v.__inst:match("([^%.]+)$")
                end
            elseif type(v) == "number" and not amount then
                local k = path[#path]
                if type(k) == "string" then
                    local l = k:lower()
                    if l:find("amount") or l:find("count") or l:find("quantity") or l == "qty" then amount = path end
                end
            end
        end)
        if not (machine and tool) then return nil end
        return { kind = "insert", path = entry.path, method = entry.method, args = entry.args,
            nargs = entry.nargs, machine = machine, tool = tool, amount = amount, item = itemName }
    end

    -- An upgrade: one block leaf and one string equal to the path that went up (the
    -- caller works that out by watching which "<Path>Level" changed). Other strings --
    -- 168's "totem_rock"/"totem_crop" is one -- are kept verbatim, which is why a
    -- template is only replayed on the block TYPE it was recorded on.
    function Cache.bpxClassifyUpgrade(entry, pathStem, blockType)
        if type(entry) ~= "table" or type(entry.args) ~= "table" or type(entry.path) ~= "string" then return nil end
        if type(pathStem) ~= "string" then return nil end
        local machine, pathSlot
        local want = pathStem:lower()
        walk(entry.args, {}, function(path, v)
            if type(v) == "table" and type(v.__inst) == "string" then
                if not machine and isBlockPath(v.__inst) then machine = path end
            elseif type(v) == "string" and not pathSlot and v:lower() == want then
                pathSlot = path
            end
        end)
        if not (machine and pathSlot) then return nil end
        return { kind = "upgrade", path = entry.path, method = entry.method, args = entry.args,
            nargs = entry.nargs, machine = machine, pathSlot = pathSlot, blockType = blockType }
    end

    function Cache.bpxDeepCopy(v)
        if type(v) ~= "table" then return v end
        local o = {}
        for k, x in pairs(v) do o[k] = Cache.bpxDeepCopy(x) end
        return o
    end

    -- set a value at a key path, creating tables on the way; false on a bad path
    function Cache.bpxSetPath(t, path, value)
        if type(t) ~= "table" or type(path) ~= "table" or #path == 0 then return false end
        local node = t
        for i = 1, #path - 1 do
            local k = path[i]
            if type(node[k]) ~= "table" then node[k] = {} end
            node = node[k]
        end
        node[path[#path]] = value
        return true
    end

    -- A template -> the argument list for one replay. `rehydrate` turns the other
    -- {__inst} leaves back into live instances (200's Cache._rehydrate in the game,
    -- identity in tests); the slots are then overwritten with this replay's values.
    function Cache.bpxFillArgs(tpl, fills, rehydrate)
        local args = Cache.bpxDeepCopy(tpl.args)
        if rehydrate then args = rehydrate(args) end
        for slot, value in pairs(fills or {}) do
            local p = tpl[slot]
            if type(p) == "table" then Cache.bpxSetPath(args, p, value) end
        end
        return args
    end
end
-- ==== end of BLUEPRINT EXTRAS (pure) ========================================
-- ==================== MATERIALS CHECK BEFORE BUILD ====================
-- "You're short 2,300 stone" -- said BEFORE you go AFK, not discovered at 3am when the
-- build has sat at 80% for five hours. The Materials Checker (185) and the queue's
-- (074/206) already sum what is left to place; what they compare it against is
-- countInventory, which is the hotbar and the held tool and nothing else. This adds the
-- other place a builder keeps blocks that the client CAN see -- the chests on your own
-- island -- and then says, per type, how much of each need was actually seen.
--
-- WHAT IT CANNOT SEE, AND SAYS SO. The island inventory proper (the inventory screen)
-- is server-side; nothing on the client lists it. So "short" here can only ever mean
-- "not seen", and a report that said "you're short 2,300 stone" to someone with 5,000
-- stone in their inventory screen is how a tool teaches people to ignore it. Every
-- shortfall is worded as what was not seen, with the inventory named as the place it
-- may still be. The one case that is PROBABLY real: the type is on your hotbar with a
-- count below the need and in none of your chests -- a hotbar slot shows the stack you
-- hold, so a low number there is the best evidence the client ever gets. Still hedged.
--
-- The need itself is not computed here: the caller hands in a type -> count map that
-- came through Cache.queueMaterials (074), so the removal / replacement / blacklist /
-- dirt->grass order is the builder's own and is not written a third time.
--
-- Pure (the counts are handed in), so tests/materials_precheck.test.lua drives every
-- rule. The buttons and the Auto Build hook are 195_materials_precheck_ui.lua.
do
    -- the exact words the owner asked for; the tests pin them
    Cache.PRECHECK_UNSEEN = "not seen in hotbar or chests; you may still have it in your inventory"

    -- 2300 -> "2,300". Not shortnum ("2.3K"): a shortfall is a number you go and farm,
    -- and a rounded one is off by up to fifty blocks.
    function Cache.precheckCommas(n)
        n = math.floor(tonumber(n) or 0)
        local s = tostring(math.abs(n))
        local out = s:reverse():gsub("(%d%d%d)", "%1,"):reverse()
        if out:sub(1, 1) == "," then out = out:sub(2) end
        return (n < 0 and "-" or "") .. out
    end

    -- The LOADED blueprint's switches, in the shape of one blockmods.json entry, so the
    -- loaded build goes through the same Cache.queueEntryMods -> queueMaterials path as
    -- every queued one. State keeps removals as a set; the file keeps a list.
    function Cache.precheckModsFromState(replaceEnabled, replacements, removeEnabled, removals)
        local list = {}
        if type(removals) == "table" then
            for k, v in pairs(removals) do
                if v and type(k) == "string" then list[#list + 1] = k end
            end
            table.sort(list)
        end
        return {
            replaceEnabled = replaceEnabled and true or false,
            replacements = type(replacements) == "table" and replacements or {},
            removeEnabled = removeEnabled and true or false,
            removals = list,
        }
    end

    -- chests: a list of { stacks = { {item=, amount=}, ... } } -- what the caller read
    -- out of each of YOUR chests. Returns item -> total, and how many chests had any.
    function Cache.precheckChestCounts(chests)
        local counts, withItems = {}, 0
        for _, c in ipairs(chests or {}) do
            local any = false
            for _, s in ipairs((type(c) == "table" and c.stacks) or {}) do
                local item, amt = s.item, tonumber(s.amount) or 1
                if type(item) == "string" and amt > 0 then
                    counts[item] = (counts[item] or 0) + amt
                    any = true
                end
            end
            if any then withItems += 1 end
        end
        return counts, withItems
    end

    -- status order, most worth reading first
    local RANK = { likely = 1, partial = 2, unseen = 3, ok = 4 }

    -- need: type -> blocks still to place. hotbar, chest: item -> count seen.
    -- Each row: bt, need, hotbar, chest, seen, short (need minus what was seen, never
    -- below 0) and status:
    --   ok      -- hotbar + chests cover it
    --   likely  -- on the hotbar with fewer than needed, in no chest: probably real
    --   partial -- some in chests (maybe the hotbar too) but not enough seen
    --   unseen  -- in neither: may be in the inventory screen, which nothing can read
    function Cache.precheckMaterials(need, hotbar, chest)
        hotbar, chest = hotbar or {}, chest or {}
        local rows, total = {}, 0
        local counts = { ok = 0, likely = 0, partial = 0, unseen = 0 }
        local shortSeen, shortLikely = 0, 0
        for bt, n in pairs(need or {}) do
            n = tonumber(n) or 0
            if n > 0 then
                local h = math.max(0, tonumber(hotbar[bt]) or 0)
                local c = math.max(0, tonumber(chest[bt]) or 0)
                local seen = h + c
                local short = math.max(0, n - seen)
                local status
                if short == 0 then status = "ok"
                elseif c > 0 then status = "partial"
                elseif h > 0 then status = "likely"
                else status = "unseen" end
                counts[status] += 1
                shortSeen += short
                if status == "likely" then shortLikely += short end
                total += n
                rows[#rows + 1] = { bt = bt, need = n, hotbar = h, chest = c, seen = seen,
                                    short = short, status = status }
            end
        end
        table.sort(rows, function(a, b)
            if a.status ~= b.status then return RANK[a.status] < RANK[b.status] end
            if a.short ~= b.short then return a.short > b.short end
            if a.need ~= b.need then return a.need > b.need end
            return tostring(a.bt) < tostring(b.bt)
        end)
        return { rows = rows, total = total, types = #rows, counts = counts,
                 shortSeen = shortSeen, shortLikely = shortLikely,
                 allSeen = (counts.likely + counts.partial + counts.unseen) == 0 }
    end

    -- one row, in words. label turns an internal name into a readable one.
    function Cache.precheckRowLine(row, label)
        label = label or tostring
        local C = Cache.precheckCommas
        local name = label(row.bt)
        if row.status == "ok" then
            return string.format("%s — need %s: covered (hotbar %s, chests %s)",
                name, C(row.need), C(row.hotbar), C(row.chest))
        elseif row.status == "likely" then
            return string.format("%s — need %s, hotbar %s, chests 0: likely short %s (the hotbar stack is lower than the need and none is in your chests — but you may still have more in your inventory)",
                name, C(row.need), C(row.hotbar), C(row.short))
        elseif row.status == "partial" then
            return string.format("%s — need %s, hotbar %s, chests %s: short %s by what we can see; you may still have the rest in your inventory",
                name, C(row.need), C(row.hotbar), C(row.chest), C(row.short))
        end
        return string.format("%s — need %s: %s", name, C(row.need), Cache.PRECHECK_UNSEEN)
    end

    -- the whole report: the Required Blocks panel's text and precheck.txt.
    -- info.title: what was checked; info.chestsRead: false when your island could not
    -- be found (then the chest column is empty for a reason the report must name);
    -- info.chests: how many of your chests were read; info.notes: extra lines.
    function Cache.precheckReport(r, label, info)
        info = info or {}
        local C = Cache.precheckCommas
        local out = {}
        local function add(s) out[#out + 1] = s end
        add(string.format("%s — %s block(s) still to place, %d type(s)",
            info.title or "MATERIALS CHECK", C(r.total), r.types))
        if r.types == 0 then
            add("Nothing left to place.")
        elseif r.allSeen then
            add("Everything needed was seen in your hotbar and chests.")
        else
            if r.counts.likely > 0 then
                add(string.format("LIKELY SHORT — %d type(s), %s block(s) (on your hotbar with too few, in no chest)",
                    r.counts.likely, C(r.shortLikely)))
            end
            if r.counts.partial > 0 then
                add(string.format("NOT ENOUGH SEEN — %d type(s) (some in chests, not enough)", r.counts.partial))
            end
            if r.counts.unseen > 0 then
                add(string.format("NOT SEEN — %d type(s): %s", r.counts.unseen, Cache.PRECHECK_UNSEEN))
            end
        end
        add("(Seen = your hotbar and held item, plus the chests on your own island. The island inventory is server-side and cannot be read, so \"short\" means not seen — not proven missing.)")
        if info.chestsRead == false then
            add("Chests were NOT counted: your own island could not be found on this server.")
        elseif info.chests then
            add(string.format("Chests read: %d on your island.", info.chests))
        end
        for _, n in ipairs(info.notes or {}) do add(n) end
        add("")
        add("PER TYPE (need / hotbar / chests)")
        for _, row in ipairs(r.rows) do add("  " .. Cache.precheckRowLine(row, label)) end
        return table.concat(out, "\n")
    end

    -- ==== BUY MISSING MATERIALS ======================================================
    -- The check says what is short; the Price Book says who sells it; the sniper knows
    -- how to buy from a vend. This is the join, in two shapes, both pure:
    --
    -- buyHerePlan: the vends in RANGE (someone else's shop you are standing in) against
    -- the shortfall. need { [type] = blocks short }; vends { { v, item, mode, price,
    -- stock, mine } }; coins the pocket; opts { maxUnit = coins a block may cost at
    -- most (nil = any), budget = coins to spend at most (nil = all) }. Cheapest vend
    -- first per type, never your own vend, never more than it holds, never more than
    -- the coins allow. Returns { buys = { { v, item, amount, unit, cost } }, rows =
    -- { { bt, short, bought, left, unit, why } }, totalCost, coinsLeft, sellers }.
    --
    -- buyTourPlan: every scanned SELL listing against the shortfall -- per type the
    -- cheapest shop with stock, grouped into one stop per shop, dearest stop first so
    -- the tour's first leg is the one that matters. A listing's stock is from the scan
    -- that saw it, so an amount is what the shop HAD, and the stop's buy on arrival
    -- is what it has. Returns { stops = { { owner, islandOwner, items = { { item,
    -- amount, unit, cost, stock } }, cost } }, totalCost, unpriced = { types }, types }.
    function Cache.buyHerePlan(need, vends, coins, opts)
        opts = opts or {}
        local maxUnit = tonumber(opts.maxUnit)
        local left = tonumber(opts.budget)
        coins = math.max(0, math.floor(tonumber(coins) or 0))
        if not left or left > coins then left = coins end
        local r = { buys = {}, rows = {}, totalCost = 0, coinsLeft = left, sellers = 0 }
        local byItem = {}
        for _, v in ipairs(vends or {}) do
            if not v.mine and v.mode ~= 1 and v.item and (tonumber(v.price) or 0) > 0 and (tonumber(v.stock) or 0) > 0 then
                byItem[v.item] = byItem[v.item] or {}
                table.insert(byItem[v.item], v)
                r.sellers += 1
            end
        end
        local types = {}
        for bt, n in pairs(need or {}) do if math.floor(tonumber(n) or 0) > 0 then types[#types + 1] = bt end end
        table.sort(types)
        for _, bt in ipairs(types) do
            local short = math.floor(tonumber(need[bt]))
            local row = { bt = bt, short = short, bought = 0, left = short, unit = nil }
            local list = byItem[bt]
            if not list then
                row.why = "no vend here sells it"
            else
                table.sort(list, function(a, b)
                    if a.price ~= b.price then return a.price < b.price end
                    return (b.stock or 0) < (a.stock or 0)
                end)
                for _, v in ipairs(list) do
                    if row.left <= 0 then break end
                    local price = tonumber(v.price)
                    if maxUnit and price > maxUnit then
                        row.why = row.why or string.format("cheapest here is %d, over your %d a block", price, maxUnit)
                    else
                        local can = math.min(row.left, math.floor(tonumber(v.stock) or 0), math.floor(r.coinsLeft / price))
                        if can > 0 then
                            r.buys[#r.buys + 1] = { v = v.v, item = bt, amount = can, unit = price, cost = can * price }
                            row.bought += can; row.left -= can
                            row.unit = row.unit or price
                            r.totalCost += can * price
                            r.coinsLeft -= can * price
                        elseif r.coinsLeft < price then
                            row.why = row.why or "out of coins"
                        end
                    end
                end
                if row.left > 0 and not row.why then
                    row.why = (r.coinsLeft < list[1].price) and "out of coins" or "the vends here ran out"
                end
            end
            r.rows[#r.rows + 1] = row
        end
        return r
    end

    function Cache.buyTourPlan(need, listings, opts)
        opts = opts or {}
        local now = tonumber(opts.now)
        local maxAge = tonumber(opts.maxAge) or 2 * 86400
        local exclude = opts.exclude or {}
        local maxUnit = tonumber(opts.maxUnit)
        -- EVERY SELLER PER TYPE, cheapest first: when the cheapest shop had 10 and the
        -- build is short 500, the next shop is asked for the rest rather than the 490
        -- vanishing from the plan. What no shop had is listed as short, by type.
        local sellers = {}
        for _, e in pairs(listings or {}) do
            local p = type(e) == "table" and tonumber(e.price)
            if p and p > 0 and tonumber(e.mode) == 0 and type(e.item) == "string" and not exclude[tostring(e.owner)]
               and (not maxUnit or p <= maxUnit) then
                local at = tonumber(e.at)
                local age = (now and at and at > 0) and math.max(0, now - at) or nil
                local stock = tonumber(e.stock)
                if not (age and age > maxAge) and not (stock and stock <= 0) then
                    sellers[e.item] = sellers[e.item] or {}
                    table.insert(sellers[e.item], { owner = tostring(e.owner or "unknown"), islandOwner = e.islandOwner,
                                                    unit = p, stock = stock, age = age })
                end
            end
        end
        local r = { stops = {}, totalCost = 0, unpriced = {}, short = {}, types = 0, covered = 0 }
        local byOwner = {}
        local types = {}
        for bt, n in pairs(need or {}) do if math.floor(tonumber(n) or 0) > 0 then types[#types + 1] = bt end end
        table.sort(types)
        for _, bt in ipairs(types) do
            r.types += 1
            local list = sellers[bt]
            if not list then
                r.unpriced[#r.unpriced + 1] = bt
            else
                table.sort(list, function(a, b)
                    if a.unit ~= b.unit then return a.unit < b.unit end
                    if (a.stock or math.huge) ~= (b.stock or math.huge) then return (a.stock or math.huge) > (b.stock or math.huge) end
                    return a.owner < b.owner
                end)
                local left = math.floor(tonumber(need[bt]))
                for _, b in ipairs(list) do
                    if left <= 0 then break end
                    local amount = b.stock and math.min(left, b.stock) or left
                    local stop = byOwner[b.owner]
                    if not stop then
                        stop = { owner = b.owner, islandOwner = b.islandOwner, items = {}, cost = 0 }
                        byOwner[b.owner] = stop
                        r.stops[#r.stops + 1] = stop
                    end
                    stop.items[#stop.items + 1] = { item = bt, amount = amount, unit = b.unit, cost = amount * b.unit, stock = b.stock, age = b.age }
                    stop.cost += amount * b.unit
                    r.totalCost += amount * b.unit
                    left -= amount
                end
                if left > 0 then r.short[#r.short + 1] = { item = bt, amount = left } else r.covered += 1 end
            end
        end
        table.sort(r.stops, function(a, b)
            if a.cost ~= b.cost then return a.cost > b.cost end
            return a.owner < b.owner
        end)
        return r
    end

    -- words. label(bt), money(n), shop(stop) -> text
    function Cache.buyHereLines(r, label, money)
        label = label or tostring; money = money or tostring
        local out = {}
        out[#out + 1] = string.format("BUY HERE — %d buy%s, %s coins, %s left in the pocket after",
            #r.buys, #r.buys == 1 and "" or "s", money(r.totalCost), money(r.coinsLeft))
        if r.sellers == 0 then out[#out + 1] = "No vend of anyone else's is selling anything in range. Stand in a shop." end
        for _, row in ipairs(r.rows) do
            out[#out + 1] = string.format("  %s — short %s: %s%s",
                label(row.bt), money(row.short),
                row.bought > 0 and string.format("buy %s at %s each", money(row.bought), money(row.unit)) or "nothing here",
                row.left > 0 and string.format(", %s still short (%s)", money(row.left), row.why or "?") or "")
        end
        return out
    end
    function Cache.buyTourLines(r, label, money, shop)
        label = label or tostring; money = money or tostring; shop = shop or function(s) return tostring(s.owner) end
        local out = {}
        out[#out + 1] = string.format("SHOPPING TOUR — %d stop%s, %s coins; %d of %d type%s fully covered",
            #r.stops, #r.stops == 1 and "" or "s", money(r.totalCost), r.covered or 0, r.types, r.types == 1 and "" or "s")
        out[#out + 1] = "(Amounts are what each shop HAD when it was scanned; the buy on arrival takes what it has.)"
        for i, s in ipairs(r.stops) do
            out[#out + 1] = string.format("%d. %s — %s coins", i, shop(s), money(s.cost))
            for _, it in ipairs(s.items) do
                out[#out + 1] = string.format("     %s x%s at %s each%s", label(it.item), money(it.amount), money(it.unit),
                    it.stock and string.format(" (had %s)", money(it.stock)) or "")
            end
        end
        if #(r.short or {}) > 0 then
            local names = {}
            for i = 1, math.min(8, #r.short) do names[i] = label(r.short[i].item) .. " x" .. money(r.short[i].amount) end
            out[#out + 1] = "Still short after every shop scanned had: " .. table.concat(names, ", ") .. (#r.short > 8 and ", …" or "")
        end
        if #r.unpriced > 0 then
            local names = {}
            for i = 1, math.min(8, #r.unpriced) do names[i] = label(r.unpriced[i]) end
            out[#out + 1] = "Nobody scanned sells (under your line per block): " .. table.concat(names, ", ") .. (#r.unpriced > 8 and ", …" or "")
        end
        return out
    end

    -- the notification: one headline and the few rows worth reading, hedged.
    -- Returns title, content.
    function Cache.precheckSummary(r, label, limit)
        label = label or tostring
        limit = limit or 3
        local C = Cache.precheckCommas
        if r.types == 0 then return "Materials Check", "Nothing left to place." end
        if r.allSeen then
            return "Materials Check — All Seen", string.format(
                "Your hotbar and chests cover all %s block(s) still to place.", C(r.total))
        end
        local parts, shown = {}, 0
        for _, row in ipairs(r.rows) do
            if row.status == "ok" or shown >= limit then break end
            shown += 1
            if row.status == "likely" then
                parts[#parts + 1] = string.format("Likely short %s %s (hotbar has %s, none in chests; you may still have more in your inventory).",
                    C(row.short), label(row.bt), C(row.hotbar))
            elseif row.status == "partial" then
                parts[#parts + 1] = string.format("%s: short %s by what we can see; you may still have the rest in your inventory.",
                    label(row.bt), C(row.short))
            else
                parts[#parts + 1] = string.format("%s x%s: %s.", label(row.bt), C(row.need), Cache.PRECHECK_UNSEEN)
            end
        end
        local notOk = r.counts.likely + r.counts.partial + r.counts.unseen
        if notOk > shown then
            parts[#parts + 1] = string.format("And %d more type(s).", notOk - shown)
        end
        local title = r.counts.likely > 0
            and string.format("Materials — likely short on %d type(s)", r.counts.likely)
            or string.format("Materials — %d type(s) not fully seen", notOk)
        return title, table.concat(parts, " ")
    end
end
-- end of MATERIALS CHECK BEFORE BUILD -----------------------------------------
-- ==================== AUTO REJOIN PLAN ====================
-- The pure half of 'Auto Rejoin If Kicked' (the switch, the listeners and the
-- teleport are in 228_auto_rejoin.lua, on the Build tab). Split off for the reason
-- 039/063/064 are: a part with UI at file level cannot be loaded by
-- tests/run_tests.py, and the decisions are what is worth proving -- which kick
-- messages mean "come back" and which mean "stop now", how long to wait between
-- attempts, and when to give up. tests/rejoin.test.lua pins all three.
--
-- One do-block, everything on Cache: this part takes no register.
do
    -- HOW MANY REJOINS AN HOUR, AND HOW HARD EACH ONE TRIES. A kick every few minutes
    -- is not bad luck, it is a server (or a rule) saying no, and a loop that rejoins
    -- forever turns one kick into a hundred. Three per rolling hour covers a server
    -- restart plus a flaky connection; the fourth is refused and the user is told.
    -- One rejoin is up to six teleport attempts on a doubling wait (5s .. 2min),
    -- about four and a half minutes in all -- inside the Resume Helper's fifteen.
    Cache.REJOIN_MAX_PER_HOUR = 3
    Cache.REJOIN_MAX_ATTEMPTS = 6
    Cache.REJOIN_BASE_SECS = 5
    Cache.REJOIN_MAX_WAIT = 120

    -- WHAT A KICK MESSAGE MEANS. Stop words win over everything: a message that says
    -- "disconnected" AND "exploit" is an exploit kick. Rejoining after a ban or a
    -- detection is the one thing this feature must never do -- it looks exactly like
    -- the behaviour that got the kick, and a second kick is rarely the last. So the
    -- list leans wide: "admin" and "moderat" stop it too, because a person chose to
    -- remove you and coming straight back is not ours to decide. "another device" /
    -- "same account" stop it as well: rejoining would fight your own other session.
    -- Matched on word starts (%f), so "urban" is not "ban" and "shacked" not "hack".
    Cache.KickStopWords = {
        "ban%f[%W]", "banned", "exploit", "cheat", "hack", "detect", "anti%-?cheat", "anti cheat",
        "suspicious", "unexpected client behavior", "unexpected client behaviour",
        "moderat", "terms of", "violat", "blacklist", "flagged", "admin",
        "another device", "different device", "same account",
    }
    -- Roblox's own disconnect codes (Enum.ConnectionError), best knowledge, NOT
    -- verified in game: 264/273 same account elsewhere, 268 unexpected client
    -- behaviour (Roblox's own detection), 281/282 security policy / blocked IP, 600 a
    -- ban. 267 is "kicked by the experience" -- meaning lives in its text, so it is
    -- read like any other message. 768-799 are teleport errors: a teleport that did not
    -- leave, which is not a disconnect (and our own retries handle their own).
    Cache.KickStopCodes = { [264] = true, [268] = true, [273] = true, [281] = true, [282] = true, [600] = true }

    -- Returns kind, reason. kind is "stop" (never rejoin), "teleport" (a teleport
    -- failed: you are still connected, so there is nothing to rejoin) or "rejoin" (a disconnect, a timeout, a shutdown, idle -- or a
    -- message we do not recognise, because "Lost connection" is worded differently in
    -- every language and a silent disconnect has no message at all).
    function Cache.classifyKick(msg, code)
        code = tonumber(code)
        local low = string.lower(tostring(msg or ""))
        for _, w in ipairs(Cache.KickStopWords) do
            local a, b = string.find(low, "%f[%w]" .. w)
            if a then return "stop", "the kick message says \"" .. string.sub(low, a, b) .. "\"" end
        end
        -- the error text usually carries its own code: "... (Error Code: 267)"
        if not code then code = tonumber(string.match(low, "error code:?%s*(%d+)")) end
        if code and Cache.KickStopCodes[code] then return "stop", "error code " .. code end
        if code and code >= 768 and code < 800 then return "teleport", "teleport error " .. code end
        if string.find(low, "teleport") and string.find(low, "fail") then return "teleport", "teleport failed" end
        if low == "" then return "rejoin", "disconnected without a message" end
        return "rejoin", "disconnected"
    end

    -- the wait before attempt n (1-based): 5, 10, 20, 40, 80, 120, 120 ...
    function Cache.rejoinBackoff(n)
        n = math.max(1, math.floor(tonumber(n) or 1))
        return math.min(Cache.REJOIN_MAX_WAIT, Cache.REJOIN_BASE_SECS * 2 ^ (n - 1))
    end

    -- the rejoins inside the last hour, oldest first; anything not a number is dropped
    -- (the log is a file a person can edit)
    function Cache.pruneRejoinLog(times, now)
        local out = {}
        for _, t in ipairs(type(times) == "table" and times or {}) do
            t = tonumber(t)
            if t and now - t < 3600 and t <= now + 60 then out[#out + 1] = t end
        end
        table.sort(out)
        return out
    end

    -- Returns allowed, used, secondsUntilOneIsFree.
    function Cache.rejoinBudget(times, now, max)
        max = max or Cache.REJOIN_MAX_PER_HOUR
        local live = Cache.pruneRejoinLog(times, now)
        if #live < max then return true, #live, 0 end
        return false, #live, math.max(0, math.ceil(live[#live - max + 1] + 3600 - now))
    end

    -- HOP TO A PUBLIC SERVER -- the decision half. A plain Teleport(game.PlaceId)
    -- always lands on a PUBLIC server, which is the one way OUT of a private one
    -- (back in needs an access code nothing here holds). The teleport kills the
    -- script, so it is refused while a build or the queue runs: their state is mid-
    -- flight and a deliberate hop is not the crash the resume machinery is shaped for.
    -- (privateServerId ~= "" means a private server; the empty string is public.)
    -- Returns "go"/"public" (a public-to-public hop is a server change, allowed and
    -- named for what it is) or nil and the refusal.
    function Cache.serverHopPlan(privateServerId, buildOn, queueOn)
        if queueOn then return nil, "Stop 'Build Queue Mode' first: a server hop kills the script mid-queue." end
        if buildOn then return nil, "Stop 'Auto Build Blueprint' first: a server hop kills the script mid-build." end
        if tostring(privateServerId or "") ~= "" then return "go" end
        return "public"
    end

    -- THE WHOLE DECISION, in the order the reasons matter.
    --   ctx = { enabled, userStopped, inFlight, busy, message, code, times, now, max }
    -- Returns action, reason: "ignore" (not ours to act on), "stop" (a ban-like kick:
    -- stand down and forget the resume), "limit" (too many this hour) or "rejoin".
    function Cache.rejoinDecision(ctx)
        if not ctx.enabled then return "ignore", "Auto Rejoin is off" end
        if ctx.userStopped then return "ignore", "you unloaded or stopped the script" end
        if ctx.inFlight then return "ignore", "a rejoin is already under way" end
        if not ctx.busy then return "ignore", "no build or queue was running" end
        local kind, why = Cache.classifyKick(ctx.message, ctx.code)
        if kind == "stop" then return "stop", why end
        if kind == "teleport" then return "ignore", why .. " -- still connected" end
        local ok, used, wait = Cache.rejoinBudget(ctx.times, ctx.now or 0, ctx.max)
        if not ok then
            return "limit", string.format("%d rejoins in the last hour (next allowed in %d min)", used, math.ceil(wait / 60))
        end
        return "rejoin", why
    end
end
-- ==================== END AUTO REJOIN PLAN ====================
-- ==================== PRICE BOOK ====================
-- Capture prices from a vend scan (yours or anyone's shop) into a persistent book,
-- then re-apply them to your OWN vends later: scan a shop, go home, hit Apply and each
-- of your vends gets the saved price for whatever item it holds. Sell prices keep the
-- LOWEST seen per item, buy prices the HIGHEST (within one capture); a new capture
-- overwrites the book entries for the items it saw, so the latest scan wins.

function Cache.loadPriceBook()
    Cache.PriceBook = { sell = {}, buy = {} }
    if not (isfile and readfile) then return end
    if not isfile("Islands trading hub/pricebook.json") then return end
    local ok, data = pcall(function() return HttpService:JSONDecode(readfile("Islands trading hub/pricebook.json")) end)
    if not ok or type(data) ~= "table" then return end
    for _, side in ipairs({"sell", "buy"}) do
        if type(data[side]) == "table" then
            for item, p in pairs(data[side]) do
                if type(item) == "string" and tonumber(p) and tonumber(p) > 0 then
                    Cache.PriceBook[side][item] = tonumber(p)
                end
            end
        end
    end
end

function Cache.savePriceBook()
    if not (writefile and isfolder and makefolder) then return end
    if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
    pcall(function()
        writefile("Islands trading hub/pricebook.json", HttpService:JSONEncode(Cache.PriceBook))
    end)
end

function Cache.priceBookCount()
    local n = 0
    for _ in pairs(Cache.PriceBook.sell) do n += 1 end
    for _ in pairs(Cache.PriceBook.buy) do n += 1 end
    return n
end

-- Export the whole book as CSV (opens straight in Google Sheets / Excel). One row per
-- item with its sell and buy price side by side. Returns rows written + the file path.
-- A WRITE THAT ASKS THE DISK. Both exports wrote through a bare pcall and then
-- reported the number of rows they had BUILT, which is a claim about intent and not
-- about the file: an executor that caps writefile truncates a 1.5MB CSV, returns
-- success, and the notification still says 16,589 rows. Read the length back and
-- compare. Same rule the crawler's hop learned -- believe the disk.
function Cache.writeVerified(path, text)
    if not writefile then return false, 0, #text end
    local ok = pcall(function() writefile(path, text) end)
    if not ok then return false, 0, #text end
    local onDisk = nil
    pcall(function() onDisk = #readfile(path) end)
    if not onDisk then return true, nil, #text end   -- cannot read back; not a failure
    return onDisk >= #text, onDisk, #text
end

function Cache.exportPriceBookCSV()
    if not (writefile and isfolder and makefolder) then return nil end
    local pb = Cache.PriceBook or { sell = {}, buy = {} }
    local items, seen = {}, {}
    for it in pairs(pb.sell or {}) do if not seen[it] then seen[it] = true; items[#items + 1] = it end end
    for it in pairs(pb.buy or {}) do if not seen[it] then seen[it] = true; items[#items + 1] = it end end
    -- THE GAME'S NAME IN THE SPREADSHEET, not the id split on its hump. A column
    -- reading "Blue flower seeds" beside "Diamond sword" is what made the export look
    -- hand-made; Cache.displayName answers with what Islands itself calls the item and
    -- falls back to a title-cased fixname for anything the dump does not cover. The
    -- Internal ID column keeps the raw string, so nothing is lost to the rename.
    table.sort(items, function(a, b) return Cache.displayName(a):lower() < Cache.displayName(b):lower() end)
    -- CSV-escape: quote fields containing a comma/quote/newline, double inner quotes
    local function esc(v)
        local s = tostring(v)
        if s:find('[",\n]') then s = '"' .. s:gsub('"', '""') .. '"' end
        return s
    end
    local rows = { "Item,Internal ID,Sell Price,Buy Price" }
    for _, it in ipairs(items) do
        rows[#rows + 1] = table.concat({
            esc(Cache.displayName(it)), esc(it),
            esc(pb.sell and pb.sell[it] or ""),
            esc(pb.buy and pb.buy[it] or ""),
        }, ",")
    end
    if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
    local path = "Islands trading hub/pricebook_export.csv"
    local whole, onDisk, expected = Cache.writeVerified(path, table.concat(rows, "\n"))
    if onDisk == 0 then return nil end
    return #items, path, whole, onDisk, expected
end

-- data: scan entries (defaults to a fresh scan). Returns how many item prices were saved.
-- Also records the full per-shop market (owner + item + price + stock) into
-- Cache.PriceListings, deduped by owner|item|mode, so you can export data on everyone.
-- What to SHOW for a shop: a resolved name, else the island's publisher, else the raw
-- id. Never nothing -- an empty Owner column loses which rows came from one shop, and
-- that is the column's whole job.
--
-- A NAME LEARNED ONCE IS KEPT. The owner key of a shop is often an id (a GUID, or the
-- island's "<guid>-island" name) that nothing can turn into a player name later -- the
-- name is only knowable while you stand there: the crawler's publisher, or the owner
-- being on the server (083 looks). So whatever learns it writes it down here, keyed
-- by the shop's owner key, and every label after that reads it -- in this session and
-- the next (shop_names.json).
Cache.ShopNames = {}
do
    local FILE = "Islands trading hub/shop_names.json"
    pcall(function()
        if isfile and readfile and isfile(FILE) then
            local d = HttpService:JSONDecode(readfile(FILE))
            if type(d) == "table" then
                for k, v in pairs(d) do
                    if type(k) == "string" and type(v) == "string" and v ~= "" then Cache.ShopNames[k] = v end
                end
            end
        end
    end)
    -- record a name for an owner key; only a real name, only when it changes
    function Cache.learnShopName(owner, name)
        owner = owner ~= nil and tostring(owner) or nil
        if not owner or type(name) ~= "string" or name == "" or Cache.looksLikeShopId(name) then return false end
        if name == owner or Cache.ShopNames[owner] == name then return false end
        Cache.ShopNames[owner] = name
        if writefile and isfolder and makefolder then
            pcall(function()
                if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
                writefile(FILE, HttpService:JSONEncode(Cache.ShopNames))
            end)
        end
        return true
    end
end
function Cache.ownerLabel(owner, islandOwner)
    local learned = owner ~= nil and Cache.ShopNames[tostring(owner)]
    if learned then return learned end
    local shown = Cache.resolveOwner(owner)
    if Cache.looksLikeShopId(shown) then
        if type(islandOwner) == "string" and islandOwner ~= "" and not Cache.looksLikeShopId(islandOwner) then
            return islandOwner
        end
    end
    return shown
end
-- WHAT A PICKER SHOWS FOR A SHOP: the label above, and when that is still an id, a
-- short "Unknown owner (bcba4a08)" -- the first eight characters still tell two
-- unknown shops apart, and 44 characters of hex told nobody anything.
function Cache.shopPickLabel(owner, islandOwner)
    local name = Cache.ownerLabel(owner, islandOwner)
    if Cache.looksLikeShopId(name) then return "Unknown owner (" .. tostring(name):sub(1, 8) .. ")" end
    return tostring(name)
end

function Cache.capturePricesToBook(data)
    data = data or Cache.buildVendScanData()
    Cache.PriceListings = Cache.PriceListings or {}
    local now = 0
    pcall(function() now = os.time() end)
    -- the book must reflect COMPETITORS, not yourself: if your own vends went into
    -- it, undercutting chases your own price down and overcutting a Buy just
    -- matches your own (highest) bid = "nothing changes". Skip your own island's
    -- vends when building sell[]/buy[]. (They still go into PriceListings for the
    -- full market export.)
    -- exclude ONLY the island you actually OWN (by owner match) — not the nearest
    -- one. Proximity-based myIslandModel returned the SHOP when you visited it, so
    -- the whole shop got excluded and the scan saved nothing.
    local myIsland = Cache.myOwnedIslandModel and Cache.myOwnedIslandModel()
    local sell, buy = {}, {}
    local ownSeen = 0
    for _, e in ipairs(data) do
        local p = tonumber(e.price)
        if p and p > 0 and type(e.item) == "string" and e.item ~= "Empty" then
            local mine = myIsland and e.vend and e.vend:IsDescendantOf(myIsland)
            if mine then ownSeen += 1 end
            if not mine then
                if e.mode == 0 then
                    if not sell[e.item] or p < sell[e.item] then sell[e.item] = p end
                elseif e.mode == 1 then
                    if not buy[e.item] or p > buy[e.item] then buy[e.item] = p end
                end
            end
            -- per-shop listing: keep one row per (owner,item,mode), refreshed each scan.
            -- When the Market Crawler is running, tag which island (server) it came
            -- from so the export shows the source shop + its publisher.
            if e.mode == 0 or e.mode == 1 then
                local isl = State.CrawlerCurrentIsland
                local key = tostring(e.owner or "unknown") .. "|" .. e.item .. "|" .. tostring(e.mode)
                Cache.PriceListings[key] = { owner = e.owner or "unknown", item = e.item,
                    mode = e.mode, price = p, stock = tonumber(e.stock) or 0, at = now,
                    island = isl and isl.name or nil, islandOwner = isl and isl.owner or nil }
                -- the crawler's publisher IS the name an id-keyed shop lacks
                if isl and isl.owner and Cache.looksLikeShopId(tostring(e.owner)) then
                    Cache.learnShopName(e.owner, isl.owner)
                end
            end
        end
    end
    local n = 0
    for item, p in pairs(sell) do Cache.PriceBook.sell[item] = p; n += 1 end
    for item, p in pairs(buy)  do Cache.PriceBook.buy[item]  = p; n += 1 end
    if n > 0 then Cache.savePriceBook() end
    Cache.savePriceListings()
    return n, ownSeen
end

function Cache.priceListingsCount()
    local n = 0
    for _ in pairs(Cache.PriceListings or {}) do n += 1 end
    return n
end

function Cache.savePriceListings()
    if not (writefile and isfolder and makefolder) then return end
    -- Listing cap. 0 (the default) means keep every listing ever scanned — a crawl of
    -- a few hundred islands blows past 6,000 easily, and silently dropping the oldest
    -- ones made the price book forget shops it had already paid to visit. Set
    -- State.PriceListingsCap to a positive number to trim to the freshest N instead.
    local cap = tonumber(State.PriceListingsCap) or 0
    if cap > 0 then
        local list = {}
        for _, v in pairs(Cache.PriceListings or {}) do list[#list + 1] = v end
        if #list > cap then
            table.sort(list, function(a, b) return (a.at or 0) > (b.at or 0) end)  -- keep freshest
            for i = #list, cap + 1, -1 do list[i] = nil end
            Cache.PriceListings = {}
            for _, v in ipairs(list) do
                Cache.PriceListings[tostring(v.owner) .. "|" .. v.item .. "|" .. tostring(v.mode)] = v
            end
        end
    end
    if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
    pcall(function() writefile("Islands trading hub/pricelistings.json", HttpService:JSONEncode(Cache.PriceListings)) end)
end
function Cache.loadPriceListings()
    Cache.PriceListings = {}
    if not (isfile and readfile) then return end
    if not isfile("Islands trading hub/pricelistings.json") then return end
    local ok, data = pcall(function() return HttpService:JSONDecode(readfile("Islands trading hub/pricelistings.json")) end)
    if ok and type(data) == "table" then Cache.PriceListings = data end
end

-- Export the full per-shop market to CSV (Owner, Item, Type, Price, Stock, Last Seen).
-- Resolves numeric owners (UserIds) to usernames at export time (cached, yields).
function Cache.exportPriceListingsCSV()
    if not (writefile and isfolder and makefolder) then return nil end
    local rows = {}
    for _, v in pairs(Cache.PriceListings or {}) do rows[#rows + 1] = v end
    if #rows == 0 then return 0 end
    -- sort: item, then cheapest sell / highest buy first (most useful for undercutting)
    table.sort(rows, function(a, b)
        if a.item ~= b.item then return Cache.displayName(a.item):lower() < Cache.displayName(b.item):lower() end
        if a.mode ~= b.mode then return (a.mode or 0) < (b.mode or 0) end
        if a.mode == 1 then return (a.price or 0) > (b.price or 0) end
        return (a.price or 0) < (b.price or 0)
    end)
    local function esc(x)
        local s = tostring(x)
        if s:find('[",\n]') then s = '"' .. s:gsub('"', '""') .. '"' end
        return s
    end
    local out = { "Owner,Item,Type,Price,Stock,Shop Island,Island Publisher,Last Seen" }
    for _, v in ipairs(rows) do
        local when = ""
        if v.at and v.at > 0 then pcall(function() when = os.date("%Y-%m-%d %H:%M", v.at) end) end
        out[#out + 1] = table.concat({
            -- the shop's PUBLISHER when the owner is still an unresolvable id: a
            -- GUID groups the rows correctly and tells a reader nothing, and the
            -- crawler already knows whose island it was standing on
            esc(Cache.ownerLabel(v.owner, v.islandOwner)), esc(Cache.displayName(v.item)),
            v.mode == 1 and "Buy" or "Sell", esc(v.price or 0), esc(v.stock or 0),
            esc(v.island or ""), esc(v.islandOwner or ""), esc(when),
        }, ",")
    end
    if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
    local path = "Islands trading hub/market_export.csv"
    local whole, onDisk, expected = Cache.writeVerified(path, table.concat(out, "\n"))
    if onDisk == 0 then return nil end
    return #rows, path, whole, onDisk, expected
end


-- Sets each of your (in-range / selected) vends to the book price for the item it
-- currently holds, keeping the vend's own mode. Sell prices get the undercut % off;
-- buy prices are applied as saved. Vends whose item has no book entry are skipped.
-- Uses the same open -> VendingMode -> close flow as Set Price, so the server's own
-- ownership checks apply — other people's vends simply reject the edit.
-- computes the target price for one of YOUR vends from the book. Returns nil if the
-- item has no book entry. Sell: undercut % off, clamped to the min-price floor. Buy:
-- overcut % on top (outbid other buyers), then the book (highest-seen) price.
-- ---- COPYING ONE SHOP --------------------------------------------------------
-- The book keeps the cheapest sell and the highest buy it has ever seen, ACROSS every
-- shop. That is the right number to undercut and the wrong number to follow: the
-- cheapest sell on the island is often one person dumping stock at a loss, and pricing
-- a whole wall off it is how you join them. Sometimes what you want is the big
-- established shop whose prices the island already accepts -- match it, or sit a few
-- percent under it, and leave the race to the bottom alone.
--
-- Cache.PriceListings has held the per-shop rows since the market export was written:
-- one per owner|item|mode. Nothing new has to be scanned for this, only read.
--
-- Every shop the scanner has seen, biggest first -- because the shop worth copying is
-- usually the one with the most on its shelves, and it saves scrolling.
function Cache.priceBookShops()
    local byOwner, pub = {}, {}
    for _, v in pairs(Cache.PriceListings or {}) do
        local o = tostring(v.owner or "unknown")
        byOwner[o] = (byOwner[o] or 0) + 1
        -- carry a publisher along, so the picker can name an id-keyed shop
        if not pub[o] and type(v.islandOwner) == "string" and v.islandOwner ~= ""
            and not Cache.looksLikeShopId(v.islandOwner) then pub[o] = v.islandOwner end
    end
    local list = {}
    for o, n in pairs(byOwner) do list[#list + 1] = { owner = o, items = n, islandOwner = pub[o] } end
    table.sort(list, function(a, b)
        if a.items ~= b.items then return a.items > b.items end
        return a.owner < b.owner
    end)
    return list
end

-- What ONE shop charges for one item, or nil if that shop does not price it.
function Cache.shopListingPrice(item, mode, owner)
    if not (item and owner) then return nil end
    local e = (Cache.PriceListings or {})[tostring(owner) .. "|" .. tostring(item) .. "|" .. tostring(mode)]
    return e and tonumber(e.price) or nil
end

-- AN ITEM THE CHOSEN SHOP DOES NOT STOCK IS LEFT ALONE, not quietly priced off the
-- market instead. "Copy that shop" is not an instruction that should reprice things
-- that shop never priced, and a silent fallback to the book would do exactly that for
-- every item they happen not to carry -- which, on a specialist shop, is most of them.
-- The skip is already counted and reported as "no book price", so it is visible.
function Cache.priceForVend(item, mode)
    if not item then return nil end
    local shop = State.PriceBookShop
    local sell, buy
    if shop and shop ~= "" then
        sell = Cache.shopListingPrice(item, 0, shop)
        buy  = Cache.shopListingPrice(item, 1, shop)
        if not sell and not buy then return nil end
    else
        sell, buy = Cache.PriceBook.sell[item], Cache.PriceBook.buy[item]
    end
    if mode == 1 then
        if buy then
            local overcut = tonumber(State.PriceBookOvercut) or 0
            if overcut > 0 then buy = math.floor(buy * (100 + overcut) / 100) end
            return math.max(1, buy)
        end
        -- FALLBACK (field report: "buy vends never get priced"): buy data is rare --
        -- few shops run buy vends, so scans learn no buy price for most items. Derive
        -- from the SELL price instead: pay 80% of it, so the vend still buys below
        -- market and the item can be resold at a profit. With a shop picked this is
        -- that shop's own sell price, which is the same rule read off one shelf.
        if not sell then return nil end
        return math.max(1, math.floor(sell * 0.8))
    else
        if not sell then return nil end
        local undercut = tonumber(State.PriceBookUndercut) or 0
        if undercut > 0 then sell = math.floor(sell * (100 - undercut) / 100) end
        local floor = parsenum(State.PriceBookMinPrice)
        if floor and floor > 0 then sell = math.max(sell, floor) end
        return math.max(1, sell)
    end
end

-- reads a vend's current mode: 0 = Sell, 1 = Buy (nil if unknown)
function Cache.vendCurrentMode(v)
    local m = v:GetAttribute("mode") or v:GetAttribute("Mode")
    if m == nil then local mc = v:FindFirstChild("mode") or v:FindFirstChild("Mode"); if mc then m = mc.Value end end
    return tonumber(m)
end

-- "vendingMachineIndustrial" is the industrial model; the other two block names are
-- the normal/upgraded machine. The Shop Organizer treats them as separate sections.
function Cache.vendSection(v)
    return v.Name == "vendingMachineIndustrial" and "Industrial" or "Normal"
end

-- reads a vend's current transaction price (nil if unknown)
function Cache.vendCurrentPrice(v)
    local p = v:GetAttribute("Price") or v:GetAttribute("TransactionPrice")
    if p == nil then local pc = v:FindFirstChild("Price") or v:FindFirstChild("TransactionPrice"); if pc then p = pc.Value end end
    return tonumber(p)
end

-- Sets each of your (in-range / selected) vends to the book price for the item it
-- holds, keeping the vend's own mode. Skips vends already at the target price so the
-- auto loop isn't spammy. quiet = don't post the summary notification.
-- Uses the same open -> VendingMode -> close flow as Set Price, so server-side
-- ownership still applies (other people's vends reject the edit).
function Cache.applyPriceBook(quiet)
    local applied, skipped, unchanged = 0, 0, 0
    local noItem, noPrice, protected = 0, 0, 0
    -- true = ignore the Sell/Buy targeting filter so BOTH your sell and buy vends
    -- get repriced (the field report: "only does the buy vends")
    -- PASS 1: compute the target price for every vend and record the LOWEST sell
    -- price you'll charge per item, so buy prices can be capped below it.
    local jobs, sellFloor = {}, {}
    for _, v in ipairs(getvendings(true)) do
        if State.IsCleaningUp then break end
        if Cache.VendWhitelist and Cache.VendWhitelist[v] then protected += 1; skipped += 1; continue end
        local sc = v:FindFirstChild("SellingContents")
        local it = sc and sc:GetChildren()[1]
        local item = it and it.Name
        local mode = v:GetAttribute("mode") or v:GetAttribute("Mode")
        if mode == nil then
            local mc = v:FindFirstChild("mode") or v:FindFirstChild("Mode")
            if mc then mode = mc.Value end
        end
        local price = Cache.priceForVend(item, mode)
        if price then
            if (mode or 0) == 0 and item then
                if not sellFloor[item] or price < sellFloor[item] then sellFloor[item] = price end
            end
            jobs[#jobs + 1] = { v = v, item = item, mode = mode, price = price }
        else
            skipped += 1
            if not item then noItem += 1 else noPrice += 1 end
        end
    end
    local crossFixed = 0
    for _, j in ipairs(jobs) do
        if State.IsCleaningUp then break end
        local v, item, mode, price = j.v, j.item, j.mode, j.price
        -- NEVER buy at/above what you sell for: a buy price >= your sell price lets
        -- anyone drain you (buy from your sell vend, sell straight back to your buy
        -- vend). Cap every buy 5% under your lowest sell price for that item.
        if (mode or 0) == 1 and item and sellFloor[item] then
            local cap = math.max(1, math.floor(sellFloor[item] * 0.95))
            if price > cap then price = cap; crossFixed += 1 end
        end
        if price then
            if Cache.vendCurrentPrice(v) == price then
                unchanged += 1  -- already correct; don't re-fire (keeps the loop cheap)
            else
                local guid = HttpService:GenerateGUID(false)
                openVending(guid, v)
                task.wait(Delay.VendingAction)
                pcall(function() Remotes.VendingMode:FireServer(guid, {{
                    mode = mode or 0, vendingMachine = v,
                    player_tracking_category = "join_from_web", transactionPrice = price,
                }}) end)
                closeVending(v)
                applied += 1
                task.wait(Delay.VendingAction)
            end
        end
    end
    if not quiet then
        -- say exactly WHY vends were skipped instead of one lump number —
        -- "still doesn't do all my vends" was undiagnosable from the old message
        local parts = { string.format("Repriced %d · %d already correct.", applied, unchanged) }
        if crossFixed > 0 then parts[#parts + 1] = crossFixed .. " buy price(s) capped below your sell price (anti-drain)." end
        if noItem > 0 then parts[#parts + 1] = noItem .. " skipped: EMPTY vend (put 1 of the item inside so it knows what to price)." end
        if noPrice > 0 then parts[#parts + 1] = noPrice .. " skipped: item not in the Price Book yet (Scan & Save near shops selling it)." end
        if protected > 0 then parts[#parts + 1] = protected .. " protected." end
        Window:Notify({Title="Price Book", Content=table.concat(parts, " "), Duration=8})
    end
    return applied, skipped, unchanged
end

function Cache.showPriceBook()
    if Cache.PriceBookUI then pcall(function() Cache.PriceBookUI:Destroy() end); Cache.PriceBookUI = nil end
    local ui, frame = buildFrameBase("IVM_PriceBook", UDim2.new(0,320,0,400), UDim2.new(0,10,0.5,-200))
    frame.Visible = true
    Cache.PriceBookUI = ui
    local titleBar = addTitleBar(frame, "Price Book", Color3.fromRGB(35,35,42))
    makedraggable(frame, titleBar)

    local closeBtn = Instance.new("TextButton")
    closeBtn.Size = UDim2.new(0,26,0,26); closeBtn.Position = UDim2.new(1,-32,0,4)
    closeBtn.BackgroundColor3 = Color3.fromRGB(60,32,34); closeBtn.Text = "X"
    closeBtn.TextColor3 = Color3.fromRGB(235,200,200); closeBtn.Font = Enum.Font.GothamBold
    closeBtn.TextSize = 14; closeBtn.ZIndex = 5; closeBtn.Parent = titleBar
    Instance.new("UICorner", closeBtn).CornerRadius = UDim.new(0,6)
    closeBtn.MouseButton1Click:Connect(function()
        if Cache.PriceBookUI then pcall(function() Cache.PriceBookUI:Destroy() end); Cache.PriceBookUI = nil end
    end)

    local search = Instance.new("TextBox")
    search.Size = UDim2.new(1,-16,0,26); search.Position = UDim2.new(0,8,0,42)
    search.BackgroundColor3 = Color3.fromRGB(25,25,30); search.BorderSizePixel = 0
    search.TextColor3 = Color3.fromRGB(230,230,230); search.PlaceholderText = "Search item..."
    search.PlaceholderColor3 = Color3.fromRGB(120,120,130); search.Font = Enum.Font.Gotham
    search.TextSize = 13; search.Text = ""; search.ClearTextOnFocus = false; search.Parent = frame
    Instance.new("UICorner", search).CornerRadius = UDim.new(0,6)

    local scroll = Instance.new("ScrollingFrame")
    scroll.Size = UDim2.new(1,-16,1,-84); scroll.Position = UDim2.new(0,8,0,76)
    scroll.BackgroundColor3 = Color3.fromRGB(22,22,27); scroll.BorderSizePixel = 0
    scroll.ScrollBarThickness = 5; scroll.ScrollBarImageColor3 = Color3.fromRGB(80,80,90)
    scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y; scroll.Parent = frame
    Instance.new("UICorner", scroll).CornerRadius = UDim.new(0,6)

    local list = Instance.new("TextLabel")
    list.Size = UDim2.new(1,-12,0,0); list.Position = UDim2.new(0,8,0,8)
    list.BackgroundTransparency = 1; list.TextColor3 = Color3.fromRGB(210,210,215)
    list.Font = Enum.Font.Gotham; list.TextSize = 13
    list.TextXAlignment = Enum.TextXAlignment.Left; list.TextYAlignment = Enum.TextYAlignment.Top
    list.TextWrapped = true; list.AutomaticSize = Enum.AutomaticSize.Y; list.Parent = scroll

    local function render(filter)
        filter = (filter or ""):lower()
        local lines = {}
        for _, side in ipairs({ {"sell", "— SELL PRICES —"}, {"buy", "— BUY PRICES —"} }) do
            local items = {}
            for item in pairs(Cache.PriceBook[side[1]]) do items[#items + 1] = item end
            table.sort(items, function(a, b) return Cache.displayName(a) < Cache.displayName(b) end)
            local any = false
            for _, item in ipairs(items) do
                if filter == "" or Cache.displayName(item):lower():find(filter, 1, true) then
                    if not any then lines[#lines + 1] = side[2]; any = true end
                    lines[#lines + 1] = string.format("%s   %s", Cache.displayName(item), shortnum(Cache.PriceBook[side[1]][item]))
                end
            end
            if any then lines[#lines + 1] = "" end
        end
        list.Text = #lines > 0 and table.concat(lines, "\n") or "Price book is empty. Use 'Save Prices' in the Vending Scanner."
    end
    search:GetPropertyChangedSignal("Text"):Connect(function() render(search.Text) end)
    render("")
    return ui
end

-- ---- Vend Selector: pick EXACTLY which vends actions target, from a list ----
-- Alt+Click selection needs a keyboard; this works everywhere (mobile executors too).
-- Lists nearby vends sorted by distance with item/price/mode, one button per vend to
-- select/deselect (blue highlight on the machine). Selecting the first vend auto-turns
-- Select Vends Mode ON so actions immediately honor the pick.
-- ADORN THE VEND, DON'T PARENT INTO IT. This was the one selection highlight in the
-- file parented to the vend MODEL rather than to gethui(): the pick registered, the
-- notification fired, actions targeted the right machine -- and nothing turned blue,
-- because a Highlight left under a model in Workspace is the game's to clear, and
-- Islands rebuilds those models constantly as blocks stream. gethighlight() parents
-- into the hidden GUI container the rest of the script uses (and pools, so selecting
-- fifty vends reuses fifty instances instead of allocating them), with the vend as
-- the adornee -- which is what actually draws the outline.
function Cache.toggleVendSelected(v)
    if Cache.SelectedVendings[v] then
        pcall(function() freehighlight(Cache.SelectedVendings[v]) end)
        Cache.SelectedVendings[v] = nil
        return false
    end
    local hl = gethighlight()
    hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    hl.FillColor = Color3.fromRGB(70,140,255); hl.OutlineColor = Color3.fromRGB(150,200,255)
    hl.FillTransparency = 0.5; hl.OutlineTransparency = 0
    hl.Adornee = v
    Cache.SelectedVendings[v] = hl
    -- make the pick take effect right away
    if not State.SelectionModeEnabled then
        local tf = Cache.ToggleFunctions["Select Vends Mode (Alt+Click)"]
        if tf then task.defer(tf, true) else State.SelectionModeEnabled = true end
        Cache.notify({Title="Vend Selection", Content="Select Vends Mode turned ON — actions now target only your selected vends.", Duration=5})
    end
    return true
end

function Cache.showVendSelector()
    if Cache.VendSelectorUI then pcall(function() Cache.VendSelectorUI:Destroy() end); Cache.VendSelectorUI = nil end
    local ui, frame = buildFrameBase("IVM_VendSelector", UDim2.new(0,340,0,470), UDim2.new(0,10,0.5,-235))
    frame.Visible = true
    Cache.VendSelectorUI = ui
    local titleBar = addTitleBar(frame, "Vend Selector", Color3.fromRGB(35,35,42))
    makedraggable(frame, titleBar)

    local closeBtn = Instance.new("TextButton")
    closeBtn.Size = UDim2.new(0,26,0,26); closeBtn.Position = UDim2.new(1,-32,0,4)
    closeBtn.BackgroundColor3 = Color3.fromRGB(60,32,34); closeBtn.Text = "X"
    closeBtn.TextColor3 = Color3.fromRGB(235,200,200); closeBtn.Font = Enum.Font.GothamBold
    closeBtn.TextSize = 14; closeBtn.ZIndex = 5; closeBtn.Parent = titleBar
    Instance.new("UICorner", closeBtn).CornerRadius = UDim.new(0,6)
    closeBtn.MouseButton1Click:Connect(function()
        if Cache.VendSelectorUI then pcall(function() Cache.VendSelectorUI:Destroy() end); Cache.VendSelectorUI = nil end
    end)

    local status = Instance.new("TextLabel")
    status.Size = UDim2.new(1,-16,0,18); status.Position = UDim2.new(0,8,0,40)
    status.BackgroundTransparency = 1; status.Font = Enum.Font.Gotham; status.TextSize = 12
    status.TextXAlignment = Enum.TextXAlignment.Left; status.TextColor3 = Color3.fromRGB(160,200,255)
    status.Parent = frame

    local btnRow = Instance.new("Frame")
    btnRow.Size = UDim2.new(1,-16,0,28); btnRow.Position = UDim2.new(0,8,0,60)
    btnRow.BackgroundTransparency = 1; btnRow.Parent = frame
    local function mkBtn(parent, text, x, w, color)
        local b = Instance.new("TextButton")
        b.Size = UDim2.new(0,w,1,0); b.Position = UDim2.new(0,x,0,0)
        b.BackgroundColor3 = color or Color3.fromRGB(45,45,55); b.Text = text
        b.TextColor3 = Color3.fromRGB(225,225,230); b.Font = Enum.Font.Gotham; b.TextSize = 12
        b.Parent = parent
        Instance.new("UICorner", b).CornerRadius = UDim.new(0,6)
        return b
    end
    local refreshBtn = mkBtn(btnRow, "Refresh", 0, 76)
    local allBtn     = mkBtn(btnRow, "Select All", 82, 82)
    local clearBtn   = mkBtn(btnRow, "Clear", 170, 62, Color3.fromRGB(60,40,42))

    -- ROW PICKER. A shop is stacked rows of vends, and "put coins in the bottom row
    -- only" was impossible from a flat distance-sorted list — every entry looked the
    -- same. Nearby vends are grouped by height (bottom row = R1) and each row gets a
    -- one-click select button, so a whole row can be targeted without hunting.
    local rowBtnHolder = Instance.new("Frame")
    rowBtnHolder.Size = UDim2.new(1,-16,0,26); rowBtnHolder.Position = UDim2.new(0,8,0,92)
    rowBtnHolder.BackgroundTransparency = 1; rowBtnHolder.Parent = frame
    local rowBtnLayout = Instance.new("UIListLayout")
    rowBtnLayout.FillDirection = Enum.FillDirection.Horizontal
    rowBtnLayout.Padding = UDim.new(0,4); rowBtnLayout.SortOrder = Enum.SortOrder.LayoutOrder
    rowBtnLayout.Parent = rowBtnHolder

    local scroll = Instance.new("ScrollingFrame")
    scroll.Size = UDim2.new(1,-16,1,-132); scroll.Position = UDim2.new(0,8,0,126)
    scroll.BackgroundColor3 = Color3.fromRGB(22,22,27); scroll.BorderSizePixel = 0
    scroll.ScrollBarThickness = 5; scroll.ScrollBarImageColor3 = Color3.fromRGB(80,80,90)
    scroll.CanvasSize = UDim2.new(0,0,0,0); scroll.Parent = frame
    Instance.new("UICorner", scroll).CornerRadius = UDim.new(0,6)
    local layout = Instance.new("UIListLayout"); layout.Padding = UDim.new(0,4)
    layout.SortOrder = Enum.SortOrder.LayoutOrder; layout.Parent = scroll

    local function selCount()
        local n = 0
        for _ in pairs(Cache.SelectedVendings) do n += 1 end
        return n
    end
    local function updateStatus()
        status.Text = string.format("Selection Mode: %s   ·   %d vend(s) selected",
            State.SelectionModeEnabled and "ON" or "OFF", selCount())
    end

    -- group the vends in range into rows by height: bottom row first. A vend is one
    -- block tall on the 3-stud lattice, so anything within 2.5 studs is the same row.
    local function vendRows()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hrpPos = hrp and hrp.Position or Vector3.new()
        local radSq = Settings.VendingRadius * Settings.VendingRadius
        local list = {}
        for _, data in pairs(Cache.VendingMachines) do
            local v, part = data.v, data.part
            if v and v.Parent and part and part.Parent then
                local d = part.Position - hrpPos
                if Settings.IgnoreRadius or (d.X*d.X + d.Y*d.Y + d.Z*d.Z) <= radSq then
                    list[#list + 1] = { v = v, y = part.Position.Y }
                end
            end
        end
        table.sort(list, function(a, b) return a.y < b.y end)
        local rows, rowOf, cur = {}, {}, nil
        for _, it in ipairs(list) do
            if not cur or (it.y - cur.y0) > 2.5 then
                cur = { y0 = it.y, list = {} }
                rows[#rows + 1] = cur
            end
            cur.list[#cur.list + 1] = it.v
            rowOf[it.v] = #rows
        end
        return rows, rowOf
    end

    local rebuild
    local function rowFor(v, dist, idx, rowNo)
        local row = Instance.new("Frame")
        row.Size = UDim2.new(1,-6,0,40); row.BackgroundColor3 = Color3.fromRGB(30,30,36)
        row.BorderSizePixel = 0; row.LayoutOrder = idx; row.Parent = scroll
        Instance.new("UICorner", row).CornerRadius = UDim.new(0,6)

        local mode = v:GetAttribute("mode") or v:GetAttribute("Mode")
        if mode == nil then local mc = v:FindFirstChild("mode") or v:FindFirstChild("Mode"); if mc then mode = mc.Value end end
        local price = v:GetAttribute("Price") or v:GetAttribute("TransactionPrice")
        if price == nil then local pc = v:FindFirstChild("Price") or v:FindFirstChild("TransactionPrice"); if pc then price = pc.Value end end
        local itemTxt = "empty"
        local sc = v:FindFirstChild("SellingContents")
        if sc then
            local it = sc:GetChildren()[1]
            if it then
                local a = it:FindFirstChild("Amount")
                itemTxt = fixname(it.Name) .. " x" .. shortnum((a and a.Value) or 0)
            end
        end
        local cb = v:FindFirstChild("CoinBalance")

        local info = Instance.new("TextLabel")
        info.Size = UDim2.new(1,-92,1,0); info.Position = UDim2.new(0,8,0,0)
        info.BackgroundTransparency = 1; info.Font = Enum.Font.Gotham; info.TextSize = 12
        info.TextXAlignment = Enum.TextXAlignment.Left; info.TextColor3 = Color3.fromRGB(225,225,230)
        info.TextWrapped = true
        info.Text = string.format("%s[%s] %s\n@ %s   ·   coins %s   ·   %dm away",
            rowNo and ("R" .. rowNo .. "  ") or "",
            mode == 1 and "Buy" or "Sell", itemTxt, shortnum(tonumber(price) or 0),
            shortnum(cb and cb.Value or 0), math.floor(dist + 0.5))
        info.Parent = row

        local btn = Instance.new("TextButton")
        btn.Size = UDim2.new(0,78,0,28); btn.Position = UDim2.new(1,-84,0.5,-14)
        btn.Font = Enum.Font.GothamBold; btn.TextSize = 12
        btn.Parent = row
        Instance.new("UICorner", btn).CornerRadius = UDim.new(0,6)
        local function paint()
            local sel = Cache.SelectedVendings[v] ~= nil
            btn.Text = sel and "Selected ✓" or "Select"
            btn.BackgroundColor3 = sel and Color3.fromRGB(45,90,160) or Color3.fromRGB(45,45,55)
            btn.TextColor3 = sel and Color3.fromRGB(210,230,255) or Color3.fromRGB(225,225,230)
        end
        paint()
        btn.MouseButton1Click:Connect(function()
            if not (v and v.Parent) then rebuild(); return end
            Cache.toggleVendSelected(v)
            paint(); updateStatus()
        end)
    end

    rebuild = function()
        for _, c in ipairs(scroll:GetChildren()) do
            if c:IsA("Frame") then c:Destroy() end
        end
        for _, c in ipairs(rowBtnHolder:GetChildren()) do
            if c:IsA("TextButton") then c:Destroy() end
        end
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hrpPos = hrp and hrp.Position or Vector3.new()
        local rows, rowOf = vendRows()

        -- one button per detected row: "Bottom" selects only the lowest row, and so on
        if #rows > 1 then
            -- at most five buttons fit; past that show the bottom four and the top,
            -- so the top row is never the one you can't reach
            local picks = {}
            if #rows <= 5 then
                for r = 1, #rows do picks[#picks + 1] = r end
            else
                picks = {1, 2, 3, 4, #rows}
            end
            local w = math.floor((324 - (#picks - 1) * 4) / #picks)
            for slot, r in ipairs(picks) do
                local label = (r == 1 and "Bottom" or (r == #rows and "Top" or ("R" .. r)))
                local b = mkBtn(rowBtnHolder, label .. " (" .. #rows[r].list .. ")", 0, w, Color3.fromRGB(40,58,80))
                b.LayoutOrder = slot
                b.MouseButton1Click:Connect(function()
                    -- exclusive: picking a row means ONLY that row, so coins/items
                    -- can't leak into the rows above it
                    for _, h in pairs(Cache.SelectedVendings) do pcall(function() h:Destroy() end) end
                    Cache.SelectedVendings = {}
                    for _, v in ipairs(rows[r].list) do
                        if v and v.Parent then Cache.toggleVendSelected(v) end
                    end
                    Cache.notify({Title="Vend Selection", Content=string.format(
                        "%s row selected — %d vend(s). Every vend action now hits only these.",
                        label, #rows[r].list), Duration=5})
                    rebuild()
                end)
            end
        end

        local flat = {}
        for _, data in pairs(Cache.VendingMachines) do
            local v, part = data.v, data.part
            if v and v.Parent and part and part.Parent then
                flat[#flat + 1] = { v = v, dist = (part.Position - hrpPos).Magnitude }
            end
        end
        table.sort(flat, function(a, b) return a.dist < b.dist end)
        local shown = math.min(#flat, 40)
        for i = 1, shown do rowFor(flat[i].v, flat[i].dist, i, rowOf[flat[i].v]) end
        scroll.CanvasSize = UDim2.new(0, 0, 0, shown * 44 + 8)
        updateStatus()
        if #flat == 0 then
            status.Text = "No vends found — walk near some and Refresh (the scanner finds them automatically)."
        elseif #rows > 1 then
            status.Text = status.Text .. "   ·   " .. #rows .. " rows in range"
        end
    end

    refreshBtn.MouseButton1Click:Connect(rebuild)
    allBtn.MouseButton1Click:Connect(function()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local radSq = Settings.VendingRadius * Settings.VendingRadius
        for _, data in pairs(Cache.VendingMachines) do
            local v, part = data.v, data.part
            if v and v.Parent and part and part.Parent and not Cache.SelectedVendings[v] then
                local d = part.Position - hrp.Position
                if d.X*d.X + d.Y*d.Y + d.Z*d.Z <= radSq then Cache.toggleVendSelected(v) end
            end
        end
        rebuild()
    end)
    clearBtn.MouseButton1Click:Connect(function()
        for _, h in pairs(Cache.SelectedVendings) do pcall(function() h:Destroy() end) end
        Cache.SelectedVendings = {}
        rebuild()
    end)

    rebuild()
    return ui
end

Cache.loadPriceBook()
Cache.loadPriceListings()

-- ==================== VERSION CHECK (Update Notice, the model) ====================
-- The pure half of the update notice: what a build version is, how two compare, and
-- what to tell the player given the public version file. 251_update_check_ui.lua
-- fetches and notifies; everything it decides is here and in tests/version_check.test.lua.
--
-- A BUILD VERSION IS "<YYYY.MM.DD>-<short sha>", stamped by build.py from the admin
-- commit the sold build was cut from. The date orders two builds; the sha only says
-- whether two builds of the SAME day are the same one. A commit hash has no order, so a
-- same-day, different-sha remote counts as "different" and is announced like a newer
-- one -- the file only ever names the build that was published last, so a build that
-- differs from it on the same day is the one that got replaced.
--
-- "dev" (the admin build, or any build made without git) NEVER NAGS: it is not a
-- release, and telling the owner to re-run a loader over his working copy is noise.
--
-- The version file is the owner's, but it arrives over the network, so every field is
-- checked for type and clipped before any of it reaches the screen. Nothing in it is
-- ever run: `loader` is shown as text, never passed to loadstring.
do
    local NOTES_MAX, LOADER_MAX = 300, 300

    function Cache.versionParse(v)
        if type(v) ~= "string" then return nil end
        local y, m, d, sha = v:match("^(%d%d%d%d)%.(%d%d)%.(%d%d)%-(%x+)$")
        if not y then return nil end
        y, m, d = tonumber(y), tonumber(m), tonumber(d)
        if m < 1 or m > 12 or d < 1 or d > 31 or #sha < 4 then return nil end
        return { date = y * 10000 + m * 100 + d, sha = sha:lower() }
    end

    -- "newer" / "different" / "same" / "older" for remote against local, or nil with a
    -- reason when either side is not a release version (including "dev").
    function Cache.versionCompare(localV, remoteV)
        if localV == "dev" then return nil, "dev" end
        local a, b = Cache.versionParse(localV), Cache.versionParse(remoteV)
        if not a then return nil, "local" end
        if not b then return nil, "remote" end
        if b.date > a.date then return "newer" end
        if b.date < a.date then return "older" end
        -- same day: a short sha may be printed at different lengths, so a prefix match
        -- is the same commit
        local n = math.min(#a.sha, #b.sha)
        if a.sha:sub(1, n) == b.sha:sub(1, n) then return "same" end
        return "different"
    end

    local function clip(s, n)
        s = tostring(s):gsub("[%c]", " ")
        if #s > n then s = s:sub(1, n) .. "..." end
        return s
    end

    -- data: the decoded JSON ({ premium = {version=, notes=, loader=}, main = {...} }),
    -- or nil when the fetch or the decode failed. Returns a verdict table:
    --   { status = "update" | "current" | "ahead" | "dev" | "unconfigured" | "no-entry"
    --              | "bad-file" | "unreachable", version =, notes =, loader =, message = }
    -- `message` is the text to show; `status == "update"` is the only one that nags.
    function Cache.versionVerdict(data, branch, localV, url)
        if type(url) ~= "string" or url == "" then
            return { status = "unconfigured", message = "No update source configured for this build." }
        end
        if localV == "dev" then
            return { status = "dev", message = "This is a development build (version dev); it is never reported out of date." }
        end
        if data == nil then
            return { status = "unreachable", message = "Couldn't reach the update source. Try again later." }
        end
        if type(data) ~= "table" then
            return { status = "bad-file", message = "The update source didn't return a version file." }
        end
        local entry = data[tostring(branch)]
        if type(entry) ~= "table" then
            return { status = "no-entry", message = "The update source lists nothing for this build (" .. tostring(branch) .. ")." }
        end
        local rv = entry.version
        local cmp, why = Cache.versionCompare(localV, rv)
        if not cmp then
            if why == "local" then
                return { status = "bad-file", message = "This build's version (" .. clip(localV, 40) .. ") can't be compared." }
            end
            return { status = "bad-file", message = "The update source's version for this build isn't readable." }
        end
        local notes = (type(entry.notes) == "string" and entry.notes ~= "") and (clip(entry.notes, NOTES_MAX):gsub("[%.%s]+$", "")) or nil
        if notes == "" then notes = nil end
        local loader = (type(entry.loader) == "string" and entry.loader ~= "") and clip(entry.loader, LOADER_MAX) or nil
        if cmp == "newer" or cmp == "different" then
            local msg = "A new version is out: " .. rv .. (notes and (" — " .. notes) or "") .. ". Re-run your loader to update."
            if loader then msg = msg .. " Loader: " .. loader end
            return { status = "update", version = rv, notes = notes, loader = loader, message = msg }
        end
        if cmp == "older" then
            return { status = "ahead", version = rv, message = "You're on " .. localV .. ", newer than the published " .. rv .. "." }
        end
        return { status = "current", version = rv, message = "You're on the latest version (" .. localV .. ")." }
    end
end
-- ==== end of VERSION CHECK ======================================================
-- ==================== CHANGELOG (What's New, the model) ====================
-- The pure half of What's New: the registry of changelog entries, how two versions
-- compare, which entries a player has not seen yet, and how an entry reads. The panel
-- and the Settings button are 248_whats_new.lua; the premium-only entries are
-- 249_whats_new_premium.lua. Split for the reason 039/073 are: a part with UI at file
-- level cannot be loaded by tests/run_tests.py, and "which entries are unseen" is the
-- decision worth proving (tests/changelog.test.lua).
--
-- ONE REGISTRY, FILLED BY SEVERAL PARTS. Entries for every tier are written in 248 and
-- premium-only ones in 249, which build.py cuts from the trial -- so the trial never
-- carries a line of text about a feature it does not have, and nothing here needs to
-- know which tier it is in. The list is append-only and parts register in load order,
-- which is NOT newest-first; `changelogSorted` puts it in order at display time, so a
-- part can add an older entry after a newer one and nothing breaks.
--
-- VERSIONS ARE DATES WRITTEN AS "YYYY.MM.DD", compared number by number. Compared as
-- strings they would still order correctly only while every segment is zero-padded;
-- one "2026.9.27" typed without the zero would sort after "2026.10.02". Numbers make
-- the padding irrelevant, and a string that is not digits-and-dots is refused when it
-- is registered rather than silently sorting somewhere odd.
--
-- Everything is inside one do-block and published on Cache: the main chunk is close to
-- its 200 registers and this part takes none of them.
do
    Cache.Changelog = Cache.Changelog or {}

    -- "2026.09.27" -> {2026, 9, 27}; nil for anything that is not digits and single dots
    function Cache.changelogParseVersion(v)
        if type(v) ~= "string" then return nil end
        if not string.find(v, "^%d[%d%.]*$") or string.find(v, "%.%.") or string.sub(v, -1) == "." then
            return nil
        end
        local out = {}
        for seg in string.gmatch(v, "%d+") do out[#out + 1] = tonumber(seg) end
        return out
    end

    -- -1 / 0 / 1 like a comparator, nil when either side is not a version. A missing
    -- segment counts as 0, so "2026.09" and "2026.09.0" are the same version.
    function Cache.changelogCompare(a, b)
        local pa, pb = Cache.changelogParseVersion(a), Cache.changelogParseVersion(b)
        if not (pa and pb) then return nil end
        for i = 1, math.max(#pa, #pb) do
            local x, y = pa[i] or 0, pb[i] or 0
            if x ~= y then return x < y and -1 or 1 end
        end
        return 0
    end

    -- REGISTER ONE ENTRY. A bad entry is refused with the reason rather than stored:
    -- an entry without a valid version could never be told apart from "seen", so it
    -- would either show on every load or never show at all.
    --   entry = { version = "2026.09.27", title = "...", lines = { "...", ... } }
    function Cache.changelogAdd(entry, list)
        list = list or Cache.Changelog
        if type(entry) ~= "table" then return false, "not a table" end
        if not Cache.changelogParseVersion(entry.version) then
            return false, "version " .. tostring(entry.version) .. " is not YYYY.MM.DD"
        end
        if type(entry.title) ~= "string" or entry.title == "" then return false, "no title" end
        local lines = {}
        for _, l in ipairs(type(entry.lines) == "table" and entry.lines or {}) do
            if type(l) == "string" and l ~= "" then lines[#lines + 1] = l end
        end
        list[#list + 1] = { version = entry.version, title = entry.title, lines = lines }
        return true
    end

    -- NEWEST FIRST; entries sharing a version keep the order they were registered in,
    -- which is the order the part that wrote them put them. table.sort is not stable,
    -- so the position is the tie-break.
    function Cache.changelogSorted(list)
        local rows = {}
        for i, e in ipairs(list or Cache.Changelog) do
            if Cache.changelogParseVersion(e.version) then rows[#rows + 1] = { e = e, i = i } end
        end
        table.sort(rows, function(a, b)
            local c = Cache.changelogCompare(a.e.version, b.e.version)
            if c ~= 0 then return c > 0 end
            return a.i < b.i
        end)
        local out = {}
        for k, r in ipairs(rows) do out[k] = r.e end
        return out
    end

    function Cache.changelogNewest(list)
        local s = Cache.changelogSorted(list)
        return s[1] and s[1].version or nil
    end

    -- WHAT TO SHOW ON LOAD. Returns the entries (newest first) and why:
    --   "update" -- the last seen version is known: everything newer than it
    --   "first"  -- nothing (valid) was ever stored: only the entries at the newest
    --               version, as a welcome
    --   "none"   -- nothing to show
    --
    -- WHY THE FIRST RUN SHOWS ONLY THE NEWEST ENTRY, AND NOT NOTHING OR EVERYTHING.
    -- With no whats_new.json there is no telling a brand-new player from one who has
    -- used the hub for weeks and simply predates this panel -- the file did not exist
    -- before it. Showing nothing would hide the latest update from exactly the players
    -- who already use the hub; showing the whole history would greet a new player with
    -- a wall of changes to features they have never seen. The newest entry is the one
    -- thing both are most likely not to know about, and it doubles as a hello that says
    -- where to find the rest (Settings). Every entry at that version is included, so an
    -- update written as several entries on one day is shown whole.
    --
    -- A seen version NEWER than anything here (the file was written by a higher tier,
    -- whose premium entries this build does not have) is simply "nothing unseen".
    function Cache.changelogUnseen(list, seen)
        local sorted = Cache.changelogSorted(list)
        if #sorted == 0 then return {}, "none" end
        local out = {}
        if Cache.changelogParseVersion(seen) then
            for _, e in ipairs(sorted) do
                if Cache.changelogCompare(e.version, seen) > 0 then out[#out + 1] = e end
            end
            return out, (#out > 0 and "update" or "none")
        end
        local newest = sorted[1].version
        for _, e in ipairs(sorted) do
            if Cache.changelogCompare(e.version, newest) == 0 then out[#out + 1] = e end
        end
        return out, "first"
    end

    -- whats_new.json holds { seen = "<version>" }; anything else reads as never seen,
    -- which is the first-run welcome -- the gentlest thing a damaged file can cause
    function Cache.changelogSeenFromData(data)
        if type(data) == "table" and Cache.changelogParseVersion(data.seen) then return data.seen end
        return nil
    end
    function Cache.changelogSeenToData(version)
        return { seen = version }
    end

    -- "2026.09.27" -> "27 Sep 2026" when it is a plausible date; anything else as given
    local MONTHS = { "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" }
    function Cache.changelogDateText(v)
        local p = Cache.changelogParseVersion(v)
        if p and #p == 3 and p[1] >= 2000 and MONTHS[p[2]] and p[3] >= 1 and p[3] <= 31 then
            return string.format("%d %s %d", p[3], MONTHS[p[2]], p[1])
        end
        return tostring(v)
    end

    -- one entry as the panel prints it: a heading, and its lines as bullets
    function Cache.changelogFormat(entry)
        local body = {}
        for i, l in ipairs(entry.lines or {}) do body[i] = "• " .. l end
        return entry.title .. "  ·  " .. Cache.changelogDateText(entry.version), table.concat(body, "\n")
    end

    -- the line under the title bar, which says why the panel opened
    function Cache.changelogSubtitle(mode, count)
        if mode == "first" then
            return "Welcome! Here is the latest update. Every past update is under Settings, “Show What's New”."
        elseif mode == "update" then
            return string.format("%d new since you last looked.", count or 0)
        end
        return "Recent updates, newest first."
    end

    -- HOW TALL THE LIST SHOULD BE, estimated, because the panel has to size its scroll
    -- area before the text has been laid out. A fixed height leaves a one-entry welcome
    -- floating in empty space; no cap lets a long history run off the screen. About 50
    -- characters fit on a line of the 380-pixel panel at this text size.
    function Cache.changelogEstimateHeight(entries, maxH)
        local h = 0
        for _, e in ipairs(entries) do
            h += 26
            for _, l in ipairs(e.lines or {}) do h += 15 * math.max(1, math.ceil((#l + 2) / 50)) end
            h += 8
        end
        return math.clamp(h, 40, maxH or 320)
    end
end
-- ==== end of CHANGELOG =======================================================
-- ==================== SECTION: TAB Vending ====================
-- THE MARKET TAB (order 25, between Shop and Chest): other people's shops. The Shop
-- tab was 85 controls -- the biggest in the script -- and it was two tabs living as
-- one: YOUR wall (stock it, tidy it, price it, see what sold) and the MARKET (the
-- Price Book, the crawler, Market Watch and Best Deals). Shop keeps the first; this
-- tab takes the second. Created here, the self-creating arrangement the Queue and
-- Debug tabs use, because 100 is the first market part and ships in every tier; 105
-- and 124 (both with premium-only pieces) append to it, so a cut leaves no dead entry.
Cache.MarketTab = Window:CreateTab("Market", "\u{21C4}", 25)
Cache.MarketTab:CreateSection("Price Book")
Cache.MarketTab:CreateNote("What the scanner has seen in other people's shops: each item's prices and where. Your own island is left out on purpose.")
Cache.MarketTab:CreateButton({ Name = "Scan & Save Prices To Book", Callback = function()
    task.spawn(function()
        local n, ownSeen = Cache.capturePricesToBook(nil)  -- nil = fresh scan of this island
        local msg
        if n > 0 then
            msg = string.format("Saved %d item price(s). Book now has %d entries.", n, Cache.priceBookCount())
        elseif (ownSeen or 0) > 0 then
            msg = string.format("0 new — the %d vend(s) in range are on YOUR island (excluded, so you don't undercut yourself). The book has %d competitor entries. Scan on OTHER shops to add more.", ownSeen, Cache.priceBookCount())
        else
            msg = string.format("0 new — no priced competitor vends in range. Walk into a shop to add entries. Book has %d entries.", Cache.priceBookCount())
        end
        Window:Notify({Title="Price Book", Content=msg, Duration=8})
    end)
end})
-- these three persist automatically (config.json data.shop) — losing your undercut/
-- floor between sessions made Auto Reprice silently reprice at 1:1
-- AND THEY HAVE TO COME BACK ON SCREEN, not just into State. 032 restores the saved
-- numbers before this part runs, but a box created with no CurrentValue draws empty --
-- so a saved 10% undercut looked exactly like an unset one. The owner retypes it, or
-- worse, focuses the empty box and tabs out, which writes the blank back as 0 and
-- silently un-does the save. Seed each box from what was restored. A zero/blank knob
-- still shows its placeholder rather than a literal "0", because "0 = copy exactly"
-- is the sentence that explains it.
Cache.MarketTab:CreateInput({ Name = "Undercut % (sell prices)", PlaceholderText = "0 = copy exactly",
    CurrentValue = (tonumber(State.PriceBookUndercut) or 0) > 0 and tostring(State.PriceBookUndercut) or "",
    Callback = function(v)
    -- clamp: >=100 would floor every sell price to 1 coin, negatives are a markup typo
    State.PriceBookUndercut = math.clamp(tonumber(v) or 0, 0, 90)
    task.spawn(function() if Cache.saveHubConfig then Cache.saveHubConfig() end end)
end})
Cache.MarketTab:CreateInput({ Name = "Overcut % (buy prices)", PlaceholderText = "0 = copy exactly",
    CurrentValue = (tonumber(State.PriceBookOvercut) or 0) > 0 and tostring(State.PriceBookOvercut) or "",
    Callback = function(v)
    -- outbid other buyers on your BUY vends; clamp so a typo can't 10x your bids
    State.PriceBookOvercut = math.clamp(tonumber(v) or 0, 0, 100)
    task.spawn(function() if Cache.saveHubConfig then Cache.saveHubConfig() end end)
end})
Cache.MarketTab:CreateInput({ Name = "Min Sell Price (floor)", PlaceholderText = "e.g. 10K — 0/blank = none",
    CurrentValue = tostring(State.PriceBookMinPrice or ""),
    Callback = function(v)
    State.PriceBookMinPrice = v  -- parsed with parsenum (supports K/M/B) at apply time
    task.spawn(function() if Cache.saveHubConfig then Cache.saveHubConfig() end end)
end})
-- WHOSE PRICES. By default the book's, which is the best price seen anywhere and the
-- thing to undercut. Pick a shop and you follow that shop instead -- see the note on
-- Cache.priceForVend for why the cheapest price on the island is often the worst one
-- to copy. The undercut and floor still apply on top, so "three percent under the big
-- shop" is a shop picked here and 3 in the box above.
--
-- The list comes from the per-shop rows the scanner already keeps, so it is whatever
-- you have scanned or crawled -- and owner ids are resolved to names, which yields,
-- which is why it fills in on a thread instead of blocking the tab being built.
do
    local ShopDropdown
    local ALL = "All shops (best price)"
    local function fillShops(notify)
        task.spawn(function()
            local rows, opts = Cache.priceBookShops(), { ALL }
            Cache.PriceBookShopByLabel = {}
            for _, r in ipairs(rows) do
                local label = string.format("%s  (%d item(s))", Cache.shopPickLabel(r.owner, r.islandOwner), r.items)
                -- two unknown shops whose ids share eight characters must not collapse
                if Cache.PriceBookShopByLabel[label] then label = label .. " #" .. (#opts + 1) end
                Cache.PriceBookShopByLabel[label] = r.owner
                opts[#opts + 1] = label
            end
            if ShopDropdown then ShopDropdown:Refresh(opts, ALL) end
            State.PriceBookShop = nil
            if notify then
                Window:Notify({Title="Price Book", Content=#rows == 0
                    and "No shops scanned yet — walk into one and press 'Scan & Save Prices To Book', or run the crawler."
                    or (#rows .. " shop(s) seen. The pick is back to every shop."), Duration=6})
            end
        end)
    end
    ShopDropdown = Cache.MarketTab:CreateDropdown({ Name = "Copy Prices From Shop",
        Options = { ALL }, CurrentOption = { ALL }, Callback = function(v)
        local pick = type(v) == "table" and v[1] or v
        State.PriceBookShop = (pick and pick ~= ALL) and Cache.PriceBookShopByLabel[pick] or nil
    end})
    Cache.MarketTab:CreateButton({ Name = "Refresh Shop List", Callback = function() fillShops(true) end})
    fillShops(false)
end
Cache.MarketTab:CreateButton({ Name = "Apply Book Prices To My Vends", Callback = function()
    if Cache.priceBookCount() == 0 then
        Window:Notify({Title="Price Book", Content="Book is empty — scan a shop and save its prices first.", Duration=4})
        return
    end
    if Cache.selEmpty("Price Book") then return end
    task.spawn(Cache.applyPriceBook)
end})
Cache.MarketTab:CreateButton({ Name = "Export Price Book (CSV for Sheets/Excel)", Callback = function()
    if not writefile then
        Window:Notify({Title="Export", Content="Your executor can't write files.", Duration=4}); return
    end
    if Cache.priceBookCount() == 0 then
        Window:Notify({Title="Export", Content="Book is empty — scan & save some prices first.", Duration=4}); return
    end
    local count, path, whole, onDisk, expected = Cache.exportPriceBookCSV()
    if count then
        -- SAY WHICH SHAPE THIS IS. The two exports differ by a factor of twenty and the
        -- names did not say so: this one is ONE ROW PER ITEM, the cheapest sell and the
        -- dearest buy seen anywhere, so thousands of shop listings collapse into a few
        -- hundred rows. Reported as a shortfall ("when I download there aren't nearly
        -- as many") and it was working exactly as built -- the per-shop rows are the
        -- other button. A count beside the listing total is what tells them apart.
        Window:Notify({Title="Exported", Content=string.format(
            "%d row(s) written to %s\nOne row per ITEM (best price seen anywhere). For one row per SHOP — every owner, price and stock — use Export Full Market instead; the book holds %d of those.%s",
            count, path, Cache.priceListingsCount(),
            (whole == false) and string.format("\n\nWARNING: only %d of %d bytes reached the file. Your executor truncated the write, so the CSV is incomplete.", onDisk or 0, expected or 0) or ""), Duration=14})
    else
        Window:Notify({Title="Export", Content="Write failed.", Duration=4})
    end
end})
-- Full market export: one row per SHOP per item (owner, price, stock) — see who sells
-- what at what price so you can undercut precisely.
Cache.MarketTab:CreateButton({ Name = "Export Full Market (CSV, per shop + owner)", Callback = function()
    if not writefile then
        Window:Notify({Title="Market Export", Content="Your executor can't write files.", Duration=4}); return
    end
    if Cache.priceListingsCount() == 0 then
        Window:Notify({Title="Market Export", Content="No shop data yet — scan shops (Scan & Save / Auto Reprice) first.", Duration=5}); return
    end
    task.spawn(function()
        Window:Notify({Title="Market Export", Content="Resolving shop owners and writing CSV...", Duration=4})
        local count, path, whole, onDisk, expected = Cache.exportPriceListingsCSV()
        -- AND STRAIGHT INTO THE SHEET, if the owner asked for that. The download is a
        -- file on a machine; the spreadsheet is where the numbers get read. Nothing
        -- happens without a deployed endpoint, so this is silent for everyone else.
        if count and count > 0 and Cache.SheetsCfg and Cache.SheetsCfg.auto and Cache.sheetsUpload then
            task.spawn(function()
                local ok, msg = Cache.sheetsUpload(readfile(path), "Market")
                Window:Notify({Title="Google Sheet", Content=(ok and "Updated. " or "Not updated. ") .. tostring(msg), Duration=12})
            end)
        end
        if count and count > 0 then
            Window:Notify({Title="Market Exported", Content=string.format(
                "%d shop listing(s) written to %s (%s)\nOpen in Google Sheets/Excel.%s",
                count, path, (onDisk and (math.floor(onDisk / 1024) .. "KB")) or "size unknown",
                (whole == false) and string.format("\n\nWARNING: only %d of %d bytes reached the file. Your executor truncated the write, so rows are MISSING from the end — that is the file being short, not the scan.", onDisk or 0, expected or 0) or ""), Duration=14})
        else
            Window:Notify({Title="Market Export", Content="Nothing to export / write failed.", Duration=4})
        end
    end)
end})
Cache.MarketTab:CreateDivider()
-- Auto Reprice: scan nearby vends -> update the book -> reprice your own vends, on a
-- loop. Set it, walk your shop past competitors, and your prices stay just under
-- theirs automatically. Vends already at the right price are skipped (no spam).
-- Saved like the three knobs above it, and seeded from the saved value — the pace you
-- chose is tuning, and an interval that quietly reset to 15s every inject is the same
-- forgotten-knob bug. queueFarmSave, not a direct write: a slider fires its callback
-- on every frame of a drag, and one writefile per frame is how you stutter the game.
Cache.MarketTab:CreateSlider({ Name = "Auto Reprice Interval", Step=1, Range={5,120}, Increment=1, Suffix="s",
    CurrentValue=math.clamp(tonumber(State.PriceBookInterval) or 15, 5, 120),
    Callback=function(v) State.PriceBookInterval = v; Cache.queueFarmSave() end})
Cache.MarketTab:CreateToggle({ Name = "Auto Reprice (scan + undercut loop)", CurrentValue=false, Callback=function(v)
    State.PriceBookAutoEnabled = v
    if v then
        State.PriceBookGen = (State.PriceBookGen or 0) + 1
        local gen = State.PriceBookGen
        Window:Notify({Title="Auto Reprice", Content="On — rescanning nearby vends and keeping your prices under the competition.", Duration=5})
        addloop(task.spawn(function()
            while State.PriceBookAutoEnabled and gen == State.PriceBookGen do
                -- capture nearby shops into the book, then reprice our own vends
                pcall(function() Cache.capturePricesToBook(nil) end)
                if Cache.priceBookCount() > 0 then
                    pcall(function() Cache.applyPriceBook(true) end)  -- quiet
                end
                local wait = math.max(5, tonumber(State.PriceBookInterval) or 15)
                for _ = 1, wait do
                    if not State.PriceBookAutoEnabled or gen ~= State.PriceBookGen then break end
                    task.wait(1)
                end
            end
        end))
    end
end})

-- THE BOOK'S OWN BUTTONS, WITH THE BOOK. These sat in 110 with the vending actions,
