-- (the whole part is one do-block: none of its locals is read by any other part, and
-- Luau's main chunk has 200 registers -- released here instead of held to the end)
do
    FarmingTab:CreateSection("Farm Land")
    FarmingTab:CreateNote("Plows, or un-plows, the ground around you as you walk.")
    FarmingTab:CreateToggle({ Name="Plow Aura", CurrentValue=false, Callback=function(v)
        State.PlowAuraEnabled = v
        if v then
            -- mutually exclusive with Un-Plow Aura (they'd fight over the same tiles)
            if State.UnplowAuraEnabled then
                local tf = Cache.ToggleFunctions["Un-Plow Aura"]
                if tf then task.defer(tf, false) else State.UnplowAuraEnabled = false end
            end
            State.PlowAuraGen += 1; local gen = State.PlowAuraGen
            Cache.PlowAuraThread = addloop(task.spawn(function()
                -- 030's NET is the folder; ten seconds for the remote, then the aura
                -- switches itself off and says why instead of hanging this thread
                -- forever behind a toggle that reads as on
                local PLOW_REQ = NET:WaitForChild("CLIENT_PLOW_BLOCK_REQUEST", 10)
                if not PLOW_REQ then
                    Cache.notify({Title="Plow Aura", Content="The game's plow remote was not found — it has probably been renamed in an update. Press 'Check For Updates'.", Duration=8})
                    State.PlowAuraEnabled = false
                    local off = Cache.ToggleFunctions["Plow Aura"]
                    if off then task.defer(off, false) end
                    return
                end
                while State.PlowAuraEnabled and gen == State.PlowAuraGen do
                    pcall(function()
                        local char = LocalPlayer.Character
                        local hrp  = char and char:FindFirstChild("HumanoidRootPart"); if not hrp then return end
                        local r2 = Settings.PlowRadius * 2
                        local op = OverlapParams.new()
                        op.FilterType = Enum.RaycastFilterType.Exclude
                        op.FilterDescendantsInstances = {char}
                        op.MaxParts = 100000  -- default 20 truncated the scan
                        local parts = Workspace:GetPartBoundsInBox(
                            CFrame.new(hrp.Position), Vector3.new(r2,r2,r2), op)
                        for i, v2 in ipairs(parts) do
                            if v2.Name == "grass" then Cache.fireInvoke(PLOW_REQ, {["block"] = v2}) end
                            if i % 30 == 0 then task.wait() end
                        end
                    end)
                    task.wait(0.3)
                end
            end))
        else
            Cache.PlowAuraThread = Cache.stoploop(Cache.PlowAuraThread)
        end
    end})
    FarmingTab:CreateSlider({ Name="Plow Radius", Step=1, Range={5,50}, Increment=1, Suffix="", CurrentValue=Settings.PlowRadius, Callback=function(v) Settings.PlowRadius = v end})
    -- Un-Plow: no reverse remote exists, but breaking a "soil" block reverts the tile.
    -- hitblock has no blacklist check (soil is only blacklisted at the nuke call sites),
    -- so firing it straight at soil parts un-plows. Mirrors the Plow Aura loop/radius.
    FarmingTab:CreateToggle({ Name="Un-Plow Aura", CurrentValue=false, Callback=function(v)
        State.UnplowAuraEnabled = v
        if v then
            -- plow + un-plow together would fight (grass->soil->grass forever)
            if State.PlowAuraEnabled then
                local tf = Cache.ToggleFunctions["Plow Aura"]
                if tf then task.defer(tf, false) else State.PlowAuraEnabled = false end
            end
            State.UnplowAuraGen += 1; local gen = State.UnplowAuraGen
            Cache.UnplowAuraThread = addloop(task.spawn(function()
                while State.UnplowAuraEnabled and gen == State.UnplowAuraGen do
                    pcall(function()
                        local char = LocalPlayer.Character
                        local hrp  = char and char:FindFirstChild("HumanoidRootPart"); if not hrp then return end
                        local r2 = Settings.PlowRadius * 2
                        local op = OverlapParams.new()
                        op.FilterType = Enum.RaycastFilterType.Exclude
                        op.FilterDescendantsInstances = {char}
                        op.MaxParts = 100000  -- default 20 truncated the scan
                        local parts = Workspace:GetPartBoundsInBox(
                            CFrame.new(hrp.Position), Vector3.new(r2,r2,r2), op)
                        for i, v2 in ipairs(parts) do
                            if v2.Name == "soil" then hitblock(v2, v2) end
                            if i % 30 == 0 then task.wait() end
                        end
                    end)
                    task.wait(0.3)
                end
            end))
        else
            Cache.UnplowAuraThread = Cache.stoploop(Cache.UnplowAuraThread)
        end
    end})

    FarmingTab:CreateSection("Trees")
    FarmingTab:CreateNote("Moves you to the trees of the chosen types and chops them.")
    CreateMultiDropdown(FarmingTab, {
        Name="Select Tree Type",
        Options={"All","Oak","Birch","Pine","Maple","Hickory","Spirit","Cherry Blossom","Apple","Orange","Lemon","Plum","Avocado","Coconut"},
        CurrentOption={"All"}, Callback=function(v) State.TreeAuraSelectedTree = v end,
    })
    FarmingTab:CreateToggle({ Name="Tween to Tree",  CurrentValue=false, Callback=function(v) State.TreeAuraTweenEnabled = v end})
    FarmingTab:CreateSlider({ Name="Tween Speed (plow / water)",     Step=1, Range={10,28}, Increment=1, Suffix="", CurrentValue=Settings.TreeTweenSpeed, Callback=function(v) Settings.TreeTweenSpeed = v end})
    FarmingTab:CreateSlider({ Name="Tween Radius", Step=1, Range={5,500}, Increment=1, Suffix="", CurrentValue=Settings.TreeAuraRadius, Callback=function(v) Settings.TreeAuraRadius = v end})
    FarmingTab:CreateDivider()
    FarmingTab:CreateToggle({ Name="Tree Aura", CurrentValue=false, Callback=function(v)
        State.TreeAuraEnabled = v
        if v then
            State.TreeAuraGen += 1; local gen = State.TreeAuraGen
            Cache.enableNoclip("tree")
            Cache.TreeAuraThread = addloop(task.spawn(function()
                while State.TreeAuraEnabled and gen == State.TreeAuraGen do pcall(treeaura); task.wait(0.05) end
            end))
        else
            Cache.TreeAuraThread = Cache.stoploop(Cache.TreeAuraThread)
            Cache.disableNoclip("tree")
            -- also stop the movement tween: it runs independently of the cancelled thread
            -- and used to keep dragging the character to the last tree for up to ~50s
            if Cache.TreeTween then pcall(function() Cache.TreeTween:Cancel() end); Cache.TreeTween = nil end
            Cache.TreeTweenTarget = nil
        end
    end})

    do -- Totem Upgrader (scoped so its locals don't count against the 200-local chunk limit)
    FarmingTab:CreateSection("Totem Upgrader (Improved)")
    FarmingTab:CreateNote("Upgrades the totems on the island to the levels set below.")
    -- NOTE: getTotemPathLevel() below reads the totem's level from GUESSED attribute/child
    -- names. Until verified against a real totem (run the inspector), it may read every
    -- totem as level 0 and re-upgrade maxed ones. Confirmed reads = accurate caps.

    State.SelectedTotemCategories = State.SelectedTotemCategories or {"All Pineapples"}
    State.SelectedPaths    = State.SelectedPaths or {"quality", "efficiency", "utility"}
    State.TargetQuality    = State.TargetQuality or 53
    State.TargetEfficiency = State.TargetEfficiency or 53
    State.TargetUtility    = State.TargetUtility or 53

    -- Group all totems by category each scan (fresh, so no manual refresh needed)
    local function getGroupedTotems()
        local groups = {
            ["All Pineapples"]   = {},
            ["All Carrots"]      = {},
            ["All Wheat"]        = {},
            ["All Iron"]         = {},
            ["All Gold"]         = {},
            ["All Ore Totems"]   = {},
            ["All Other Crops"]  = {},
        }
        local islands = Workspace:FindFirstChild("Islands")
        if not islands then return groups end
        local scanned = 0
        for _, island in ipairs(islands:GetChildren()) do
            local blocks = island:FindFirstChild("Blocks")
            if blocks then
                for _, obj in ipairs(blocks:GetChildren()) do
                    -- yield every 400 blocks: on a busy server this walks tens of thousands
                    -- of parts, and doing it in one frame is what caused the totem lag spike
                    scanned += 1
                    if scanned % 400 == 0 then task.wait() end
                    local name = obj.Name:lower()
                    if name:find("totem") then
                        if name:find("pineapple") then
                            table.insert(groups["All Pineapples"], obj)
                        elseif name:find("carrot") then
                            table.insert(groups["All Carrots"], obj)
                        elseif name:find("wheat") then
                            table.insert(groups["All Wheat"], obj)
                        elseif name:find("iron") then
                            table.insert(groups["All Iron"], obj)
                            table.insert(groups["All Ore Totems"], obj)
                        elseif name:find("gold") then
                            table.insert(groups["All Gold"], obj)
                            table.insert(groups["All Ore Totems"], obj)
                        elseif name:find("rock") or name:find("ore") or name:find("coal")
                            or name:find("copper") or name:find("emerald") or name:find("ruby")
                            or name:find("diamond") or name:find("obsidian") or name:find("crystal")
                            or name:find("stone") then
                            -- coal (and every other ore) used to fall through to "Other Crops",
                            -- which both hid it from the Ore category AND fired it as
                            -- totem_crop — the server rejected every upgrade ("can't level a
                            -- coal totem"). All ore-ish names now land here.
                            table.insert(groups["All Ore Totems"], obj)
                        else
                            table.insert(groups["All Other Crops"], obj)
                        end
                    end
                end
            end
        end
        return groups
    end

    -- Best-effort level read. Returns 0 if the game stores levels another way (safe fallback = uncapped).
    local function getTotemPathLevel(totem, path)
        if not totem then return 0 end
        local attrName = path:sub(1,1):upper() .. path:sub(2) .. "Level"
        local level = totem:GetAttribute(attrName) or totem:GetAttribute(path .. "Level") or 0
        if level > 0 then return level end
        local child = totem:FindFirstChild(attrName) or totem:FindFirstChild(path .. "Level")
        if child and (child:IsA("IntValue") or child:IsA("NumberValue")) then return child.Value end
        local config = totem:FindFirstChild("Configuration") or totem:FindFirstChild("config")
        if config then
            local c = config:FindFirstChild(attrName) or config:FindFirstChild(path .. "Level")
            if c and (c:IsA("IntValue") or c:IsA("NumberValue")) then return c.Value end
        end
        level = totem:GetAttribute("Level") or 0
        if level > 0 then return level end
        return 0
    end

    CreateMultiDropdown(FarmingTab, {
        Name = "Select Totem Categories",
        Options = {"All Pineapples", "All Carrots", "All Wheat", "All Iron", "All Gold", "All Ore Totems", "All Other Crops"},
        CurrentOption = {"All Pineapples"},
        Callback = function(selected) State.SelectedTotemCategories = selected or {} end
    })

    FarmingTab:CreateSlider({ Name="Upgrade Delay (0=fastest)", Step=0.01, Range={0,0.3}, Increment=0.01, Suffix="s", CurrentValue=Settings.TotemActionDelay, Callback=function(v) Settings.TotemActionDelay = v end})
    FarmingTab:CreateSlider({ Name="Target Quality Level",    Step=1, Range={0,53}, Increment=1, Suffix="", CurrentValue=State.TargetQuality,    Callback=function(v) State.TargetQuality = v end})
    FarmingTab:CreateSlider({ Name="Target Efficiency Level", Step=1, Range={0,53}, Increment=1, Suffix="", CurrentValue=State.TargetEfficiency, Callback=function(v) State.TargetEfficiency = v end})
    FarmingTab:CreateSlider({ Name="Target Utility Level",    Step=1, Range={0,53}, Increment=1, Suffix="", CurrentValue=State.TargetUtility,    Callback=function(v) State.TargetUtility = v end})

    FarmingTab:CreateDropdown({
        Name = "Paths to Upgrade",
        Options = {"All 3 Paths", "Quality Only", "Efficiency Only", "Utility Only"},
        CurrentOption = {"All 3 Paths"},
        Callback = function(v)
            local choice = type(v) == "table" and v[1] or v
            if choice == "Quality Only" then State.SelectedPaths = {"quality"}
            elseif choice == "Efficiency Only" then State.SelectedPaths = {"efficiency"}
            elseif choice == "Utility Only" then State.SelectedPaths = {"utility"}
            else State.SelectedPaths = {"quality", "efficiency", "utility"} end
        end
    })

    FarmingTab:CreateToggle({
        Name = "Auto Upgrade Selected Categories",
        CurrentValue = false,
        Callback = function(v)
            State.AutoTotemUpgradeEnabled = v
            if v then
                if not Remotes.UpgradeBlock then
                    State.AutoTotemUpgradeEnabled = false
                    Window:Notify({Title="Totem Upgrader", Content="UpgradeBlock remote not found — can't upgrade. Run the totem inspector to confirm the real remote name.", Duration=6})
                    return
                end
                Cache.TotemDone = {}  -- fresh run: forget how much we've already fired
                State.TotemUpgradeGen = (State.TotemUpgradeGen or 0) + 1
                local gen = State.TotemUpgradeGen
                addloop(task.spawn(function()
                    -- SPEED: the old loop fired ONE level per totem per pass with a 2.5s
                    -- pass wait + 3.5s bursts (~1 level/sec globally = 20h for 500 totems).
                    -- Now we fire the whole REMAINING batch per totem/path each pass,
                    -- self-throttled by the bounded fireInvoke cap (fires as fast as the
                    -- server accepts, backs off when it saturates). A per-totem fired-count
                    -- cap stops us re-spamming maxed totems when the level read is unreliable.
                    --
                    -- ANTI-LAG: getGroupedTotems() walks every block on every island. Running
                    -- it every pass froze the client for players with lots of totems (the
                    -- "lags, only starts after a few minutes" report). Scan once, reuse the
                    -- list for ~10s, and yield periodically while firing so a fast server
                    -- can't run hundreds of invokes in a single frame.
                    local totems = {}
                    local lastScan = -1e9
                    while State.AutoTotemUpgradeEnabled and gen == State.TotemUpgradeGen do
                        local didWork = false
                        if tick() - lastScan > 10 then
                            lastScan = tick()
                            local groups = getGroupedTotems()
                            local list, seen = {}, {}
                            for _, category in ipairs(State.SelectedTotemCategories) do
                                if groups[category] then
                                    for _, totem in ipairs(groups[category]) do
                                        if not seen[totem] then seen[totem] = true; table.insert(list, totem) end
                                    end
                                end
                            end
                            totems = list
                        end
                        pcall(function()
                            local baseDelay = Settings.TotemActionDelay or 0
                            local fireCount = 0
                            for _, totem in ipairs(totems) do
                                if not (State.AutoTotemUpgradeEnabled and gen == State.TotemUpgradeGen) then break end
                                if not totem.Parent then continue end
                                local done = Cache.TotemDone[totem]
                                if not done then done = {}; Cache.TotemDone[totem] = done end
                                local lname = totem.Name:lower()
                                -- ore-ish totems (incl. coal!) must fire as totem_rock — coal
                                -- used to classify as totem_crop and every upgrade was rejected
                                local isOre = lname:find("iron") or lname:find("gold") or lname:find("rock")
                                    or lname:find("ore") or lname:find("coal") or lname:find("copper")
                                    or lname:find("emerald") or lname:find("ruby") or lname:find("diamond")
                                    or lname:find("obsidian") or lname:find("crystal") or lname:find("stone")
                                local totemType = isOre and "totem_rock" or "totem_crop"
                                for _, path in ipairs(State.SelectedPaths) do
                                    if not (State.AutoTotemUpgradeEnabled and gen == State.TotemUpgradeGen) then break end
                                    local target = 53
                                    if path == "quality" then target = State.TargetQuality
                                    elseif path == "efficiency" then target = State.TargetEfficiency
                                    elseif path == "utility" then target = State.TargetUtility end
                                    local fired = done[path] or 0
                                    local currentLevel = getTotemPathLevel(totem, path)
                                    if currentLevel >= target then done[path] = math.huge; continue end  -- confirmed maxed
                                    -- OBEY THE TARGET: total fires per totem/path can never
                                    -- exceed it. The old logic recomputed batch = target -
                                    -- currentLevel every pass, and with an unreliable level
                                    -- read (always 0) it re-fired the full target every pass
                                    -- until a +15 buffer tripped — ~3x overshoot ("doesn't
                                    -- listen to the levels you set"). Now `fired` acts as the
                                    -- floor of the real level, so we send exactly the missing
                                    -- amount and stop.
                                    local remaining = target - math.max(currentLevel, fired)
                                    if remaining <= 0 then continue end
                                    for _ = 1, remaining do
                                        if not (State.AutoTotemUpgradeEnabled and gen == State.TotemUpgradeGen) then break end
                                        if Cache.fireInvoke(Remotes.UpgradeBlock, totem, totemType, path) then
                                            fired += 1; didWork = true; fireCount += 1
                                            if baseDelay > 0 then task.wait(baseDelay)
                                            elseif fireCount % 25 == 0 then task.wait() end  -- yield so a fast server can't freeze the frame
                                        else
                                            task.wait(0.1)  -- outstanding cap hit: server saturated, ease off
                                        end
                                    end
                                    done[path] = fired
                                end
                            end
                        end)
                        task.wait(didWork and 0.3 or 1.5)
                    end
                end))
            end
        end
    })
    end -- end Totem Upgrader scope
end
-- ==================== SECTION: TAB Build ====================
-- everything in the build tab
local BlueprintDD, ReplaceSourceDropdown, ReplaceWithDropdown
local AllBlockTypes = {}

local function updaterequiredblocksui()
    if not RequiredBlocksLabel then return end
    if not Cache.LoadedBlueprintData then RequiredBlocksLabel.Text = "No blueprint loaded."; return end
    local InvCounts = Cache.countInventory()
    local counts = {}
    for _, block in ipairs(Cache.LoadedBlueprintData) do
        if not (State.BlueprintRemoveEnabled and State.BlueprintRemovals[block.blockType]) then
            -- MATCH WHAT THE ENGINES ACTUALLY PLACE. Every other reader of the
            -- replacement map gates on BlueprintReplaceEnabled and maps dirt to grass;
            -- this panel did neither, so it was the one place that disagreed with the
            -- build. With replacements configured but the toggle OFF it told you to
            -- farm the substitute while the build placed the original, and on any
            -- blueprint containing dirt it demanded dirt -- a material the build never
            -- asks the server for, because both engines send grass.
            local bType = block.blockType
            if State.BlueprintReplaceEnabled and State.BlueprintReplacements[bType] then
                bType = State.BlueprintReplacements[bType]
            end
            if bType == "dirt" then bType = "grass" end
            if not IsBlacklisted(bType) then counts[bType] = (counts[bType] or 0) + 1 end
        end
    end
    local sorted = {}
    local nTypes, nBlocks = 0, 0
    for name, count in pairs(counts) do
        table.insert(sorted, {name=name, count=count}); nTypes += 1; nBlocks += count
    end
    table.sort(sorted, function(a,b) return a.count > b.count end)
    -- SAY WHICH SUM THIS IS, AND SAY HOW SHORT. Two things write this panel: this
    -- filler, which counts the WHOLE blueprint, and Check Materials Needed, which
    -- counts what is LEFT to build against what you hold. Either can overwrite the
    -- other on its own -- loading a blueprint, clearing a replacement and six other
    -- callers re-run this one -- so an unlabelled list changed meaning under the
    -- reader with nothing on screen to show it had. The header is what separates them.
    -- The shortfall costs nothing here (both numbers are already in hand) and it is
    -- the number you actually farm against, so a [Need] row now carries it.
    local text = string.format("WHOLE BLUEPRINT — %d type(s), %s block(s)\n\n", nTypes, shortnum(nBlocks))
    local Tools2  = ReplicatedStorage:FindFirstChild("Tools")
    local Blocks2 = ReplicatedStorage:FindFirstChild("Blocks")
    for _, item in ipairs(sorted) do
        local has = InvCounts[item.name] or 0
        local ok  = has >= item.count and "[OK]" or "[Need]"
        local display = fixname(item.name)
        if Tools2 then local T = Tools2:FindFirstChild(item.name); if T then local D = T:FindFirstChild("DisplayName"); if D and D:IsA("StringValue") then display = D.Value end end end
        if display == fixname(item.name) and Blocks2 then local B = Blocks2:FindFirstChild(item.name); if B then local D = B:FindFirstChild("DisplayName"); if D and D:IsA("StringValue") then display = D.Value end end end
        local short = (has >= item.count) and "" or string.format("   short %s", shortnum(item.count - has))
        text = text .. string.format("%s %s: %s / %s%s\n", ok, display, shortnum(has), shortnum(item.count), short)
    end
    RequiredBlocksLabel.Text = text
end

BuildTab:CreateSection("1)  Blueprint — Pick / Load")
BuildTab:CreateNote("Pick the blueprint to build, rename it or delete it.")
BuildTab:CreateInput({ Name="Blueprint Name", PlaceholderText="MyBlueprint", Callback=function(v) State.BlueprintName = v ~= "" and v or "MyBlueprint" end})
BlueprintDD = BuildTab:CreateDropdown({ Name="Select Blueprint", Options=refreshblueprints(), CurrentOption={"None"}, Callback=function(v)
    -- normalize FIRST: Refresh() calls back with {Default} (a table), so comparing the
    -- raw v to a string meant the silent-refresh guard never actually fired, and every
    -- "silent" refresh re-ran loadblueprint. Also map deselect ({}) to "None" —
    -- loadblueprint(nil) used to error on string concat.
    local val = (type(v) == "table" and v[1] or v) or "None"
    if State.IsSilentRefresh and val == State.SelectedBlueprint then return end
    State.SelectedBlueprint = val; loadblueprint(val)
    if Cache.LoadedBlueprintData then
        task.spawn(function()
            if ReplaceSourceDropdown then
                local blockTypes, seen = {}, {}
                for _, block in ipairs(Cache.LoadedBlueprintData) do
                    local d = fixname(block.blockType)
                    if not seen[d] then seen[d] = true; table.insert(blockTypes, d); Cache.ItemNameMap[d] = block.blockType end
                end
                AllBlockTypes = blockTypes
                if #blockTypes > 0 then ReplaceSourceDropdown:Refresh(blockTypes) end
            end
            updaterequiredblocksui()
            if Cache.refreshRemoveTypes then Cache.refreshRemoveTypes() end
        end)
    end
end})
-- THE LIBRARY IS THE WAY TO PICK ONE. The dropdown stays -- every generator, import
