    elseif v then
        Window:Notify({Title="Required Blocks UI", Content="Couldn't build the panel on this executor.", Duration=8})
    end
end})
BuildTab:CreateToggle({ Name="Show Movement UI", CurrentValue=false, Callback=function(v)
    State.ShowMovementUI = v
    -- Rebuild it if it is not standing. A teleport destroys it (see createmovementui),
