-- ==================== SURVIVING A SLOT SWITCH ====================
-- A Build Queue slot switch teleports you to the other island's server, and a
-- teleport ends the script. It carries on only if something runs it again on the
-- other side, and there are exactly two things that can:
--
--   1. queue_on_teleport -- the executor re-runs a line after the teleport. Not every
--      executor has it (several popular free ones do not).
--   2. the executor's AUTOEXEC folder -- a file there runs every time a game starts.
--      Every executor has one.
--
-- The queue only ever used the first. The second was the owner's own autoexec install
-- (243), which is cut from the sold builds -- so on an executor without
-- queue_on_teleport a buyer's queue built one entry, switched slot, and stopped.
--
-- THE RESUME HELPER is the second path made safe for anyone: a small file in autoexec
-- that runs the hub ONLY while a switch is in flight. Before a switch, a timestamp is
-- written to "Islands trading hub/resume.flag"; the helper runs the loader only when
-- that flag is under fifteen minutes old, and every load clears it. Join a game any
-- other time and the helper does nothing at all -- installing it does not turn the hub
-- into something that starts itself.
do
    local FLAG = "Islands trading hub/resume.flag"
    local HELPER = "IslandsHubResume.lua"
    Cache.AUTOEXEC_FOLDERS = { "autoexec", "../autoexec", "autoexecute", "../autoexecute", "auto-exec", "scripts/autoexec" }
    Cache.RESUME_WINDOW = 900

    -- what the helper file holds. The loader line is baked in at install time, so a
    -- key-gated loader that set ISLANDS_HUB_LOADER is the one the resume goes through.
    function Cache.resumeHelperSource(loader)
        return table.concat({
            "-- Islands Trading Hub: resume helper. Runs the hub ONLY while a slot switch or rejoin",
            "-- is in flight (a fresh Islands trading hub/resume.flag), otherwise nothing.",
            "local ok, t = pcall(function()",
            "    return isfile(\"" .. FLAG .. "\") and tonumber(readfile(\"" .. FLAG .. "\"))",
            "end)",
            "if ok and t and os.time() - t >= 0 and os.time() - t < " .. Cache.RESUME_WINDOW .. " then",
            "    if not game:IsLoaded() then game.Loaded:Wait() end",
            "    " .. tostring(loader),
            "end",
        }, "\n")
    end

    function Cache.findResumeHelper()
        if not isfile then return nil end
        for _, f in ipairs(Cache.AUTOEXEC_FOLDERS) do
            local ok, there = pcall(isfile, f .. "/" .. HELPER)
            if ok and there then return f end
        end
        return nil
    end

    -- Returns (true, folder) or (false, reason). Same folder hunt as the owner's
    -- installer: executors disagree on the name, and some run autoexec from one level
    -- above the sandbox writefile is confined to.
    function Cache.installResumeHelper()
        if not writefile then return false, "your executor has no writefile" end
        if not Cache.LOADER_LINE then return false, "no loader line to resume with" end
        local body = Cache.resumeHelperSource(Cache.LOADER_LINE)
        local lastErr = "no autoexec folder was writable"
        for _, f in ipairs(Cache.AUTOEXEC_FOLDERS) do
            pcall(function() if makefolder and not (isfolder and isfolder(f)) then makefolder(f) end end)
            local ok, err = pcall(writefile, f .. "/" .. HELPER, body)
            if ok and (not isfile or isfile(f .. "/" .. HELPER)) then return true, f end
            if not ok then lastErr = tostring(err) end
        end
        return false, lastErr
    end

    function Cache.removeResumeHelper()
        local removed = 0
        for _, f in ipairs(Cache.AUTOEXEC_FOLDERS) do
            if isfile and delfile and pcall(isfile, f .. "/" .. HELPER) and isfile(f .. "/" .. HELPER) then
                if pcall(delfile, f .. "/" .. HELPER) then removed += 1 end
            end
        end
        return removed
    end

    function Cache.writeResumeFlag()
        if not (writefile and isfolder and makefolder) then return false end
        return (pcall(function()
            if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
            writefile(FLAG, tostring(os.time()))
        end))
    end
    function Cache.clearResumeFlag()
        if isfile and delfile then pcall(function() if isfile(FLAG) then delfile(FLAG) end end) end
    end

    -- THE SWITCH ARMS BOTH PATHS, AND ONLY ONE MAY FIRE. With the helper installed the
    -- flag is the whole mechanism, and also queueing on teleport would inject the hub
    -- twice on arrival -- two instances resuming one queue. So the helper, when it is
    -- there, is used instead of queue_on_teleport rather than as well as it.
    local plainQueue = Cache.queueSelfOnTeleport
    function Cache.queueSelfOnTeleport()
        local flagged = Cache.writeResumeFlag()
        if flagged and Cache.findResumeHelper() then return true end
        return plainQueue and plainQueue() or false
    end

    -- every load consumes the flag: it has done its job the moment anything ran us
    Cache.clearResumeFlag()

    -- WILL A SLOT SWITCH COME BACK? Answered before it is needed, not discovered after
    -- the first entry. Returns the verdict and the lines behind it.
    function Cache.resumeReport()
        local lines = {}
        local qot = Cache.findQueueTeleport and Cache.findQueueTeleport() ~= nil
        local helper = Cache.findResumeHelper()
        local custom = false
        pcall(function() custom = type(getgenv) == "function" and type(getgenv().ISLANDS_HUB_LOADER) == "string" end)
        lines[#lines + 1] = "queue_on_teleport: " .. (qot and "yes" or "no (this executor does not have it)")
        lines[#lines + 1] = "Resume Helper: " .. (helper and ("installed (" .. helper .. ")") or "not installed")
        lines[#lines + 1] = "Reloads through: " .. (custom and "your loader (ISLANDS_HUB_LOADER)"
            or ("the " .. tostring(Cache.BUILD_BRANCH or "main") .. " build from the repository"))
        local ok = helper ~= nil or qot
        local verdict
        if helper then
            verdict = "A slot switch WILL resume: the Resume Helper runs the hub on arrival."
        elseif qot then
            verdict = "A slot switch should resume through queue_on_teleport. If it does not, press 'Install Resume Helper' — it works on every executor."
        else
            verdict = "A slot switch will NOT resume: this executor has no queue_on_teleport. Press 'Install Resume Helper' and it will."
        end
        return ok, verdict, lines
    end
end
-- ==================== END SURVIVING A SLOT SWITCH ====================
-- ==== SLOT SWITCH: record, derive and fire the remote ======================
-- Record: spy for `seconds` while the user manually switches to slot `n`; store the
-- LAST captured call (the switch fires right before the reload) for that slot.
function Cache.recordSlotRemote(n, seconds)
    if not Cache.ensureRemoteSpy() then
        Window:Notify({Title="Slot Capture", Content="Your executor lacks hookmetamethod/getnamecallmethod — can't capture. Slot switching stays on GUI mode.", Duration=8})
        return
    end
    Cache.SlotRemotes = Cache.SlotRemotes or {}
    Cache.spyRecordBegin()
    Window:Notify({Title="Slot Capture", Content="Recording " .. (seconds or 20) .. "s — NOW open Profiles and load slot " .. n .. " manually.", Duration=8})
    task.spawn(function()
        local t0 = os.clock()
        local pre = Cache.myIslandModel()
        while os.clock() - t0 < (seconds or 20) do
            task.wait(0.2)
            if pre and not pre.Parent then break end  -- island reloaded = switch happened, stop early
        end
        Cache.spyRecordEnd()
        local log = Cache.SpyLog or {}
        -- auto-pick, scored: LoadProfile is THE switch (field-confirmed);
        -- GetProfiles just fetches the save list and must never win again
        local best, bestScore
        for _, c in ipairs(log) do
            local hay = (c.path or ""):lower()
            for _, a in pairs(c.args or {}) do if type(a) == "string" then hay = hay .. " " .. a:lower() end end
            local score
            if hay:find("loadprofile") then score = 3
            elseif hay:find("profile") or hay:find("slot") or hay:find("save") or hay:find("island") or hay:find("load") then score = 1 end
            if score and hay:find("getprofiles") then score = 0 end
            if score and score > 0 and (not bestScore or score >= bestScore) then best, bestScore = c, score end
        end
        -- fallback: the last call before the reload -- but never GetProfiles
        if not best then
            for k = #log, 1, -1 do
                if not (log[k].path or ""):lower():find("getprofiles") then best = log[k]; break end
            end
        end
        if best then
            Cache.SlotRemotes[tostring(n)] = best
            Cache.saveSlotRemotes()
            Window:Notify({Title="Slot Capture", Content="Captured slot " .. n .. ": " .. tostring(best.path) ..
                " (picked from " .. #log .. " recorded call(s)). Check it with 'Switch To Slot Now'.", Duration=12})
        else
            Window:Notify({Title="Slot Capture", Content="No remote calls captured. Make sure you actually switched the slot during the window.", Duration=8})
        end
    end)
end

-- No recording for slot n? Derive one from ANY recorded slot by swapping the
-- slot number inside the args — record ONCE, switch to every slot. Works when
-- the game passes the slot as a number ({slot = 5}) or a "...5"-style string
-- ("Save5"); instance references and path-like strings are left untouched.
-- 'Test Slot Remote' validates the guess; if the game uses opaque save IDs
-- instead, per-slot recording still works as before.
function Cache.deriveSlotRemote(n)
    local nn = tostring(n)
    for m, rec in pairs(Cache.SlotRemotes or {}) do
        if rec and rec.path and tostring(m) ~= nn then
            local mm = tostring(m)
            local function swap(v)
                if type(v) == "number" and tostring(v) == mm then return tonumber(nn) end
                if type(v) == "string" then
                    if v == mm then return nn end
                    -- "Save5"/"slot 5" style: swap a trailing slot number, but never
                    -- touch dotted instance paths
                    if not v:find("%.") then
                        local s, cnt = v:gsub("(%D)" .. mm .. "$", "%1" .. nn)
                        if cnt > 0 then return s end
                    end
                    return v
                end
                if type(v) == "table" then
                    if v.__inst ~= nil then return v end  -- serialized Instance ref: keep
                    local out = {}
                    for k, val in pairs(v) do out[k] = swap(val) end
                    return out
                end
                return v
            end
            return { path = rec.path, method = rec.method, nargs = rec.nargs, args = swap(rec.args or {}) }
        end
    end
    return nil
end

-- ---- READ THE SLOT LIST INSTEAD OF TYPING NUMBERS -------------------------
-- The Profiles menu is backed by a GetProfiles remote (seen in a live capture --
-- the slot-switch recorder scores it to zero so it can never be mistaken for the
-- LOAD remote). Asking it directly gives us which slots exist, what is on them,
-- and which one you are standing on, so the queue can offer a list instead of
-- asking you to remember slot numbers.
--
-- The reply shape is NOT documented anywhere, so this parses defensively: an
-- array of profiles (index = slot), or a table keyed by slot number, and it
-- accepts any of the obvious field spellings for name/active/empty. Anything it
-- cannot read simply comes back as an unnamed slot -- never an error.
function Cache.readSlotField(rec, names)
    if type(rec) ~= "table" then return nil end
    for _, k in ipairs(names) do
        local v = rec[k]
        if v ~= nil then return v end
    end
    return nil
end

function Cache.parseProfiles(reply)
    local out = {}
    if type(reply) ~= "table" then return out end
    -- some remotes wrap the payload one level down
    local list = reply
    for _, k in ipairs({"profiles", "saves", "slots", "data", "result"}) do
        if type(reply[k]) == "table" then list = reply[k]; break end
    end
    local function add(slot, rec)
        slot = tonumber(slot)
        if not slot or slot < 1 or slot > 50 then return end
        local name = Cache.readSlotField(rec, {"name", "islandName", "island_name", "title", "label", "displayName"})
        local active = Cache.readSlotField(rec, {"active", "isActive", "current", "isCurrent", "loaded", "isLoaded", "selected"})
        local empty = Cache.readSlotField(rec, {"empty", "isEmpty", "unused"})
        -- an entry with no data at all reads as an empty slot
        if empty == nil and type(rec) == "table" and next(rec) == nil then empty = true end
        out[#out + 1] = {
            slot = slot,
            name = type(name) == "string" and name ~= "" and name or nil,
            active = active == true,
            empty = empty == true,
        }
    end
    -- ONE pairs walk covers every shape, and must not be split on `#list`: a table
    -- holding only slots 2, 4 and 5 has a `#` of 0 or 1 depending on where the gaps
    -- fall, so an ipairs branch silently dropped every entry past the first hole --
    -- which is the normal case, since nobody fills their save slots in order.
    -- In an array the key IS the slot number, so the same line handles both, plus
    -- "Save3"/"slot3" style string keys.
    for k, rec in pairs(list) do
        add(tonumber(k) or tostring(k):match("(%d+)"), rec)
    end
    table.sort(out, function(a, b) return a.slot < b.slot end)
    return out
end

-- Ask the server for the save list. Never blocks the caller: the invoke runs in
-- its own thread behind a deadline, like every other RemoteFunction call here.
function Cache.fetchSlots()
    local rem = Cache._findRemote("ReplicatedStorage.rbxts_include.node_modules.@rbxts.net.out._NetManaged.GetProfiles")
    if not rem then return nil, "GetProfiles remote not found (game update?)" end
    local done, ok, reply = false, false, nil
    task.spawn(function()
        ok, reply = pcall(function()
            if rem:IsA("RemoteFunction") then return rem:InvokeServer() end
            rem:FireServer(); return nil     -- an event can't answer us
        end)
        done = true
    end)
    local deadline = tick() + 5
    while not done and tick() < deadline do task.wait() end
    if not done then return nil, "the server didn't answer in 5s" end
    if not ok then return nil, "GetProfiles errored: " .. tostring(reply) end
    if reply == nil then return nil, "GetProfiles is an event here, not a query — it can't report the slots" end
    local slots = Cache.parseProfiles(reply)
    if #slots == 0 then return nil, "the reply held no recognisable slots" end
    Cache.KnownSlots = slots
    -- learning which slot we are ON also stops the queue's first entry doing a
    -- pointless reload onto the island it is already standing on
    for _, sl in ipairs(slots) do
        if sl.active then Cache.BuildQueueCurrentSlot = sl.slot end
    end
    return slots
end

-- dropdown labels: "2 - Main Island (current)" / "5 - (empty)"
function Cache.slotOptions()
    local opts = {}
    for _, sl in ipairs(Cache.KnownSlots or {}) do
        opts[#opts + 1] = string.format("%d%s%s", sl.slot,
            sl.empty and " - (empty)" or (sl.name and (" - " .. sl.name) or ""),
            sl.active and "  (current)" or "")
    end
    if #opts == 0 then opts[1] = "Press 'Detect Island Slots'" end
    return opts
end

-- fire the recorded remote for slot n. returns true if it fired.
function Cache.fireSlotRemote(n)
    -- KNOWN REMOTE (confirmed by a real user capture): the Profiles UI loads a
    -- save via _NetManaged.LoadProfile:FireServer(slotIndex) with a 0-BASED
    -- index — clicking "Save 5" fired args [4]. Try it first: no recording
    -- needed at all. Recordings/derivation stay as fallbacks in case a game
    -- update renames or moves it.
    if Cache.queueSelfOnTeleport then Cache.queueSelfOnTeleport() end  -- survive the slot reload
    local num = tonumber(n)
    if num and num >= 1 then
        local lp = Cache._findRemote("ReplicatedStorage.rbxts_include.node_modules.@rbxts.net.out._NetManaged.LoadProfile")
        if lp and lp:IsA("RemoteEvent") then
            if (pcall(function() lp:FireServer(num - 1) end)) then return true end
        end
    end
    local rec = Cache.SlotRemotes and Cache.SlotRemotes[tostring(n)]
    if not rec or not rec.path then rec = Cache.deriveSlotRemote(n) end
    if not rec or not rec.path then return false end
    local remote = Cache._findRemote(rec.path)
    if not remote then return false end
    local args = {}
    for i = 1, (rec.nargs or 0) do args[i] = Cache._rehydrate(rec.args[i]) end
    if rec.method == "InvokeServer" then
        -- InvokeServer is a RemoteFunction: it BLOCKS until the server replies, and a
        -- rate-limited/dropped slot-switch request would hang the Build Queue thread
        -- forever (a pcall does NOT catch a hang). Fire it in an inner thread and stop
        -- waiting after a deadline — a real slot switch is confirmed by the island
        -- reload the caller watches for, not by this reply.
        local done, ok = false, false
        task.spawn(function()
            ok = pcall(function() remote:InvokeServer(unpack(args, 1, rec.nargs or #args)) end)
            done = true
        end)
        local deadline = tick() + 1.5
        while not done and tick() < deadline do task.wait() end
        -- replied with an error fast -> let the caller try the GUI fallback; still
        -- pending (working or hung) or succeeded -> treat as dispatched, don't freeze
        if done and not ok then return false end
        return true
    else
        -- FireServer is a RemoteEvent: non-blocking, can't hang
        return (pcall(function() remote:FireServer(unpack(args, 1, rec.nargs or #args)) end))
    end
end

