-- selIndex: which entry to leave selected after the refresh (defaults to the first)
function Cache.refreshQueueUI(selIndex)
    if not Cache.QueueDD then return end
    local opts = Cache.buildQueueOptions()
    Cache.QueueDD:Refresh(opts, opts[math.clamp(selIndex or 1, 1, #opts)])
end

