Cache.QueueTab = Window:CreateTab("Queue", "\u{2630}", 52)
Cache.QueueTab:CreateSection("1)  Pick The Island")
Cache.QueueTab:CreateNote("Several blueprints back to back, each at the position it was added, switching island slot between them if asked. Pick a slot first (or leave it blank for the island you are on), then add.")
-- Pick the slot from the game's own save list rather than remembering numbers:
-- Detect fills this dropdown with the slots that exist, names them, and marks the
-- one you are standing on. The typed input below still works if detection fails.
do
    local SlotDD
    Cache.QueueTab:CreateButton({ Name="Detect Island Slots", Callback=function()
        task.spawn(function()
            local slots, why = Cache.fetchSlots()
            if not slots then
                Window:Notify({Title="Slots", Content="Couldn't read your save list — " .. tostring(why)
                    .. ". Type the slot number below instead; auto-switch still works.", Duration=10})
                return
            end
            local opts = Cache.slotOptions()
            -- keep the slot already chosen: Refresh fires the callback with whatever
            -- it is handed, which quietly retargeted the next queue entry to slot 1
            local keep
            for _, o in ipairs(opts) do
                if State.BuildQueueSlotInput and tonumber(tostring(o):match("^(%d+)")) == State.BuildQueueSlotInput then keep = o; break end
            end
            if SlotDD then SlotDD:Refresh(opts, keep) end
            local cur = Cache.BuildQueueCurrentSlot
            Window:Notify({Title="Slots", Content=string.format("Found %d slot(s)%s. Pick one, then add your blueprint to the queue.",
                #slots, cur and (" — you're on slot " .. cur) or ""), Duration=8})
        end)
    end})
    SlotDD = Cache.QueueTab:CreateDropdown({ Name="Island Slot (auto-switch)", Options=Cache.slotOptions(),
        CurrentOption={Cache.slotOptions()[1]}, Callback=function(v)
        local txt = tostring(type(v) == "table" and v[1] or v)
        -- label is "2 - Name (current)"; the leading number is the slot
        State.BuildQueueSlotInput = tonumber(txt:match("^(%d+)"))
        State.BuildQueueSlotList = nil   -- a pick is one slot; a list is typed below
    end})
end
-- Typed fallback, and the way to clear the pick: blank = build on whatever island
-- is loaded, no switching. It also takes SEVERAL slots ("2-4", "2,5"; see
-- parseSlotList in 190): Add and Duplicate then queue one entry per slot, all at the
-- same spot. Everything that needs ONE slot (switch now, record) uses the first.
Cache.QueueTab:CreateInput({ Name="Island Slot # (blank = no switch)", PlaceholderText="blank = current island · 2 · 2-4 · 2,5", Callback=function(v)
    local list, bad = Cache.parseSlotList(v)
    if not list then
        State.BuildQueueSlotInput, State.BuildQueueSlotList = nil, nil
        Window:Notify({Title="Queue", Content="Could not read '" .. tostring(bad) ..
            "' as a slot. Type a slot number, a range like 2-4 or a list like 2,5. Until then entries build on the island you are on.", Duration=8})
        return
    end
    State.BuildQueueSlotInput = list[1]
    State.BuildQueueSlotList = #list > 1 and list or nil
end})

Cache.QueueTab:CreateSection("2)  Add And Arrange")
-- the button's work as a function, so the Blueprint Library's "Queue" can do the same
function Cache.queueAddSelected()
    local name = State.SelectedBlueprint
    if not name or name == "None" or not Cache.LoadedBlueprintData then
        Window:Notify({Title="Queue", Content="Select a blueprint first, then position it with the preview/movement UI.", Duration=4})
        return
    end
    -- With the preview OFF the position should come from where the player is STANDING
    -- right now — but getblueprintstartcframe locks its anchor as a side effect of the
    -- first call, so every later Add would silently reuse the first spot. Clear the
    -- stale lock so each Add recaptures fresh. (Preview ON keeps the locked anchor:
    -- that's the position the user is looking at and adjusting.)
    if not State.BlueprintPreviewEnabled then
        Cache.BlueprintAnchor = nil
        Cache.BlueprintAnchorLocked = false
    end
    -- without a locked anchor the position comes from the character; with no HRP
    -- getblueprintstartcframe silently returns the world origin — refuse that.
    if not (Cache.BlueprintAnchor and Cache.BlueprintAnchorLocked)
    and not (LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")) then
        Window:Notify({Title="Queue", Content="No build position: lock a preview position or stand where it should build.", Duration=4})
        return
    end
    local startCF = getblueprintstartcframe()
    if not startCF then
        Window:Notify({Title="Queue", Content="Could not resolve a build position.", Duration=3})
        return
    end
    -- startCF.Position already includes the preview offset; rotation has to be kept
    -- separately because a locked anchor only preserves its Position (see
    -- getblueprintstartcframe), not its orientation.
    local p = startCF.Position
    local slots = State.BuildQueueSlotList or { State.BuildQueueSlotInput }
    local first = #State.BuildQueue + 1
    for _, e in ipairs(Cache.queueEntriesForSlots({ name = name, pos = {p.X, p.Y, p.Z},
        rot = State.BlueprintPreviewRotationY or 0, origin = Cache.queueOriginNow() }, slots)) do
        table.insert(State.BuildQueue, e)
    end
    Cache.saveBuildQueue()
    Cache.refreshQueueUI(#State.BuildQueue)
    local where = #slots > 1 and (" on slots " .. table.concat(slots, ", "))
        or (State.BuildQueueSlotInput and (" [slot "..State.BuildQueueSlotInput.."]") or "")
    Window:Notify({Title="Queue", Content=string.format("%s: %s%s @ (%d, %d, %d)",
        #State.BuildQueue > first and ("#" .. first .. "–#" .. #State.BuildQueue) or ("#" .. first),
        name, where, math.floor(p.X), math.floor(p.Y), math.floor(p.Z)), Duration=4})
end
Cache.QueueTab:CreateButton({ Name="Add Blueprint To Queue (at preview position)", Callback=function()
    Cache.queueAddSelected()
end})

Cache.QueueDD = Cache.QueueTab:CreateDropdown({ Name="Queue Entries", Options=Cache.buildQueueOptions(),
    CurrentOption={Cache.buildQueueOptions()[1]}, Callback=function(v)
    local s = type(v) == "table" and v[1] or v
    State.BuildQueueSelected = s and tonumber(string.match(tostring(s), "^(%d+)%.")) or nil
end})
-- the dropdown constructor doesn't fire the callback for its initial option, so sync
-- the selection for a queue restored from disk (otherwise Remove/Move need a re-click)
State.BuildQueueSelected = #State.BuildQueue > 0 and 1 or nil

Cache.QueueTab:CreateButton({ Name="Move Selected Up", Callback=function()
    if State.BuildQueueEnabled then
        Window:Notify({Title="Queue", Content="Stop the queue before reordering it.", Duration=3}); return
    end
    local i = State.BuildQueueSelected
    if not i or i <= 1 or i > #State.BuildQueue then return end
    State.BuildQueue[i-1], State.BuildQueue[i] = State.BuildQueue[i], State.BuildQueue[i-1]
    Cache.saveBuildQueue()
    Cache.refreshQueueUI(i - 1)
end})
Cache.QueueTab:CreateButton({ Name="Move Selected Down", Callback=function()
    if State.BuildQueueEnabled then
        Window:Notify({Title="Queue", Content="Stop the queue before reordering it.", Duration=3}); return
    end
    local i = State.BuildQueueSelected
    if not i or i < 1 or i >= #State.BuildQueue then return end
    State.BuildQueue[i+1], State.BuildQueue[i] = State.BuildQueue[i], State.BuildQueue[i+1]
    Cache.saveBuildQueue()
    Cache.refreshQueueUI(i + 1)
end})
Cache.QueueTab:CreateButton({ Name="Remove Selected From Queue", Callback=function()
    if State.BuildQueueEnabled then
        Window:Notify({Title="Queue", Content="Stop the queue before editing it.", Duration=3}); return
    end
    local i = State.BuildQueueSelected
    if not i or not State.BuildQueue[i] then
        Window:Notify({Title="Queue", Content="Select an entry to remove.", Duration=3}); return
    end
    local removed = table.remove(State.BuildQueue, i)
    Cache.saveBuildQueue()
    Cache.refreshQueueUI(i)
    Window:Notify({Title="Queue", Content="Removed '"..removed.name.."'.", Duration=2})
end})
Cache.QueueTab:CreateButton({ Name="Clear Queue", Callback=function()
    if State.BuildQueueEnabled then
        Window:Notify({Title="Queue", Content="Stop the queue before clearing it.", Duration=3}); return
    end
    State.BuildQueue = {}
    Cache.saveBuildQueue()
    Cache.refreshQueueUI()
    Window:Notify({Title="Queue", Content="Queue cleared.", Duration=2})
end})
Cache.QueueTab:CreateButton({ Name="Set Selected Entry's Slot (from input)", Callback=function()
    if State.BuildQueueEnabled then
        Window:Notify({Title="Queue", Content="Stop the queue before editing it.", Duration=3}); return
    end
    local i = State.BuildQueueSelected
    local e = i and State.BuildQueue[i]
    if not e then Window:Notify({Title="Queue", Content="Select an entry first.", Duration=3}); return end
    if State.BuildQueueSlotList then
        Window:Notify({Title="Queue", Content="One entry builds on one slot. To put it on several, press 'Duplicate Selected To Slot (from input)' with the list, then remove the original.", Duration=8})
        return
    end
    -- moving a part-built entry to ANOTHER slot makes it a fresh plan there: its
    -- progress (progress.json) belongs to the island it was interrupted on, and
    -- queueProgressFor cannot tell slots apart -- only names and positions
    if e.slot ~= State.BuildQueueSlotInput then e.started = nil end
    e.slot = State.BuildQueueSlotInput
    Cache.saveBuildQueue()
    Cache.refreshQueueUI(i)
    Window:Notify({Title="Queue", Content=e.slot and ("Entry #"..i.." now builds on slot "..e.slot..".")
        or ("Entry #"..i.." now builds on the current island."), Duration=3})
end})
-- same build, same spot, different island: copies the selected entry's exact
-- position/rotation so you don't have to stand in the same place on the other
-- slot ("vil bare have den samme sted placering som den anden men andet slot")
Cache.QueueTab:CreateButton({ Name="Duplicate Selected To Slot (from input)", Callback=function()
    if State.BuildQueueEnabled then
        Window:Notify({Title="Queue", Content="Stop the queue before editing it.", Duration=3}); return
    end
    local i = State.BuildQueueSelected
    local e = i and State.BuildQueue[i]
    if not e then Window:Notify({Title="Queue", Content="Select an entry first.", Duration=3}); return end
    local slots = State.BuildQueueSlotList or { State.BuildQueueSlotInput }
    local added = Cache.queueEntriesForSlots(e, slots)
    for _, d in ipairs(added) do table.insert(State.BuildQueue, d) end
    Cache.saveBuildQueue()
    Cache.refreshQueueUI(#State.BuildQueue)
    Window:Notify({Title="Queue", Content=string.format("%d cop%s of %s at the same spot — %s",
        #added, #added == 1 and "y" or "ies", e.name,
        #slots > 1 and ("slots " .. table.concat(slots, ", "))
        or (State.BuildQueueSlotInput and ("slot " .. State.BuildQueueSlotInput) or "current island")), Duration=5})
end})

-- SAVED QUEUES: the table halves are in 190 (tested); this is the disk and the
-- controls. One file, name -> { entries, savedAt }; the running queue is untouched
-- until Load replaces or appends it.
do
    local function readStore()
        if not (isfile and readfile) or not isfile(Cache.SAVED_QUEUES_FILE) then return {} end
        local ok, data = pcall(function() return HttpService:JSONDecode(readfile(Cache.SAVED_QUEUES_FILE)) end)
        return (ok and type(data) == "table") and data or {}
    end
    local function writeStore(store)
        if not (writefile and isfolder and makefolder) then return false end
        if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
        return pcall(function() writefile(Cache.SAVED_QUEUES_FILE, HttpService:JSONEncode(store)) end)
    end
    Cache.readSavedQueues, Cache.writeSavedQueues = readStore, writeStore

    local SavedDD, byLabel, picked
    local savedName = ""
    local function refresh(keep)
        local opts
        opts, byLabel = Cache.queueNamedOptions(readStore())
        if SavedDD then SavedDD:Refresh(opts, keep or opts[1]) end
        if not keep then picked = byLabel[opts[1]] end
    end

    Cache.QueueTab:CreateSection("3)  Saved Queues")
    Cache.QueueTab:CreateNote("Keep a queue you build again under a name — “the whole farm”, “all four slots” — and load it in one press. Loading never starts it; entries land exactly where they were queued, on any server.")
    Cache.QueueTab:CreateInput({ Name="Queue Name", PlaceholderText="e.g. the whole farm", Callback=function(v)
        savedName = tostring(v or "")
    end})
    Cache.QueueTab:CreateButton({ Name="Save Queue As Name", Callback=function()
        local store = readStore()
        local ok, why = Cache.queueSaveNamed(store, savedName, State.BuildQueue, os.time())
        if not ok then Window:Notify({Title="Saved Queues", Content=why, Duration=5}); return end
        if not writeStore(store) then
            Window:Notify({Title="Saved Queues", Content="Could not write queues.json on this executor.", Duration=6}); return
        end
        refresh()
        Window:Notify({Title="Saved Queues", Content=string.format("Saved '%s' (%d entr%s). Loading it later never starts it.",
            why, #State.BuildQueue, #State.BuildQueue == 1 and "y" or "ies"), Duration=5})
    end})
    SavedDD = Cache.QueueTab:CreateDropdown({ Name="Saved Queue", Options=Cache.queueNamedOptions(readStore()),
        CurrentOption={Cache.queueNamedOptions(readStore())[1]}, Callback=function(v)
        local label = tostring(type(v) == "table" and v[1] or v)
        picked = byLabel and byLabel[label] or nil
    end})
    do
        local opts; opts, byLabel = Cache.queueNamedOptions(readStore())
        picked = byLabel[opts[1]]
    end
    local function loadPicked(append)
        if State.BuildQueueEnabled then
            Window:Notify({Title="Saved Queues", Content="Stop the queue before loading one.", Duration=4}); return
        end
        local q, n = Cache.queueLoadNamed(readStore(), picked, State.BuildQueue, append)
        if not q then Window:Notify({Title="Saved Queues", Content=n, Duration=5}); return end
        State.BuildQueue = q
        Cache.saveBuildQueue()
        Cache.refreshQueueUI(append and #q or 1)
        State.BuildQueueSelected = #q > 0 and (append and #q or 1) or nil
        Window:Notify({Title="Saved Queues", Content=string.format("%s %d entr%s from '%s'. Turn on 'Build Queue Mode' to run it.",
            append and "Added" or "Loaded", n, n == 1 and "y" or "ies", tostring(picked)), Duration=5})
    end
    Cache.QueueTab:CreateButton({ Name="Load Saved Queue (replaces the queue)", Callback=function() loadPicked(false) end})
    Cache.QueueTab:CreateButton({ Name="Add Saved Queue To End", Callback=function() loadPicked(true) end})
    Cache.QueueTab:CreateButton({ Name="Delete Saved Queue", Callback=function()
        local store = readStore()
        if not (picked and store[picked]) then
            Window:Notify({Title="Saved Queues", Content="Pick a saved queue first.", Duration=4}); return
        end
        store[picked] = nil
        if not writeStore(store) then
            Window:Notify({Title="Saved Queues", Content="Could not write queues.json on this executor, so nothing was deleted.", Duration=6}); return
        end
        refresh()
        Window:Notify({Title="Saved Queues", Content="Deleted. The queue itself was not touched.", Duration=4})
    end})
end

