-- Pull From Chests (196) is premium and admin; the runner below asks it before each
-- entry and the trial's answer is "nothing" rather than a nil call
if not Cache.queueEntryPull then Cache.queueEntryPull = function() return nil end end
Cache.QueueTab:CreateToggle({ Name="Build Queue Mode", CurrentValue=false, Callback=function(v)
    State.BuildQueueEnabled = v

    if not v then
        -- invalidate the runner and stop whatever build it started
        State.BuildQueueGen = (State.BuildQueueGen or 0) + 1
        if State.AutoBlueprintEnabled then
            local tf = Cache.ToggleFunctions["Auto Build Blueprint"]
            if tf then tf(false) end
        end
        -- persist "not running" — EXCEPT when DoFullCleanup force-toggles us off during
        -- a slot switch (the switch teleport triggers it): overwriting the file there
        -- would erase the active/pendingSlot state the post-teleport auto-resume needs.
        -- A manual toggle-off or panic (IsCleaningUp stays false) always persists.
        -- An Auto Rejoin teleport (228) is the same case: its OnTeleport cleanup must
        -- leave active=true on disk for the queue to resume on the new server.
        if not ((Cache.BuildQueueSwitchInFlight or Cache.RejoinInFlight) and State.IsCleaningUp) then
            Cache.BuildQueuePendingSlot = nil
            Cache.saveBuildQueue()
        end
        return
    end

    local function abort(msg)
        Window:Notify({Title="Queue", Content=msg, Duration=4})
        State.BuildQueueEnabled = false
        local qf = Cache.ToggleFunctions["Build Queue Mode"]
        if qf then task.defer(qf, false) end
    end
    if #State.BuildQueue == 0 then abort("Queue is empty. Add blueprints first."); return end
    -- a queue that switches slot and cannot come back builds one entry and goes quiet:
    -- say so now, while the owner is still looking, instead of after the teleport
    do
        local switches = false
        for _, e in ipairs(State.BuildQueue) do
            if e.slot and e.slot ~= Cache.BuildQueueCurrentSlot then switches = true; break end
        end
        if switches and Cache.resumeReport then
            local ok, verdict = Cache.resumeReport()
            if not ok then
                Window:Notify({Title="Queue — Slot Switches Won't Resume", Content=verdict, Duration=16})
            end
        end
    end
    if State.AutoBlueprintEnabled then abort("Stop the running Auto Build first."); return end
    if State.BlueprintBuildMode == "Original" then
        -- Original mode has no "done" signal of its own: the queue only advances once
        -- EVERY block is placed, which stalls forever on missing inventory/blacklisted
        -- blocks. Chunked self-completes and skips unplaceable blocks.
        Window:Notify({Title="Queue", Content="Original mode only advances when every block gets placed — Chunked is recommended for queue runs.", Duration=8})
    end

    State.BuildQueueGen = (State.BuildQueueGen or 0) + 1
    local gen = State.BuildQueueGen
    Cache.BuildQueueSkip, Cache.BuildQueuePauseAfter = false, false

    -- if we don't know which slot is loaded, assume it's the first entry's: the user
    -- naturally starts the queue standing on the island they queued first.
    if Cache.BuildQueueCurrentSlot == nil and State.BuildQueue[1] and State.BuildQueue[1].slot then
        Cache.BuildQueueCurrentSlot = State.BuildQueue[1].slot
        Window:Notify({Title="Queue", Content="Assuming you're currently on slot " ..
            Cache.BuildQueueCurrentSlot .. ".", Duration=4})
    end
    Cache.saveBuildQueue()  -- persist active=true so a slot switch can auto-resume

    addloop(task.spawn(function()
        local builtCount = 0
        local pausedEarly = false
        while State.BuildQueueEnabled and gen == State.BuildQueueGen do
            local step, which = Cache.queueStep(State.BuildQueue, Cache.BuildQueueCurrentSlot)
            if step == "finish" then break end

            -- wrong island? switch slots first (may teleport-reload; see runSlotSwitch)
            if step == "switch" then
                local arrived = Cache.runSlotSwitch(which, function()
                    return State.BuildQueueEnabled and gen == State.BuildQueueGen
                end)
                if not arrived then break end
                continue  -- slot is now current; re-evaluate the entry and build it
            end
            local entry = which

            -- load this entry's blueprint (silently, so the dropdown callback's
            -- side effects don't fire) and give it a fresh progress map
            State.SelectedBlueprint = entry.name
            loadblueprint(entry.name)
            if not Cache.LoadedBlueprintData then
                local idx = table.find(State.BuildQueue, entry)
                if idx then table.remove(State.BuildQueue, idx) end
                Cache.saveBuildQueue(); Cache.refreshQueueUI()
                Window:Notify({Title="Queue", Content="Skipped '"..tostring(entry.name).."' (file missing or unreadable).", Duration=4})
                continue
            end
            if BlueprintDD then
                State.IsSilentRefresh = true
                BlueprintDD:Refresh(refreshblueprints(), entry.name)
                State.IsSilentRefresh = false
            end
            Cache.BlueprintPlaced = {}
            Cache.BlueprintPlacedCount = 0
            State.BlueprintPlacedCount = 0

            -- restore the captured position/rotation as a locked anchor, moved with
            -- the island if it sits elsewhere on this server (see queueEntryPosition)
            local saved = entry.started and loadblueprintstate() or nil
            local plan = Cache.queueStartPlan(entry, saved, Cache.islandBaseOrigin())
            local at, shift = plan.at, plan.shift
            if shift > 0 then
                Window:Notify({Title="Queue", Content=string.format(
                    "This island sits %.0f studs from where '%s' was queued; building it on the island, not where it used to be.",
                    shift, entry.name), Duration=6})
            end
            Cache.BlueprintAnchor = CFrame.new(at)
            Cache.BlueprintAnchorLocked = true
            State.BlueprintPreviewOffset = Vector3.new(0, 0, 0)
            State.BlueprintPreviewRotationY = entry.rot or 0

            -- a new entry builds fresh: tell the toggle NOT to auto-resume stale disk
            -- progress that happens to share its name. An entry this queue already
            -- started (crash, rejoin, stop) continues from its own save instead --
            -- see queueProgressFor for why the name alone does not decide that.
            local resumed = plan.resumed
            if resumed then
                Cache.BlueprintPlaced = saved.placedBlocks
                Cache.BlueprintPlacedCount = resumed
                State.BlueprintPlacedCount = resumed
                State.BlueprintResuming = true
            end
            -- PULL FIRST, if asked (196; the no-op above in a build without it): the
            -- gap this entry still has beyond the hotbar comes out of your own chests
            -- into the pocket BEFORE the check looks, so the check pauses only on what
            -- no chest had. After the progress is restored, for the same reason as
            -- the check below.
            if Settings.QueuePullFirst then
                local okp, err = pcall(Cache.queueEntryPull, entry)
                if not okp then warn("[Queue] pull from chests failed: " .. tostring(err)) end
            end
            -- MATERIALS FOR THIS ENTRY, if asked (190 decides what the answer means;
            -- 195 reads it). After the progress is restored, so a continued entry is
            -- only asked for what it still has to place. A pause keeps the entry.
            if Settings.QueueCheckEach and Cache.queueEntryPrecheck then
                local okc, r = pcall(Cache.queueEntryPrecheck, entry)
                if okc and r then
                    local mode = ({ "likely", "seen", "tell" })[Settings.QueueShortMode or 1] or "likely"
                    local verdict, rows = Cache.queueMaterialsVerdict(r, mode)
                    if verdict == "pause" then
                        State.BlueprintResuming = false
                        local msg = Cache.queuePauseMessage(entry.name, rows, fixname)
                        Window:Notify({Title="Queue Paused — Materials", Content=msg, Duration=15})
                        pcall(Cache.discordNotify, "queuepause", tostring(entry.name) .. ":" .. #rows, { message = msg })
                        pausedEarly = true
                        break
                    elseif verdict == "warn" then
                        local _, c = Cache.precheckSummary(r, fixname)
                        Window:Notify({Title="Queue — Materials Not All Seen", Content=c, Duration=10})
                    end
                elseif not okc then
                    warn("[Queue] materials check failed: " .. tostring(r))
                end
            end
            if not resumed then State.BlueprintForceFresh = true end
            if not entry.started then
                entry.started = true
                Cache.saveBuildQueue()
            end

            local total = #Cache.LoadedBlueprintData
            Window:Notify({Title="Queue", Content=resumed
                and string.format("Continuing '%s' at %d/%d blocks (%d more queued)",
                    entry.name, resumed, total, #State.BuildQueue - 1)
                or string.format("Building '%s' (%d blocks, %d more queued)",
                    entry.name, total, #State.BuildQueue - 1), Duration=4})

            local tf = Cache.ToggleFunctions["Auto Build Blueprint"]
            if not tf then break end
            -- clear the skip BEFORE the build goes on: the panel button's guard opens
            -- the moment AutoBlueprintEnabled does, and a press in the first half
            -- second used to be confirmed to the owner and then wiped by this reset
            Cache.BuildQueueSkip = false
            tf(true)
            task.wait(0.5)

            -- wait for this build to finish. Chunked mode completes on its own;
            -- Original mode never self-stops, so once every block is placed we
            -- force the toggle off ourselves.
            local skipThis = false
            local lastHeartbeat = tick()
            while State.BuildQueueEnabled and gen == State.BuildQueueGen and State.AutoBlueprintEnabled do
                -- the panel's 'Skip This Build': stop the build, drop the entry, go on.
                -- Cleared on every entry start, so a press always means THIS build.
                if Cache.BuildQueueSkip then
                    Cache.BuildQueueSkip = false
                    skipThis = true
                    State.BlueprintBuildCompleted = false
                    tf(false)
                    break
                end
                -- Original mode only: it never self-stops. Chunked self-completes AFTER
                -- ground-truth verification and retry sweeps — force-stopping it on the
                -- optimistic counter would skip exactly those correctness passes.
                if State.BlueprintBuildMode == "Original" and total > 0 and (State.BlueprintPlacedCount or 0) >= total then
                    State.BlueprintBuildCompleted = true
                    tf(false)
                    break
                end
                -- heartbeat the savedAt timestamp so a mid-build crash still counts
                -- as "recent" for the auto-resume freshness window
                if tick() - lastHeartbeat > 240 then
                    lastHeartbeat = tick()
                    Cache.saveBuildQueue()
                end
                task.wait(1)
            end

            local after = Cache.queueAfterBuild(State.BuildQueueEnabled and gen == State.BuildQueueGen,
                State.BlueprintBuildCompleted == true, skipThis)
            if after == "stop" then break end

            if after == "skip" then
                local idx = table.find(State.BuildQueue, entry)
                if idx then table.remove(State.BuildQueue, idx) end
                Cache.saveBuildQueue()
                Cache.refreshQueueUI()
                Window:Notify({Title="Queue", Content=string.format("Skipped '%s' (%d block(s) stood). %s",
                    Cache.queueEntryLabel(entry.name), State.BlueprintPlacedCount or 0,
                    State.BuildQueue[1] and "On to the next entry." or "The queue is empty now."), Duration=6})
                task.wait(1)
                continue
            end

            -- the panel's 'Pause After This Build': finish the entry in front, then
            -- stop with everything behind it kept -- "I want the island after this one"
            if after == "next" and Cache.BuildQueuePauseAfter then
                Cache.BuildQueuePauseAfter = false
                local idx = table.find(State.BuildQueue, entry)
                if idx then table.remove(State.BuildQueue, idx) end
                builtCount += 1
                Cache.saveBuildQueue()
                Cache.refreshQueueUI()
                Window:Notify({Title="Queue Paused", Content=string.format(
                    "'%s' finished; paused as asked, with %d entr%s kept. Turn 'Build Queue Mode' on to continue.",
                    Cache.queueEntryLabel(entry.name), #State.BuildQueue, #State.BuildQueue == 1 and "y" or "ies"), Duration=8})
                pausedEarly = true   -- same tail: toggle off without "Queue Complete"
                break
            end

            if after == "next" then
                local idx = table.find(State.BuildQueue, entry)
                if idx then table.remove(State.BuildQueue, idx) end
                builtCount += 1
                Cache.saveBuildQueue()
                Cache.refreshQueueUI()
                task.wait(1)
            else
                -- the build ended before completion (manual toggle-off, error, ...)
                -- keep the entry so the queue can be restarted from it
                Window:Notify({Title="Queue Stopped", Content="Build ended before completion; queue paused. The entry was kept.", Duration=5})
                break
            end
        end

        if gen == State.BuildQueueGen and State.BuildQueueEnabled then
            State.BuildQueueEnabled = false
            local qf = Cache.ToggleFunctions["Build Queue Mode"]
            if qf then task.defer(qf, false) end
            if builtCount > 0 and not pausedEarly then
                Window:Notify({Title="Queue Complete", Content=string.format("Finished %d queued build%s.",
                    builtCount, builtCount == 1 and "" or "s"), Duration=6})
            end
        end
    end))
end})

-- THE QUEUE PANEL: the whole queue at a glance while it runs -- which entry is
-- building and how far, what waits behind it, which one was interrupted, and the
-- time left for all of it. The dropdown shows one line at a time and Build Stats only
-- the entry in front, so "is it on the right one, and what next?" meant stopping to
-- look. Its text is Cache.queuePanelLines (190, tested); this draws and repaints it
-- once a second while it is open. DoFullCleanup destroys it with the other panels.
do
    local function paint(label)
        local q = State.BuildQueue or {}
        local running = State.BuildQueueEnabled == true
        local building = running and State.AutoBlueprintEnabled and q[1] ~= nil
            and Cache.LastLoadedBlueprint == q[1].name
        local total = building and Cache.LoadedBlueprintData and #Cache.LoadedBlueprintData or nil
        local placed = State.BlueprintPlacedCount or 0
        local mins
        if building and Cache.refreshQueueRest then
            pcall(Cache.refreshQueueRest)
            local rest = Cache.QueueRest
            if rest and rest.key == Cache.queueKey(q) then
                mins = Cache.queueTimeLeft(math.max(0, (total or 0) - placed), rest.blocks, State.BuildLastGoodBpm)
            end
        end
        label.Text = table.concat(Cache.queuePanelLines(q, { running = running, placed = placed, total = total,
            currentSlot = Cache.BuildQueueCurrentSlot, minutesLeft = mins }), "\n")
    end

    local function close()
        if Cache.QueuePanelUI then pcall(function() Cache.QueuePanelUI:Destroy() end); Cache.QueuePanelUI = nil end
    end

    local function open()
        close()
        local ui, frame = buildFrameBase("IVM_QueuePanel", UDim2.new(0,340,0,300), UDim2.new(1,-360,0.5,-150))
        frame.Visible = true
        Cache.QueuePanelUI = ui
        local titleBar = addTitleBar(frame, "Build Queue", Color3.fromRGB(35,35,42))
        makedraggable(frame, titleBar)

        local closeBtn = Instance.new("TextButton")
        closeBtn.Size = UDim2.new(0,26,0,26); closeBtn.Position = UDim2.new(1,-32,0,4)
        closeBtn.BackgroundColor3 = Color3.fromRGB(60,32,34); closeBtn.Text = "X"
        closeBtn.TextColor3 = Color3.fromRGB(235,200,200); closeBtn.Font = Enum.Font.GothamBold
        closeBtn.TextSize = 14; closeBtn.ZIndex = 5; closeBtn.Parent = titleBar
        Instance.new("UICorner", closeBtn).CornerRadius = UDim.new(0,6)
        closeBtn.MouseButton1Click:Connect(close)

        -- the two things worth doing WHILE it runs, so they live on the panel that is
        -- open while it runs: skip the build in front, or finish it and then stop.
        -- Both are read by the runner (203's wait loop and queueAfterBuild) and are
        -- harmless when nothing runs: a press then just says so.
        local function smallButton(text, x, cb)
            local b = Instance.new("TextButton")
            b.Size = UDim2.new(0.5,-12,0,26); b.Position = UDim2.new(x,8,0,42)
            b.BackgroundColor3 = Color3.fromRGB(35,35,42); b.Text = text
            b.TextColor3 = Color3.fromRGB(220,220,225); b.Font = Enum.Font.Gotham
            b.TextSize = 13; b.Parent = frame
            Instance.new("UICorner", b).CornerRadius = UDim.new(0,6)
            b.MouseButton1Click:Connect(cb)
            return b
        end
        smallButton("Skip This Build", 0, function()
            if not (State.BuildQueueEnabled and State.AutoBlueprintEnabled) then
                Window:Notify({Title="Queue", Content="Nothing is building right now.", Duration=3}); return
            end
            Cache.BuildQueueSkip = true
            Window:Notify({Title="Queue", Content="Skipping the build in front; the queue moves on to the next entry.", Duration=4})
        end)
        local function pauseText()
            return (State.BuildQueueEnabled and Cache.BuildQueuePauseAfter)
                and "Will Pause After This" or "Pause After This Build"
        end
        local pauseBtn
        pauseBtn = smallButton(pauseText(), 0.5, function()
            if not State.BuildQueueEnabled then
                Window:Notify({Title="Queue", Content="The queue is not running.", Duration=3}); return
            end
            Cache.BuildQueuePauseAfter = not Cache.BuildQueuePauseAfter
            pauseBtn.Text = pauseText()
            Window:Notify({Title="Queue", Content=Cache.BuildQueuePauseAfter
                and "The entry in front finishes, then the queue pauses with the rest kept."
                or "Pause cancelled; the queue runs on.", Duration=4})
        end)

        local scroll = Instance.new("ScrollingFrame")
        scroll.Size = UDim2.new(1,-16,1,-84); scroll.Position = UDim2.new(0,8,0,76)
        scroll.BackgroundColor3 = Color3.fromRGB(22,22,27); scroll.BorderSizePixel = 0
        scroll.ScrollBarThickness = 5; scroll.ScrollBarImageColor3 = Color3.fromRGB(80,80,90)
        scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y; scroll.Parent = frame
        Instance.new("UICorner", scroll).CornerRadius = UDim.new(0,6)

        local list = Instance.new("TextLabel")
        list.Size = UDim2.new(1,-12,0,0); list.Position = UDim2.new(0,8,0,8)
        list.BackgroundTransparency = 1; list.TextColor3 = Color3.fromRGB(210,210,215)
        list.Font = Enum.Font.Gotham; list.TextSize = 13
        list.TextXAlignment = Enum.TextXAlignment.Left; list.TextYAlignment = Enum.TextYAlignment.Top
        list.TextWrapped = true; list.AutomaticSize = Enum.AutomaticSize.Y; list.Parent = scroll

        addloop(task.spawn(function()
            while Cache.QueuePanelUI == ui and ui.Parent do
                pcall(paint, list)
                -- the repaint also keeps the Pause button honest: the runner and a
                -- queue restart clear the flag without going through the button
                pcall(function() pauseBtn.Text = pauseText() end)
                task.wait(1)
            end
        end))
    end

    Cache.QueueTab:CreateButton({ Name="Show Queue Panel", Callback=function() task.spawn(open) end})
end

Cache.QueueTab:CreateSection("5)  Slot Switching & Auto-Resume")
-- Switch slots right now, and prove the queue can do it unattended. This used to
-- REFUSE to run without a recording -- but fireSlotRemote tries the game's own
-- LoadProfile remote first and needs no recording at all, so the button was more
-- pessimistic than the thing it tested: it reported "no recording yet" over a slot
-- switch that would have worked, which reads as "auto-switch is not available".
Cache.QueueTab:CreateButton({ Name="Switch To Slot Now (also tests auto-switch)", Callback=function()
    local n = State.BuildQueueSlotInput
    if not n then Window:Notify({Title="Slot Switch", Content="Type a slot number in 'Island Slot #' first.", Duration=5}); return end
    task.spawn(function()
        local how = (Cache.SlotRemotes and Cache.SlotRemotes[tostring(n)]) and "your recording"
            or (Cache.deriveSlotRemote(n) and "a derived recording" or "the game's own LoadProfile remote")
        local okFire, fired = pcall(Cache.fireSlotRemote, n)
        if okFire and fired then
            Window:Notify({Title="Slot Switch", Content="Sent the switch to slot " .. n .. " via " .. how ..
                ". If the island reloads, the queue can switch slots on its own — just set the slot number before adding each build.", Duration=10})
        else
            Window:Notify({Title="Slot Switch", Content="Couldn't switch to slot " .. n ..
                " — the game may have moved the remote. Use 'Record Slot Switch' once (any slot; the others derive from it), then try again.", Duration=12})
        end
    end)
end})
 -- FALLBACK ONLY. The queue fires the game's own LoadProfile remote directly, which
-- needs no setup. Record a real switch only if 'Switch To Slot Now' below fails --
-- e.g. a game update moved that remote.
-- WILL IT COME BACK AFTER THE SWITCH? See 201: the answer depends on the executor,
-- and it is worth knowing before the queue has built one entry and gone quiet.
Cache.QueueTab:CreateButton({ Name="Test Auto-Resume", Callback=function()
    local ok, verdict, lines = Cache.resumeReport()
    Window:Notify({Title=ok and "Auto-Resume — Ready" or "Auto-Resume — Not Set Up", Content=verdict .. "\n\n" .. table.concat(lines, "\n"), Duration=18})
end})
Cache.QueueTab:CreateButton({ Name="Install Resume Helper", Callback=function()
    local ok, where = Cache.installResumeHelper()
    if ok then
        Window:Notify({Title="Resume Helper Installed", Content=string.format(
            "Written to %s. It runs the hub only while a slot switch or an auto rejoin is in flight, and does nothing when you join a game any other time. Press 'Test Auto-Resume' to check.", tostring(where)), Duration=14})
    else
        Window:Notify({Title="Resume Helper", Content="Could not write it: " .. tostring(where) .. ". Your executor may not allow writing to its autoexec folder; queue_on_teleport is then the only way back.", Duration=14})
    end
end})
Cache.QueueTab:CreateButton({ Name="Remove Resume Helper", Callback=function()
    local n = Cache.removeResumeHelper()
    Window:Notify({Title="Resume Helper", Content=n > 0 and "Removed." or "It was not installed.", Duration=6})
end})
Cache.QueueTab:CreateButton({ Name="Record Slot Switch (only if auto-switch fails)", Callback=function()
    local n = State.BuildQueueSlotInput
    if not n then
        Window:Notify({Title="Slot Capture", Content="Type the target slot number in 'Island Slot #' first.", Duration=5}); return
    end
    Cache.recordSlotRemote(n, 25)
end})

-- Auto-resume: if the queue was running when the previous session ended (a slot switch
-- teleport kills the script), pick it back up once the island has loaded. Only fires
-- when the saved state says active=true, so a normal stop/panic never auto-starts
-- anything. Requires the script to be in the executor's autoexec to survive teleports.
if Cache.BuildQueueResumeStale then
    Cache.BuildQueueResumeStale = false
    -- queue was mid-run when a PREVIOUS (not recent) session ended: don't hijack the
    -- player's session by silently building — remind them and let them decide.
    -- Persist inactive so the reminder doesn't repeat every inject unless they run it.
    State.BuildQueueEnabled = false
    pcall(Cache.saveBuildQueue)
    task.delay(8, function()
        if Window and #State.BuildQueue > 0 and not State.BuildQueueEnabled then
            Window:Notify({Title="Build Queue Paused", Content="A queue from an earlier session has " ..
                #State.BuildQueue .. " entr" .. (#State.BuildQueue == 1 and "y" or "ies") ..
                " left. Toggle Build Queue Mode to continue it.", Duration=10})
        end
    end)
end
if Cache.BuildQueueResumePending then
    Cache.BuildQueueResumePending = false
    -- registered via addloop so Unload Script's thread sweep cancels it: a bare
    -- task.spawn would survive unload, wake up later, and restart the queue headless
    -- (rewriting active=true on disk right after unload persisted active=false)
    addloop(task.spawn(function()
        -- if the user touches the queue toggle (on OR off) while we wait, the gen
        -- moves and this thread must stand down — it used to re-enable a queue the
        -- user had just manually stopped during the load window
        local genAt = State.BuildQueueGen or 0
        task.wait(3)
        if not Cache.waitForIslandLoaded(180) then
            -- Window can be nil by now if the script was cleaned up while we waited
            if Window then Window:Notify({Title="Queue", Content="Island didn't finish loading; queue not resumed. Toggle Build Queue Mode to retry.", Duration=8}) end
            return
        end
        task.wait(5) -- let blocks/inventory replicate before placing
        if (State.BuildQueueGen or 0) ~= genAt then return end
        if State.BuildQueueEnabled or #State.BuildQueue == 0 then return end
        local qf = Cache.ToggleFunctions["Build Queue Mode"]
        if qf and Window then
            Window:Notify({Title="Queue", Content="Resuming build queue (" .. #State.BuildQueue .. " entr" ..
                (#State.BuildQueue == 1 and "y" or "ies") .. " left)...", Duration=6})
            qf(true)
        end
    end))
end
-- ==== end of BUILD QUEUE UI ================================================
-- ==== ISLAND AUTO-SYNC ON INJECT ===========================================
-- ---- Island auto-sync on inject: resume with ZERO manual steps ----
-- On join, if there's saved build progress, quietly load that blueprint, restore its
-- anchor, rescan the island, and correct the numbers to reality — all in the
-- background. One notification tells you where you stand; toggling Auto Build then
-- continues instantly (the engine skips its own start-scan when freshly synced).
-- No manual Verify Build / Clear Saves / toggle-off-and-on dance.
addloop(task.spawn(function()
    task.wait(4)
    local saved = loadblueprintstate()
    if not (saved and saved.blueprintName and (saved.placedCount or 0) > 0) then return end
    if Cache.waitForIslandLoaded and not Cache.waitForIslandLoaded(180) then return end
    task.wait(4)  -- let blocks replicate before scanning
    -- something already took over (queue auto-resume / user started building): stand down
    if State.AutoBlueprintEnabled or State.BuildQueueEnabled then return end
    if State.SelectedBlueprint ~= saved.blueprintName then
        State.IsSilentRefresh = true
        pcall(function() BlueprintDD:Refresh(refreshblueprints(), saved.blueprintName) end)
        State.IsSilentRefresh = false
        pcall(loadblueprint, saved.blueprintName)
    end
    if not Cache.LoadedBlueprintData then return end
    local shift = saved.anchorPosition and Cache.restoreSavedAnchor(saved) or nil
    if saved.placedBlocks then
        Cache.BlueprintPlaced = saved.placedBlocks
        Cache.BlueprintPlacedCount = saved.placedCount or 0
        State.BlueprintPlacedCount = saved.placedCount or 0
    end
    local startCF = getblueprintstartcframe()
    if not startCF then return end
    -- ALIGN ON REJOIN. Rebasing off the island's Base gets the anchor into the right
    -- neighbourhood, but the island can also come back rotated or re-laid, so the
    -- rebased origin is still only a guess. Search for where this blueprint actually
    -- stands and snap onto it before a single block is placed — otherwise the first
    -- toggle of Auto Build starts a second, offset copy beside the real one.
    -- autoAlignAnchor self-guards (resume only, >=30% match, 3x better, >1.5 studs),
    -- so it stays quiet when the rebased origin was already right.
    if shift and shift > 0.05 then
        Cache.notify({Title="Auto Build", Content=string.format(
            "Rejoined — the island sits %.0f studs from where the build was saved. Re-aligning the blueprint onto it.", shift), Duration=7})
    end
    -- The sub-cell miss first, because everything below reads the lattice: the search
    -- builds its candidate origins on it, the preview draws on it, and the verify scan
    -- counts standing blocks by exact position key. A grid a fraction of a cell off
    -- therefore makes the search find nothing, the preview look crooked, and the scan
    -- report blocks as missing that are standing right there -- all three from one
    -- wrong number. Correct it before any of them run.
    startCF = Cache.autoFixAlignment(Cache.LoadedBlueprintData, startCF, "Rejoin — Grid Corrected")
    do
        local okAlign, aligned = pcall(Cache.autoAlignAnchor, Cache.LoadedBlueprintData, startCF)
        if okAlign and aligned then startCF = aligned end
    end
    local real, missing = Cache.verifyBuildPlacement(Cache.LoadedBlueprintData, startCF)
    if not real then return end
    saveblueprintstate()
    Window:Notify({Title="Build Synced", Content=string.format(
        "'%s': %d/%d blocks standing — %d missing. Just toggle Auto Build to continue.",
        saved.blueprintName, real, #Cache.LoadedBlueprintData, missing), Duration=9})
end))

-- ALIGN THE PREVIEW YOU ARE POSITIONING BY HAND, not only the build you start.
-- The automatic correction runs at build start, on resume and on rejoin -- all of
-- them too late for the one job the preview has, which is showing you where the
-- blocks will land WHILE you line them up. A grid vote a fraction of a cell out
-- draws the ghost off the rows you are trying to meet, and every move control steps
-- a whole 3-stud cell, so no amount of nudging closes that gap: you would have to
-- know to press Fix Alignment first, which is exactly the knowledge a preview is
-- supposed to save you.
--
-- Measure once the preview is STANDING STILL. Not per frame (the measurement walks
-- the island), not mid-drag (the origin it spent that walk on is gone by the time it
-- finishes), and never again once it has a usable read. Parked in mid-air with
-- nothing to measure against, it stays untried and has another go the moment you
-- drag it next to something standing.
addloop(task.spawn(function()
    local lastKey
    while true do
        task.wait(4)
        if not Cache.PreviewAlignDone and State.BuildAutoAlignGrid
        and State.BlueprintPreviewEnabled and Cache.LoadedBlueprintData
        and not State.AutoBlueprintEnabled then
            local okCF, cf = pcall(getblueprintstartcframe)
            if okCF and cf then
                local key = tostring(State.SelectedBlueprint) .. "|" .. string.format(
                    "%.1f,%.1f,%.1f", cf.Position.X, cf.Position.Y, cf.Position.Z)
                if key == lastKey then
                    local okM, m = pcall(Cache.measureGridMiss, Cache.LoadedBlueprintData, cf)
                    if okM and m then
                        -- a read is a read: on-grid answers the question just as well
                        -- as a correction does, and re-walking the island every 4
                        -- seconds to be told the same thing is a waste
                        Cache.PreviewAlignDone = true
                        if not m.onGrid and Cache.applyGridMiss(m) then
                            Cache.notify({Title="Preview — Grid Corrected", Content=string.format(
                                "The preview was sitting %.1f, %.1f, %.1f studs off the blocks next to it (%d%% of %d measured agreed). Snapped onto the island's lattice — the move controls line up from here. Positioning it by hand? Turn off 'Auto Align (build start + preview)' and it will stay where you put it.",
                                m.sx, m.sy, m.sz, m.share, m.matched), Duration=10})
                        end
                    end
                end
                lastKey = key
            end
        end
    end
end))
-- ==== end of ISLAND AUTO-SYNC ON INJECT ====================================
-- ==== QUEUE MATERIALS UI ===================================================
if not Cache.queuePriceButton then Cache.queuePriceButton = function() end end
if not Cache.queueCostLines then Cache.queueCostLines = function() return nil end end
-- Pull From Chests (196) is premium and admin: the trial draws no rows for it
if not Cache.queuePullButton then Cache.queuePullButton = function() end end
-- One button under the Build Queue: what every queued build needs, summed per type,
-- against what you carry. The arithmetic is 074_queue_materials.lua; this part only
-- gathers its inputs -- each entry's blueprint file, the mods file, the hotbar, and
-- the progress of the one entry this island is building -- and shows the answer in
-- the Required Blocks panel plus a written report.
do
    -- the same path 210's MODS_FILE names. 210 is a later part and keeps it as a
    -- file-level local, so it cannot be read from here; the file itself is the
    -- contract (saveBlueprintMods writes it on every change).
    local QUEUE_MODS_FILE = "Islands trading hub/blockmods.json"

    -- loadblueprint's lookup (080) without loadblueprint's side effects: it resets the
    -- placed map, reloads the mods into State and drops the anchor, which would wreck
    -- the build that is loaded -- or running -- right now just to price another one.
    local function readQueueBlocks(name)
        if not (isfile and readfile) or name == nil or name == "None" then return nil end
        local f = "Islands trading hub/Blueprints/" .. tostring(name) .. ".json"
        if not isfile(f) then f = "Islands trading hub/Blueprints/blueprint_" .. tostring(name) .. ".json" end
        if not isfile(f) then return nil end
        local ok, data = pcall(function() return HttpService:JSONDecode(readfile(f)) end)
        return ok and Cache.queueBlueprintBlocks(data) or nil
    end

    -- THE ONE ENTRY WHOSE PROGRESS IS HERE. Cache.BlueprintPlaced is keyed by world
    -- position and belongs to whatever was built last. It is entry #1's only when #1
    -- is the blueprint loaded, the anchor is locked where #1 was queued (the runner
    -- puts it exactly there), the rotation matches, and we are on #1's slot -- a
    -- duplicate at the same spot on another slot has the same keys and none of the
    -- blocks. Anything less and no entry gets a discount: overcounting says "go get
    -- more", undercounting strands a build half-way.
    local function currentQueueEntry(q)
        local e = q[1]
        if not (e and type(e.pos) == "table" and Cache.LastLoadedBlueprint == e.name) then return nil end
        if not (Cache.BlueprintAnchor and Cache.BlueprintAnchorLocked) then return nil end
        if e.slot and e.slot ~= Cache.BuildQueueCurrentSlot then return nil end
        if math.abs((e.rot or 0) - (State.BlueprintPreviewRotationY or 0)) > 1e-3 then return nil end
        -- where the runner put it: the queued spot, moved with the island (190)
        local a, p = Cache.BlueprintAnchor.Position, Cache.queueEntryPosition(e, Cache.islandBaseOrigin())
        if math.abs(a.X - p.X) > 0.5 or math.abs(a.Y - p.Y) > 0.5 or math.abs(a.Z - p.Z) > 0.5 then return nil end
        if not (Cache.BlueprintPlaced and next(Cache.BlueprintPlaced)) then return nil end
        -- the locked branch of getblueprintstartcframe has no side effects (only the
        -- unlocked one locks an anchor where you stand), so asking here is safe
        local startCF = getblueprintstartcframe()
        return 1, function(bd)
            local pos = (startCF * parseBlueprintCFrame(bd.cframe)).Position
            return string.format("%d,%d,%d", math.floor(pos.X*10 + 0.5), math.floor(pos.Y*10 + 0.5), math.floor(pos.Z*10 + 0.5))
        end
    end

    -- THE QUEUE'S TALLY, GATHERED. Every input queueMaterials needs, read the way this
    -- button reads them, then the call. Published so the Materials Check Before Build
    -- (188) and Build Cost's whole-queue price (187) tally the queue exactly as this
    -- button does rather than a second way -- 187 used to carry its own copy.
    -- Yields (the beat); call from a thread. Errors propagate -- callers pcall it.
    function Cache.queueTally(q, have)
        local allMods
        if isfile and readfile and isfile(QUEUE_MODS_FILE) then
            local ok, data = pcall(function() return HttpService:JSONDecode(readfile(QUEUE_MODS_FILE)) end)
            if ok and type(data) == "table" then allMods = data end
        end
        local cur, keyOf = currentQueueEntry(q)
        return Cache.queueMaterials(q, {
            readBlocks = readQueueBlocks, allMods = allMods, isBlacklisted = IsBlacklisted,
            current = cur, placed = Cache.BlueprintPlaced, placedKey = keyOf,
            have = have or {}, beat = function() task.wait() end,
        })
    end

    -- THE REST OF THE QUEUE, for Build Stats' queue line (060): read once per change
    -- of the queue, on a thread -- the entries behind the current one do not change
    -- while it builds, and reading every blueprint file on every stats tick would be
    -- the hitch the panel is there to report, not cause.
    local restBusy = false
    function Cache.refreshQueueRest()
        local q = State.BuildQueue or {}
        local key = Cache.queueKey(q)
        if restBusy or (Cache.QueueRest and Cache.QueueRest.key == key) then return end
        restBusy = true
        task.spawn(function()
            local ok, r = pcall(Cache.queueTally, q, {})
            if ok and r then
                local blocks, builds = Cache.queueRestBlocks(r)
                Cache.QueueRest = { key = key, blocks = blocks, builds = builds }
            end
            restBusy = false
        end)
    end

    -- the queue tab's last section: what the whole queue needs and how long it takes.
    -- 195's chest-aware check and 187's price are handed the tab here rather than
    -- drawing their own rows, so all four sit together (187 is cut from the trial).
    local QT = Cache.QueueTab
    -- section 6: 206 loads after 203, so this is the tab's last section on screen --
    -- it must not be named "before you run" when it stands after the run switch
    QT:CreateSection("6)  Materials, Cost And Time")
    QT:CreateButton({ Name="Check Materials For Whole Queue", Callback=function()
        local q = State.BuildQueue or {}
        if #q == 0 then
            Window:Notify({Title="Queue Materials", Content="The queue is empty. Add blueprints to it first.", Duration=4}); return
        end
        task.spawn(function()
            local ok, r = pcall(Cache.queueTally, q, Cache.countInventory())
            if not ok or not r then
                Window:Notify({Title="Queue Materials", Content="Couldn't tally the queue: " .. tostring(r), Duration=6}); return
            end
            local report = Cache.queueMaterialsReport(r, fixname)
            local wrote = false
            if writefile and isfolder and makefolder then
                wrote = pcall(function()
                    if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
                    writefile("Islands trading hub/queue_materials.txt", report)
                end)
            end
            -- the first line names the sum, because the panel's other fillers write
            -- a different one into the same label
            local mf = Cache.showRequiredBlocks(report)

            local where = mf and "the Required Blocks panel" or "queue_materials.txt"
            local warn = #r.missing > 0 and string.format(" %d entr%s had no readable blueprint file and %s left out.",
                #r.missing, #r.missing == 1 and "y" or "ies", #r.missing == 1 and "is" or "are") or ""
            local file = wrote and " Full report: queue_materials.txt." or ""
            if r.totalNeed == 0 then
                Window:Notify({Title="Queue Materials", Content="Nothing left to place across the queue." .. warn .. file, Duration=8})
            elseif r.shortTotal == 0 then
                Window:Notify({Title="Queue Materials — All Good", Content=string.format(
                    "Your hotbar covers all %d block(s) across %d entr%s.%s%s", r.totalNeed, #q, #q == 1 and "y" or "ies", warn, file), Duration=8})
            else
                local top = r.rows[1]
                Window:Notify({
                    Title = string.format("Queue short %d type(s), %s block(s)", r.shortTypes, shortnum(r.shortTotal)),
                    Content = string.format("Needs %s block(s) in total; most short: %s x%s. Per type and per entry in %s. Counts only your hotbar and held item — stacks in your inventory screen or chests aren't seen.%s%s",
                        shortnum(r.totalNeed), fixname(top.bt), shortnum(top.short), where, warn, file),
                    Duration = 12,
                })
            end
        end)
    end})

    -- HOW LONG THE QUEUE TAKES (048): the same tally, timed by how fast your own
    -- finished builds went -- or the one running now
    -- EVERYTHING IN ONE PRESS: the three questions above share one tally, so asking
    -- them one button at a time tallied the queue three times and overwrote the panel
    -- twice. This asks once and writes one report -- how long, what is missing, what
    -- the shortfall costs (premium; the trial's fallback answers nil and the report
    -- says the Price Book line is not in this build's reach by leaving it out).
    QT:CreateButton({ Name="Check The Whole Queue (One Press)", Callback=function()
        local q = State.BuildQueue or {}
        if #q == 0 then
            Window:Notify({Title="Queue Check", Content="The queue is empty. Add blueprints to it first.", Duration=4}); return
        end
        task.spawn(function()
            local ok, r = pcall(Cache.queueTally, q, Cache.countInventory())
            if not ok or not r then
                Window:Notify({Title="Queue Check", Content="Couldn't tally the queue: " .. tostring(r), Duration=6}); return
            end
            local live = State.AutoBlueprintEnabled and tonumber(State.BuildLastGoodBpm) or nil
            local rate = Cache.buildRateEstimate(Cache.loadBuildRates and Cache.loadBuildRates() or {}, live)
            local est = Cache.queueTimeEstimate(r, rate)
            local lines = Cache.queueTimeLines(est, rate, fixname)
            lines[#lines + 1] = ""
            lines[#lines + 1] = Cache.queueMaterialsReport(r, fixname)
            local costLines, pr = Cache.queueCostLines(r)
            if costLines then
                lines[#lines + 1] = ""
                for _, l in ipairs(costLines) do lines[#lines + 1] = l end
            end
            local report = table.concat(lines, "\n")
            Cache.showRequiredBlocks(report)
            local cost = pr and (", missing " .. shortnum(pr.shortCost) .. " coins at the cheapest shops") or ""
            Window:Notify({Title="Queue Check", Content=string.format(
                "%s Short %d type(s), %s block(s)%s. The whole answer is in the Required Blocks panel.",
                lines[1], r.shortTypes, shortnum(r.shortTotal), cost), Duration=12})
        end)
    end})
    Cache.queueChestCheckButton(QT)
    Cache.queuePullButton(QT)
    Cache.queueMirrorButton(QT)
    Cache.queuePriceButton(QT)
    QT:CreateButton({ Name="Estimate Queue Time", Callback=function()
        local q = State.BuildQueue or {}
        if #q == 0 then
            Window:Notify({Title="Queue Time", Content="The queue is empty. Add blueprints to it first.", Duration=4}); return
        end
        task.spawn(function()
            local ok, r = pcall(Cache.queueTally, q, {})
            if not ok or not r then
                Window:Notify({Title="Queue Time", Content="Couldn't read the queue: " .. tostring(r), Duration=6}); return
            end
            local live = State.AutoBlueprintEnabled and tonumber(State.BuildLastGoodBpm) or nil
            local rate = Cache.buildRateEstimate(Cache.loadBuildRates and Cache.loadBuildRates() or {}, live)
            local est = Cache.queueTimeEstimate(r, rate)
            local lines = Cache.queueTimeLines(est, rate, fixname)
            local mf = Cache.showRequiredBlocks(table.concat(lines, "\n"))
            Window:Notify({Title="Queue Time", Content=lines[1] .. (mf and " Per entry in the Required Blocks panel." or ""), Duration=10})
        end)
    end})
end
-- ==== end of QUEUE MATERIALS UI ============================================
-- ==== PLATFORM FARM: build a platform, break it, repeat ========================
--
-- "Blocks broken" is a number you earn by breaking blocks, and an island runs out of
-- blocks long before the number runs out of room -- which is why clearing your own
-- island for it is self-defeating: the ground you break is the ground you wanted.
-- So make the blocks instead. Place a platform out of a material you hold plenty of,
-- break every block of it, place it again. The blocks return to your inventory as
-- they break, so one stack of anything cheap feeds the loop for as long as you leave
-- it running, and nothing that was already on the island is touched.
--
-- IT ONLY EVER BREAKS WHAT IT PLACED. The demolish phase does not sweep a radius the
-- way Block Nuke does. Before placing anything it records which cells of the platform
-- footprint were ALREADY occupied, places only into the empty ones, and then breaks
-- only the blocks that appeared in those cells. Run it standing on your island, on a
-- neighbour's, or in a shop, and the worst it can do is place blocks and take them
-- back again.
--
-- Wrapped in a function, not a do-block: a do-block's locals still count against the
-- main chunk's register peak, and this chunk is close enough to Luau's 200-register
-- limit that the Settings-tab keybind block had to do the same thing (see there).
function Cache.platformFarmUI()
    -- ---- geometry -----------------------------------------------------------
    -- Cell keys are measured against the anchor, so they are plain integer lattice
    -- coordinates whatever sub-cell offset this island's grid happens to carry.
    local function cellKey(anchor, p)
        return string.format("%d,%d,%d",
            math.floor((p.X - anchor.X) / 3 + 0.5),
            math.floor((p.Y - anchor.Y) / 3 + 0.5),
            math.floor((p.Z - anchor.Z) / 3 + 0.5))
    end

    -- the Blocks-folder child a part belongs to, or nil for scenery/characters/drops
    local function blockOf(part)
        local cur = part
        for _ = 1, 4 do
            local par = cur.Parent
            if not par then return nil end
            if par.Name == "Blocks" then return cur end
            if par == Workspace then return nil end
            cur = par
        end
        return nil
    end

    -- N x N x layers of lattice positions, centred on the anchor. The half-offset is
    -- floor(n/2), NOT (n-1)/2: the latter is a half-integer for even n, which shifts
    -- the whole platform 1.5 studs off the island's lattice and every placement in it
    -- is then refused for being between cells.
    local function platformCells(anchor, n, layers)
        local half = math.floor(n / 2)
        local out = {}
        for k = 0, layers - 1 do
            for i = 0, n - 1 do
                for j = 0, n - 1 do
                    out[#out + 1] = Vector3.new(
                        anchor.X + (i - half) * 3,
                        anchor.Y + k * 3,
                        anchor.Z + (j - half) * 3)
                end
            end
        end
        return out
    end

    -- ONE box query for the whole footprint, not one per cell. A 32x32x4 platform is
    -- four thousand cells, and four thousand GetPartBoundsInBox calls a cycle is the
    -- kind of per-item cost that ate the nuke's speed before it was measured.
    local function occupancyOf(anchor, n, layers)
        local half = math.floor(n / 2)
        local minP = Vector3.new(anchor.X - half * 3, anchor.Y, anchor.Z - half * 3)
        local maxP = Vector3.new(anchor.X + (n - 1 - half) * 3,
                                 anchor.Y + (layers - 1) * 3,
                                 anchor.Z + (n - 1 - half) * 3)
        local size = (maxP - minP) + Vector3.new(3, 3, 3) - Vector3.new(0.2, 0.2, 0.2)
        local op = OverlapParams.new()
        op.FilterType = Enum.RaycastFilterType.Exclude
        op.FilterDescendantsInstances = { LocalPlayer.Character }
        op.MaxParts = 100000  -- the default of 20 would report an empty footprint
        local parts = Workspace:GetPartBoundsInBox(CFrame.new((minP + maxP) / 2), size, op)
        local occ = {}
        for i, part in ipairs(parts) do
            local blk = blockOf(part)
            if blk then
                local bp = (blk:IsA("BasePart") and blk.Position) or part.Position
                occ[cellKey(anchor, bp)] = blk
            end
            if i % 500 == 0 then task.wait() end
        end
        return occ
    end

    -- ---- the material -------------------------------------------------------
    -- The typed box wins over the dropdown: the dropdown can only offer what the
    -- hotbar shows, and the id the place request wants is the internal one ("grass",
    -- "oak_wood"). Anyone who knows the id should not have to put the item in a slot
    -- to use it.
    -- WHAT YOU TYPE IS WHAT YOU SEE, NOT ONLY THE ID. The box used to hand its text to
    -- the place request as it stood, so "Grass" -- the name on the item -- matched
    -- nothing you hold ("grass") and the farm said "No 'Grass' in your hotbar" to
    -- someone holding a full stack. Cache.resolveHeldItem (032, tested) answers a
    -- display name or an id, in any case.
    local function material()
        local typed = State.PlatformMaterialTyped
        if type(typed) == "string" and typed:gsub("%s", "") ~= "" then
            return Cache.resolveHeldItem(typed, Cache.countInventory())
        end
        local sel = State.PlatformMaterial
        if type(sel) ~= "string" or sel == "" or sel == "Empty" then return nil end
        return Cache.toInternal(sel)
    end

    -- ---- one build-and-demolish cycle ---------------------------------------
    -- Returns false to ask the loop to stop (and says why itself).
    local function cycle(gen)
        local mat = material()
        if not mat then
            Cache.notify({Title="Platform Farm", Content="Pick a material first — choose one from 'Platform Material', or type the block's internal id (e.g. grass) into 'Material Id (overrides)'.", Duration=10})
            return false
        end
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if not hrp then task.wait(0.5); return true end

        local n = math.max(1, math.floor(Settings.PlatformSize or 8))
        local layers = math.max(1, math.floor(Settings.PlatformLayers or 1))
        local g = Cache.gridOffset()
        local function snap(v, o) return math.floor((v - o) / 3 + 0.5) * 3 + o end

        -- THE ANCHOR IS FIXED FOR THE RUN, AND THAT IS THE POINT.
        --
        -- Re-deriving it from the player every cycle looks harmless and is not: layer
        -- 0 is placed into the cells your legs occupy, which stands you three studs
        -- higher, so the NEXT cycle's anchor is one cell up, and the one after that
        -- another. Within a dozen platforms the farm is building in open sky, where
        -- Islands refuses every placement because nothing supports it, and the run
        -- ends with "nothing placed" at a spot the owner never chose. Anchor once,
        -- where the run was started, and keep building there.
        local anchor = Cache.PlatformAnchor
        if not anchor or not State.PlatformStay then
            -- Layer 0 is the cell layer directly ABOVE the ground under your feet, so
            -- it rests on that ground and each layer above rests on the one below.
            anchor = Vector3.new(
                snap(hrp.Position.X, g.X),
                snap(hrp.Position.Y - 4.5, g.Y) + 3,
                snap(hrp.Position.Z, g.Z))
            Cache.PlatformAnchor = anchor
        end

        -- STAY WHERE THE PLATFORM IS. Demolishing the floor you are standing on drops
        -- you off it. Only pull you back when you have actually drifted off the
        -- footprint, so it does not fight you for control of your character every few
        -- seconds -- and never when you asked it not to.
        if State.PlatformStay then
            if (hrp.Position - anchor).Magnitude > math.max(24, n * 3) then
                pcall(function()
                    hrp.CFrame = CFrame.new(anchor + Vector3.new(0, 4.5, 0))
                    hrp.AssemblyLinearVelocity = Vector3.zero
                end)
                task.wait(0.15)
            end
        end

        local occ = occupancyOf(anchor, n, layers)
        if gen ~= State.PlatformFarmGen then return false end

        -- ---- place ----
        local have = (Cache.countInventory()[mat]) or 0
        local cells = platformCells(anchor, n, layers)
        local want = {}
        for _, p in ipairs(cells) do
            if not occ[cellKey(anchor, p)] then want[#want + 1] = p end
        end
        if #want == 0 then
            Cache.notify({Title="Platform Farm", Content="Every cell of the footprint is already filled. Move somewhere with room above the ground, or raise the size.", Duration=10})
            return false
        end
        -- BROKEN BLOCKS TAKE A MOMENT TO COME BACK. The cycle that just demolished a
        -- platform returns its blocks to you, but not before the next cycle asks how
        -- many you have -- so an empty count right after a demolish is usually the
        -- refund still in the post, not an empty hotbar. Wait for it before giving up.
        if have <= 0 then
            local until_ = os.clock() + 8
            repeat
                task.wait(0.25)
                if gen ~= State.PlatformFarmGen then return false end
                have = (Cache.countInventory()[mat]) or 0
            until have > 0 or os.clock() >= until_
        end
        -- the hotbar is all countInventory can see, so a zero that outlives the wait
        -- means "nothing in a slot", not "nothing owned": say that rather than
        -- telling someone with a full island inventory that they are out of blocks.
        if have <= 0 then
            Cache.notify({Title="Platform Farm — Out Of Material", Content=string.format(
                "No '%s' in your hotbar. Put a stack of it in a slot (the script can only count the 8 hotbar slots and the held tool, not your island inventory) and switch it back on.",
                fixname(mat)), Duration=14})
            return false
        end
        -- budget is what we INTEND to send; `sent` below is what actually went out,
        -- and the difference matters: the place loop can run out of time against a
        -- saturated pool, and waiting for blocks we never asked for would stall every
        -- cycle for the full six seconds.
        local budget = math.min(#want, have)
        local placedKeys = {}
        local i = 1
        local placeEnd = os.clock() + 20
        while i <= budget do
            if gen ~= State.PlatformFarmGen then return false end
            if Cache.sendPlacePooled(CFrame.new(want[i]), mat) then
                Cache.PlatformPlaced = (Cache.PlatformPlaced or 0) + 1
                placedKeys[cellKey(anchor, want[i])] = true
                i = i + 1
            else
                -- pool saturated: wait for a slot and RETRY THE SAME CELL. Skipping to
                -- the next one on a full pool is what left the old placement loops
                -- walking a list they never fired into (see the nuke's batch loop).
                if os.clock() >= placeEnd then break end
                task.wait()
            end
        end

        local sent = i - 1

        -- ---- collect and demolish, in the same loop ----
        --
        -- WAITING FOR THE WHOLE PLATFORM BEFORE HITTING ANY OF IT WAS THE SLOW PART.
        -- The old cycle polled the footprint until the count stopped climbing -- up to
        -- six seconds of scanning a region while every block already standing in it
        -- sat there unbroken -- and only then started swinging. Blocks arrive over
        -- hundreds of milliseconds, so there is always something to hit long before
        -- the last one lands. Now one loop does both: claim whatever has appeared,
        -- hit it, claim again. The placements finish arriving while the first of them
        -- are already breaking, and a cycle costs about what the breaking costs.
        local seenMine, ourName = {}, nil
        local alive = {}

        -- OURS IS: a cell we placed into, that was empty when we looked, and that now
        -- holds a block. All three, not any one of them -- this is the whole reason
        -- the farm is safe to run on top of an island you care about.
        local function claimNew()
            local fresh = occupancyOf(anchor, n, layers)
            local batch = {}
            for k, blk in pairs(fresh) do
                if placedKeys[k] and not occ[k] and blk.Parent and not seenMine[blk] then
                    batch[#batch + 1] = blk
                end
            end
            -- The one way a real island block could still reach this list is the
            -- occupancy scan having missed it, and such a stray is by definition the
            -- odd one out in a platform of one material. Settle the name on the first
            -- batch big enough to have a majority, then hold every later straggler to
            -- it -- a straggler arriving alone has no majority of its own to appeal to.
            if not ourName and #batch > 1 then
                local tally, top = {}, 0
                for _, blk in ipairs(batch) do
                    local c = (tally[blk.Name] or 0) + 1
                    tally[blk.Name] = c
                    if c > top then ourName, top = blk.Name, c end
                end
            end
            local added = 0
            for _, blk in ipairs(batch) do
                if not ourName or blk.Name == ourName then
                    seenMine[blk] = true
                    alive[#alive + 1] = blk
                    added = added + 1
                end
            end
            return added
        end

        -- A platform is one material, so the tool is decided once for the whole cycle
        -- rather than re-asked per block. Which tool the server thinks you hold is what
        -- it judges every break request on.
        if State.PlatformHoldTool then Cache.equipBreakTool() end

        local claimed = claimNew()
        local brokeAtStart, hitsThisCycle = Cache.PlatformBroke or 0, 0
        local demoEnd = os.clock() + 45
        local quietRounds = 0
        while os.clock() < demoEnd do
            if gen ~= State.PlatformFarmGen then return false end

            -- hit everything currently standing, retrying a block rather than skipping
            -- it when the pool is full (the lesson the nuke's batch loop records)
            local still, j = {}, 1
            while j <= #alive do
                if gen ~= State.PlatformFarmGen then return false end
                local blk = alive[j]
                if not blk.Parent then
                    Cache.PlatformBroke = (Cache.PlatformBroke or 0) + 1
                    j = j + 1
                elseif hitblock(blk, Cache.getPart(blk)) then
                    hitsThisCycle = hitsThisCycle + 1
                    still[#still + 1] = blk
                    j = j + 1
                else
                    if os.clock() >= demoEnd then
                        for t = j, #alive do still[#still + 1] = alive[t] end
                        break
                    end
                    task.wait()
                end
            end
            alive = still

            task.wait()
            -- sweep the ones that died while the batch was in flight
            local left = {}
            for _, blk in ipairs(alive) do
                if blk.Parent then left[#left + 1] = blk
                else Cache.PlatformBroke = (Cache.PlatformBroke or 0) + 1 end
            end
            alive = left

            -- then look for placements that have landed since
            local added = claimNew()
            claimed = claimed + added
            -- DONE IS: nothing standing, and nothing new arriving. Two quiet rounds
            -- rather than one, because a single empty scan mid-flight is normal.
            if #alive == 0 and added == 0 then
                quietRounds = quietRounds + 1
                if quietRounds >= 2 or claimed >= sent then break end
                task.wait(0.1)
            else
                quietRounds = 0
            end
        end

        if claimed == 0 then
            -- ARM THE SAME RECOVERY AUTO BUILD USES. Nothing placed is either a bad
            -- block id or the game having changed its place request, and only one of
            -- those has a fix from in here. The chunked engine (182) arms this exact
            -- capture on the same evidence and for the same reason.
            local armed = false
            if not Cache.EverPlaced and not Cache.BlockPlaceTemplate
            and Cache.ensureRemoteSpy and Cache.ensureRemoteSpy() then
                armed = true
                Cache.captureBlockPlace(180)
            end
            Cache.notify({Title="Platform Farm — Nothing Placed", Content=string.format(
                "%d placement request(s) went out for '%s' and no block appeared.%s",
                sent, fixname(mat), armed
                    and " Either that id is not a placeable block, or the game has changed its place request — place ONE block by hand in the next 3 minutes and the script learns the current format, for this session and every future one."
                    or " Check the block id: an id the game doesn't know is placed into nothing, quietly."), Duration=18})
            return false
        end
        Cache.PlatformCycles = (Cache.PlatformCycles or 0) + 1
        -- A WHOLE PLATFORM STANDING AFTER 45s OF HITS is not a hard material: not one
        -- block of it went. That is the break request being refused, and the fix is the
        -- one Block Nuke has always had -- learn the live format from one hand-swing.
        if #alive > 0 and hitsThisCycle >= 40 and (Cache.PlatformBroke or 0) == brokeAtStart then
            if Cache.armBreakFix("Platform Farm", hitsThisCycle) then return false end
        end
        if #alive > 0 then
            -- blocks that would not break in thirty seconds are not this loop's to
            -- solve, but leaving them silently would grow a platform forever
            Cache.notify({Title="Platform Farm", Content=string.format(
                "%d of this cycle's blocks would not break in 45s and were left standing. If that repeats, the material needs more swings than the loop allows — try a softer block, or pick a stronger tool under 'Break Tool'.",
                #alive), Duration=12})
        end
        -- a progress line every 20s, not every cycle: the cycles are seconds long
        local now = os.clock()
        if now - (Cache.PlatformSaidAt or 0) > 20 then
            Cache.PlatformSaidAt = now
            local secs = math.max(1, now - (Cache.PlatformStartedAt or now))
            Cache.notify({Title="Platform Farm", Content=string.format(
                "%d broken, %d placed, %d platform(s) — %.0f blocks broken a minute.",
                Cache.PlatformBroke or 0, Cache.PlatformPlaced or 0, Cache.PlatformCycles or 0,
                (Cache.PlatformBroke or 0) / secs * 60), Duration=6})
        end
        return true
    end

    -- ---- UI -----------------------------------------------------------------
    -- ITS OWN TAB, which is also what lets it be cut without leaving a dead sidebar
    -- entry -- the arrangement 150_tab_combat.lua exists to demonstrate. Order 65 puts
    -- it between Combat (60) and Farming (70): it is a grind, not a build. On Cache
    -- rather than a file-level local, because the register budget is the thing that
    -- bites in this file and Cache.ShopTab already sets the precedent.
    Cache.HammerTab = Window:CreateTab("Hammer", "\u{26CF}", 65)
    local T = Cache.HammerTab
    T:CreateSection("Platform Farm — Build It, Then Break It")
    T:CreateNote("Places a platform of your material and breaks every block of it, on a loop, to farm blocks-broken. It only breaks the blocks it placed — cells that were already filled are left alone.")

    local MatDD
    MatDD = T:CreateDropdown({ Name="Platform Material", Options=getinv(), CurrentOption={""}, Callback=function(v)
        State.PlatformMaterial = type(v) == "table" and v[1] or v
    end})
    T:CreateButton({ Name="Refresh Materials", Callback=function()
        Cache.InvCache = nil    -- getinv caches for half a second; this wants it now
        -- no selection argument: rebuild the list and leave the current pick alone
        if MatDD and MatDD.Refresh then MatDD:Refresh(getinv()) end
    end})
    -- the Backpack is usually still empty when the UI is built, so the first list is
    -- {"Empty"}; fill it in once the character has loaded, WITHOUT picking for them
    task.spawn(function()
        task.wait(3)
        Cache.InvCache = nil
        if MatDD and MatDD.Refresh then pcall(function() MatDD:Refresh(getinv()) end) end
    end)
    -- the hotbar is usually empty when the UI is built, so both tool lists start at
    -- {"Auto"}; fill them in once the character has loaded
    task.spawn(function() task.wait(3); pcall(Cache.syncBreakToolDDs) end)
    T:CreateInput({ Name="Material Id (overrides)", PlaceholderText="e.g. grass", Callback=function(v)
        State.PlatformMaterialTyped = v or ""
    end})
    -- 32x32x4 is four thousand blocks a cycle; the far end of these sliders is for
    -- servers that take it, not a recommendation.
    T:CreateSlider({ Name="Platform Size (N x N)", Step=1, Range={2,32}, Increment=1, Suffix="", CurrentValue=Settings.PlatformSize, Callback=function(v) Settings.PlatformSize = v end})
    T:CreateSlider({ Name="Layers (stacked)", Step=1, Range={1,8}, Increment=1, Suffix="", CurrentValue=Settings.PlatformLayers, Callback=function(v) Settings.PlatformLayers = v end})
    -- On: the run keeps one anchor and pulls you back to it when you drift off.
    -- Off: every cycle builds wherever you are standing, so you can walk the farm
    -- around -- at the cost of the platform climbing if it stands you on itself.
    -- The same control as the Block Nuker's, sharing the same Cache.BreakToolName --
    -- picking a hammer in one place sets it in both, because there is only ever one
    -- tool in your hand and two dropdowns disagreeing about it would be a bug.
    Cache.PlatformToolDD = T:CreateDropdown({ Name="Break Tool",
        Options = Cache.BreakToolName and {"Auto", Cache.BreakToolName} or {"Auto"},
        CurrentOption = { Cache.BreakToolName or "Auto" }, Callback=function(v)
        local pick = type(v) == "table" and v[1] or v
        Cache.BreakToolName = (pick and pick ~= "Auto") and pick or nil
        Cache.ToldNoBreakTool = false
        if Cache.queueFarmSave then Cache.queueFarmSave() end
        Cache.syncBreakToolDDs()
    end})
    T:CreateButton({ Name="Find My Break Tools", Callback=function()
        local list = Cache.breakToolList()
        Cache.syncBreakToolDDs()
        Cache.notify({Title="Break Tool", Content=(#list > 0)
            and ("Found: " .. table.concat(list, ", ") .. ". Every tool in your hotbar is listed, likeliest breakers first — it never guesses a tool you do not own, and never hides one because of its name.")
            or "No tools at all in your hotbar. Put one in a slot and press this again.", Duration=10})
    end})
    -- BY HAND, ON PURPOSE. The automatic capture only arms after a run has proved
    -- nothing breaks, once a session; this is the same capture for whoever already
    -- knows -- after a game update, or when a learned format has gone stale.
    T:CreateButton({ Name="Learn Block Break (break one by hand)", Callback=function()
        Cache.HitHealArmed = true
        Cache.captureBlockHit(30)
    end})
    T:CreateButton({ Name="Forget The Learned Break", Callback=function()
        Cache.BlockHitTemplate = nil
        Cache.HitHealArmed = false
        pcall(function() if isfile and delfile and isfile("Islands trading hub/blockhit.json") then delfile("Islands trading hub/blockhit.json") end end)
        Cache.notify({Title="Block Break", Content="Forgotten. Breaking uses the built-in format again until you press 'Learn Block Break (break one by hand)'.", Duration=8})
    end})
    T:CreateToggle({ Name="Hold The Break Tool While Demolishing", CurrentValue=true, Callback=function(v)
        State.PlatformHoldTool = v
        Cache.ToldNoBreakTool = false
    end})
    T:CreateToggle({ Name="Stay At The Build Spot (teleport back)", CurrentValue=true, Callback=function(v)
        State.PlatformStay = v
        if v then Cache.PlatformAnchor = nil end   -- re-anchor where you are now
    end})
    T:CreateToggle({ Name="Platform Farm", CurrentValue=false, Callback=function(v)
        State.PlatformFarmEnabled = v
        if not v then
            State.PlatformFarmGen = (State.PlatformFarmGen or 0) + 1
            if Cache.PlatformStartedAt then
                local secs = math.max(1, os.clock() - Cache.PlatformStartedAt)
                Cache.PlatformStartedAt = nil
                Cache.notify({Title="Platform Farm — Stopped", Content=string.format(
                    "%d block(s) broken and %d placed over %d platform(s) in %d second(s) — %.0f broken a minute.",
                    Cache.PlatformBroke or 0, Cache.PlatformPlaced or 0, Cache.PlatformCycles or 0,
                    math.floor(secs + 0.5), (Cache.PlatformBroke or 0) / secs * 60), Duration=12})
            end
            return
        end
        State.PlatformFarmGen = (State.PlatformFarmGen or 0) + 1
        local gen = State.PlatformFarmGen
        Cache.PlatformBroke, Cache.PlatformPlaced, Cache.PlatformCycles = 0, 0, 0
        Cache.PlatformStartedAt, Cache.PlatformSaidAt = os.clock(), 0
        Cache.PlatformAnchor = nil
        addloop(task.spawn(function()
            while State.PlatformFarmEnabled and gen == State.PlatformFarmGen do
                local ok, keepGoing = pcall(cycle, gen)
                if not ok then
                    -- say why, rather than the switch just going dark
                    Cache.notify({Title="Platform Farm — Stopped", Content="It hit a script error: " .. tostring(keepGoing), Duration=12})
                    break
                end
                if keepGoing == false then break end
                task.wait()
            end
            -- one switch-off path, whether the loop ended itself or was stopped
            if gen == State.PlatformFarmGen and State.PlatformFarmEnabled then
                local tf = Cache.ToggleFunctions and Cache.ToggleFunctions["Platform Farm"]
                if tf then pcall(tf, false) else State.PlatformFarmEnabled = false end
            end
        end))
    end})
end
Cache.platformFarmUI()
-- ==== end of PLATFORM FARM =====================================================

-- Tools for making NEW blueprints from what is standing on an island, plus block
-- removal helpers. Moved below the build/queue flow: daily use is pick->build.
ToolsTab:CreateSection("Create Blueprint & Island Tools")
ToolsTab:CreateNote("Make a blueprint from a selection or the whole island, and clear junk off the island.")

-- ---- selecting blocks on the island ---------------------------------------
ToolsTab:CreateToggle({ Name="Region Selection (Alt+Click)", CurrentValue=false, Callback=function(v)
    State.BlueprintSelectionMode = v
    if not v then
        State.BlueprintPos1 = nil; State.BlueprintPos2 = nil
        safedestroy(Cache.BlueprintRegionHL);  Cache.BlueprintRegionHL  = nil
        safedestroy(Cache.BlueprintRegionSB);  Cache.BlueprintRegionSB  = nil
        safedestroy(Cache.BlueprintRegionPart); Cache.BlueprintRegionPart = nil
    end
end})
ToolsTab:CreateToggle({ Name="Block Selection (Alt+Click)", CurrentValue=false, Callback=function(v)
    State.SpecificBlockSelectionEnabled = v
    if not v then
        for _, data in pairs(Cache.SpecificSelection or {}) do if data.highlight then data.highlight:Destroy() end end
        Cache.SpecificSelection = {}
    end
end})
ToolsTab:CreateButton({ Name="Clear Block Selection", Callback=function()
    for _, hl in pairs(Cache.SpecificSelection or {}) do if hl.highlight then hl.highlight:Destroy() end end
    Cache.SpecificSelection = {}
    Window:Notify({Title="Cleared", Content="Selection cleared.", Duration=2})
end})

-- Fills the Block-Selection set from the Alt+Click REGION (Pos1/Pos2), so the remove
-- tools work on whole areas without clicking every block individually. Returns how
-- many blocks were added. Yields on big regions; call from a spawned thread.
function Cache.selectRegionBlocks()
    if not (State.BlueprintPos1 and State.BlueprintPos2) then return 0 end
    local half = Vector3.new(1.5, 1.5, 1.5)
    local p1, p2 = State.BlueprintPos1, State.BlueprintPos2
    local minPos = Vector3.new(math.min(p1.X, p2.X), math.min(p1.Y, p2.Y), math.min(p1.Z, p2.Z)) - half
    local maxPos = Vector3.new(math.max(p1.X, p2.X), math.max(p1.Y, p2.Y), math.max(p1.Z, p2.Z)) + half
    local op = OverlapParams.new()
    op.FilterType = Enum.RaycastFilterType.Exclude
    op.FilterDescendantsInstances = { LocalPlayer.Character }
    op.MaxParts = 100000  -- default is 20(!) which would truncate any real region
    local parts = Workspace:GetPartBoundsInBox(
        CFrame.new((minPos + maxPos) / 2), maxPos - minPos - Vector3.new(0.1, 0.1, 0.1), op)  -- shrink: +0.1 overlapped the ring of blocks OUTSIDE the marked region
    Cache.SpecificSelection = Cache.SpecificSelection or {}
    local sel = Cache.SpecificSelection
    local added = 0
    for i, part in ipairs(parts) do
        local block, cur = nil, part
        while cur and cur.Parent do
            if cur.Parent.Name == "Blocks" then block = cur; break end
            if cur.Parent == Workspace then break end
            cur = cur.Parent
        end
        -- bedrock is unbreakable; selecting it would make the remove loop spin forever
        if block and block.Name ~= "bedrock" and not sel[block] then
            sel[block] = {}
            added += 1
        end
        if i % 500 == 0 then task.wait() end
    end
    return added
end

-- Block remover: break every block in the current Block-Selection set via the proven
-- BlockHit remote. No tool auto-switch (per request) -- equip your pickaxe/axe first.
-- Blocks needing several hits are handled by the loop toggle re-calling this.
function Cache.removeSelectedBlocks()
    local sel = Cache.SpecificSelection or {}
    local any = false
    -- walk a copy of the keys: this loop yields per block, and Alt+Click or "Select
    -- Stray Sky Blocks" adding to the set mid-walk is undefined for pairs/next
    local keys = {}
    for block in pairs(sel) do keys[#keys + 1] = block end
    for _, block in ipairs(keys) do
        local data = sel[block]
        if State.IsCleaningUp then break end
        if block and block.Parent then
            any = true
            if State.NukeAutoTool then Cache.equipToolFor(block.Name) end
            hitblock(block, Cache.getPart(block))
            task.wait(0.03)
        else
            if data and data.highlight then pcall(function() freehighlight(data.highlight) end) end
            sel[block] = nil
        end
    end
    return any
end
ToolsTab:CreateButton({ Name="Remove Selected Blocks", Callback=function()
    task.spawn(function()
        -- no clicked blocks but a region is marked? use the region.
        if not next(Cache.SpecificSelection or {}) then
            local added = Cache.selectRegionBlocks()
            if added > 0 then
                Window:Notify({Title="Remove", Content="Selected " .. added .. " block(s) from the region.", Duration=3})
            end
        end
        if not next(Cache.SpecificSelection or {}) then
            Window:Notify({Title="Remove", Content="Nothing selected: Alt+Click blocks (Block Selection) or mark two corners (Region Selection).", Duration=4}); return
        end
        Cache.removeSelectedBlocks()
    end)
end})
-- STRAY SKY CLEANUP. The old anchor bug left streaks of blocks hanging in the sky —
-- placed while the origin drifted, so they belong to no blueprint position. Selecting
-- them by hand across an island is hopeless. This finds every standing block that is
-- (a) NOT part of the blueprint at its current origin and (b) ABOVE the blueprint's
-- top layer — nothing legitimate lives up there, so terrain, chests and the shop
-- itself can never match. It only SELECTS (highlights): review what lit up, then run
-- the existing 'Auto Remove Selected (loop)' to actually delete.
ToolsTab:CreateButton({ Name="Select Stray Sky Blocks (junk above the build)", Callback=function()
    if not Cache.LoadedBlueprintData then
        Window:Notify({Title="Stray Cleanup", Content="Select the blueprint first — strays are defined as blocks that DON'T belong to it.", Duration=5}); return
    end
    if State.AutoBlueprintEnabled and not State.BlueprintPaused then
        Window:Notify({Title="Stray Cleanup", Content="Pause the build first.", Duration=4}); return
    end
    task.spawn(function()
        local startCF = getblueprintstartcframe()
        if not startCF then Window:Notify({Title="Stray Cleanup", Content="Could not resolve the build position.", Duration=4}); return end
        Window:Notify({Title="Stray Cleanup", Content="Scanning the island for junk above the build...", Duration=4})
        -- blueprint occupancy + top height, at the current origin
        local bpKeys, topY = {}, -math.huge
        for i, bd in ipairs(Cache.LoadedBlueprintData) do
            if type(bd) == "table" and type(bd.cframe) == "table" then
                local p = (startCF * parseBlueprintCFrame(bd.cframe)).Position
                bpKeys[string.format("%d,%d,%d", math.floor(p.X*10 + 0.5), math.floor(p.Y*10 + 0.5), math.floor(p.Z*10 + 0.5))] = true
                if p.Y > topY then topY = p.Y end
            end
            if i % 4000 == 0 then task.wait() end
        end
        if topY == -math.huge then Window:Notify({Title="Stray Cleanup", Content="Blueprint has no usable blocks.", Duration=4}); return end
        local isl = Cache.buildIslandModel()
        local blocks = isl and isl:FindFirstChild("Blocks")
        if not blocks then Window:Notify({Title="Stray Cleanup", Content="No island found to scan.", Duration=4}); return end
        -- one walk: collect non-blueprint candidates, and find the roofline — the
        -- highest island block that IS a blueprint position. Junk hangs at or above
        -- the roof; personal builds/farms/chests live far below it.
        local candidates, placedTopY, n = {}, -math.huge, 0
        for _, b in ipairs(blocks:GetChildren()) do
            local part = Cache.getPart(b)
            local p = part and part.Position
            if p and b.Name ~= "bedrock" then
                local key = string.format("%d,%d,%d", math.floor(p.X*10 + 0.5), math.floor(p.Y*10 + 0.5), math.floor(p.Z*10 + 0.5))
                if bpKeys[key] then
                    if p.Y > placedTopY then placedTopY = p.Y end
                else
                    candidates[#candidates + 1] = { b = b, y = p.Y }
                end
            end
            n += 1
            if n % 12000 == 0 then task.wait() end
        end
        -- threshold: just under the roofline (or the blueprint top if nothing is
        -- placed yet). 3.1 = one cell of slack so junk wedged level with the roof
        -- still counts.
        local minY = (placedTopY > -math.huge and placedTopY or topY) - 3.1
        Cache.SpecificSelection = Cache.SpecificSelection or {}
        local sel, found = Cache.SpecificSelection, 0
        for _, c in ipairs(candidates) do
            if c.y > minY and not sel[c.b] then
                sel[c.b] = {}
                found += 1
            end
        end
        if found == 0 then
            Window:Notify({Title="Stray Cleanup", Content="Nothing above the build that isn't the build — no junk found.", Duration=6})
        else
            Window:Notify({Title="Stray Cleanup", Content=string.format(
                "%d stray block(s) highlighted above the build. Check they're the junk (they glow), then turn on 'Auto Remove Selected (loop)' to delete them.",
                found), Duration=12})
        end
    end)
end})
ToolsTab:CreateToggle({ Name="Auto Remove Selected (loop)", CurrentValue=false, Callback=function(v)
    State.RemoveLoopEnabled = v
    if v then
        State.RemoveGen = (State.RemoveGen or 0) + 1; local gen = State.RemoveGen
        addloop(task.spawn(function()
            -- no clicked blocks but a region is marked? fill the selection from it
            -- (done in this thread: the region scan yields on big areas)
            if not next(Cache.SpecificSelection or {}) then
                local added = Cache.selectRegionBlocks()
                if added > 0 then
                    Window:Notify({Title="Auto Remove", Content="Selected " .. added .. " block(s) from the region — removing...", Duration=3})
                end
            end
            -- still nothing: tell the user and snap the switch back off (it used to
            -- stay visually ON with a dead loop, feeling completely unresponsive)
            if not next(Cache.SpecificSelection or {}) then
                Window:Notify({Title="Auto Remove", Content="Nothing selected: Alt+Click blocks (Block Selection) or mark two corners (Region Selection).", Duration=4})
                State.RemoveLoopEnabled = false
                local tf = Cache.ToggleFunctions["Auto Remove Selected (loop)"]
                if tf then task.defer(tf, false) end
                return
            end
            while State.RemoveLoopEnabled and gen == State.RemoveGen do
                Cache.removeSelectedBlocks()
                if not next(Cache.SpecificSelection or {}) then
                    State.RemoveLoopEnabled = false
                    -- sync the switch so it doesn't stay visually ON after self-stopping
                    local tf = Cache.ToggleFunctions["Auto Remove Selected (loop)"]
                    if tf then task.defer(tf, false) end
                    Window:Notify({Title="Auto Remove", Content="Selection fully removed.", Duration=3})
                    break
                end
                task.wait(0.15)
            end
        end))
    end
end})
ToolsTab:CreateDivider()

-- ---- saving a selection or the island as a blueprint ----------------------
-- Save Selection
ToolsTab:CreateButton({ Name="Save Selection", Callback=function()
    if not (writefile and isfolder and makefolder) then Window:Notify({Title="Error",Content="Filesystem not supported.",Duration=3}); return end
    task.spawn(function()
        local blocks = {}
        local minPos, maxPos
        -- UPGRADES AND CONTENTS RIDE ALONG (086_bp_extras.lua): an optional `extra` per
        -- entry, which old readers and both engines ignore. Guarded so a build without
        -- 086 saves exactly what it always did.
        local extraBudget = { n = 0 }
        local function attachExtra(entry, block)
            return Cache.bpxAttach and Cache.bpxAttach(entry, block, extraBudget) or entry
        end

        if State.BlueprintPos1 and State.BlueprintPos2 then
            local half = Vector3.new(1.5,1.5,1.5)
            minPos = Vector3.new(math.min(State.BlueprintPos1.X,State.BlueprintPos2.X), math.min(State.BlueprintPos1.Y,State.BlueprintPos2.Y), math.min(State.BlueprintPos1.Z,State.BlueprintPos2.Z)) - half
            maxPos = Vector3.new(math.max(State.BlueprintPos1.X,State.BlueprintPos2.X), math.max(State.BlueprintPos1.Y,State.BlueprintPos2.Y), math.max(State.BlueprintPos1.Z,State.BlueprintPos2.Z)) + half
            local regionCF = CFrame.new((minPos+maxPos)/2)
            local regionSize = maxPos - minPos - Vector3.new(0.1,0.1,0.1)  -- shrink: +0.1 saved a shell of foreign blocks around the region
            local op = OverlapParams.new(); op.FilterType = Enum.RaycastFilterType.Exclude; op.FilterDescendantsInstances = {LocalPlayer.Character}
            op.MaxParts = 100000  -- OverlapParams defaults to 20 parts, silently truncating region saves
            local parts = Workspace:GetPartBoundsInBox(regionCF, regionSize, op)
            local originCF = CFrame.new(minPos); local saved = {}
            for _, part in ipairs(parts) do
                local block, cur = nil, part
                while cur and cur.Parent do
                    if cur.Parent.Name == "Blocks" then block = cur; break end
                    if cur.Parent == Workspace then break end
                    cur = cur.Parent
                end
                if block and not saved[block] then
                    saved[block] = true
                    local bp2 = (block:IsA("BasePart") and block) or (block:IsA("Model") and (block.PrimaryPart or block:FindFirstChildWhichIsA("BasePart")))
                    -- `extra` (086): the block's upgrade levels and machine contents, optional
                    if bp2 then table.insert(blocks, attachExtra({blockType=block.Name, cframe={originCF:ToObjectSpace(bp2.CFrame):GetComponents()}}, block)) end
                end
            end
        else
            local selected = {}
            for block in pairs(Cache.SpecificSelection or {}) do if block and block.Parent then table.insert(selected, block) end end
            if #selected == 0 then Window:Notify({Title="Error",Content="No selection.",Duration=3}); return end
            for _, block in ipairs(selected) do
                local bp2 = (block:IsA("BasePart") and block) or (block:IsA("Model") and (block.PrimaryPart or block:FindFirstChildWhichIsA("BasePart")))
                if bp2 then
                    local pos = bp2.Position
                    if not minPos then minPos = pos; maxPos = pos
                    else
                        minPos = Vector3.new(math.min(minPos.X,pos.X),math.min(minPos.Y,pos.Y),math.min(minPos.Z,pos.Z))
                        maxPos = Vector3.new(math.max(maxPos.X,pos.X),math.max(maxPos.Y,pos.Y),math.max(maxPos.Z,pos.Z))
                    end
                end
            end
            if not minPos then Window:Notify({Title="Error",Content="No valid blocks.",Duration=3}); return end
            local originCF = CFrame.new(minPos - Vector3.new(1.5,1.5,1.5))
            for _, block in ipairs(selected) do
                local bp2 = (block:IsA("BasePart") and block) or (block:IsA("Model") and (block.PrimaryPart or block:FindFirstChildWhichIsA("BasePart")))
                if bp2 then table.insert(blocks, attachExtra({blockType=block.Name, cframe={originCF:ToObjectSpace(bp2.CFrame):GetComponents()}}, block)) end
            end
        end

        if #blocks == 0 then Window:Notify({Title="Error",Content="No blocks could be saved.",Duration=3}); return end
        local ok, encoded = pcall(function() return HttpService:JSONEncode({blocks=blocks}) end)
        if not ok then Window:Notify({Title="Error",Content="Failed to encode.",Duration=3}); return end

        local folder = "Islands trading hub/Blueprints"
        ensureBlueprintFolder()
        local baseName = State.BlueprintName ~= "" and State.BlueprintName or "MyBlueprint"
        local fileName = baseName; local counter = 2
        while isfile(folder .. "/" .. fileName .. ".json") do fileName = baseName .. counter; counter += 1 end
        State.BlueprintName = fileName
        writefile(folder .. "/" .. fileName .. ".json", encoded)
        Window:Notify({Title="Saved", Content="Saved " .. fileName .. " with " .. #blocks .. " blocks.", Duration=3})
        if BlueprintDD then
            local bps = refreshblueprints()
            State.IsSilentRefresh = true; BlueprintDD:Refresh(bps, fileName); State.IsSilentRefresh = false
            loadblueprint(fileName)
            if Cache.LoadedBlueprintData then
                Window:Notify({Title="Blueprint Loaded", Content=string.format("Auto-loaded %d blocks.", #Cache.LoadedBlueprintData), Duration=3})
                if ReplaceSourceDropdown then
                    -- DE-DUPE ON THE LABEL AND KEEP THE MAP, the way 170 does. This
                    -- de-duped on the INTERNAL name, so two types that display the
                    -- same put the same row in the list twice -- and it never wrote
                    -- Cache.ItemNameMap, which is the only thing that can turn the
                    -- row back into a block type.
                    local blockTypes, seen = {}, {}
                    Cache.ItemNameMap = Cache.ItemNameMap or {}
                    for _, block in ipairs(Cache.LoadedBlueprintData) do
                        local d = fixname(block.blockType)
                        if not seen[d] then
                            seen[d] = true
                            table.insert(blockTypes, d)
                            Cache.ItemNameMap[d] = block.blockType
                        end
                    end
                    AllBlockTypes = blockTypes
                    if #blockTypes > 0 then ReplaceSourceDropdown:Refresh(blockTypes) end
                end
                updaterequiredblocksui()
                if Cache.refreshRemoveTypes then Cache.refreshRemoveTypes() end
            end
        end
    end)
end})

-- THE ISLAND AS BLUEPRINT ENTRIES: what 'Save Island' writes, and what the automatic
-- backup (254) writes on a schedule -- one scan, so a backup is exactly a Save Island.
-- Returns entries, originCF -- or nil, why. yieldEvery (optional) yields a frame every
-- that many blocks: a backup runs while you play, and a 30,000-block island read in
-- one go is a visible hitch. Save Island, pressed on purpose, does not yield.
function Cache.scanIslandToBlueprint(yieldEvery)
    local islands = Workspace:FindFirstChild("Islands")
    if not islands then return nil, "Could not find Islands folder." end
    local allBlocks, minPos = {}, nil
    -- YOUR island only: the folder also holds neighbours' islands, and saving them
    -- all put their plots in the backup and dragged its origin to their corner
    local mine = Cache.buildIslandModel and Cache.buildIslandModel()
    for _, island in ipairs(mine and { mine } or islands:GetChildren()) do
        local bf = island:FindFirstChild("Blocks"); if not bf then continue end
        for _, block in ipairs(bf:GetChildren()) do
            local part = (block:IsA("Model") and (block.PrimaryPart or block:FindFirstChildWhichIsA("BasePart"))) or block
            if part and part:IsA("BasePart") then
                table.insert(allBlocks, block)
                local pos = part.Position
                if not minPos then minPos = pos
                else minPos = Vector3.new(math.min(minPos.X,pos.X), math.min(minPos.Y,pos.Y), math.min(minPos.Z,pos.Z)) end
            end
        end
    end
    if #allBlocks == 0 then return nil, "No blocks found." end
    local originCF = CFrame.new(minPos - Vector3.new(1.5,1.5,1.5))
    local bpBlocks = {}
    -- optional `extra` per entry (086): upgrade levels and machine contents
    local extraBudget = { n = 0 }
    for i, block in ipairs(allBlocks) do
        if yieldEvery and i % yieldEvery == 0 then task.wait() end
        local blockPart = (block:IsA("Model") and (block.PrimaryPart or block:FindFirstChildWhichIsA("BasePart"))) or block
        if blockPart then
            local partsData = {}
            if block:IsA("Model") then
                for _, p in ipairs(block:GetDescendants()) do
                    if p:IsA("BasePart") then
                        local meshId, meshTex, meshScale, meshType
                        if p:IsA("MeshPart") then meshId = p.MeshId; meshTex = p.TextureID
                        else local sm = p:FindFirstChildOfClass("SpecialMesh")
                            if sm then meshId=sm.MeshId; meshTex=sm.TextureID; meshScale={sm.Scale.X,sm.Scale.Y,sm.Scale.Z}; meshType=sm.MeshType.Value end
                        end
                        table.insert(partsData, {
                            cframe={blockPart.CFrame:ToObjectSpace(p.CFrame):GetComponents()},
                            size={p.Size.X,p.Size.Y,p.Size.Z}, color={p.Color.R,p.Color.G,p.Color.B},
                            transparency=p.Transparency, material=p.Material.Name, className=p.ClassName,
                            meshId=meshId, meshTex=meshTex, meshScale=meshScale, meshType=meshType,
                        })
                    end
                end
            end
            local entry = {
                blockType=block.Name,
                cframe={originCF:ToObjectSpace(blockPart.CFrame):GetComponents()},
                parts=partsData,
            }
            if Cache.bpxAttach then Cache.bpxAttach(entry, block, extraBudget) end
            table.insert(bpBlocks, entry)
        end
    end
    return bpBlocks, originCF
end

