-- Rebuild the multiselect from the loaded blueprint: each type labeled with its count,
-- sorted most-first, preselecting anything already marked for removal.
function Cache.refreshRemoveTypes()
    local dd = Cache.RemoveTypesDD
    if not dd then return end
    Cache.RemoveTypeMap = {}
    local bp = Cache.LoadedBlueprintData
    if not bp then dd:Refresh({"Load blueprint first"}, {}); return end
    local counts = {}
    for _, block in ipairs(bp) do
        local bt = block.blockType
        if bt then counts[bt] = (counts[bt] or 0) + 1 end
    end
    local rows = {}
    for bt, n in pairs(counts) do rows[#rows + 1] = { bt = bt, n = n } end
    table.sort(rows, function(a, b) return a.n > b.n end)
    local opts, preselect = {}, {}
    for _, r in ipairs(rows) do
        local label = string.format("%s  x%s", fixname(r.bt), shortnum(r.n))
        Cache.RemoveTypeMap[label] = r.bt
        opts[#opts + 1] = label
        if State.BlueprintRemovals[r.bt] then preselect[#preselect + 1] = label end
    end
    if #opts == 0 then opts = {"(blueprint has no blocks)"} end
    dd:Refresh(opts, preselect)
end
Cache.refreshRemoveTypes()   -- initialize (shows the placeholder until a blueprint loads)

-- PER-BLUEPRINT MODS. Replacements and removals only ever lived in memory — nothing
-- wrote them anywhere. Re-injecting, switching builds and coming back, or just loading
-- the same blueprint tomorrow silently dropped the lot, and the build then went back to
-- placing the raw Minecraft types the server refuses. Keyed by blueprint name, so each
-- build keeps its own palette instead of one global set leaking across builds.
local MODS_FILE = "Islands trading hub/blockmods.json"

-- ---- mods on disk, per blueprint ------------------------------------------
function Cache.saveBlueprintMods()
    if not (writefile and isfolder and makefolder) then return end
    -- loadBlueprintMods drives the real toggles, whose callbacks land back here; writing
    -- the file mid-restore is pure churn
    if State.ModsLoading then return end
    local name = State.SelectedBlueprint
    if not name or name == "None" then return end
    if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
    -- merge, never overwrite: this file holds every blueprint's mods, and rewriting it
    -- from one build's state would wipe the others
    local all = {}
    if isfile and readfile and isfile(MODS_FILE) then
        local ok, data = pcall(function() return HttpService:JSONDecode(readfile(MODS_FILE)) end)
        if ok and type(data) == "table" then all = data end
    end
    local reps, removals = {}, {}
    for k, v in pairs(State.BlueprintReplacements) do reps[k] = v end
    for k in pairs(State.BlueprintRemovals) do removals[#removals + 1] = k end
    all[name] = {
        replacements   = reps,
        removals       = removals,
        replaceEnabled = State.BlueprintReplaceEnabled and true or false,
        removeEnabled  = State.BlueprintRemoveEnabled and true or false,
    }
    local ok, encoded = pcall(function() return HttpService:JSONEncode(all) end)
    if ok then pcall(function() writefile(MODS_FILE, encoded) end) end
end

function Cache.loadBlueprintMods(name)
    State.ModsLoading = true
    -- always start clean: switching to a blueprint with no saved mods must not inherit
    -- the previous build's replacements
    State.BlueprintReplacements = {}
    State.BlueprintRemovals = {}
    local entry
    if isfile and readfile and name and name ~= "None" and isfile(MODS_FILE) then
        local ok, all = pcall(function() return HttpService:JSONDecode(readfile(MODS_FILE)) end)
        if ok and type(all) == "table" and type(all[name]) == "table" then entry = all[name] end
    end
    if entry then
        if type(entry.replacements) == "table" then
            for k, v in pairs(entry.replacements) do
                if type(k) == "string" and type(v) == "string" then State.BlueprintReplacements[k] = v end
            end
        end
        if type(entry.removals) == "table" then
            for _, k in ipairs(entry.removals) do
                if type(k) == "string" then State.BlueprintRemovals[k] = true end
            end
        end
    end
    -- the toggles are what actually gate the maps: restoring the map while the switch
    -- reads OFF looks exactly like the replacements vanished again. Drive the real
    -- toggle so the UI and the state can't disagree.
    local tf = Cache.ToggleFunctions and Cache.ToggleFunctions["Enable Replacement"]
    if tf then pcall(tf, (entry and entry.replaceEnabled) and true or false) end
    local tr = Cache.ToggleFunctions and Cache.ToggleFunctions["Enable Removal"]
    if tr then pcall(tr, (entry and entry.removeEnabled) and true or false) end
    State.ModsLoading = false
    -- keep the copy-from list current: it can only offer OTHER builds
    if Cache.refreshCopyModsList then pcall(Cache.refreshCopyModsList) end
end

-- every build in the mods file except the one loaded now
function Cache.refreshCopyModsList()
    if not Cache.CopyModsDD then return end
    local names = {}
    if isfile and readfile and isfile(MODS_FILE) then
        local ok, all = pcall(function() return HttpService:JSONDecode(readfile(MODS_FILE)) end)
        if ok and type(all) == "table" then
            for name, entry in pairs(all) do
                if name ~= State.SelectedBlueprint and type(entry) == "table" then
                    -- an entry with nothing in it is not worth offering (JSONEncode
                    -- writes an empty map as [], so check both shapes)
                    local hasReps = type(entry.replacements) == "table" and next(entry.replacements) ~= nil
                    local hasRems = type(entry.removals) == "table" and #entry.removals > 0
                    if hasReps or hasRems then names[#names + 1] = name end
                end
            end
        end
    end
    table.sort(names)
    if #names == 0 then names[1] = "No other build has saved mods" end
    pcall(function() Cache.CopyModsDD:Refresh(names) end)
end

-- move (newName) or drop (newName nil) one build's saved mods on disk. The re-keying
-- rules are Cache.reindexBlueprintMods in 080, where a test can reach them; this is the
-- file around them.
function Cache.moveBlueprintMods(oldName, newName)
    if not (isfile and readfile and writefile and isfile(MODS_FILE)) then return end
    local ok, all = pcall(function() return HttpService:JSONDecode(readfile(MODS_FILE)) end)
    if not ok or type(all) ~= "table" then return end
    local changed
    all, changed = Cache.reindexBlueprintMods(all, oldName, newName)
    if not changed then return end
    local encoded
    ok, encoded = pcall(function() return HttpService:JSONEncode(all) end)
    if ok then pcall(function() writefile(MODS_FILE, encoded) end) end
end

-- take another build's replacements/removals wholesale. Returns the counts applied,
-- or nil when there was nothing to copy.
function Cache.copyBlueprintMods(from)
    if not (isfile and readfile and isfile(MODS_FILE)) then return nil end
    local ok, all = pcall(function() return HttpService:JSONDecode(readfile(MODS_FILE)) end)
    if not ok or type(all) ~= "table" then return nil end
    local entry = all[from]
    if type(entry) ~= "table" then return nil end
    local reps, rems = 0, 0
    if type(entry.replacements) == "table" then
        for k, v in pairs(entry.replacements) do
            if type(k) == "string" and type(v) == "string" then
                State.BlueprintReplacements[k] = v; reps += 1
            end
        end
    end
    if type(entry.removals) == "table" then
        for _, k in ipairs(entry.removals) do
            if type(k) == "string" then State.BlueprintRemovals[k] = true; rems += 1 end
        end
    end
    if reps == 0 and rems == 0 then return nil end
    -- the maps are inert until their switches are on, and a copy the user asked for
    -- that visibly changes nothing is the bug report we already fixed once
    local tf = Cache.ToggleFunctions and Cache.ToggleFunctions["Enable Replacement"]
    if reps > 0 and tf then pcall(tf, true) end
    local tr = Cache.ToggleFunctions and Cache.ToggleFunctions["Enable Removal"]
    if rems > 0 and tr then pcall(tr, true) end
    if Cache.BlueprintPreviewContainer then
        Cache.BlueprintPreviewContainer:Destroy(); Cache.BlueprintPreviewContainer = nil
    end
    Cache.LastPreviewCFrame = nil
    if Cache.refreshRemoveTypes then pcall(Cache.refreshRemoveTypes) end
    updaterequiredblocksui()
    Cache.saveBlueprintMods()
    return reps, rems
end

-- The two manual recovery buttons that used to live here ("Fix Auto Build (place 1
-- block by hand)" / "Reset Auto Build Fix") are gone: end users shouldn't have to know
-- what a payload capture is. The recovery itself is untouched and fully automatic —
-- armHeal() in the build runner arms the same capture the moment the server starts
-- rejecting placements, and tells you to place one block by hand.

-- ==================== SIGNS TAB, AND THE JOIN CODE SIGN ====================
-- The generator is 064_code_sign.lua. This is the controls, split off it for the
-- reason Block Fill is split the same way: a part with UI in it cannot be loaded by
-- tests/run_tests.py, which joins the stubs and the named parts into one chunk with
-- no UI library in it. Engine in the pure range, buttons here.
--
-- THIS PART OWNS THE SIGNS TAB, created here rather than in 082_ui_helpers.lua --
-- the arrangement 150_tab_combat.lua and 207_platform_farm.lua use, so that cutting
-- the part cuts the sidebar entry with it and never leaves one that opens on nothing.
-- It sits at 56, between Blueprints (55) and Combat (60).
--
-- Blueprints is about blueprints you CAPTURED -- save a selection, transform one,
-- clear the ground for it. This tab is about blueprints GENERATED from something you
-- typed. That is the line between the two, and it is why a code sign was never going
-- to read as another row on the Blueprints tab.
--
-- THE ICON IS AN EMOJI, NOT AN ASSET. The set in 030_services.lua has twelve pictures
-- and none of them is a sign, and a thirteenth cannot be invented: an asset id is
-- whatever number the image was uploaded under, so a guessed one renders as somebody
-- else's picture. This tab sat blank for that reason. An emoji has no id to guess --
-- the tab builder draws a short string that resolves to no image as a label in the
-- icon slot, tinted and animated like any other icon.
--
-- TEXT PRESENTATION, NOT EMOJI PRESENTATION -- which is the whole difference between
-- an icon and a sticker. The first pick here was U+1F520, four letters in a square,
-- chosen because it is from 2010 and widely drawn. It IS widely drawn: as a full-colour
-- blue tile, because its Emoji_Presentation property is Yes, and a character with that
-- property is drawn from the colour emoji font whatever you ask of it. The tab builder
-- sets TextColor3 to the same muted grey every other icon is tinted with, and the
-- colour glyph simply ignored it -- so the sidebar was nine line icons and one blue
-- sticker sitting among them.
--
-- U+270E is a pencil from Unicode 1.1 -- older still, so the availability argument only
-- gets stronger -- and its Emoji_Presentation is No. A text-presentation character is
-- drawn by the ordinary font, which means it takes the tint, and it goes muted and
-- accent-coloured with the rest of the sidebar as the tab is selected. Writing is also
-- nearer to what this tab does than an alphabet chart was.
--
-- The rule for the next one: an emoji in the icon slot must be text-presentation, or it
-- will not match the icons around it no matter how good the picture is.
Cache.SignsTab = Window:CreateTab("Signs", "✎", 56)

-- The live preview is 216_sign_preview.lua, a part of its own so it can be cut.
-- Sixteen callbacks below tell it the picture has changed; this is where those
-- calls land in a tier that does not have it.
if not Cache.markSignPreviewDirty then Cache.markSignPreviewDirty = function() end end

Cache.SignsTab:CreateSection("Join Code Sign")
Cache.SignsTab:CreateNote("Write on the island in blocks. Type it, pick a block, generate — it becomes a normal blueprint, so Check Materials Needed tells you the cost before you place a thing. A text box cannot hold a newline, so use a bar for one: BOBS|SHOP is two lines.")
do
    Cache.SignsTab:CreateInput({ Name="Code To Build", PlaceholderText="4K7QW2  —  or BOBS|SHOP for two lines", Callback=function(v)
        Cache.SignText = v
        Cache.markSignPreviewDirty()
    end})
    Cache.SignDD = Cache.SignsTab:CreateDropdown({ Name="Sign Block", Options={"Press Refresh Sign Blocks"},
        CurrentOption={"Press Refresh Sign Blocks"}, Callback=function(v)
            Cache.SignBlockName = type(v) == "table" and v[1] or v
            Cache.markSignPreviewDirty()
    end})
    -- WHEN THE PICKER COMES BACK EMPTY AND NOBODY CAN SAY WHY. Every block picker in
    -- the script -- this one, the QR's, Block Fill's -- reads LocalPlayer.Backpack
    -- through one function, so "nothing shows up" is one question with several
    -- possible answers and no way to tell them apart from the outside. This reports
    -- what the code actually sees rather than what it concluded: whether there is a
    -- Backpack, how many children it has, what they are called, what class they are,
    -- and whether they carry the Amount child Islands puts on a stack.
    --
    -- It ships in every tier on purpose, unlike the diagnostics that went to admin.
    -- Those explain features a buyer does not have; this one explains why a feature
    -- they DO have is showing them an empty list, which is the difference between a
    -- developer tool and a support answer. It writes to disk as well as notifying,
    -- so it still produces something if the notification is itself the problem.
    Cache.SignsTab:CreateButton({ Name="Why Is The Block List Empty?", Callback=function()
        task.spawn(function()
            local lines = {}
            local function say(fmt, ...) lines[#lines + 1] = select("#", ...) > 0 and string.format(fmt, ...) or fmt end

            local bp = LocalPlayer:FindFirstChild("Backpack")
            say("Backpack instance: %s", bp and "found" or "NOT FOUND (the character may still be loading)")
            local kids = bp and bp:GetChildren() or {}
            say("Children of Backpack: %d", #kids)
            local char = LocalPlayer.Character
            local held = char and char:FindFirstChildWhichIsA("Tool")
            say("Currently held Tool: %s", held and held.Name or "none")
            say("ReplicatedStorage.Tools: %s", ReplicatedStorage:FindFirstChild("Tools") and "found" or "NOT FOUND")
            say("ReplicatedStorage.Blocks: %s", ReplicatedStorage:FindFirstChild("Blocks") and "found" or "NOT FOUND")
            say("")
            say("What is in the Backpack, as the script sees it:")
            for i, item in ipairs(kids) do
                local amt = item:FindFirstChild("Amount") or item:FindFirstChild("Value")
                say("  %2d. %-28s class=%-12s amount=%s", i, tostring(item.Name), item.ClassName,
                    amt and tostring(amt.Value) or "(no Amount child)")
                if i >= 60 then say("  ... and %d more", #kids - 60); break end
            end
            say("")
            local ok, blocks = pcall(getbackpackblocks)
            if not ok then
                say("getbackpackblocks ERRORED: %s", tostring(blocks))
            else
                say("getbackpackblocks returned %d name(s):", #blocks)
                for i = 1, math.min(#blocks, 60) do say("  %s", tostring(blocks[i])) end
            end

            local body = table.concat(lines, "\n")
            local wrote = false
            if writefile and isfolder and makefolder then
                wrote = pcall(function()
                    if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
                    writefile("Islands trading hub/block_picker_report.txt", body)
                end)
            end
            Window:Notify({Title="Block List", Content=string.format(
                "Backpack: %s, %d item(s). getbackpackblocks: %s.%s",
                bp and "found" or "MISSING", #kids,
                ok and (#blocks .. " name(s)") or "ERRORED",
                wrote and "\nFull report written to Islands trading hub/block_picker_report.txt" or ""),
                Duration = 20})
            print("[Islands Hub] block picker report:\n" .. body)
        end)
    end})

    -- ---- presets ----------------------------------------------------------
    -- TWENTY CONTROLS IS THE PRICE OF BEING ABLE TO BUILD ANY SIGN, and it is a bad
    -- price to pay for the four signs anybody actually builds. A preset sets the
    -- shape of one of those four in a press.
    --
    -- What it deliberately does NOT do is choose blocks. Which blocks you have is a
    -- fact about your inventory, not about a style, and a preset that quietly moved
    -- 'Frame Block' onto whatever sorted first would be picking your colours for you.
    -- So it sets the numbers, moves the actual sliders rather than only the values
    -- behind them, and then says which pickers it has left for you.
    do
        local PRESETS = {
            ["Plain letters"]   = { border=0, pad=0, shadow=0, gap=1, align="Left",   style="Solid",   wants={} },
            ["Framed"]          = { border=1, pad=2, shadow=0, gap=1, align="Centre", style="Solid",
                                    wants={"Frame Block", "Backing Block (behind the letters)"} },
            -- three of padding, because that is what the inner line needs to exist
            ["Double framed"]   = { border=1, pad=3, shadow=0, gap=1, align="Centre", style="Double",
                                    wants={"Frame Block", "Backing Block (behind the letters)"} },
            ["Bracketed"]       = { border=2, pad=2, shadow=0, gap=2, align="Centre", style="Corners",
                                    wants={"Frame Block", "Backing Block (behind the letters)"} },
            ["Shop sign"]       = { border=2, pad=2, shadow=0, gap=2, align="Centre", style="Notched",
                                    wants={"Frame Block", "Backing Block (behind the letters)"} },
            -- padding, because an outline drawn into no air is an outline you cannot see
            ["Carved"]          = { border=0, pad=2, shadow=1, gap=1, align="Centre", style="Solid",
                                    wants={"Outline Block", "Shadow Block", "Backing Block (behind the letters)"} },
        }
        local ORDER = { "Plain letters", "Framed", "Double framed", "Bracketed", "Shop sign", "Carved" }
        Cache.SignsTab:CreateDropdown({ Name="Style Preset", Options=ORDER, CurrentOption={"Plain letters"},
            Callback=function(v)
                local pick = type(v) == "table" and v[1] or v
                local pr = PRESETS[pick]
                if not pr then return end
                Cache.SignBorder, Cache.SignPad = pr.border, pr.pad
                Cache.SignShadow, Cache.SignLineGap = pr.shadow, pr.gap
                Cache.SignAlign = pr.align
                Cache.SignBorderStyle = pr.style
                Cache.markSignPreviewDirty()
                -- move the controls too, or the panel shows the old numbers while the
                -- sign is built from the new ones -- which is the worst of both
                local sf = Window.SliderFunctions or {}
                if sf["Frame Thickness"] then sf["Frame Thickness"](pr.border) end
                if sf["Padding Inside The Frame"] then sf["Padding Inside The Frame"](pr.pad) end
                if sf["Shadow Offset"] then sf["Shadow Offset"](pr.shadow) end
                if sf["Line Spacing"] then sf["Line Spacing"](pr.gap) end
                -- and the two dropdowns (created further down, so looked up at run time)
                if Cache.SignAlignDD then pcall(function() Cache.SignAlignDD:Set(pr.align) end) end
                if Cache.SignFrameStyleDD then pcall(function() Cache.SignFrameStyleDD:Set(pr.style) end) end
                Cache.queueFarmSave()
                Cache.notify({Title="Join Code Sign", Content=(#pr.wants > 0)
                    and (pick .. ": set. Now pick a block in '" .. table.concat(pr.wants, "' and '") .. "' — a style cannot know what you are carrying.")
                    or (pick .. ": set. Bare letters in one block, nothing else to choose."), Duration=12})
        end})
    end

    -- A FRAME AND A PLATE ARE WHAT MAKE IT A SIGN RATHER THAN LETTERS ON THE GROUND.
    -- Both are optional and both default to off, because the cheapest sign is bare
    -- letters and that is what a join code usually wants. "None" is a real choice in
    -- these two, not a prompt to pick something.
    Cache.SignFrameDD = Cache.SignsTab:CreateDropdown({ Name="Frame Block", Options={"None"},
        CurrentOption={"None"}, Callback=function(v)
            local pick = type(v) == "table" and v[1] or v
            Cache.SignFrameName = (pick ~= "None") and pick or nil
            Cache.markSignPreviewDirty()
    end})
    Cache.SignPlateDD = Cache.SignsTab:CreateDropdown({ Name="Backing Block (behind the letters)", Options={"None"},
        CurrentOption={"None"}, Callback=function(v)
            local pick = type(v) == "table" and v[1] or v
            Cache.SignPlateName = (pick ~= "None") and pick or nil
            Cache.markSignPreviewDirty()
    end})
    Cache.SignsTab:CreateButton({ Name="Refresh Sign Blocks", Callback=function()
        local blocks = getbackpackblocks()
        if #blocks == 0 then
            Window:Notify({Title="Join Code Sign", Content=Cache.emptyPickerReason(), Duration=12}); return
        end
        if Cache.SignDD then Cache.SignDD:Refresh(blocks, Cache.SignBlockName or blocks[1]) end
        Cache.SignBlockName = Cache.SignBlockName or blocks[1]
        -- the frame and plate lists carry None at the top, since having neither is
        -- the common case and a dropdown with no way back to it is a trap
        local withNone = { "None" }
        for _, b in ipairs(blocks) do withNone[#withNone + 1] = b end
        if Cache.SignFrameDD   then Cache.SignFrameDD:Refresh(withNone, Cache.SignFrameName or "None") end
        if Cache.SignPlateDD   then Cache.SignPlateDD:Refresh(withNone, Cache.SignPlateName or "None") end
        if Cache.SignOutlineDD then Cache.SignOutlineDD:Refresh(withNone, Cache.SignOutlineName or "None") end
        if Cache.SignShadowDD  then Cache.SignShadowDD:Refresh(withNone, Cache.SignShadowName or "None") end
    end})
    -- Measured in glyph pixels like the line gap, so a frame stays proportional when
    -- the scale changes instead of thinning to a hairline around something enormous.
    -- AROUND THE LETTERS, NEVER THROUGH THEM. An outline is the letters' own pixels
    -- dilated outwards and the letters written back on top, so the holes in 0, 8 and
    -- Q cannot close -- which is exactly how an earlier attempt at a heavier face
    -- turned five characters into five identical blobs.
    Cache.SignOutlineDD = Cache.SignsTab:CreateDropdown({ Name="Outline Block", Options={"None"},
        CurrentOption={"None"}, Callback=function(v)
            local pick = type(v) == "table" and v[1] or v
            Cache.SignOutlineName = (pick ~= "None") and pick or nil
            Cache.markSignPreviewDirty()
    end})
    -- AN OUTLINE NEEDS SOMEWHERE TO GO. It is drawn into the air around the letters,
    -- so with no padding and no plate there is no air and it has nothing to fill —
    -- which reads as "the outline did not work". Two of padding is the least that
    -- shows a one-block outline all the way round.
    Cache.SignsTab:CreateSlider({ Name="Outline Thickness", Step=1, Range={1,4}, Increment=1, Suffix=" px",
        CurrentValue=Cache.SignOutline or 1, Callback=function(v)
            Cache.SignOutline = math.floor(tonumber(v) or 1); Cache.queueFarmSave()
            Cache.markSignPreviewDirty()
    end})
    Cache.SignShadowDD = Cache.SignsTab:CreateDropdown({ Name="Shadow Block", Options={"None"},
        CurrentOption={"None"}, Callback=function(v)
            local pick = type(v) == "table" and v[1] or v
            Cache.SignShadowName = (pick ~= "None") and pick or nil
            Cache.markSignPreviewDirty()
    end})
    Cache.SignsTab:CreateSlider({ Name="Shadow Offset", Step=1, Range={0,4}, Increment=1, Suffix=" px",
        CurrentValue=Cache.SignShadow or 1, Callback=function(v)
            Cache.SignShadow = math.floor(tonumber(v) or 1); Cache.queueFarmSave()
            Cache.markSignPreviewDirty()
    end})
    Cache.SignsTab:CreateSlider({ Name="Frame Thickness", Step=1, Range={0,4}, Increment=1, Suffix=" px",
        CurrentValue=Cache.SignBorder or 1, Callback=function(v)
            Cache.SignBorder = math.floor(tonumber(v) or 1); Cache.queueFarmSave()
            Cache.markSignPreviewDirty()
    end})
    -- A PLAIN BAND READS AS "THE SIGN RAN OUT", not as a border somebody chose, and
    -- that is the whole complaint about the old frame. Corners costs a quarter of the
    -- blocks and still reads from a distance, because the eye finishes the rectangle
    -- itself. Double needs three of padding — one clear cell outside its inner line
    -- and one inside — and falls back to Solid below that rather than jamming the
    -- line against the text, which is what its first version did.
    Cache.SignFrameStyleDD = Cache.SignsTab:CreateDropdown({ Name="Frame Style", Options=Cache.SIGN_FRAME_STYLES,
        CurrentOption={Cache.SignBorderStyle or "Solid"}, Callback=function(v)
            Cache.SignBorderStyle = type(v) == "table" and v[1] or v
            Cache.queueFarmSave()
            Cache.markSignPreviewDirty()
    end})
    Cache.SignsTab:CreateSlider({ Name="Padding Inside The Frame", Step=1, Range={0,6}, Increment=1, Suffix=" px",
        CurrentValue=Cache.SignPad or 1, Callback=function(v)
            Cache.SignPad = math.floor(tonumber(v) or 1); Cache.queueFarmSave()
            Cache.markSignPreviewDirty()
    end})

    local fontNames = {}
    for name in pairs(Cache.SIGN_FONTS) do fontNames[#fontNames + 1] = name end
    table.sort(fontNames)
    Cache.SignsTab:CreateDropdown({ Name="Sign Font", Options=fontNames, CurrentOption={Cache.SignFont or fontNames[1]},
        Callback=function(v)
            Cache.SignFont = type(v) == "table" and v[1] or v
            Cache.queueFarmSave()
            Cache.markSignPreviewDirty()
    end})
    -- ONE BLOCK PER PIXEL IS UNREADABLE FROM ANYWHERE USEFUL. A 5x7 glyph at scale 1
    -- is 15 by 21 studs, which reads from across a plot and not from the sky. Scale is
    -- the knob that matters most here and it costs the square of itself in blocks, so
    -- the count goes in the notification rather than being left as a surprise.
    Cache.SignsTab:CreateSlider({ Name="Block Size Per Pixel", Step=1, Range={1,6}, Increment=1, Suffix=" blocks",
        CurrentValue=Cache.SignScale or 1, Callback=function(v)
            Cache.SignScale = math.floor(tonumber(v) or 1); Cache.queueFarmSave()
            Cache.markSignPreviewDirty()
    end})
    -- THE ONE DECISION YOU CANNOT GUESS, worked out instead. Scale costs the square
    -- of itself, so the difference between a sign that fits and a build that stops
    -- halfway is one notch on the slider above -- and every number needed to settle
    -- it is already known. It moves the slider rather than only the value behind it,
    -- because a panel showing one number while the sign is built from another is the
    -- worst of both.
    Cache.SignsTab:CreateButton({ Name="Biggest That Fits The Island", Callback=function()
        local text = tostring(Cache.SignText or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if text == "" then
            Window:Notify({Title="Join Code Sign", Content="Type the code in first — there is nothing to size.", Duration=6}); return
        end
        local grid, W, H = Cache.signCanvas(text, Cache.SignFont, "x", Cache.SignLineGap,
            Cache.SignAlign, { border = Cache.SignBorder, borderType = Cache.SignFrameName and "f" or nil,
              borderStyle = Cache.SignBorderStyle, pad = Cache.SignPad,
              backingType = Cache.SignPlateName and "p" or nil,
              outlineType = Cache.SignOutlineName and "o" or nil, outline = Cache.SignOutline,
              shadow = Cache.SignShadow, shadowType = Cache.SignShadowName and "s" or nil,
              wrap = Cache.SignWrap })
        if not grid then
            Window:Notify({Title="Join Code Sign", Content="That code draws nothing to size.", Duration=6}); return
        end
        local cells = 0
        for v = 0, H - 1 do for u = 0, W - 1 do if grid[v][u] then cells += 1 end end end
        -- NIL IS NOT ZERO. An unreadable island is "cannot tell", and sizing a sign
        -- against a number we did not manage to read is how you fill someone's island.
        local free, used = Cache.islandBlocksFree()
        if not free then
            Window:Notify({Title="Join Code Sign", Content="Couldn't read how much of the island is free, so there is nothing to size against. Stand on the island and try again.", Duration=10}); return
        end
        local thick = math.max(1, math.floor(tonumber(Cache.SignThickness) or 1))
        local best, cost = Cache.biggestScaleThatFits(cells, thick, free, 6)
        if not best then
            Window:Notify({Title="Join Code Sign", Content=string.format(
                "Even one block per pixel is %d blocks and only %d are free of the island's %d (%d already standing). Shorten the code, drop the frame, or clear space.",
                cost, free, Cache.ISLAND_BLOCK_LIMIT, used), Duration=12}); return
        end
        Cache.SignScale = best
        local sf = Window.SliderFunctions or {}
        if sf["Block Size Per Pixel"] then sf["Block Size Per Pixel"](best) end
        Cache.queueFarmSave(); Cache.markSignPreviewDirty()
        Window:Notify({Title="Join Code Sign", Content=string.format(
            "%d block%s per pixel — %d blocks, leaving %d of the island's %d free.%s",
            best, (best == 1) and "" or "s", cost, free - cost, Cache.ISLAND_BLOCK_LIMIT,
            (best == 6) and " That is the largest this offers, so there is room to spare." or ""), Duration=12})
    end})
    -- Measured in glyph rows, not blocks, so the gap stays proportional when the
    -- scale changes -- a sign built at four blocks a pixel wants four times the air
    -- between its lines, not the same one block.
    Cache.SignsTab:CreateSlider({ Name="Line Spacing", Step=1, Range={0,4}, Increment=1, Suffix=" rows",
        CurrentValue=Cache.SignLineGap or 1, Callback=function(v)
            Cache.SignLineGap = math.floor(tonumber(v) or 1); Cache.queueFarmSave()
            Cache.markSignPreviewDirty()
    end})
    -- MORE LINES WITHOUT TYPING BARS. A bar is a break you meant; a four-word shop
    -- name is not four deliberate breaks, it is one line that does not fit. Zero is
    -- off, which is what a join code wants -- it is six characters and has no spaces
    -- to break at. Bars still win: this subdivides what they produced.
    Cache.SignsTab:CreateSlider({ Name="Wrap At", Step=1, Range={0,24}, Increment=1, Suffix=" characters",
        CurrentValue=Cache.SignWrap or 0, Callback=function(v)
            Cache.SignWrap = math.floor(tonumber(v) or 0); Cache.queueFarmSave()
            Cache.markSignPreviewDirty()
    end})
    Cache.SignAlignDD = Cache.SignsTab:CreateDropdown({ Name="Line Alignment", Options={"Left","Centre","Right"},
        CurrentOption={Cache.SignAlign or "Left"}, Callback=function(v)
            Cache.SignAlign = type(v) == "table" and v[1] or v
            Cache.queueFarmSave()
            Cache.markSignPreviewDirty()
    end})
    Cache.SignsTab:CreateSlider({ Name="Sign Thickness", Step=1, Range={1,4}, Increment=1, Suffix=" deep",
        CurrentValue=Cache.SignThickness or 1, Callback=function(v)
            Cache.SignThickness = math.floor(tonumber(v) or 1); Cache.queueFarmSave()
            Cache.markSignPreviewDirty()
    end})
    -- No layout can fix this: a flat sign reads correctly from one side and
    -- backwards from the other, because the two viewers' right-hand vectors point
    -- opposite ways. Normally you walk round it. This is for when you cannot.
    Cache.SignsTab:CreateToggle({ Name="Build It Mirrored", CurrentValue=false, Callback=function(v)
        Cache.SignMirror = v
        Cache.markSignPreviewDirty()
    end})
    Cache.SignsTab:CreateDropdown({ Name="Sign Layout", Options=Cache.SIGN_LAYOUTS,
        CurrentOption={Cache.SignLayout or Cache.SIGN_LAYOUTS[1]}, Callback=function(v)
            Cache.SignLayout = type(v) == "table" and v[1] or v
            Cache.queueFarmSave()
    end})

    Cache.SignsTab:CreateButton({ Name="Generate Code Sign Blueprint", Callback=function()
        task.spawn(function()
            if not (writefile and isfolder and makefolder) then
                Window:Notify({Title="Join Code Sign", Content="Filesystem not supported by this executor.", Duration=5}); return
            end
            local text = tostring(Cache.SignText or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if text == "" then
                Window:Notify({Title="Join Code Sign", Content="Type the code into 'Code To Build' first.", Duration=6}); return
            end
            local display = Cache.SignBlockName
            if not display or display == "" or display == "Press Refresh Sign Blocks" then
                Window:Notify({Title="Join Code Sign", Content="Press 'Refresh Sign Blocks' and pick the block to build it from.", Duration=6}); return
            end
            local internal = getinternalname(display)
            local blocks, cw, ch, unknown = Cache.signBlocks(text, Cache.SignFont, internal,
                Cache.SignScale, Cache.SignThickness, Cache.SignLayout,
                Cache.SignLineGap, Cache.SignAlign,
                { border = Cache.SignBorder, borderType = Cache.SignFrameName and getinternalname(Cache.SignFrameName) or nil,
                  pad = Cache.SignPad,
                  backingType = Cache.SignPlateName and getinternalname(Cache.SignPlateName) or nil,
                  outlineType = Cache.SignOutlineName and getinternalname(Cache.SignOutlineName) or nil,
                  outline = Cache.SignOutline, borderStyle = Cache.SignBorderStyle,
                  shadow = Cache.SignShadow,
                  shadowType = Cache.SignShadowName and getinternalname(Cache.SignShadowName) or nil,
                  wrap = Cache.SignWrap,
                  mirror = Cache.SignMirror })
            if not blocks then
                Window:Notify({Title="Join Code Sign", Content=string.format(
                    "That code at this size is %d cells — too large to generate. Lower 'Block Size Per Pixel'.", cw), Duration=9}); return
            end
            -- EVERY CHARACTER UNKNOWN IS NOT A SIGN, IT IS A MISTAKE. Saying "0 blocks"
            -- and stopping tells you nothing; naming what it could not draw does.
            local bad = {}
            for c in pairs(unknown) do bad[#bad + 1] = c end
            table.sort(bad)
            if #blocks == 0 then
                Window:Notify({Title="Join Code Sign", Content=(#bad > 0)
                    and ("Nothing to build: this font has no glyph for " .. table.concat(bad, " ") .. ". A join code is A-Z and 0-9.")
                    or "Nothing to build — the code is empty.", Duration=10}); return
            end
            -- WILL IT EVEN FIT? The cap is per island and counts what is already
            -- standing, so a sign that is fine on an empty island is impossible on a
            -- full one. The blueprint is still written either way -- it is a file, and
            -- you may be about to clear space or build it somewhere else -- but a
            -- build that cannot finish should say so before it is started, not after
            -- nine hundred blocks have gone down.
            local free, used = Cache.islandBlocksFree()
            local fit = ""
            if free then
                if #blocks > free then
                    fit = string.format("\n\nTHIS WILL NOT FIT: %d blocks against %d free of the island's %d (%d already standing). Clear space, drop the scale, or build it on another island.",
                        #blocks, free, Cache.ISLAND_BLOCK_LIMIT, used)
                else
                    fit = string.format("\n%d of the island's %d blocks would be free afterwards.", free - #blocks, Cache.ISLAND_BLOCK_LIMIT)
                end
            end
            local ok, encoded = pcall(function() return HttpService:JSONEncode({ blocks = blocks }) end)
            if not ok then Window:Notify({Title="Join Code Sign", Content="Failed to encode the sign.", Duration=5}); return end
            ensureBlueprintFolder()
            local folder = "Islands trading hub/Blueprints"
            local base = "Code_" .. text:upper():gsub("|", "_"):gsub("[^%w_]", "")
            local name, counter = base, 2
            while isfile(folder .. "/" .. name .. ".json") do name = base .. counter; counter += 1 end
            writefile(folder .. "/" .. name .. ".json", encoded)
            State.SelectedBlueprint = name
            if BlueprintDD then BlueprintDD:Refresh(refreshblueprints(), name) end
            Window:Notify({Title="Join Code Sign", Content=string.format(
                "'%s' — %d blocks of %s, %d by %d cells (%d by %d studs).%s\nIt is selected as your blueprint: press 'Check Materials Needed' to see what it costs, then turn on 'Auto Build Blueprint' to place it.",
                name, #blocks, display, cw, ch, cw * 3, ch * 3,
                (#bad > 0) and ("\nSkipped, no glyph: " .. table.concat(bad, " ") .. ".") or "") .. fit, Duration=20})
        end)
    end})
end
-- ==================== QR CODE SIGN (the buttons) ====================
-- The encoder is 065_qr_encode.lua. This appends to the Signs tab that
-- 214_code_sign.lua creates, so it must load after it.
-- Where the calls into 216_sign_preview.lua land in a tier that does not have it,
-- the same fallback 214 carries for the sign half.
if not Cache.markQRPreviewDirty then Cache.markQRPreviewDirty = function() end end

Cache.SignsTab:CreateSection("QR Code")
Cache.SignsTab:CreateNote("A scannable QR, built out of two blocks. It needs a LIGHT block as well as a dark one — a QR module is dark or light, never dark or empty, and a code made of blocks and gaps reads as whatever happens to lie under the gaps.")
do
    Cache.SignsTab:CreateInput({ Name="QR Contents", PlaceholderText="a join code, or a link", Callback=function(v)
        Cache.QRText = v
        Cache.markQRPreviewDirty()
    end})
    Cache.QRDarkDD = Cache.SignsTab:CreateDropdown({ Name="Dark Block", Options={"Press Refresh QR Blocks"},
        CurrentOption={"Press Refresh QR Blocks"}, Callback=function(v)
            Cache.QRDarkName = type(v) == "table" and v[1] or v
            Cache.markQRPreviewDirty()
    end})
    Cache.QRLightDD = Cache.SignsTab:CreateDropdown({ Name="Light Block", Options={"Press Refresh QR Blocks"},
        CurrentOption={"Press Refresh QR Blocks"}, Callback=function(v)
            Cache.QRLightName = type(v) == "table" and v[1] or v
            Cache.markQRPreviewDirty()
    end})
    Cache.SignsTab:CreateButton({ Name="Refresh QR Blocks", Callback=function()
        local blocks = getbackpackblocks()
        if #blocks == 0 then
            Window:Notify({Title="QR Code", Content=Cache.emptyPickerReason(), Duration=12}); return
        end
        -- PICK THE PAIR IF THE GAME HAS ONE. Islands has a black block and a white
        -- one, which is the pair a camera wants, so the first refresh finds them by
        -- name rather than leaving both dropdowns on whatever sorted first -- two
        -- greys that look chosen and scan as nothing.
        local function firstMatching(word)
            for _, b in ipairs(blocks) do
                if tostring(b):lower():find(word, 1, true) then return b end
            end
            return nil
        end
        Cache.QRDarkName  = Cache.QRDarkName  or firstMatching("black") or blocks[1]
        -- ...and the light one must not end up being the dark one again
        local light = Cache.QRLightName or firstMatching("white")
        if not light or light == Cache.QRDarkName then
            for _, b in ipairs(blocks) do
                if b ~= Cache.QRDarkName then light = b; break end
            end
        end
        -- THIS WAS THE BUG: QRLightName was never assigned, only displayed. The
        -- dropdown showed a block that Cache did not hold, so Generate read nil and
        -- told you to pick a light block while one sat there already selected.
        Cache.QRLightName = light
        if Cache.QRFrameDD then
            local withNone = { "None" }
            for _, b in ipairs(blocks) do withNone[#withNone + 1] = b end
            Cache.QRFrameDD:Refresh(withNone, Cache.QRFrameName or "None")
        end
        if Cache.QRDarkDD  then Cache.QRDarkDD:Refresh(blocks, Cache.QRDarkName) end
        if Cache.QRLightDD then Cache.QRLightDD:Refresh(blocks, Cache.QRLightName) end
        Cache.markQRPreviewDirty()
        Window:Notify({Title="QR Code", Content=string.format(
            "Dark: %s. Light: %s. Change either if that is not the contrasting pair you meant — a QR is read by contrast and nothing else.",
            tostring(Cache.QRDarkName), tostring(Cache.QRLightName)), Duration=10})
    end})
    -- HIGHER CORRECTION IS NOT FREE: it buys back damaged modules with room the
    -- payload wanted, so the same text needs a bigger symbol and more blocks. L is
    -- the right default for something standing on your own island where nothing is
    -- going to scuff it.
    Cache.SignsTab:CreateDropdown({ Name="Error Correction", Options=Cache.QR_LEVELS,
        CurrentOption={Cache.QRLevel or "L"}, Callback=function(v)
            Cache.QRLevel = type(v) == "table" and v[1] or v
            Cache.queueFarmSave()
            Cache.markQRPreviewDirty()
    end})
    Cache.SignsTab:CreateSlider({ Name="Blocks Per Module", Step=1, Range={1,4}, Increment=1, Suffix=" blocks",
        CurrentValue=Cache.QRScale or 1, Callback=function(v)
            Cache.QRScale = math.floor(tonumber(v) or 1); Cache.queueFarmSave()
            Cache.markQRPreviewDirty()
    end})
    -- The same sizing the sign has, against the same island. A QR has no empty
    -- cells -- every module and every quiet cell is a block -- so its count is the
    -- whole canvas rather than what is filled.
    Cache.SignsTab:CreateButton({ Name="Biggest QR That Fits", Callback=function()
        local text = tostring(Cache.QRText or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if text == "" then
            Window:Notify({Title="QR Code", Content="Type the contents in first — there is nothing to size.", Duration=6}); return
        end
        local level = Cache.qrFreeLevel(text, Cache.QRLevel or "L")
        local modules, sizeOrWhy = Cache.qrEncode(text, level)
        if not modules then
            Window:Notify({Title="QR Code", Content=tostring(sizeOrWhy), Duration=10}); return
        end
        local grid, W, H = Cache.qrCanvas(modules, sizeOrWhy, "d", "l", 1, Cache.QRQuiet,
            { border = Cache.QRBorder, borderType = Cache.QRFrameName and "f" or nil,
              pad = Cache.QRPad, caption = Cache.QRCaption, captionFont = Cache.QRCaptionFont,
              captionType = "d", captionScale = 1, captionGap = 1 })
        if not grid then
            Window:Notify({Title="QR Code", Content="That code is too large to lay out.", Duration=8}); return
        end
        local cells = 0
        for v = 0, H - 1 do for u = 0, W - 1 do if grid[v][u] then cells += 1 end end end
        local free, used = Cache.islandBlocksFree()
        if not free then
            Window:Notify({Title="QR Code", Content="Couldn't read how much of the island is free, so there is nothing to size against. Stand on the island and try again.", Duration=10}); return
        end
        local thick = math.max(1, math.floor(tonumber(Cache.QRThickness) or 1))
        local best, cost = Cache.biggestScaleThatFits(cells, thick, free, 4)
        if not best then
            Window:Notify({Title="QR Code", Content=string.format(
                "Even one block per module is %d blocks and only %d are free of the island's %d (%d already standing). Shorten the contents or clear space.",
                cost, free, Cache.ISLAND_BLOCK_LIMIT, used), Duration=12}); return
        end
        Cache.QRScale = best
        local sf = Window.SliderFunctions or {}
        if sf["Blocks Per Module"] then sf["Blocks Per Module"](best) end
        Cache.queueFarmSave(); Cache.markQRPreviewDirty()
        Window:Notify({Title="QR Code", Content=string.format(
            "%d block%s per module — %d blocks, %d modules a side, leaving %d of the island's %d free.",
            best, (best == 1) and "" or "s", cost, sizeOrWhy, free - cost, Cache.ISLAND_BLOCK_LIMIT), Duration=12})
    end})
    -- A FRAME, AND THE LINE IT MUST NOT CROSS. It is drawn OUTSIDE the quiet zone,
    -- never into it: those four light modules are what give a reader an edge, and a
    -- border one module in would look tidy and stop the code resolving. Extra padding
    -- is more light, which only ever helps.
    --
    -- There is no outline and no shadow on this one and there will not be. Both put
    -- blocks between and around modules, which is exactly what a QR cannot survive.
    Cache.QRFrameDD = Cache.SignsTab:CreateDropdown({ Name="QR Frame Block", Options={"None"},
        CurrentOption={"None"}, Callback=function(v)
            local pick = type(v) == "table" and v[1] or v
            Cache.QRFrameName = (pick ~= "None") and pick or nil
            Cache.markQRPreviewDirty()
    end})
    Cache.SignsTab:CreateSlider({ Name="QR Frame Thickness", Step=1, Range={0,4}, Increment=1, Suffix=" modules",
        CurrentValue=Cache.QRBorder or 1, Callback=function(v)
            Cache.QRBorder = math.floor(tonumber(v) or 1); Cache.queueFarmSave()
            Cache.markQRPreviewDirty()
    end})
    Cache.SignsTab:CreateSlider({ Name="Extra Light Margin", Step=1, Range={0,6}, Increment=1, Suffix=" modules",
        CurrentValue=Cache.QRPad or 0, Callback=function(v)
            Cache.QRPad = math.floor(tonumber(v) or 0); Cache.queueFarmSave()
            Cache.markQRPreviewDirty()
    end})
    Cache.SignsTab:CreateSlider({ Name="QR Thickness", Step=1, Range={1,3}, Increment=1, Suffix=" deep",
        CurrentValue=Cache.QRThickness or 1, Callback=function(v)
            Cache.QRThickness = math.floor(tonumber(v) or 1); Cache.queueFarmSave()
            Cache.markQRPreviewDirty()
    end})
    Cache.SignsTab:CreateDropdown({ Name="QR Layout", Options=Cache.SIGN_LAYOUTS,
        CurrentOption={Cache.QRLayout or "Flat On The Ground"}, Callback=function(v)
            Cache.QRLayout = type(v) == "table" and v[1] or v
            Cache.queueFarmSave()
    end})
    -- The quiet zone is not decoration: without a light margin a reader has no edge
    -- to lock onto and the symbol does not resolve at all. Four modules is the spec.
    Cache.SignsTab:CreateToggle({ Name="Quiet Zone (leave this on)", CurrentValue=true, Callback=function(v)
        Cache.QRQuiet = v and 4 or 0
        Cache.markQRPreviewDirty()
    end})
    -- THIS MATTERS MORE HERE THAN ON A SIGN. One face of anything flat is mirrored,
    -- and a mirrored word is merely awkward -- you walk round it. A mirrored QR is
    -- unreadable: no scanner will take one. If the side you can stand in front of is
    -- the wrong side, this is the only way to get a code that scans.
    Cache.SignsTab:CreateToggle({ Name="Build The QR Mirrored", CurrentValue=false, Callback=function(v)
        Cache.QRMirror = v
        Cache.markQRPreviewDirty()
    end})
    Cache.SignsTab:CreateInput({ Name="Caption Under It (optional)", PlaceholderText="e.g. SCAN TO JOIN",
        Callback=function(v) Cache.QRCaption = v; Cache.markQRPreviewDirty() end})
    -- The caption is drawn by the sign generator, so it gets the same four fonts and
    -- the same A-Z, 0-9 and punctuation. It is built in the DARK block: a caption in
    -- the light one would be invisible against its own quiet zone.
    Cache.SignsTab:CreateDropdown({ Name="Caption Font", Options=(function()
            local n = {} for k in pairs(Cache.SIGN_FONTS) do n[#n+1] = k end table.sort(n) return n
        end)(), CurrentOption={Cache.QRCaptionFont or "5x7"}, Callback=function(v)
            Cache.QRCaptionFont = type(v) == "table" and v[1] or v
            Cache.queueFarmSave()
            Cache.markQRPreviewDirty()
    end})

    -- WHEN IT DOES NOT SCAN AND NOBODY CAN SAY WHY. Everything that stops a built
    -- code from reading is measurable from here, and none of it is visible in a list
    -- of settings: the contrast between two blocks, which way round they are, whether
    -- the quiet zone is on, whether it is being built mirrored, how many studs a
    -- module ends up being, and whether the blueprint that is selected is even this
    -- code. So this reports what the script can see rather than what it concluded --
    -- the same job the block picker's diagnostic does, which is the one that turned
    -- out to answer a real problem rather than explain a feature.
    --
    -- It ships in every tier for that reason: it explains why something a buyer HAS
    -- is not working, which is a support answer and not a developer tool.
    Cache.SignsTab:CreateButton({ Name="Why Won't My QR Scan?", Callback=function()
        task.spawn(function()
            local lines = {}
            local function say(fmt, ...) lines[#lines + 1] = select("#", ...) > 0 and string.format(fmt, ...) or fmt end

            local text = tostring(Cache.QRText or ""):gsub("^%s+", ""):gsub("%s+$", "")
            say("Contents: %s", (text ~= "") and ("'" .. text .. "' (" .. #text .. " characters)") or "EMPTY — nothing to encode")
            local dark, light = Cache.QRDarkName, Cache.QRLightName
            if dark == "Press Refresh QR Blocks" then dark = nil end
            if light == "Press Refresh QR Blocks" then light = nil end
            say("Dark block:  %s", dark or "NOT PICKED")
            say("Light block: %s", light or "NOT PICKED")
            if dark and light and dark == light then
                say("  BOTH ARE THE SAME BLOCK. A reader works on the difference between them; there is none.")
            end

            -- the measurement that predicts it better than anything else
            local dc, lc = Cache.blockColour(dark), Cache.blockColour(light)
            if not (dc and lc) then
                say("Contrast: cannot tell — one of the two has no template loaded yet. That is not the same as 'fine'.")
            else
                local ratio, rightWayRound = Cache.qrContrast(dc, lc)
                say("Contrast: %.1f to 1 (%s)", ratio,
                    (not rightWayRound) and "THE WRONG WAY ROUND — the dark one is the lighter of the two"
                    or (ratio < 3) and "TOO LITTLE, this will probably not scan"
                    or (ratio < 4.5) and "thin; fine in good light, marginal in shade"
                    or "good")
            end

            say("Quiet zone: %s", (Cache.QRQuiet == 0)
                and "OFF — the four light modules round the code are the edge a reader locks onto. Turn it on."
                or "on (4 modules)")
            say("Built mirrored: %s", Cache.QRMirror
                and "YES — correct only if the face you can stand in front of is the back one. A mirrored code no reader will take."
                or "no")
            local layout = Cache.QRLayout or "Flat On The Ground"
            say("Layout: %s%s", layout, (layout == "Flat On The Ground")
                and "  — you read this from a slant unless the camera is directly above it. Upright is easier to scan."
                or "  — stand square in front of it")

            if text ~= "" then
                local want = Cache.QRLevel or "L"
                local level = Cache.qrFreeLevel(text, want)
                local modules, sizeOrWhy, version = Cache.qrEncode(text, level)
                if not modules then
                    say("Encoder: REFUSED — %s", tostring(sizeOrWhy))
                else
                    local scale = math.max(1, math.floor(tonumber(Cache.QRScale) or 1))
                    say("Symbol: version %d, %d modules a side, correction %s%s",
                        version, sizeOrWhy, level, (level ~= want) and (" (taken free, you asked for " .. want .. ")") or "")
                    say("On the ground: %d blocks a module = %d studs a module, %d studs a side",
                        scale, scale * 3, (sizeOrWhy + (Cache.QRQuiet or 4) * 2) * scale * 3)
                end
            end

            local sel = tostring(State.SelectedBlueprint or "None")
            say("Selected blueprint: %s%s", sel,
                sel:find("^QR_") and "" or "  — that is not a generated QR. Press 'Generate QR Blueprint' and it selects itself.")
            local free, used = Cache.islandBlocksFree()
            say("Island: %s", free and string.format("%d of %d free (%d standing)", free, Cache.ISLAND_BLOCK_LIMIT, used)
                or "could not read how full it is")
            say("")
            say("If the preview scans and the built code does not, it is not the code: it is")
            say("the angle you are looking from, a shadow lying across it, or the face you")
            say("are standing in front of being the mirrored one.")

            local body = table.concat(lines, "\n")
            local wrote = false
            if writefile and isfolder and makefolder then
                wrote = pcall(function()
                    if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
                    writefile("Islands trading hub/qr_report.txt", body)
                end)
            end
            Window:Notify({Title="QR Code", Content=body
                .. (wrote and "\n\nWritten to Islands trading hub/qr_report.txt" or ""), Duration=30})
            print("[Islands Hub] QR report:\n" .. body)
        end)
    end})

    Cache.SignsTab:CreateButton({ Name="Generate QR Blueprint", Callback=function()
        task.spawn(function()
            if not (writefile and isfolder and makefolder) then
                Window:Notify({Title="QR Code", Content="Filesystem not supported by this executor.", Duration=5}); return
            end
            local text = tostring(Cache.QRText or ""):gsub("^%s+", ""):gsub("%s+$", "")
            if text == "" then
                Window:Notify({Title="QR Code", Content="Type what it should contain into 'QR Contents' first.", Duration=6}); return
            end
            local dark = Cache.QRDarkName
            if not dark or dark == "" or dark == "Press Refresh QR Blocks" then
                Window:Notify({Title="QR Code", Content="Press 'Refresh QR Blocks' and pick a dark block.", Duration=6}); return
            end
            local light = Cache.QRLightName
            if not light or light == "" or light == "Press Refresh QR Blocks" or light == dark then
                Window:Notify({Title="QR Code", Content="Pick a LIGHT block that is not the dark one. A QR with one block type is not a QR — the light modules have to be built too, or a camera reads the ground through them.", Duration=12}); return
            end
            -- WHAT THE TWO BLOCKS ACTUALLY LOOK LIKE. The template the preview clones
            -- to draw a ghost is a real part with a real colour, so the pair can be
            -- measured rather than hoped about -- and a pair that does not contrast is
            -- the likeliest reason a built code refuses to scan. A missing template is
            -- reported as nothing, never as a pass: "cannot tell" is not "fine".
            -- Cache.blockColour is that lookup, shared with the sign preview, which
            -- paints its cells in the same measured colours.
            local ratio, rightWayRound = Cache.qrContrast(Cache.blockColour(dark), Cache.blockColour(light))
            local contrastNote = ""
            if ratio then
                if not rightWayRound then
                    contrastNote = string.format("\n\nTHESE ARE THE WRONG WAY ROUND: '%s' is the lighter of the two. The code will be inverted; some readers take that and some refuse it. Swap them.", tostring(dark))
                elseif ratio < 3 then
                    contrastNote = string.format("\n\nTHIS PAIR WILL PROBABLY NOT SCAN: %s and %s are only %.1f:1 apart in brightness. A reader works on that difference, and under about 3:1 there is not enough of one. Pick a darker dark or a lighter light.", tostring(dark), tostring(light), ratio)
                elseif ratio < 4.5 then
                    contrastNote = string.format("\n\nContrast is %.1f:1, which is thin. It may scan in good light and fail in shade; 4.5:1 or better is comfortable.", ratio)
                else
                    contrastNote = string.format("\nContrast %.1f:1 — good.", ratio)
                end
            end
            -- TAKE THE CORRECTION THAT COSTS NOTHING. A short payload that needs
            -- version 1 at L usually still fits version 1 at H: same modules, same
            -- blocks, a code that survives a chipped block. Applied rather than
            -- offered, and said out loud below.
            local level, _, upgraded = Cache.qrFreeLevel(text, Cache.QRLevel or "L")
            local modules, sizeOrWhy, version, mask = Cache.qrEncode(text, level)
            if not modules then
                Window:Notify({Title="QR Code", Content=tostring(sizeOrWhy), Duration=10}); return
            end
            local blocks, span = Cache.qrBlocks(modules, sizeOrWhy, getinternalname(dark), getinternalname(light),
                Cache.QRScale, Cache.QRThickness, Cache.QRLayout, Cache.QRQuiet,
                { mirror = Cache.QRMirror, caption = Cache.QRCaption,
                  captionFont = Cache.QRCaptionFont, captionType = getinternalname(dark),
                  captionScale = Cache.QRScale, captionGap = math.max(1, Cache.QRScale or 1),
                  border = Cache.QRBorder, pad = Cache.QRPad,
                  borderType = Cache.QRFrameName and getinternalname(Cache.QRFrameName) or nil })
            if not blocks then
                Window:Notify({Title="QR Code", Content=string.format(
                    "That is %d cells — too large to generate. Lower 'Blocks Per Module'.", span), Duration=9}); return
            end
            -- WILL IT EVEN FIT? The cap is per island and counts what is already
            -- standing, so a sign that is fine on an empty island is impossible on a
            -- full one. The blueprint is still written either way -- it is a file, and
            -- you may be about to clear space or build it somewhere else -- but a
            -- build that cannot finish should say so before it is started, not after
            -- nine hundred blocks have gone down.
            local free, used = Cache.islandBlocksFree()
            local fit = ""
            if free then
                if #blocks > free then
                    fit = string.format("\n\nTHIS WILL NOT FIT: %d blocks against %d free of the island's %d (%d already standing). Clear space, drop the scale, or build it on another island.",
                        #blocks, free, Cache.ISLAND_BLOCK_LIMIT, used)
                else
                    fit = string.format("\n%d of the island's %d blocks would be free afterwards.", free - #blocks, Cache.ISLAND_BLOCK_LIMIT)
                end
            end
            local ok, encoded = pcall(function() return HttpService:JSONEncode({ blocks = blocks }) end)
            if not ok then Window:Notify({Title="QR Code", Content="Failed to encode the QR.", Duration=5}); return end
            ensureBlueprintFolder()
            local folder = "Islands trading hub/Blueprints"
            local base = "QR_" .. text:upper():gsub("[^%w]", ""):sub(1, 16)
            local name, counter = base, 2
            while isfile(folder .. "/" .. name .. ".json") do name = base .. counter; counter += 1 end
            writefile(folder .. "/" .. name .. ".json", encoded)
            State.SelectedBlueprint = name
            if BlueprintDD then BlueprintDD:Refresh(refreshblueprints(), name) end
            Window:Notify({Title="QR Code", Content=string.format(
                "'%s' — version %d, mask %d, %d blocks across %d by %d cells (%d studs a side).\nIt is selected as your blueprint: press 'Check Materials Needed' for the cost, then 'Auto Build Blueprint' to place it.%s",
                name, version, mask, #blocks, span, span, span * 3,
                (Cache.QRLayout == "Flat On The Ground") and "\nLying flat: read it from above." or "")
                .. (upgraded and string.format(
                    "\nBuilt at correction %s rather than %s: it fits the same %d modules, so the extra damage tolerance cost nothing.",
                    level, tostring(Cache.QRLevel or "L"), sizeOrWhy) or "")
                .. contrastNote .. fit, Duration=22})
        end)
    end})
end
-- ==================== SIGN AND QR PREVIEW ====================
-- Twenty controls decide what a sign looks like, and until now the only way to see
-- the answer was to generate a blueprint, select it, turn the world preview on and
-- walk round it. Change the font and you do all of that again. So the four things
-- that actually change the shape -- the text, the font, the frame and the spacing --
-- were being chosen blind, and the fastest way to pick a font was to build five.
--
-- This draws the sign on screen, at one small square per block, the instant any of
-- those controls moves.
--
-- IT IS THE BUILDER'S OWN CANVAS, NOT A DRAWING OF ONE. Cache.signCanvas lays the
-- sign out and Cache.signBlocks turns that same grid into blocks -- see the split in
-- 064_code_sign.lua. A preview with its own idea of where an A goes is a preview that
-- drifts the first time one of the two is changed, and then it is worse than nothing,
-- because it is confidently wrong about the only thing it is for.
--
-- THE COLOURS ARE THE BLOCKS' OWN, read off the templates in ReplicatedStorage.Blocks
-- through Cache.blockColour -- the same measurement the QR's contrast check uses. A
-- block whose template has not replicated draws as a flat grey and the panel says the
-- colour is a guess, because a sign previewed in the wrong colours is exactly the
-- mistake this is supposed to prevent.
--
-- A part of its own, and after 215 so both sign tabs exist: it appends to the Signs
-- tab rather than making one, so it can be cut without leaving a dead sidebar entry.
do
    -- The box the sign is fitted into. A cell is a whole number of pixels -- half a
    -- pixel of rounding per cell is a column that quietly disappears, and a missing
    -- column in a preview of a 5-pixel-wide letter is the letter.
    local BOX_W, BOX_H = 460, 300
    local MAX_CELLS = 6000        -- past this the frames cost more than the answer

    -- The squares are pooled. A repaint of a 40x18 sign is 720 frames, the repaints
    -- come one per control movement, and Instance.new in that loop turned a slider
    -- drag into a stutter. Built once, hidden when not needed, recoloured in place.
    local pool, qrPool = {}, {}

    local function cellAt(p, parent, i)
        local f = p[i]
        if not f then
            f = Instance.new("Frame")
            f.BorderSizePixel = 0
            f.BackgroundTransparency = 0
            f.Parent = parent
            p[i] = f
        end
        return f
    end

    local function createsignpreviewui()
        if Cache.SignPreviewUI then pcall(function() Cache.SignPreviewUI:Destroy() end) end
        pool = {}
        local ui, frame = buildFrameBase("IVM_SignPreview",
            UDim2.new(0, BOX_W + 24, 0, BOX_H + 96), UDim2.new(0.5, -(BOX_W + 24)/2, 0.5, -(BOX_H + 96)/2))
        frame.Visible = State.ShowSignPreview

        local titleBar = addTitleBar(frame, "Sign Preview", Color3.fromRGB(30, 30, 38), "Show Sign Preview")
        makedraggable(frame, titleBar)

        -- The canvas sits on a mid grey rather than the panel's near-black: a sign
        -- built out of dark blocks on a black background is invisible, and "I cannot
        -- see it" would read as "it did not draw".
        local canvas = Instance.new("Frame"); canvas.Name = "Canvas"
        canvas.Size = UDim2.new(0, BOX_W, 0, BOX_H); canvas.Position = UDim2.new(0, 12, 0, 42)
        canvas.BackgroundColor3 = Color3.fromRGB(70, 72, 80); canvas.BorderSizePixel = 0
        canvas.ClipsDescendants = true; canvas.Parent = frame
        Instance.new("UICorner", canvas).CornerRadius = UDim.new(0, 6)

        local note = Instance.new("TextLabel"); note.Name = "Note"
        note.Size = UDim2.new(1, -24, 0, 40); note.Position = UDim2.new(0, 12, 0, BOX_H + 48)
        note.BackgroundTransparency = 1; note.Text = ""
        note.TextColor3 = Color3.fromRGB(170, 180, 205); note.Font = Enum.Font.GothamBold
        note.TextSize = 12; note.TextXAlignment = Enum.TextXAlignment.Left
        note.TextYAlignment = Enum.TextYAlignment.Top; note.TextWrapped = true
        note.TextStrokeTransparency = 1; note.Parent = frame

        Cache.SignPreviewUI = ui
        Cache.SignPreviewFrame = frame
        Cache.SignPreviewCanvas = canvas
        Cache.SignPreviewNote = note
        return ui
    end
    Cache.createSignPreviewUI = createsignpreviewui

    -- A GUESSED COLOUR IS STILL A COLOUR, but it must not look like a measured one.
    local FALLBACK = Color3.fromRGB(150, 150, 155)

    -- Repaints from whatever the Signs tab currently holds. Cheap enough to call on
    -- every control movement, but it is called from the heartbeat behind a dirty flag
    -- anyway: a slider drag fires its callback every frame, and forty repaints a
    -- second of a sign nobody has finished choosing is forty repaints wasted.
    function Cache.repaintSignPreview()
        local canvas = Cache.SignPreviewCanvas
        if not (canvas and canvas.Parent) then return end
        local note = Cache.SignPreviewNote

        local text = tostring(Cache.SignText or ""):gsub("^%s+", ""):gsub("%s+$", "")
        local display = Cache.SignBlockName
        if display == "Press Refresh Sign Blocks" then display = nil end
        if text == "" or not display then
            for _, f in ipairs(pool) do f.Visible = false end
            if note then
                note.Text = (text == "")
                    and "Type something into the code box and it appears here."
                    or "Press Refresh Sign Blocks and pick the block to draw it in."
            end
            return
        end

        -- The names go in as themselves rather than as internal names: nothing here
        -- places a block, and the grid's values are only ever looked up in the colour
        -- table below. Using the display name keeps Cache.blockColour's own memo keyed
        -- the way the pickers hold it.
        local opts = {
            border      = Cache.SignBorder,
            borderType  = Cache.SignFrameName,
            pad         = Cache.SignPad,
            backingType = Cache.SignPlateName,
            outlineType = Cache.SignOutlineName,
            outline     = Cache.SignOutline,
            borderStyle = Cache.SignBorderStyle,
            shadow      = Cache.SignShadow,
            shadowType  = Cache.SignShadowName,
            wrap        = Cache.SignWrap,
        }
        local ok, grid, W, H, unknown = pcall(Cache.signCanvas, text, Cache.SignFont,
            display, Cache.SignLineGap, Cache.SignAlign, opts)
        if not ok or not grid then
            for _, f in ipairs(pool) do f.Visible = false end
            if note then note.Text = ok and "Nothing to draw." or "Could not lay this sign out." end
            return
        end

        if W * H > MAX_CELLS then
            for _, f in ipairs(pool) do f.Visible = false end
            if note then
                note.Text = string.format("%d by %d pixels is too much to draw here."
                    .. " The blueprint will still build; shorten the text or drop the"
                    .. " frame and padding to see it.", W, H)
            end
            return
        end

        -- whole pixels per cell, and at least one, so a wide sign shrinks rather than
        -- losing every other column to rounding
        local cell = math.max(1, math.min(math.floor(BOX_W / W), math.floor(BOX_H / H)))
        local drawnW, drawnH = W * cell, H * cell
        local offX = math.floor((BOX_W - drawnW) / 2)
        local offY = math.floor((BOX_H - drawnH) / 2)

        -- one colour lookup per distinct block type, not one per cell
        local colours, guessed = {}, {}
        local function colourFor(bt)
            local c = colours[bt]
            if c == nil then
                c = Cache.blockColour and Cache.blockColour(bt) or nil
                if not c then guessed[bt] = true; c = FALLBACK end
                colours[bt] = c
            end
            return c
        end

        local mirror = Cache.SignMirror and true or false
        local i = 0
        for py = 0, H - 1 do
            for px = 0, W - 1 do
                local bt = grid[py][mirror and (W - 1 - px) or px]
                if bt then
                    i += 1
                    local f = cellAt(pool, canvas, i)
                    f.Size = UDim2.new(0, cell, 0, cell)
                    -- row 0 is the BOTTOM row of the sign and the TOP of a Roblox
                    -- frame is y=0, so the rows are laid out upside down on purpose
                    f.Position = UDim2.new(0, offX + px * cell, 0, offY + (H - 1 - py) * cell)
                    f.BackgroundColor3 = colourFor(bt)
                    f.Visible = true
                end
            end
        end
        for k = i + 1, #pool do pool[k].Visible = false end

        if note then
            local bad = {}
            for c in pairs(unknown or {}) do bad[#bad + 1] = c end
            table.sort(bad)
            local scale = math.max(1, math.floor(tonumber(Cache.SignScale) or 1))
            local thick = math.max(1, math.floor(tonumber(Cache.SignThickness) or 1))
            local msg = string.format("%d by %d pixels — %d blocks at %d per pixel, %d deep.",
                W, H, i * scale * scale * thick, scale, thick)
            local guessedList = {}
            for bt in pairs(guessed) do guessedList[#guessedList + 1] = bt end
            table.sort(guessedList)
            if #guessedList > 0 then
                msg = msg .. "\nShown grey, real colour unknown: " .. table.concat(guessedList, ", ") .. "."
            end
            if #bad > 0 then
                msg = msg .. "\nThis font has no glyph for " .. table.concat(bad, " ") .. "."
            end
            note.Text = msg
        end
    end

    -- Everything that changes the picture sets this; the heartbeat in the render loop
    -- clears it. One repaint per settled change rather than one per callback.
    function Cache.markSignPreviewDirty()
        Cache.SignPreviewDirty = true
    end

    -- ---- the QR, on screen, where you can point a phone at it -------------------
    -- THE QUESTION THIS ANSWERS IS "WILL IT SCAN", AND IT ANSWERS IT BEFORE THE BUILD.
    -- Everything that stops a block-built QR from scanning -- too little contrast
    -- between the two blocks, the code built mirrored, a frame drawn into the quiet
    -- zone -- is invisible in a list of settings and obvious in a picture. And the
    -- picture here is not a mockup: Cache.qrCanvas lays the code out and Cache.qrBlocks
    -- builds from that same grid, so a reader that gets the text off this panel will
    -- get it off the blocks.
    --
    -- So scan THIS, with your phone, before you spend nine hundred blocks. If it reads
    -- here and not on the island, the code is right and something about the build is in
    -- the way -- the angle you are looking from, a shadow across it, or the face you
    -- are standing in front of being the mirrored one.
    --
    -- Drawn at one pixel-block per module regardless of Blocks Per Module: that slider
    -- multiplies every module equally, so it changes how big the code is on the ground
    -- and nothing whatever about the picture.
    local QR_BOX = 380

    local function createqrpreviewui()
        if Cache.QRPreviewUI then pcall(function() Cache.QRPreviewUI:Destroy() end) end
        qrPool = {}
        local ui, frame = buildFrameBase("IVM_QRPreview",
            UDim2.new(0, QR_BOX + 24, 0, QR_BOX + 96), UDim2.new(0.5, -(QR_BOX + 24)/2, 0.5, -(QR_BOX + 96)/2))
        frame.Visible = State.ShowQRPreview

        local titleBar = addTitleBar(frame, "QR Preview", Color3.fromRGB(30, 30, 38), "Show QR Preview")
        makedraggable(frame, titleBar)

        -- NO MARGIN AND NO ROUNDED CORNER ON THIS ONE. The canvas is sized to exactly
        -- the drawn code, so nothing of the panel shows through around it: the light
        -- modules ARE the quiet zone, and a dark panel bleeding into their edge is the
        -- one thing that would stop a reader finding it.
        local holder = Instance.new("Frame"); holder.Name = "Holder"
        holder.Size = UDim2.new(0, QR_BOX, 0, QR_BOX); holder.Position = UDim2.new(0, 12, 0, 42)
        holder.BackgroundColor3 = Color3.fromRGB(255, 255, 255); holder.BorderSizePixel = 0
        holder.Parent = frame
        local canvas = Instance.new("Frame"); canvas.Name = "Canvas"
        canvas.AnchorPoint = Vector2.new(0.5, 0.5); canvas.Position = UDim2.fromScale(0.5, 0.5)
        canvas.Size = UDim2.new(0, QR_BOX, 0, QR_BOX)
        canvas.BackgroundTransparency = 1; canvas.BorderSizePixel = 0
        canvas.Parent = holder

        local note = Instance.new("TextLabel"); note.Name = "Note"
        note.Size = UDim2.new(1, -24, 0, 44); note.Position = UDim2.new(0, 12, 0, QR_BOX + 48)
        note.BackgroundTransparency = 1; note.Text = ""
        note.TextColor3 = Color3.fromRGB(170, 180, 205); note.Font = Enum.Font.GothamBold
        note.TextSize = 12; note.TextXAlignment = Enum.TextXAlignment.Left
        note.TextYAlignment = Enum.TextYAlignment.Top; note.TextWrapped = true
        note.TextStrokeTransparency = 1; note.Parent = frame

        Cache.QRPreviewUI = ui
        Cache.QRPreviewFrame = frame
        Cache.QRPreviewCanvas = canvas
        Cache.QRPreviewNote = note
        return ui
    end
    Cache.createQRPreviewUI = createqrpreviewui

    function Cache.repaintQRPreview()
        local canvas = Cache.QRPreviewCanvas
        if not (canvas and canvas.Parent) then return end
        local note = Cache.QRPreviewNote
        local function blank(msg)
            for _, f in ipairs(qrPool) do f.Visible = false end
            if note then note.Text = msg end
        end

        local text = tostring(Cache.QRText or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if text == "" then return blank("Type what the code should contain and it appears here.") end
        local dark, light = Cache.QRDarkName, Cache.QRLightName
        if dark == "Press Refresh QR Blocks" then dark = nil end
        if light == "Press Refresh QR Blocks" then light = nil end
        if not (dark and light) then
            return blank("Press Refresh QR Blocks — a code needs a dark block and a light one.")
        end

        -- the same free upgrade the builder takes, so the panel shows the code that
        -- will actually be built rather than the one that was asked for
        local want = Cache.QRLevel or "L"
        local okL, level, _, upgraded = pcall(Cache.qrFreeLevel, text, want)
        if not okL then level, upgraded = want, false end
        local okE, modules, sizeOrWhy = pcall(Cache.qrEncode, text, level)
        if not okE or not modules then
            return blank(okE and tostring(sizeOrWhy) or "Could not encode that.")
        end
        local size = sizeOrWhy
        local okC, grid, W, H = pcall(Cache.qrCanvas, modules, size, dark, light, 1,
            Cache.QRQuiet, { border = Cache.QRBorder, borderType = Cache.QRFrameName,
                             pad = Cache.QRPad, caption = Cache.QRCaption,
                             captionFont = Cache.QRCaptionFont, captionType = dark,
                             captionScale = 1, captionGap = 1 })
        if not okC or not grid then return blank("Could not lay that code out.") end
        if W * H > MAX_CELLS then
            return blank(string.format("%d by %d modules is too much to draw here. Lower the"
                .. " error correction or shorten the contents.", W, H))
        end

        local cell = math.max(1, math.floor(QR_BOX / math.max(W, H)))
        local drawnW, drawnH = W * cell, H * cell
        canvas.Size = UDim2.new(0, drawnW, 0, drawnH)

        local colours, guessed = {}, {}
        local function colourFor(bt)
            local c = colours[bt]
            if c == nil then
                c = Cache.blockColour and Cache.blockColour(bt) or nil
                if not c then guessed[bt] = true; c = FALLBACK end
                colours[bt] = c
            end
            return c
        end

        local mirror = Cache.QRMirror and true or false
        local i = 0
        for v = 0, H - 1 do
            for u = 0, W - 1 do
                local bt = grid[v][mirror and (W - 1 - u) or u]
                if bt then
                    i += 1
                    local f = cellAt(qrPool, canvas, i)
                    f.Size = UDim2.new(0, cell, 0, cell)
                    f.Position = UDim2.new(0, u * cell, 0, (H - 1 - v) * cell)
                    f.BackgroundColor3 = colourFor(bt)
                    f.Visible = true
                end
            end
        end
        for k = i + 1, #qrPool do qrPool[k].Visible = false end

        if note then
            local scale = math.max(1, math.floor(tonumber(Cache.QRScale) or 1))
            local thick = math.max(1, math.floor(tonumber(Cache.QRThickness) or 1))
            local msg = string.format("%d modules, %s correction — %d blocks at %d per module, %d deep.",
                size, tostring(level), i * scale * scale * thick, scale, thick)
            if upgraded then
                msg = msg .. string.format("\n%s fits the same %d modules as %s, so it is taken for free.",
                    tostring(level), size, tostring(want))
            end
            -- The contrast number is the single best predictor of whether a built code
            -- reads, and it is measured off the real templates, not guessed from names.
            local ratio, rightWayRound = Cache.qrContrast(Cache.blockColour(dark), Cache.blockColour(light))
            if ratio then
                if not rightWayRound then
                    msg = msg .. string.format("\nWRONG WAY ROUND: %s is the lighter of the two. Swap them.", tostring(dark))
                elseif ratio < 3 then
                    msg = msg .. string.format("\nContrast %.1f:1 — too little. This will probably not scan.", ratio)
                elseif ratio < 4.5 then
                    msg = msg .. string.format("\nContrast %.1f:1 — thin. Fine in good light, marginal in shade.", ratio)
                else
                    msg = msg .. string.format("\nContrast %.1f:1 — good.", ratio)
                end
            end
            if next(guessed) then
                msg = msg .. "\nOne of the two blocks has no template yet, so a colour here is a guess."
            end
            if mirror then msg = msg .. "\nShown mirrored, as it will be built." end
            msg = msg .. "\nScan this with your phone. If it reads here it will read on the island."
            note.Text = msg
        end
    end

    function Cache.markQRPreviewDirty()
        Cache.QRPreviewDirty = true
    end

    Cache.SignsTab:CreateSection("Preview")
    Cache.SignsTab:CreateToggle({ Name="Show Sign Preview", CurrentValue=false, Callback=function(v)
        State.ShowSignPreview = v
        -- rebuilt on demand for the same reason the movement panel is: DoFullCleanup
        -- runs on a teleport and destroys this while the script keeps running, and a
        -- toggle that reads ON with nothing on screen has no way to say why
        if v and not (Cache.SignPreviewFrame and Cache.SignPreviewFrame.Parent) then
            pcall(createsignpreviewui)
        end
        if Cache.SignPreviewFrame then
            Cache.SignPreviewFrame.Visible = v
            if v then Cache.markSignPreviewDirty() end
        elseif v then
            Window:Notify({Title="Sign Preview", Content="Couldn't draw the preview panel on this executor. Generate the blueprint and use the world preview instead.", Duration=10})
        end
    end})
    Cache.SignsTab:CreateToggle({ Name="Show QR Preview", CurrentValue=false, Callback=function(v)
        State.ShowQRPreview = v
        if v and not (Cache.QRPreviewFrame and Cache.QRPreviewFrame.Parent) then
            pcall(createqrpreviewui)
        end
        if Cache.QRPreviewFrame then
            Cache.QRPreviewFrame.Visible = v
            if v then Cache.markQRPreviewDirty() end
        elseif v then
            Window:Notify({Title="QR Preview", Content="Couldn't draw the preview panel on this executor. Generate the blueprint and check the code by building it.", Duration=10})
        end
    end})
end
-- end of SIGN AND QR PREVIEW --------------------------------------------------------
-- ==================== BLUEPRINT SHARE CODES (the buttons) ====================
-- The codec is 071_share_codec.lua. This appends a section to the Blueprints tab.
--
-- WHY TEXT AND NOT THE FILE. Handing somebody a blueprint used to mean handing them
-- a JSON file and telling them which folder it goes in. A code goes anywhere text
-- goes; a typical build is a few hundred characters of it, because the codec keeps
-- a block on the 3-stud lattice to a byte or two before it compresses.
--
-- WHY THERE IS A FILE BUTTON ANYWAY. The box a code is pasted into is a single-line
-- Roblox TextBox (the UI adapter's CreateInput: no MultiLine, the text handed over
-- on focus lost), and a very long string pasted into one is slow at best and cut
-- short at worst. A cut code is refused by its lengths and checksum rather than
-- built wrong, but refusing is not importing -- so the same code can come in from
-- share_code.txt, which has no such limit. Random or float-heavy builds are where
-- that bites; a lattice build of twenty thousand blocks usually does not.
do
    local function build()
        local SHARE_FILE = "Islands trading hub/share_code.txt"
        local FOLDER = "Islands trading hub/Blueprints"
        -- past this a paste into the box is where things start going wrong, so the
        -- file is written as well and the notification says why
        local LONG_CODE = 16000

        local function say(text, secs)
            Window:Notify({Title="Share Code", Content=text, Duration=secs or 8})
        end

        -- what is ON DISK under that name, not Cache.LoadedBlueprintData: the loaded
        -- copy may be flipped or turned by the movement panel, and a share code of a
        -- blueprint should be that blueprint. Same two file names and the same two
        -- layouts loadblueprint accepts.
        local function readBlocks(name)
            if not (isfile and readfile) then return nil, "Your executor cannot read files." end
            local path = FOLDER .. "/" .. name .. ".json"
            if not isfile(path) then path = FOLDER .. "/blueprint_" .. name .. ".json" end
            if not isfile(path) then return nil, "There is no file for '" .. name .. "' any more — refresh the blueprint list." end
            local ok, data = pcall(function() return HttpService:JSONDecode(readfile(path)) end)
            if not ok or type(data) ~= "table" then return nil, "That blueprint file is not valid JSON." end
            if data.blocks then return data.blocks end
            if data.Blocks then
                local out = {}
                for bt, list in pairs(data.Blocks) do
                    for _, id in ipairs(list) do
                        if id.C then out[#out + 1] = { blockType = bt, cframe = id.C } end
                    end
                end
                return out
            end
            return nil, "That blueprint file holds no blocks."
        end

        -- setclipboard, toclipboard and syn.write_clipboard through getfenv: none of
        -- them is guaranteed, and a bare read of a name no executor promises is the
        -- global read check_globals.py refuses
        local function copyText(text)
            local env = getfenv(0)
            local syn = rawget(env, "syn")
            for _, fn in ipairs({ rawget(env, "setclipboard"), rawget(env, "toclipboard"),
                                  type(syn) == "table" and syn.write_clipboard or nil }) do
                if type(fn) == "function" and pcall(fn, text) then return true end
            end
            return false
        end
        local function writeShareFile(text)
            if not writefile then return false end
            if isfolder and makefolder and not isfolder("Islands trading hub") then
                pcall(makefolder, "Islands trading hub")
            end
            return (pcall(writefile, SHARE_FILE, text))
        end

        local function importCode(code, source)
            local blocks, nameOrWhy = Cache.shareDecode(code)
            if not blocks then say(nameOrWhy, 14); return end
            if #blocks == 0 then say("That code holds an empty blueprint — nothing to import.", 8); return end
            if not (writefile and isfile) then say("Your executor cannot write files, so the blueprint has nowhere to go.", 8); return end
            local typed = tostring(Cache.ShareImportName or ""):gsub("^%s+", ""):gsub("%s+$", "")
            local base = (typed ~= "" and typed) or (nameOrWhy ~= "" and nameOrWhy) or "Shared"
            base = base:gsub("[^%w_%-]", "_")
            local name, counter = base, 2
            while isfile(FOLDER .. "/" .. name .. ".json") do name = base .. counter; counter += 1 end
            local ok, encoded = pcall(function() return HttpService:JSONEncode({ blocks = blocks }) end)
            if not ok then say("Could not turn the imported blocks into a blueprint file.", 8); return end
            local okW = pcall(function() ensureBlueprintFolder(); writefile(FOLDER .. "/" .. name .. ".json", encoded) end)
            if not okW then say("Could not write the blueprint file.", 8); return end
            -- selected the way the QR and sign generators select theirs: a loud
            -- Refresh, so the dropdown's own callback loads it and fills the pickers
            State.SelectedBlueprint = name
            if BlueprintDD then BlueprintDD:Refresh(refreshblueprints(), name) end
            local chars = #(tostring(code):gsub("%s+", ""))
            local types = {}
            local nTypes = 0
            for _, b in ipairs(blocks) do
                if not types[b.blockType] then types[b.blockType] = true; nTypes += 1 end
            end
            say(string.format("Imported '%s' from %s: %d blocks of %d types, from %d characters. It is selected as your blueprint — press 'Check Materials Needed' before you build it.",
                name, source, #blocks, nTypes, chars), 12)
        end

        ToolsTab:CreateSection("Share Blueprints As Text")
        ToolsTab:CreateNote("Turn the selected blueprint into a code you can paste to someone, or paste theirs in to get the blueprint. A code too long for one Discord message is split into numbered parts: post them one by one, and on the other side paste each one and press Import until it says it has them all.")

        -- THE CODE IS WRITTEN IN CJK CHARACTERS BY DEFAULT: 14 bits each against
        -- base64's 6, so it is 2.3 times shorter and a castle fits one Discord
        -- message. Anywhere that mangles such characters, this switches to plain
        -- letters and digits; either kind imports the same way.
        ToolsTab:CreateToggle({ Name="Plain Letters Only (longer code)", CurrentValue=false, Callback=function(v)
            Cache.ShareAscii = v
        end})
        ToolsTab:CreateButton({ Name="Copy Share Code", Callback=function() task.spawn(function()
            local name = State.SelectedBlueprint
            if not name or name == "None" then
                say("Pick a blueprint in 'Select Blueprint' first — the code is made from the selected one.", 8); return
            end
            local blocks, why = readBlocks(name)
            if not blocks then say(why, 8); return end
            if #blocks == 0 then say("'" .. name .. "' has no blocks to share.", 8); return end
            say(string.format("Encoding %d blocks...", #blocks), 3)
            local code, info = Cache.shareEncode(blocks, name, { ascii = Cache.ShareAscii == true })
            -- TOO LONG FOR ONE MESSAGE: split it, hand over part 1, and let 'Copy Next
            -- Part' walk the rest. The file gets every part, one to a line, so the
            -- whole thing can still be sent in one go.
            local parts = Cache.shareSplit(code)
            if #parts > 1 then
                Cache.ShareOutParts, Cache.ShareOutIndex = parts, 1
                local copiedP = copyText(parts[1])
                writeShareFile(table.concat(parts, "\n\n"))
                say(string.format("'%s': %d blocks in %d characters — too long for one Discord message, so it is split into %d parts. %s Post it, then press 'Copy Next Part' for part 2. All %d parts are also in %s.",
                    name, info.blocks, info.chars, #parts,
                    copiedP and "Part 1 of " .. #parts .. " is on your clipboard." or "Your executor has no clipboard; take the parts from the file.",
                    #parts, SHARE_FILE), 16)
                return
            end
            Cache.ShareOutParts, Cache.ShareOutIndex = nil, nil
            local copied = copyText(code)
            local long = info.chars > LONG_CODE
            local wrote = (not copied or long) and writeShareFile(code)
            local where
            if copied and wrote then
                where = "Copied to your clipboard, and saved to " .. SHARE_FILE .. " — at this length a paste into a text box may be cut off, so send the file if it is."
            elseif copied then
                where = "Copied to your clipboard."
            elseif wrote then
                where = "Your executor has no clipboard, so it is saved to " .. SHARE_FILE .. "."
            else
                where = "Your executor has neither a clipboard nor file writing, so the code could not be handed over."
            end
            local extra = ""
            if info.floats > 0 then
                extra = string.format(" %d block(s) sit off the 3-stud lattice or at an odd angle and were stored in full.", info.floats)
            end
            if info.skipped > 0 then
                extra = extra .. string.format(" %d entr%s with no block type or position were left out, as the builder would.", info.skipped, info.skipped == 1 and "y" or "ies")
            end
            say(string.format("'%s': %d blocks of %d types in %d characters. %s%s",
                name, info.blocks, info.types, info.chars, where, extra), 14)
        end) end})

        ToolsTab:CreateButton({ Name="Copy Next Part", Callback=function()
            local parts, i = Cache.ShareOutParts, Cache.ShareOutIndex
            if not parts then say("Nothing to walk through — 'Copy Share Code' splits a code into parts only when it is too long for one message.", 8); return end
            if i >= #parts then say(string.format("That was the last part (%d of %d). Press 'Copy Share Code' again to start over.", #parts, #parts), 8); return end
            i += 1
            Cache.ShareOutIndex = i
            if copyText(parts[i]) then
                say(string.format("Part %d of %d copied.%s", i, #parts, i == #parts and " That is the last one." or " Post it, then press this again."), 8)
            else
                say("Your executor has no clipboard; the parts are in " .. SHARE_FILE .. ".", 8)
            end
        end})

        -- the parts pasted so far, and what to say about them
        local function takeText(text, source)
            local st, res = Cache.shareCollect(Cache.ShareIn, text)
            Cache.ShareIn = st
            if res.err then say(res.err, 12); return end
            if not res.complete then
                local miss = {}
                for i, k in ipairs(res.missing) do miss[i] = tostring(k) end
                say(string.format("Got %d of %d parts. Still need part%s %s — paste the next one and press 'Import Share Code' again.",
                    res.got, res.n, #miss == 1 and "" or "s", table.concat(miss, ", ")), 10)
                return
            end
            importCode(res.code, (res.n and res.n > 1) and (res.n .. " parts") or source)
        end

        ToolsTab:CreateInput({ Name="Paste Share Code", PlaceholderText="ITH2:... or a part, ITHP1:...", Callback=function(v)
            Cache.ShareCodeText = v
        end})
        ToolsTab:CreateInput({ Name="Imported Blueprint Name", PlaceholderText="the name in the code", Callback=function(v)
            Cache.ShareImportName = v
        end})
        ToolsTab:CreateButton({ Name="Import Share Code", Callback=function() task.spawn(function()
            local code = tostring(Cache.ShareCodeText or "")
            if code:gsub("%s+", "") == "" then
                say("Paste a code into 'Paste Share Code' first (click away from the box so it takes).", 8); return
            end
            takeText(code, "the pasted code")
        end) end})
        ToolsTab:CreateButton({ Name="Clear Pasted Parts", Callback=function()
            Cache.ShareIn = nil
            say("Forgot the parts pasted so far. Start again from part 1.", 6)
        end})
        ToolsTab:CreateButton({ Name="Import From share_code.txt", Callback=function() task.spawn(function()
            if not (isfile and readfile) then say("Your executor cannot read files.", 8); return end
            if not isfile(SHARE_FILE) then
                say("There is no " .. SHARE_FILE .. ". Put the code in a file with that name (just the code, nothing else) and press this again.", 10); return
            end
            local ok, text = pcall(readfile, SHARE_FILE)
            if not ok then say("Could not read " .. SHARE_FILE .. ".", 8); return end
            -- the file may hold a whole code or every part of one; collected fresh, so
            -- parts half-pasted into the box earlier do not get mixed in
            Cache.ShareIn = nil
            takeText(text, "share_code.txt")
        end) end})
    end
    build()
end
-- ==================== BLUEPRINT LIBRARY (the panel) ====================
-- Every saved blueprint as a card: a top-down picture, its size, its block count,
-- and a button to select it. The arithmetic is 076_bp_library.lua; this is the file
-- reading, the panel and the buttons, appended to the Blueprints tab (ToolsTab).
--
-- WHY A PANEL AND NOT THE DROPDOWN. The blueprint dropdown is a list of file names, and
-- after a few imports and pixel-art runs it is "Castle2", "PIX_logo3", "Shared4" --
-- names nobody remembers the contents of. Loading each one to find out means a
-- preview, a materials check and a wait per guess. A picture from above and "212
-- blocks, 9 x 9 x 4" answers that without touching the build state at all: nothing
-- here loads a blueprint until a card's Select button hands it to the dropdown.
--
-- WHY IT READS IN THE BACKGROUND. readfile and JSONDecode of an 80,000-block island
-- cannot be split, but everything after them can, and a library is many files. The
-- panel opens at once on what is already known (summaries are kept for the session,
-- keyed by a fingerprint of the file's text, so reopening is instant), then reads
-- the rest one file at a time with a yield between them and a progress line, the
-- cards on screen first.
--
-- A FUNCTION, NOT A DO-BLOCK, for 224's and 225's reason: a function body has its
-- own 200 registers. This part keeps some fifty locals live at once (the files, the
-- theme, the widgets, the card painter), and a do-block's locals are the MAIN
-- CHUNK's registers while the block is open -- on top of the 160-odd column-0
-- locals every part shares. The executor's compiler (no optimisation, full debug
-- info) ran out at `local function scan()`: "Out of local registers ... exceeded
-- limit 200", and the hub never loaded. check_register_budget.py counts column-0
-- locals only and could not see it; check.sh now compiles each output with
-- luau-compile at the executor's settings, which is what catches the next one.
function Cache.bpLibraryUI()
    local FOLDER = "Islands trading hub/Blueprints"
    local SEEN_FILE = "Islands trading hub/bp_library_seen.json"
    local SHARE_FILE = "Islands trading hub/share_code.txt"
    local FAV_FILE = "Islands trading hub/bp_library_favs.json"
    local PER_ROW, ROWS = 3, 3
    local PER_PAGE = PER_ROW * ROWS
    -- 236, not 206: at 206 the text beside the picture had 86 pixels, which is why
    -- names broke mid-word and the stats came out as a wall
    local CARD_W, CARD_H, GAP = 236, 150, 10
    local THUMB = 100         -- pixels on a card's thumbnail side
    local MAX_CELLS = 48      -- thumbnail cells on the long side, at most
    local BANDS = 4           -- height shades on a thumbnail

    -- name -> { key, s = summary or nil, bad = reason or nil, date, dateKind }
    Cache.BpLibSummaries = Cache.BpLibSummaries or {}
    Cache.BpLibView = Cache.BpLibView or { query = "", sort = Cache.BP_LIB_SORTS[1], page = 1 }

    local function say(text, secs)
        Window:Notify({Title="Blueprint Library", Content=text, Duration=secs or 8})
    end

    -- FILE DATES. Executors give no modification time, and no writer in this script
    -- puts one in the file. So a date is either one the file itself carries (a
    -- savedAt/createdAt/time number, for files written by something that does) or
    -- the moment this library first saw the file, remembered on disk -- and the card
    -- says which, because "first seen 2d ago" on a build saved last year would be a
    -- lie if it were printed as a save date.
    local function loadSeen()
        if Cache.BpLibSeen then return Cache.BpLibSeen end
        Cache.BpLibSeen = {}
        if isfile and readfile and isfile(SEEN_FILE) then
            local ok, t = pcall(function() return HttpService:JSONDecode(readfile(SEEN_FILE)) end)
            if ok and type(t) == "table" then Cache.BpLibSeen = t end
        end
        return Cache.BpLibSeen
    end
    local function saveSeen()
        if not writefile then return end
        pcall(function() writefile(SEEN_FILE, HttpService:JSONEncode(Cache.BpLibSeen or {})) end)
    end
    local function fileDate(data)
        if type(data) ~= "table" then return nil end
        for _, k in ipairs({ "savedAt", "createdAt", "time" }) do
            local v = tonumber(data[k])
            if v and v > 1e9 then return v end
        end
        return nil
    end

    -- FAVOURITES: a set of names on disk, starred on the card and always sorted first
    local function loadFavs()
        if Cache.BpLibFavs then return Cache.BpLibFavs end
        Cache.BpLibFavs = {}
        if isfile and readfile and isfile(FAV_FILE) then
            local ok, t = pcall(function() return HttpService:JSONDecode(readfile(FAV_FILE)) end)
            if ok and type(t) == "table" then
                for _, n in ipairs(t) do if type(n) == "string" then Cache.BpLibFavs[n] = true end end
            end
        end
        return Cache.BpLibFavs
    end
    local function saveFavs()
        if not writefile then return end
        local list = {}
        for n in pairs(Cache.BpLibFavs or {}) do list[#list + 1] = n end
        table.sort(list)
        pcall(function() writefile(FAV_FILE, HttpService:JSONEncode(list)) end)
    end

    -- a star is keyed by name too, so Rename/Delete (175) has to move it with the
    -- build: renamed, the card came back unstarred; deleted, the star waited for the
    -- next build of that name. Same re-keying as the mods file, so the same pure walk.
    function Cache.moveBlueprintFav(oldName, newName)
        local favs = loadFavs()
        local _, changed = Cache.reindexBlueprintMods(favs, oldName, newName)
        if changed then saveFavs() end
    end

    local function pathOf(name)
        local p = FOLDER .. "/" .. name .. ".json"
        if isfile and not isfile(p) and isfile(FOLDER .. "/blueprint_" .. name .. ".json") then
            p = FOLDER .. "/blueprint_" .. name .. ".json"
        end
        return p
    end

    local function listNames()
        local out = {}
        for _, n in ipairs(refreshblueprints()) do
            if n ~= "None" then out[#out + 1] = n end
        end
        return out
    end

    -- the same three clipboards 218 tries, through getfenv so a name no executor
    -- promises is never a bare global read
    local function copyText(text) return Cache.copyText(text) end   -- 082's, shared

    -- ---- the panel ------------------------------------------------------------
    local ui, frame, grid, status, pageLabel, sortBtn, prevBtn, nextBtn, countLabel
    local paintGen, scanGen = 0, 0
    local repaint -- forward: the scanner repaints when a card on screen is read

    local function entries()
        local out = {}
        for _, name in ipairs(Cache.BpLibNames or {}) do
            local c = Cache.BpLibSummaries[name]
            out[#out + 1] = { name = name, summary = c and c.s, bad = c and c.bad,
                              date = c and c.date, dateKind = c and c.dateKind }
        end
        return out
    end
    local function visible()
        local v = Cache.BpLibView
        local list = Cache.bpLibFavsFirst(Cache.bpLibFilterSort(entries(), v.query, v.sort), loadFavs(), v.onlyFavs)
        local page, p, pages = Cache.bpLibPage(list, v.page, PER_PAGE)
        v.page = p
        return page, p, pages, #list
    end

    -- ONE QUIET PALETTE, AND THE HUB'S OWN ACCENT. The first version gave every card
    -- three saturated buttons (green, brown, blue), nine cards a page: twenty-seven
    -- patches of colour competing with the pictures, which are the only thing on the
    -- panel worth looking at. Now there is one accent, the theme's, and it marks the
    -- one thing that is special -- the blueprint in use.
    -- THE WINDOW'S OWN PALETTE, read from it. Library.Theme is the live UI library's
    -- (020): the navy the hub window is drawn in and its periwinkle accent. The
    -- `Themes` table in bootstrap is a different, older set that only the old panels
    -- use -- taking the accent from there is how this panel first came out purple
    -- beside a blue window. The numbers after `or` are that same theme, for a load
    -- where the library is not up yet.
    local TH = (Library and Library.Theme) or {}
    local function mix(a, b, t) return Color3.new(a.R + (b.R - a.R) * t, a.G + (b.G - a.G) * t, a.B + (b.B - a.B) * t) end
    local C = {
        panel     = TH.Background or Color3.fromRGB(13, 17, 28),
        card      = TH.Surface or Color3.fromRGB(17, 22, 36),
        cardHover = TH.Surface2 or Color3.fromRGB(21, 27, 44),
        raised    = TH.Surface3 or Color3.fromRGB(34, 43, 66),
        stroke    = TH.Stroke or Color3.fromRGB(32, 41, 63),
        strokeHi  = TH.StrokeHover or Color3.fromRGB(66, 88, 130),
        well      = TH.AccentDark or Color3.fromRGB(10, 14, 24),
        text      = TH.Text or Color3.fromRGB(226, 232, 240),
        sub       = TH.Muted or Color3.fromRGB(128, 141, 166),
        accent    = TH.Accent or Color3.fromRGB(122, 162, 247),
        warn      = TH.Warning or Color3.fromRGB(240, 176, 108),
        gold      = Color3.fromRGB(245, 200, 90),
    }
    -- guarded: this runs at LOAD, and a load-time error stops every tab after this one
    -- (the Combat-tab bug's shape). A theme value that is not a real Color3 -- the smoke
    -- test's mock world has exactly that -- falls back to the plain muted colour.
    local okMix, faint = pcall(mix, C.sub, C.card, 0.35)
    C.faint = okMix and faint or C.sub
    C.onAccent = C.well
    -- Builder Sans, the window's type, when the library published it (020)
    local FF = Library and Library.Fonts or nil
    local function face(label, weight)
        if FF and FF[weight] then pcall(function() label.FontFace = FF[weight] end) end
    end
    local function mkButton(parent, text, pos, size, colour)
        local b = Instance.new("TextButton")
        b.Size = size; b.Position = pos
        b.BackgroundColor3 = colour or C.card; b.BorderSizePixel = 0
        b.Text = text; b.TextColor3 = C.text
        b.Font = Enum.Font.GothamMedium; b.TextSize = 13; b.AutoButtonColor = false
        face(b, "Medium")
        b.Parent = parent
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
        return b
    end
    -- an outline button: text and a hairline, no fill until you point at it
    local function ghost(parent, text, pos, size)
        local b = mkButton(parent, text, pos, size, C.card)
        b.BackgroundTransparency = 1; b.AutoButtonColor = false
        b.TextColor3 = C.sub; b.TextSize = 11
        local st = Instance.new("UIStroke"); st.Color = C.stroke; st.Thickness = 1
        st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border; st.Parent = b
        b.MouseEnter:Connect(function() b.BackgroundTransparency = 0; b.BackgroundColor3 = C.raised; b.TextColor3 = C.text; st.Color = C.strokeHi end)
        b.MouseLeave:Connect(function() b.BackgroundTransparency = 1; b.TextColor3 = C.sub; st.Color = C.stroke end)
        return b
    end
    local function mkLabel(parent, text, pos, size, textSize, bold, colour)
        local l = Instance.new("TextLabel")
        l.Size = size; l.Position = pos; l.BackgroundTransparency = 1
        l.Text = text; l.TextColor3 = colour or Color3.fromRGB(200, 200, 200)
        l.Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham; l.TextSize = textSize or 12
        face(l, bold and "Bold" or "Regular")
        l.TextXAlignment = Enum.TextXAlignment.Left; l.TextYAlignment = Enum.TextYAlignment.Top
        l.TextWrapped = true; l.TextTruncate = Enum.TextTruncate.AtEnd
        l.TextStrokeTransparency = 1; l.Parent = parent
        return l
    end

    -- SELECT does what the generators do after writing a file: a loud Refresh, so
    -- the dropdown's own callback loads the blueprint and fills every picker that
    -- hangs off it. Setting State alone would leave the dropdown showing another name.
    local function selectBlueprint(name)
        if not table.find(refreshblueprints(), name) then
            say("“" .. name .. "” is not in the Blueprints folder any more. Reopen the library to refresh the list.", 8); return
        end
        State.SelectedBlueprint = name
        if BlueprintDD then BlueprintDD:Refresh(refreshblueprints(), name) end
        local c = Cache.BpLibSummaries[name]
        local what = (c and c.s) and (" — " .. Cache.bpLibCardText(c.s)) or ""
        say("Selected “" .. name .. "”" .. what .. ". It is in 'Select Blueprint' now; press 'Check Materials Needed' before you build it.", 10)
    end

    -- SHARE reads the file again rather than keeping blocks around: a summary is all
    -- this panel holds, and a share code of a blueprint should be what is on disk.
    local function shareBlueprint(name)
        if not Cache.shareEncode then say("Share codes are not part of this build.", 6); return end
        if not (isfile and readfile) then say("Your executor cannot read files.", 6); return end
        local path = pathOf(name)
        if not isfile(path) then say("“" .. name .. "” is not in the Blueprints folder any more.", 8); return end
        local ok, data = pcall(function() return HttpService:JSONDecode(readfile(path)) end)
        local blocks = ok and Cache.bpLibBlocks(data)
        if not blocks then say("“" .. name .. "” is not a blueprint file this script can read.", 8); return end
        if #blocks == 0 then say("“" .. name .. "” has no blocks to share.", 6); return end
        say(string.format("Encoding %d blocks...", #blocks), 3)
        local okE, code, info = pcall(Cache.shareEncode, blocks, name, { ascii = Cache.ShareAscii == true })
        if not okE or type(code) ~= "string" then say("Could not make a share code: " .. tostring(code), 10); return end
        -- too long for one message: hand over part 1 and let 'Copy Next Part' walk
        -- the rest, exactly the state 218's own button leaves behind
        local parts = Cache.shareSplit and Cache.shareSplit(code) or { code }
        if #parts > 1 then
            Cache.ShareOutParts, Cache.ShareOutIndex = parts, 1
            local copied = copyText(parts[1])
            local wrote = writefile and pcall(writefile, SHARE_FILE, table.concat(parts, "\n\n"))
            say(string.format("“%s”: %d characters, split into %d parts. %s Press 'Copy Next Part' for the next one.%s",
                name, #code, #parts, copied and "Part 1 is on your clipboard." or "Your executor has no clipboard.",
                wrote and (" All parts are also in " .. SHARE_FILE .. ".") or ""), 14)
            return
        end
        Cache.ShareOutParts, Cache.ShareOutIndex = nil, nil
        if copyText(code) then
            say(string.format("“%s”: %d blocks in %d characters, copied to your clipboard.", name,
                type(info) == "table" and info.blocks or #blocks, #code), 10)
        elseif writefile and pcall(writefile, SHARE_FILE, code) then
            say("Your executor has no clipboard, so the code for “" .. name .. "” is saved to " .. SHARE_FILE .. ".", 10)
        else
            say("Your executor has neither a clipboard nor file writing, so the code could not be handed over.", 10)
        end
    end

    -- the template's colour, or the name's hue when the template is grey under a
    -- texture (076 decides)
    local function colourOf(bt)
        local c = Cache.blockColour and Cache.blockColour(bt) or nil
        local r, g, b
        if c then r, g, b = Cache.bpLibBlockColour(bt, c.R, c.G, c.B) else r, g, b = Cache.bpLibBlockColour(bt) end
        return r and Color3.new(r, g, b) or nil
    end

    -- A CARD IS THE BUTTON. Clicking anywhere on it uses that blueprint, which is what
    -- nine green "Select" buttons were asking you to do; Queue and Share are the two
    -- other things you might want, so they are small and quiet. What a card says is
    -- what you choose a build by: its name, how big it is, and what it is made of --
    -- the materials as a short list with each block's own colour beside it, which is
    -- read at a glance where "black block 13.6k, white block 5.5k, neon white 399" had
    -- to be read word by word.
    local function paintCard(e, slot)
        local col, row = (slot - 1) % PER_ROW, math.floor((slot - 1) / PER_ROW)
        local inUse = State.SelectedBlueprint == e.name
        local card = Instance.new("TextButton")
        card.Size = UDim2.new(0, CARD_W, 0, CARD_H)
        card.Position = UDim2.new(0, col * (CARD_W + GAP), 0, row * (CARD_H + GAP))
        card.BackgroundColor3 = C.card; card.BorderSizePixel = 0
        card.Text = ""; card.AutoButtonColor = false
        card.Parent = grid
        Instance.new("UICorner", card).CornerRadius = UDim.new(0, 10)
        local edge = Instance.new("UIStroke"); edge.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        edge.Color = inUse and C.accent or C.stroke; edge.Thickness = inUse and 1.5 or 1
        edge.Parent = card
        card.MouseEnter:Connect(function() card.BackgroundColor3 = C.cardHover; if not inUse then edge.Color = C.strokeHi end end)
        card.MouseLeave:Connect(function() card.BackgroundColor3 = C.card; if not inUse then edge.Color = C.stroke end end)
        card.MouseButton1Click:Connect(function()
            selectBlueprint(e.name)
            if repaint then repaint() end
        end)

        local canvas = Instance.new("Frame")
        canvas.Size = UDim2.new(0, THUMB, 0, THUMB); canvas.Position = UDim2.new(0, 8, 0, 8)
        canvas.BackgroundColor3 = C.well; canvas.BorderSizePixel = 0
        canvas.ClipsDescendants = true; canvas.Parent = card
        Instance.new("UICorner", canvas).CornerRadius = UDim.new(0, 8)

        local tx = THUMB + 18                         -- the text column
        local tw = CARD_W - tx - 10
        local s = e.summary
        local nameL = mkLabel(card, Cache.bpLibDisplayName(e.name), UDim2.new(0, tx, 0, 8), UDim2.new(0, tw, 0, 34), 14, true, C.text)
        nameL.TextTruncate = Enum.TextTruncate.AtEnd
        local y = 44
        if s then
            -- the count and how many kinds; the footprint goes under the picture it
            -- describes, where there is room for it (one line held both and cut both)
            mkLabel(card, string.format("%s blocks  ·  %d kind%s", Cache.bpLibShortNum(s.count), s.nTypes, s.nTypes == 1 and "" or "s"),
                UDim2.new(0, tx, 0, y), UDim2.new(0, tw, 0, 14), 11, false, C.sub)
            y += 20
            -- the three biggest materials, each: swatch, name, count on the right
            for i = 1, math.min(3, #(s.types or {})) do
                local t = s.types[i]
                local sw = Instance.new("Frame")
                sw.Size = UDim2.new(0, 8, 0, 8); sw.Position = UDim2.new(0, tx, 0, y + 3)
                sw.BackgroundColor3 = colourOf(t[1]) or C.faint; sw.BorderSizePixel = 0; sw.Parent = card
                Instance.new("UICorner", sw).CornerRadius = UDim.new(0, 2)
                -- a hairline, or a black block's swatch vanishes into the card
                local swEdge = Instance.new("UIStroke"); swEdge.Color = C.stroke; swEdge.Thickness = 1; swEdge.Parent = sw
                local nm = mkLabel(card, Cache.bpLibTypeLabel(t[1]), UDim2.new(0, tx + 13, 0, y), UDim2.new(0, tw - 13 - 34, 0, 14), 11, false, C.text)
                nm.TextWrapped = false
                local ct = mkLabel(card, Cache.bpLibShortNum(t[2]), UDim2.new(0, tx + tw - 34, 0, y), UDim2.new(0, 34, 0, 14), 11, false, C.faint)
                ct.TextXAlignment = Enum.TextXAlignment.Right
                y += 16
            end
            -- under the picture: its footprint, or what is wrong with it. The date only
            -- when you sorted by it -- on every card it was nine copies of "saved 3d ago"
            -- (and only a date the file itself carries: "first seen" is when this panel
            -- first read it, which on a first open is "just now" for every card)
            local under, tint = s.placed > 0 and string.format("%d × %d × %d", s.w, s.d, s.h) or "no positions", C.faint
            if s.offLattice > 0 then under, tint = s.offLattice .. " off the grid", C.warn
            elseif Cache.BpLibView.sort == "Newest" and e.dateKind == "saved" then
                local age = Cache.bpLibAge(os.time(), e.date)
                if age then under = age end
            end
            local ul = mkLabel(card, under, UDim2.new(0, 8, 1, -28), UDim2.new(0, THUMB, 0, 22), 10, false, tint)
            ul.TextXAlignment = Enum.TextXAlignment.Center; ul.TextYAlignment = Enum.TextYAlignment.Center
        elseif e.bad then
            mkLabel(card, "Can't read this file: " .. e.bad, UDim2.new(0, tx, 0, y), UDim2.new(0, tw, 0, 44), 11, false, C.warn)
        else
            mkLabel(card, "Reading…", UDim2.new(0, tx, 0, y), UDim2.new(0, tw, 0, 14), 11, false, C.faint)
        end

        -- the star, on the picture's corner: gold when it is a favourite, a faint
        -- outline when it is not -- present, but not asking for attention on every card
        local favs = loadFavs()
        local star = Instance.new("TextButton")
        star.Size = UDim2.new(0, 22, 0, 22); star.Position = UDim2.new(0, 12, 0, 12)
        star.BackgroundColor3 = C.well; star.BackgroundTransparency = favs[e.name] and 0.2 or 0.5
        star.BorderSizePixel = 0; star.Text = favs[e.name] and "★" or "☆"
        star.TextColor3 = favs[e.name] and C.gold or C.sub
        star.Font = Enum.Font.GothamBold; star.TextSize = 14; star.ZIndex = 3; star.Parent = card
        Instance.new("UICorner", star).CornerRadius = UDim.new(1, 0)
        star.MouseButton1Click:Connect(function()
            favs[e.name] = (not favs[e.name]) or nil
            saveFavs()
            if repaint then repaint() end
        end)

        -- IN USE, on the picture's other corner from the star
        if inUse then
            local tag = mkLabel(card, "In use", UDim2.new(0, 12, 0, THUMB - 16), UDim2.new(0, 50, 0, 18), 11, true, C.onAccent)
            tag.TextXAlignment = Enum.TextXAlignment.Center; tag.TextYAlignment = Enum.TextYAlignment.Center
            tag.BackgroundTransparency = 0; tag.BackgroundColor3 = C.accent; tag.ZIndex = 3
            Instance.new("UICorner", tag).CornerRadius = UDim.new(1, 0)
        end

        -- DELETE, right on the card, in two presses: the first turns the button into
        -- "Sure?" for three seconds, the second deletes. One press on a card you were
        -- aiming Queue at must never cost a build. Shares 175's Cache.deleteBlueprint
        -- (file, mods, star, dropdown); then the card leaves the list it came from.
        local del = ghost(card, "Delete", UDim2.new(1, -174, 1, -30), UDim2.new(0, 52, 0, 22))
        local armedAt
        del.MouseButton1Click:Connect(function()
            if not Cache.deleteBlueprint then say("Deleting is not part of this build.", 5); return end
            if not (armedAt and os.clock() - armedAt < 3) then
                armedAt = os.clock()
                del.Text = "Sure?"; del.TextColor3 = C.warn or C.text
                task.delay(3, function()
                    if del.Parent and armedAt and os.clock() - armedAt >= 3 then
                        del.Text = "Delete"; del.TextColor3 = C.text; armedAt = nil
                    end
                end)
                return
            end
            armedAt = nil
            local ok, msg = Cache.deleteBlueprint(e.name)
            say(msg, ok and 4 or 6)
            if ok then
                local names = Cache.BpLibNames or {}
                local i = table.find(names, e.name)
                if i then table.remove(names, i) end
                if Cache.BpLibSummaries then Cache.BpLibSummaries[e.name] = nil end
                if repaint then repaint() end
            end
        end)

        -- QUEUE: use it, then add it exactly as the Queue tab's button does (at the
        -- preview's position, or where you stand)
        local q = ghost(card, "Queue", UDim2.new(1, -118, 1, -30), UDim2.new(0, 52, 0, 22))
        q.MouseButton1Click:Connect(function()
            if not Cache.queueAddSelected then say("The Build Queue is not part of this build.", 6); return end
            selectBlueprint(e.name)
            task.spawn(function()
                -- the dropdown's callback loads the file; give it a moment to land
                local t0 = os.clock()
                while os.clock() - t0 < 3 and not (State.SelectedBlueprint == e.name and Cache.LoadedBlueprintData) do
                    task.wait(0.1)
                end
                Cache.queueAddSelected()
                if repaint then repaint() end
            end)
        end)
        local sh = ghost(card, "Share", UDim2.new(1, -62, 1, -30), UDim2.new(0, 52, 0, 22))
        sh.MouseButton1Click:Connect(function() task.spawn(shareBlueprint, e.name) end)

        -- the picture last: it is the only part that can take more than a frame
        if s and s.thumb.cols > 0 then
            local th = s.thumb
            -- the whole box on the long side (less a margin), the short side to scale
            local box = THUMB - 8
            local long = math.max(th.cols, th.rows)
            local w = math.max(1, math.floor(box * th.cols / long + 0.5))
            local h = math.max(1, math.floor(box * th.rows / long + 0.5))
            local inner = Instance.new("Frame")
            inner.BackgroundTransparency = 1; inner.BorderSizePixel = 0
            inner.Size = UDim2.new(0, w, 0, h)
            inner.Position = UDim2.new(0, math.floor((THUMB - w) / 2), 0, math.floor((THUMB - h) / 2))
            inner.Parent = canvas
            Cache.bpLibPaintThumb(inner, s, 1, colourOf, BANDS, true)
        end
    end

    repaint = function()
        if not (ui and ui.Parent and grid) then return end
        paintGen += 1
        local gen = paintGen
        task.spawn(function()
            for _, c in ipairs(grid:GetChildren()) do
                if c:IsA("GuiObject") then c:Destroy() end
            end
            local page, p, pages, total = visible()
            local first = total == 0 and 0 or (p - 1) * PER_PAGE + 1
            pageLabel.Text = total == 0 and "" or string.format("%d–%d of %d", first, first + #page - 1, total)
            sortBtn.Text = "Sort · " .. Cache.BpLibView.sort
            if prevBtn then prevBtn.TextTransparency = p > 1 and 0 or 0.7 end
            if nextBtn then nextBtn.TextTransparency = p < pages and 0 or 0.7 end
            if total == 0 then
                mkLabel(grid, (#(Cache.BpLibNames or {}) == 0)
                    and ("No blueprints saved yet. They live in " .. FOLDER .. ".")
                    or (Cache.BpLibView.onlyFavs and "No favourites yet. Tap the ☆ on a card to add one, or switch back to All.")
                    or "No blueprint name contains that text.",
                    UDim2.new(0, 8, 0, 8), UDim2.new(1, -16, 0, 40), 13, false)
                return
            end
            for i, e in ipairs(page) do
                if gen ~= paintGen or not (ui and ui.Parent) then return end
                paintCard(e, i)
                task.wait()
            end
        end)
    end

    -- THE SCANNER. One at a time, with a yield between files and inside the big
    -- ones; the cards on screen first. A file whose fingerprint matches what is
    -- cached is not decoded again, which is what makes a reopen instant.
    local function scan()
        scanGen += 1
        local gen = scanGen
        task.spawn(function()
            if not (isfile and readfile) then
                if status then status.Text = "Your executor cannot read files, so there is nothing to show." end
                return
            end
            local seen = loadSeen()
            local seenChanged = false
            local names = Cache.BpLibNames or {}
            -- visible page first, then the rest in list order
            local order, queued = {}, {}
            for _, e in ipairs((visible())) do order[#order + 1] = e.name; queued[e.name] = true end
            for _, n in ipairs(names) do if not queued[n] then order[#order + 1] = n end end
            local read, changedAny = 0, false
            for idx, name in ipairs(order) do
                if gen ~= scanGen or not (ui and ui.Parent) then return end
                local okR, text = pcall(readfile, pathOf(name))
                if okR and type(text) == "string" then
                    local key = Cache.bpLibKey(name, text)
                    local c = Cache.BpLibSummaries[name]
                    if not c or c.key ~= key then
                        read += 1
                        status.Text = string.format("Reading %d of %d: %s (%d KB)", idx, #order, name, math.floor(#text / 1024))
                        task.wait()
                        local okD, data = pcall(function() return HttpService:JSONDecode(text) end)
                        text = nil
                        local blocks = okD and Cache.bpLibBlocks(data)
                        local entry = { key = key }
                        if not blocks then
                            entry.bad = okD and "not a blueprint file" or "not valid JSON"
                        else
                            entry.s = Cache.bpLibSummary(blocks, { maxCells = MAX_CELLS, yieldEvery = 4000,
                                progress = function(i, n, phase)
                                    if status then
                                        status.Text = string.format("Reading %d of %d: %s — %d%%", idx, #order, name,
                                            math.floor(((phase - 1) * n + i) / (2 * n) * 100))
                                    end
                                end })
                        end
                        local own = fileDate(data)
                        if own then
                            entry.date, entry.dateKind = own, "saved"
                        else
                            if not tonumber(seen[name]) then seen[name] = os.time(); seenChanged = true end
                            entry.date, entry.dateKind = tonumber(seen[name]), "seen"
                        end
                        data, blocks = nil, nil
                        Cache.BpLibSummaries[name] = entry
                        changedAny = true
                        if gen ~= scanGen then return end
                        -- repaint as soon as a card on screen has something to show
                        for _, e in ipairs((visible())) do
                            if e.name == name then repaint(); break end
                        end
                    end
                else
                    Cache.BpLibSummaries[name] = { key = "", bad = "could not be read" }
                end
                if idx % 4 == 0 then task.wait() end
            end
            if seenChanged then saveSeen() end
            -- the order of a sort by size or blocks may have changed under the page
            if changedAny and Cache.BpLibView.sort ~= "Name" then repaint() end
            if status then
                -- SAY NOTHING WHEN THERE IS NOTHING TO SAY. "Read 10 files; 10 blueprints
                -- in the library" was the scanner reporting to itself; the count is in the
                -- title and the footer. What is worth a line is a file that cannot be read.
                local bad = 0
                for _, n in ipairs(names) do
                    local c = Cache.BpLibSummaries[n]
                    if c and c.bad then bad += 1 end
                end
                status.Text = bad == 0 and ""
                    or bad == 1 and "1 file in the folder could not be read as a blueprint."
                    or string.format("%d files in the folder could not be read as a blueprint.", bad)
                if countLabel then countLabel.Text = tostring(#names) end
            end
        end)
    end

    function Cache.openBpLibrary()
        Cache.BpLibNames = listNames()
        -- forget summaries of files that are gone, so memory tracks the folder
        local keep = {}
        for _, n in ipairs(Cache.BpLibNames) do keep[n] = true end
        for n in pairs(Cache.BpLibSummaries) do if not keep[n] then Cache.BpLibSummaries[n] = nil end end

        if Cache.BpLibUI then pcall(function() Cache.BpLibUI:Destroy() end) end
        local W = PER_ROW * CARD_W + (PER_ROW - 1) * GAP + 24
        local H = 36 + 46 + 20 + ROWS * CARD_H + (ROWS - 1) * GAP + 48
        ui, frame = buildFrameBase("IVM_BlueprintLibrary", UDim2.new(0, W, 0, H), UDim2.new(0.5, -W / 2, 0.5, -H / 2))
        Cache.BpLibUI = ui
        -- THE FRAME LOOKS LIKE THE WINDOW: buildFrameBase and addTitleBar (082) draw the
        -- old grey panels, so their colours and type are set over here rather than
        -- changed there, where every other panel would change with them
        frame.BackgroundColor3 = C.panel
        for _, k in ipairs(frame:GetChildren()) do
            if k:IsA("UIStroke") then k.Color = C.stroke; k.Thickness = 1 end
        end
        local bar = addTitleBar(frame, "Blueprints", C.panel)
        makedraggable(frame, bar)
        for _, k in ipairs(bar:GetChildren()) do
            if k:IsA("TextLabel") then k.TextColor3 = C.text; k.TextSize = 16; face(k, "Bold") end
        end
        -- (the hairline under the bar is addTitleBar's own now, 082)
        -- the count beside the title, where "Read 10 files" used to be
        countLabel = mkLabel(bar, tostring(#Cache.BpLibNames), UDim2.new(0, 106, 0, 9), UDim2.new(0, 30, 0, 18), 11, true, C.sub)
        countLabel.TextXAlignment = Enum.TextXAlignment.Center; countLabel.TextYAlignment = Enum.TextYAlignment.Center
        countLabel.BackgroundTransparency = 0; countLabel.BackgroundColor3 = C.raised
        Instance.new("UICorner", countLabel).CornerRadius = UDim.new(1, 0)
        local close = Instance.new("TextButton")
        close.Size = UDim2.new(0, 28, 0, 28); close.Position = UDim2.new(1, -34, 0, 4)
        close.BackgroundTransparency = 1; close.Text = "✕"; close.TextColor3 = C.sub
        close.Font = Enum.Font.GothamBold; close.TextSize = 14; close.Parent = bar
        close.MouseEnter:Connect(function() close.TextColor3 = C.text end)
        close.MouseLeave:Connect(function() close.TextColor3 = C.sub end)
        close.MouseButton1Click:Connect(function()
            scanGen += 1; paintGen += 1
            pcall(function() ui:Destroy() end)
            Cache.BpLibUI = nil; ui = nil
        end)

        -- THE TOOLBAR: search, which ones, in what order, read again. The filter is two
        -- halves of one control with the active half lit, because "☆ All" read as a
        -- button that stars everything.
        local SEG, SORT, RE = 190, 140, 32
        local box = Instance.new("TextBox")
        box.Size = UDim2.new(0, W - 24 - SEG - SORT - RE - 24, 0, 30); box.Position = UDim2.new(0, 12, 0, 44)
        box.BackgroundColor3 = C.card; box.BorderSizePixel = 0
        face(box, "Regular")
        do local st = Instance.new("UIStroke"); st.Color = C.stroke; st.Thickness = 1
            st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border; st.Parent = box end
        box.PlaceholderText = "Search blueprints"; box.Text = Cache.BpLibView.query or ""
        box.ClearTextOnFocus = false; box.TextColor3 = C.text
        box.PlaceholderColor3 = C.faint
        box.Font = Enum.Font.Gotham; box.TextSize = 13; box.TextXAlignment = Enum.TextXAlignment.Left
        box.Parent = frame
        Instance.new("UICorner", box).CornerRadius = UDim.new(0, 6)
        Instance.new("UIPadding", box).PaddingLeft = UDim.new(0, 10)
        box:GetPropertyChangedSignal("Text"):Connect(function()
            Cache.BpLibView.query = box.Text
            Cache.BpLibView.page = 1
            repaint()
        end)

        local segX = W - 12 - RE - 8 - SORT - 8 - SEG
        local seg = Instance.new("Frame")
        seg.Size = UDim2.new(0, SEG, 0, 30); seg.Position = UDim2.new(0, segX, 0, 44)
        seg.BackgroundColor3 = C.card; seg.BorderSizePixel = 0; seg.Parent = frame
        Instance.new("UICorner", seg).CornerRadius = UDim.new(0, 6)
        do local st = Instance.new("UIStroke"); st.Color = C.stroke; st.Thickness = 1; st.Parent = seg end
        local allBtn = mkButton(seg, "All", UDim2.new(0, 3, 0, 3), UDim2.new(0.5, -4, 1, -6), C.card)
        local favBtn = mkButton(seg, "★ Favourites", UDim2.new(0.5, 1, 0, 3), UDim2.new(0.5, -4, 1, -6), C.card)
        local function paintSeg()
            local only = Cache.BpLibView.onlyFavs == true
            allBtn.BackgroundColor3 = only and C.card or C.raised
            allBtn.TextColor3 = only and C.sub or C.text
            favBtn.BackgroundColor3 = only and C.raised or C.card
            favBtn.TextColor3 = only and C.gold or C.sub
        end
        paintSeg()
        allBtn.MouseButton1Click:Connect(function()
            Cache.BpLibView.onlyFavs = nil; Cache.BpLibView.page = 1; paintSeg(); repaint()
        end)
        favBtn.MouseButton1Click:Connect(function()
            Cache.BpLibView.onlyFavs = true; Cache.BpLibView.page = 1; paintSeg(); repaint()
        end)
        sortBtn = mkButton(frame, "Sort · " .. Cache.BpLibView.sort, UDim2.new(0, segX + SEG + 8, 0, 44), UDim2.new(0, SORT, 0, 30))
        sortBtn.TextColor3 = C.sub
        do local st = Instance.new("UIStroke"); st.Color = C.stroke; st.Thickness = 1
            st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border; st.Parent = sortBtn end
        sortBtn.MouseButton1Click:Connect(function()
            local sorts = Cache.BP_LIB_SORTS
            local i = table.find(sorts, Cache.BpLibView.sort) or 0
            Cache.BpLibView.sort = sorts[i % #sorts + 1]
            Cache.BpLibView.page = 1
            repaint()
        end)
        local rescan = mkButton(frame, "↻", UDim2.new(1, -(12 + RE), 0, 44), UDim2.new(0, RE, 0, 30))
        rescan.TextSize = 16; rescan.TextColor3 = C.sub
        do local st = Instance.new("UIStroke"); st.Color = C.stroke; st.Thickness = 1
            st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border; st.Parent = rescan end
        -- Rescan forgets the fingerprints and reads every file again: the key samples
        -- a file rather than hashing all of it, so a same-length edit between two
        -- samples is only noticed here (076's bpLibKey says so)
        rescan.MouseButton1Click:Connect(function()
            Cache.BpLibNames = listNames()
            for _, c in pairs(Cache.BpLibSummaries) do c.key = nil end
            repaint(); scan()
        end)

        status = mkLabel(frame, "", UDim2.new(0, 12, 0, 80), UDim2.new(1, -24, 0, 16), 11, false, C.sub)
        status.TextTruncate = Enum.TextTruncate.AtEnd

        grid = Instance.new("Frame")
        grid.BackgroundTransparency = 1; grid.BorderSizePixel = 0
        grid.Position = UDim2.new(0, 12, 0, 100)
        grid.Size = UDim2.new(1, -24, 0, ROWS * CARD_H + (ROWS - 1) * GAP)
        grid.Parent = frame

        -- the footer: where you are, and the two ways to go, dimmed when there is nowhere
        pageLabel = mkLabel(frame, "", UDim2.new(0.5, -80, 1, -34), UDim2.new(0, 160, 0, 20), 12, false, C.sub)
        pageLabel.TextXAlignment = Enum.TextXAlignment.Center; pageLabel.TextYAlignment = Enum.TextYAlignment.Center
        prevBtn = mkButton(frame, "‹", UDim2.new(0.5, -120, 1, -36), UDim2.new(0, 32, 0, 24))
        nextBtn = mkButton(frame, "›", UDim2.new(0.5, 88, 1, -36), UDim2.new(0, 32, 0, 24))
        prevBtn.TextSize, nextBtn.TextSize = 18, 18
        prevBtn.MouseButton1Click:Connect(function()
            Cache.BpLibView.page = math.max(1, Cache.BpLibView.page - 1); repaint()
        end)
        nextBtn.MouseButton1Click:Connect(function()
            Cache.BpLibView.page += 1; repaint()   -- bpLibPage clamps it to the last page
        end)

        repaint()
        scan()
    end

    ToolsTab:CreateSection("Blueprint Library")
    ToolsTab:CreateNote("Every saved blueprint as a card: a picture from above, its size in blocks, how many blocks and kinds, and buttons to select it or copy its share code. Search by name and sort by size, block count or date.")
    ToolsTab:CreateButton({ Name="Open Blueprint Library", Callback=function()
        if not (listfiles and isfolder) then
            say("Your executor cannot list files, so the library has nothing to show.", 8); return
        end
        local ok, err = pcall(Cache.openBpLibrary)
        if not ok then say("Could not open the library: " .. tostring(err), 10) end
    end})
end
Cache.bpLibraryUI()
-- ==================== END BLUEPRINT LIBRARY (the panel) ====================
-- misc stuff
-- ==================== SECTION: TAB Misc ====================
-- BLOCK NUKE FIRST. It was the last of seven sections on this tab, behind anti-AFK,
-- flight, labels and radius settings -- and it is the only thing here that DESTROYS
-- anything. It is also the only thing here anyone opens this tab in a hurry for.
--
-- The radius goes to 300 rather than 120 now that a pass is not paying sixteen
-- milliseconds per hundred parts scanned. Reach is not free even so: the batch is
-- sorted nearest-first and the request pool is finite, so a big radius mostly means
-- more candidates queued behind the ones under your feet -- and if the game refuses
-- hits past some distance of its own, the stop report says so (many requests, few
-- blocks broken).
MiscTab:CreateSection("Block Nuker")
MiscTab:CreateNote("Breaks every block within the radius, nearest first, with the right tool in hand. Nothing else on this tab breaks anything.")
local BlockNukeDD
local BlockNukeOptions = getislandblocks()
BlockNukeDD = CreateMultiDropdown(MiscTab, { Name="Select Blocks", Options=BlockNukeOptions, CurrentOption={"All"}, Callback=function(v)
    BlockNukeHasAll = false; BlockNukeSet = {}
    for _, b in ipairs(v) do
        if b == "All" then BlockNukeHasAll = true; BlockNukeSet = {}; break end
        BlockNukeSet[b] = true
    end
end})
MiscTab:CreateButton({ Name="Refresh Blocks", Callback=function()
    local newOptions = getislandblocks()
    if BlockNukeDD then BlockNukeDD:Refresh(newOptions, "All") end
    -- the multi-dropdown's Refresh doesn't fire its callback, so match the filter to
    -- the "All" it now shows instead of nuking only the old selection
    BlockNukeHasAll = true; BlockNukeSet = {}
end})
MiscTab:CreateSlider({ Name="Nuke Radius", Step=1, Range={5,300}, Increment=1, Suffix="", CurrentValue=Settings.BlockNukeRadius, Callback=function(v) Settings.BlockNukeRadius = v end})
-- shared by Block Nuke and the Build-tab "Remove Selected Blocks": auto-equip an axe
-- for woody blocks / pickaxe for stony blocks, chosen from tools you own (by name).
MiscTab:CreateToggle({ Name="Auto Tool (Axe/Pickaxe)", CurrentValue=false, Callback=function(v)
    State.NukeAutoTool = v; Cache.LastToolCategory = nil
end})
-- HOLD THE HAMMER, NOT A HAMMER. Auto Tool above picks axe-or-pickaxe per block by
-- keyword, which is the right call for a mixed pile; this is the other case -- one
-- named tool, held for everything, because the server judges a break request on what
-- it thinks you are holding and the hammer you want is rarely the one it guesses.
-- Set it and 'Keep This Tool Held' takes precedence over the per-block swapping.
Cache.NukeToolDD = MiscTab:CreateDropdown({ Name="Break Tool",
    Options = Cache.BreakToolName and {"Auto", Cache.BreakToolName} or {"Auto"},
    CurrentOption = { Cache.BreakToolName or "Auto" }, Callback=function(v)
    local pick = type(v) == "table" and v[1] or v
    Cache.BreakToolName = (pick and pick ~= "Auto") and pick or nil
    Cache.ToldNoBreakTool = false
    if Cache.queueFarmSave then Cache.queueFarmSave() end
    Cache.syncBreakToolDDs()
end})
MiscTab:CreateButton({ Name="Find My Break Tools", Callback=function()
    local list = Cache.breakToolList()
    Cache.syncBreakToolDDs()
    Cache.notify({Title="Break Tool", Content=(#list > 0)
        and ("Found: " .. table.concat(list, ", ") .. ". Every tool in your hotbar is listed, likeliest breakers first — it never guesses a tool you do not own, and never hides one because of its name.")
        or "No tools at all in your hotbar. Put one in a slot and press this again.", Duration=10})
end})
MiscTab:CreateToggle({ Name="Keep This Tool Held", CurrentValue=false, Callback=function(v)
    State.NukeHoldTool = v
    Cache.ToldNoBreakTool = false
end})
-- OFF by default like every other automation, and this one moves your character, which
-- is the most intrusive thing the script does without being asked.
-- ON by default, and the one setting here that makes the radius safe to raise. It
-- measures how far away blocks are when they actually break and stops sending past
-- that, so a wide radius costs nothing instead of spending the whole request pool on
-- blocks the server drops. It is also what lets the bubble empty, which is what the
-- hop below waits for.
MiscTab:CreateToggle({ Name="Only Hit What Can Break (learn the reach)", CurrentValue=true, Callback=function(v)
    State.NukeLearnReach = v
    if not v then
        Cache.notify({Title="Block Nuke", Content="Off — it will send break requests at everything inside the radius again, including blocks past the server's own range, which are dropped.", Duration=10})
    end
end})
MiscTab:CreateToggle({ Name="Hop To The Next Blocks (teleport)", CurrentValue=false, Callback=function(v)
    State.NukeHop = v
    Cache.NukeHops = 0
    Cache.NukeDudSpots, Cache.NukeHopDest = {}, nil
    Cache.NukeHopFails, Cache.NukeHopReadyAt = 0, 0
    Cache.NukeHopHoldUntil = 0
    if v then
        Cache.notify({Title="Block Nuke", Content=string.format("On — when nothing is left inside the radius, it teleports you to the nearest block it takes and carries on. It checks you actually arrived before counting a hop, and gives up after %d hops that break nothing.", Settings.NukeMaxHops or 25), Duration=10})
    end
end})
-- BREAK EVERYTHING, ONE BUTTON, PRESSED TWICE. "All" in the picker, the radius at
-- its widest, the reach learner on so the wide radius costs nothing, the hop on so
-- it tours the island when the bubble empties, then the nuke itself -- five settings
-- that together mean "take the island down", which an owner clearing a slot for a
-- new build sets by hand every time. Through the controls, so every switch moves on
-- screen. Two presses within ten seconds, because the one thing this must never be
-- is a slip of the mouse: the first press only says what the second will do.
MiscTab:CreateButton({ Name="Break Everything Here (press twice)", Callback=function()
    local now = os.clock()
    if not (Cache.NukeAllArmedAt and now - Cache.NukeAllArmedAt < 10) then
        Cache.NukeAllArmedAt = now
        Cache.notify({Title="Break Everything — Are You Sure?", Content="Press it again within 10 seconds to break EVERY block the server lets you break on this island: the picker goes to All, the radius to 300, the reach learner and the hop go on, and Block Nuke starts. Bedrock, rock, soil and portals are left alone. Stop it with 'Block Nuke' or the Panic button.", Duration=10})
        return
    end
    Cache.NukeAllArmedAt = nil
    if BlockNukeDD then BlockNukeDD:Refresh(getislandblocks(), "All") end
    BlockNukeHasAll = true; BlockNukeSet = {}
    -- THE WIDE RADIUS IS THIS RUN'S, NOT THE OWNER'S SETTING. The slider's callback
    -- writes Settings.BlockNukeRadius and saves the config, so moving it to 300 here
    -- would make 300 the radius of every later Block Nuke and of the next launch --
    -- a quarry farmed at 40 the day before would spend its whole request pool past
    -- the reach. The owner's value is kept and put back when the nuke switches off.
    if Cache.NukeAllPrevRadius == nil then Cache.NukeAllPrevRadius = Settings.BlockNukeRadius end
    local sl = Cache.SliderFunctions or {}
    if sl["Nuke Radius"] then pcall(sl["Nuke Radius"], 300) else Settings.BlockNukeRadius = 300 end
    local T = Cache.ToggleFunctions or {}
    for _, name in ipairs({ "Only Hit What Can Break (learn the reach)", "Hop To The Next Blocks (teleport)" }) do
        if T[name] then pcall(T[name], true) end
    end
    if T["Block Nuke"] then pcall(T["Block Nuke"], true) end
    Cache.notify({Title="Break Everything", Content="Started: every block in reach, nearest first, hopping on to the next when the bubble empties. 'Block Nuke' switches it off; the stop message says how many broke.", Duration=8})
end})
MiscTab:CreateToggle({ Name="Block Nuke", CurrentValue=false, Callback=function(v)
    BlockBreakToggle = v
    -- SAY WHAT IT DID, ONCE, WHEN YOU STOP IT. "It feels slow" and "the game takes
    -- twenty swings to break one of these" look identical from the outside, and they
    -- need opposite fixes: the first is ours, the second is the block. Broken per
    -- minute against requests sent is the pair that separates them, and the moment
    -- the switch goes off is the one moment the owner is already looking at it.
    -- Break Everything widened the radius for its run only: the owner's own comes back
    if not v and Cache.NukeAllPrevRadius ~= nil then
        local prev = Cache.NukeAllPrevRadius
        Cache.NukeAllPrevRadius = nil
        local sl = Cache.SliderFunctions or {}
        if sl["Nuke Radius"] then pcall(sl["Nuke Radius"], prev) else Settings.BlockNukeRadius = prev end
    end
    if not v and Cache.NukeStartedAt then
        local secs = math.max(1, os.clock() - Cache.NukeStartedAt)
        local broke, sent = Cache.NukeBroke or 0, Cache.NukeSent or 0
        Cache.NukeStartedAt = nil
        Cache.notify({Title="Block Nuke — Stopped", Content=string.format(
            "%d block(s) broken in %d second(s) — %.0f a minute, on %d break request(s) sent (%.1f per block). If the rate is low but the requests are many, the game is making you swing that often; if both are low, raise 'Max Block Hits In Flight' in Settings.",
            broke, math.floor(secs + 0.5), broke / secs * 60, sent,
            broke > 0 and (sent / broke) or sent), Duration=14})
    end
    if v then
        Cache.NukeStartedAt = os.clock()
        Cache.NukeBroke, Cache.NukeSent = 0, 0
        Cache.NukeHitDist = {}
        -- the reach is a property of the SERVER, not of this run, so it deliberately
        -- survives a stop and start: the samples are expensive to gather again
        Cache.NukeHops, Cache.NukeBrokeAtHop = 0, -1
        -- a fresh run tours the island again: forget last run's dud clusters, the
        -- hop that was in flight when it stopped, and the can't-teleport strikes
        Cache.NukeDudSpots, Cache.NukeHopDest = {}, nil
        Cache.NukeHopFails, Cache.NukeHopReadyAt = 0, 0
        State.BlockNukeGen += 1; local gen = State.BlockNukeGen
        -- rescan interval only; blocknuke() now hits every block in range per pass, so
        -- a short interval keeps it responsive without the old one-at-a-time crawl.
        addloop(task.spawn(function()
            -- 0 = a pass every frame. The old fixed tenth of a second was the last
            -- fixed delay left in the nuke: the pass is already bounded (passEnd) and
            -- the scan already yields on time spent, so sleeping on top of that just
            -- left the request pool draining with nothing being queued into it.
            while BlockBreakToggle and gen == State.BlockNukeGen do
                pcall(blocknuke); task.wait(Settings.NukePassDelay or 0)
            end
        end))
    end
end})

