-- ALWAYS DAY / ALWAYS NIGHT. ClockTime is replicated, so the game's own day/night
-- cycle writes over a one-shot set within seconds — the lock has to re-pin on every
-- change, not just once. The re-pin is guarded by a flag because our own write fires
-- the same signal (an unguarded version is an infinite loop). One lock, two toggles:
-- turning either on releases the other, so they can never fight over ClockTime.
function Cache.setClockLock(hour, name)
    local L = game:GetService("Lighting")
    if hour then
        if Cache.DayLockOriginal == nil then Cache.DayLockOriginal = L.ClockTime end
        Cache.ClockLockHour = hour
        if not Cache.DayLockConn then
            Cache.DayLockConn = L:GetPropertyChangedSignal("ClockTime"):Connect(function()
                if Cache.ClockPinning or not Cache.ClockLockHour then return end
                Cache.ClockPinning = true
                pcall(function()
                    if L.ClockTime ~= Cache.ClockLockHour then L.ClockTime = Cache.ClockLockHour end
                end)
                Cache.ClockPinning = false
            end)
        end
        pcall(function() L.ClockTime = hour end)
        -- release the opposite toggle so the UI matches what is actually pinned.
        -- Its callback fires unconditionally (Update always calls Callback), and
        -- without this flag that off-callback would immediately tear down the lock
        -- we just installed — the switch would read ON with nothing pinned.
        local other = Cache.ToggleFunctions and Cache.ToggleFunctions[name]
        if other then
            Cache.ClockSwapping = true
            pcall(other, false)
            Cache.ClockSwapping = false
        end
    else
        if Cache.ClockSwapping then return end
        Cache.ClockLockHour = nil
        if Cache.DayLockConn then Cache.DayLockConn:Disconnect(); Cache.DayLockConn = nil end
        -- only restore if we actually pinned: panic/cleanup force every toggle off,
        -- and blindly writing ClockTime there would yank a normal session's lighting
        if Cache.DayLockOriginal then
            pcall(function() L.ClockTime = Cache.DayLockOriginal end)
            Cache.DayLockOriginal = nil
        end
    end
end
MiscTab:CreateToggle({ Name="Always Day", CurrentValue=false, Callback=function(v)
    Cache.setClockLock(v and 14 or nil, "Always Night")
end})
MiscTab:CreateToggle({ Name="Always Night", CurrentValue=false, Callback=function(v)
    Cache.setClockLock(v and 0 or nil, "Always Day")
end})

MiscTab:CreateSection("Movement")
MiscTab:CreateNote("Speed, jump, flight and a free camera.")
-- Walk Speed. Setting Humanoid.WalkSpeed once does not hold: the character is rebuilt
-- on every respawn, and the game's own scripts write the property back whenever they
-- feel like it (tools, sprint states, the sitting/leaving-a-boat handlers). So re-apply
-- on the property's own changed signal and on respawn, rather than firing every frame
-- from RenderStepped for something that changes a handful of times a minute.
do
    local function applyWalkSpeed()
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildWhichIsA("Humanoid")
        if not hum then return end
        local want = tonumber(Settings.WalkSpeed) or 32
        -- guard the write: assigning inside WalkSpeed's own changed signal would
        -- re-fire it forever
        if math.abs(hum.WalkSpeed - want) > 0.01 then hum.WalkSpeed = want end
    end
    local function bindCharacter()
        if Cache.WalkSpeedPropConn then Cache.WalkSpeedPropConn:Disconnect(); Cache.WalkSpeedPropConn = nil end
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildWhichIsA("Humanoid")
        if not hum then return end
        Cache.WalkSpeedPropConn = hum:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
            if State.WalkSpeedEnabled then applyWalkSpeed() end
        end)
        applyWalkSpeed()
    end
    MiscTab:CreateToggle({ Name="Walk Speed", CurrentValue=false, Callback=function(v)
        State.WalkSpeedEnabled = v
        if v then
            bindCharacter()
            if not Cache.WalkSpeedRespawnConn then
                Cache.WalkSpeedRespawnConn = LocalPlayer.CharacterAdded:Connect(function()
                    task.wait(0.4)
                    if State.WalkSpeedEnabled then bindCharacter() end
                end)
            end
        else
            if Cache.WalkSpeedPropConn then Cache.WalkSpeedPropConn:Disconnect(); Cache.WalkSpeedPropConn = nil end
            if Cache.WalkSpeedRespawnConn then Cache.WalkSpeedRespawnConn:Disconnect(); Cache.WalkSpeedRespawnConn = nil end
            -- hand the character back at the stock speed, not at whatever the slider
            -- happened to be on when it was switched off
            pcall(function()
                local char = LocalPlayer.Character
                local hum  = char and char:FindFirstChildWhichIsA("Humanoid")
                if hum then hum.WalkSpeed = 16 end
            end)
        end
    end})
    MiscTab:CreateSlider({ Name="Walk Speed Amount", Step=1, Range={16,100}, Increment=1, Suffix="",
        CurrentValue=Settings.WalkSpeed or 32, Callback=function(v)
            Settings.WalkSpeed = v
            -- live: dragging the slider changes your speed now, not on the next respawn
            if State.WalkSpeedEnabled then applyWalkSpeed() end
        end})
end
MiscTab:CreateToggle({ Name="Infinite Jump", CurrentValue=false, Callback=function(v)
    if v then
        if not Cache.InfJumpConn then Cache.InfJumpConn = UserInputService.JumpRequest:Connect(function()
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildWhichIsA("Humanoid")
            if hum then hum:ChangeState(Enum.HumanoidStateType.Jumping) end
        end) end
    else
        if Cache.InfJumpConn then Cache.InfJumpConn:Disconnect(); Cache.InfJumpConn = nil end
    end
end})
-- Flight: BodyVelocity + PlatformStand, camera-relative WASD, Space up / Shift down.
-- Uses the shared noclip so you pass through blocks -- pair it with Block Nuke to hover
-- over an area and clear it without falling / removing the ground under you. Moderate
-- default speed (Islands rejects very fast movement); tune with the slider.
MiscTab:CreateToggle({ Name="Flight (WASD / Space / Shift)", CurrentValue=false, Callback=function(v)
    State.FlightEnabled = v
    if v then
        Cache.enableNoclip("flight")
        local function attach()
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            local hum  = char and char:FindFirstChildWhichIsA("Humanoid")
            if not (hrp and hum) then return end
            hum.PlatformStand = true
            local bv = hrp:FindFirstChild("IVM_FlightBV")
            if not bv then bv = Instance.new("BodyVelocity"); bv.Name = "IVM_FlightBV" end
            bv.MaxForce = Vector3.new(1,1,1) * 90000
            bv.P = 8000
            bv.Velocity = Vector3.zero
            bv.Parent = hrp
        end
        attach()
        Cache.FlightRespawnConn = LocalPlayer.CharacterAdded:Connect(function()
            task.wait(0.4); if State.FlightEnabled then attach() end
        end)
        Cache.FlightStepConn = RunService.RenderStepped:Connect(function()
            if not State.FlightEnabled then return end
            local char = LocalPlayer.Character
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            local cam  = Workspace.CurrentCamera
            local bv   = hrp and hrp:FindFirstChild("IVM_FlightBV")
            if not (hrp and cam and bv) then return end
            local dir = Vector3.zero
            if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir = dir + cam.CFrame.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir = dir - cam.CFrame.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir = dir + cam.CFrame.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir = dir - cam.CFrame.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.Space) then dir = dir + Vector3.new(0,1,0) end
            if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then dir = dir - Vector3.new(0,1,0) end
            if dir.Magnitude > 0 then dir = dir.Unit end
            bv.Velocity = dir * (Settings.FlightSpeed or 55)  -- zero input = hover in place
        end)
    else
        State.FlightEnabled = false
        if Cache.FlightStepConn then Cache.FlightStepConn:Disconnect(); Cache.FlightStepConn = nil end
        if Cache.FlightRespawnConn then Cache.FlightRespawnConn:Disconnect(); Cache.FlightRespawnConn = nil end
        local char = LocalPlayer.Character
        local hrp  = char and char:FindFirstChild("HumanoidRootPart")
        if hrp then local bv = hrp:FindFirstChild("IVM_FlightBV"); if bv then bv:Destroy() end end
        local hum = char and char:FindFirstChildWhichIsA("Humanoid")
        if hum then hum.PlatformStand = false end
        Cache.disableNoclip("flight")
    end
end})
MiscTab:CreateSlider({ Name="Flight Speed", Step=5, Range={20,100}, Increment=5, Suffix="", CurrentValue=Settings.FlightSpeed or 55, Callback=function(v) Settings.FlightSpeed = v end})
-- Freecam: self-contained (no remote loadstring). Toggle here or press Shift+P.
do
    -- grab the default control module so we can freeze the character while flying.
    -- without this, WASD moves the camera AND walks the character at the same time.
    local controls
    local function getControls()
        if controls then return controls end
        pcall(function()
            local pm = require(LocalPlayer:WaitForChild("PlayerScripts", 5):WaitForChild("PlayerModule", 5))
            controls = pm:GetControls()
        end)
        return controls
    end

    local function stopFreecam()
        -- nothing to undo: cleanup calls this unconditionally, and resetting camera and
        -- controls when freecam was never on stomped on a re-injected instance's state
        if not State.FreecamEnabled and not Cache.FreecamStep then return end
        State.FreecamEnabled = false
        UserInputService.MouseBehavior = Enum.MouseBehavior.Default
        local cam = workspace.CurrentCamera
        if cam then cam.CameraType = Enum.CameraType.Custom end
        if Cache.FreecamStep then Cache.FreecamStep:Disconnect(); Cache.FreecamStep = nil end
        local c = getControls(); if c then pcall(function() c:Enable() end) end
    end

    local function startFreecam()
        local cam = workspace.CurrentCamera
        if not cam then return end
        State.FreecamEnabled = true
        local c = getControls(); if c then pcall(function() c:Disable() end) end
        local camPos = cam.CFrame.Position
        local pitch, yaw = cam.CFrame:ToEulerAnglesYXZ()
        cam.CameraType = Enum.CameraType.Scriptable
        UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter

        if Cache.FreecamStep then Cache.FreecamStep:Disconnect() end
        Cache.FreecamStep = RunService.RenderStepped:Connect(function(dt)
            if not State.FreecamEnabled then return end
            cam = workspace.CurrentCamera
            local d = UserInputService:GetMouseDelta()
            yaw   = yaw - d.X * 0.0035
            pitch = math.clamp(pitch - d.Y * 0.0035, -1.4, 1.4)
            local rot = CFrame.fromEulerAnglesYXZ(pitch, yaw, 0)
            local move = Vector3.zero
            local function down(k) return UserInputService:IsKeyDown(k) end
            if down(Enum.KeyCode.W) then move = move + rot.LookVector end
            if down(Enum.KeyCode.S) then move = move - rot.LookVector end
            if down(Enum.KeyCode.D) then move = move + rot.RightVector end
            if down(Enum.KeyCode.A) then move = move - rot.RightVector end
            if down(Enum.KeyCode.E) then move = move + Vector3.new(0,1,0) end
            if down(Enum.KeyCode.Q) then move = move - Vector3.new(0,1,0) end
            local speed = (down(Enum.KeyCode.LeftShift) and 120 or 45)
            camPos = camPos + move * speed * dt
            cam.CFrame = CFrame.new(camPos) * rot
        end)
    end

    -- expose the proper teardown so DoFullCleanup can restore the camera/controls
    -- on panic/unload (freecam had no cleanup before — camera stayed detached)
    Cache.stopFreecam = stopFreecam

    MiscTab:CreateToggle({ Name="Freecam (Shift+P)", CurrentValue=false, Callback=function(v)
        if v then startFreecam() else stopFreecam() end
    end})

    if Cache.FreecamKey then Cache.FreecamKey:Disconnect() end
    Cache.FreecamKey = addconn(UserInputService.InputBegan:Connect(function(input, gpe)
        if gpe then return end
        if input.KeyCode == Enum.KeyCode.P
        and (UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.RightShift)) then
            -- flip the REGISTERED toggle so the UI switch stays in sync with Shift+P
            -- (it used to call start/stop directly, leaving the switch stuck showing OFF)
            local tf = Cache.ToggleFunctions["Freecam (Shift+P)"]
            if tf then tf() else
                if State.FreecamEnabled then stopFreecam() else startFreecam() end
            end
        end
    end))
end
