-- ---- Island travel --------------------------------------------------------
-- VISIT_ONLINE_ISLAND is the request the game itself fires (field-captured); the
-- older CLIENT_VISIT_ISLAND_REQUEST is tried as a fallback with a deadline, so a
-- server that ignores it can't hang the button.
MiscTab:CreateDivider()
MiscTab:CreateInput({ Name="Visit Player's Island", PlaceholderText="Username", Callback=function(v) State.VisitTarget = v end})
MiscTab:CreateButton({ Name="Visit Island (experimental)", Callback=function()
    local name = State.VisitTarget
    if not name or name == "" then Window:Notify({Title="Visit", Content="Type a username first.", Duration=3}); return end
    task.spawn(function()
        local ok, uid = pcall(function() return Players:GetUserIdFromNameAsync(name) end)
        if not ok or not uid then Window:Notify({Title="Visit", Content="Couldn't resolve that username.", Duration=4}); return end
        -- CONFIRMED field capture: VISIT_ONLINE_ISLAND({targetUserId}) is how the
        -- game itself visits — try that first, then the old request remote
        Window:Notify({Title="Visit", Content="Requesting a visit to " .. name .. "'s island...", Duration=4})
        if Cache.visitIslandByUserId and Cache.visitIslandByUserId(uid) then
            Window:Notify({Title="Visit", Content="Visit accepted — teleporting to " .. name .. "'s island...", Duration=6})
            return
        end
        local rem = Cache._findRemote("ReplicatedStorage.rbxts_include.node_modules.@rbxts.net.out._NetManaged.CLIENT_VISIT_ISLAND_REQUEST")
        if not rem then Window:Notify({Title="Visit", Content="Visit remote not found (game update?).", Duration=5}); return end
        local function probe(...)
            local args = table.pack(...)
            local done, s, r = false, false, nil
            task.spawn(function()
                s, r = pcall(function() return rem:InvokeServer(table.unpack(args, 1, args.n)) end)
                done = true
            end)
            local dl = tick() + 3
            while not done and tick() < dl do task.wait() end
            return done and s and r ~= nil and r ~= false
                and not (type(r) == "table" and (r.success == false or r.Success == false))
        end
        -- a successful visit teleports (killing the script), so probe one shape
        -- at a time and stop at the first that looks accepted
        local hit = probe(uid)
            or probe({ userId = uid })
            or probe({ userId = uid, name = name })
        Window:Notify({Title="Visit", Content=hit
            and "The server accepted a visit request — give it ~10s."
            or  "No visit request shape was accepted on this server.", Duration=10})
    end)
end})

