    local FILE = "Islands trading hub/whats_new.json"
    local C = {
        text = Color3.fromRGB(225, 225, 230), dim = Color3.fromRGB(150, 150, 160),
        head = Color3.fromRGB(245, 245, 250), card = Color3.fromRGB(30, 30, 37),
        ok = Color3.fromRGB(70, 140, 220), bar = Color3.fromRGB(35, 35, 42),
    }

    -- nil when there is no file, it cannot be read, or it holds something else: all
    -- three are "never seen", which is the first-run welcome (see 096 for why)
    function Cache.readWhatsNewSeen()
        if not (isfile and readfile) then return nil end
        local ok, data = pcall(function()
            if not isfile(FILE) then return nil end
            return HttpService:JSONDecode(readfile(FILE))
        end)
        return ok and Cache.changelogSeenFromData(data) or nil
    end

    -- records the NEWEST version in this build, not the newest one shown: after
    -- 'Got it' the panel must not come back until something newer ships
    function Cache.markWhatsNewSeen()
        local newest = Cache.changelogNewest()
        if not (newest and writefile) then return false end
        return pcall(function()
            if isfolder and makefolder and not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
            writefile(FILE, HttpService:JSONEncode(Cache.changelogSeenToData(newest)))
        end)
    end

    local function lbl(parent, text, size, color, bold, order)
        local l = Instance.new("TextLabel")
        l.BackgroundTransparency = 1; l.Text = text; l.TextColor3 = color or C.text
        l.Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham; l.TextSize = size or 12
        l.TextXAlignment = Enum.TextXAlignment.Left; l.TextYAlignment = Enum.TextYAlignment.Top
        l.TextWrapped = true
        l.Size = UDim2.new(1, 0, 0, 0); l.AutomaticSize = Enum.AutomaticSize.Y
        l.LayoutOrder = order or 0; l.Parent = parent
        return l
    end
    local function button(parent, text, color, size, order)
        local b = Instance.new("TextButton")
        b.Text = text; b.TextColor3 = C.head; b.Font = Enum.Font.GothamBold; b.TextSize = 13
        b.BackgroundColor3 = color; b.BorderSizePixel = 0; b.AutoButtonColor = true
        b.Size = size; b.LayoutOrder = order or 0; b.Parent = parent
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
        return b
    end

    local function dismiss()
        Cache.markWhatsNewSeen()
        if Cache.WhatsNewUI then pcall(function() Cache.WhatsNewUI:Destroy() end) end
        Cache.WhatsNewUI = nil
    end

    -- BUILT FRESH EACH TIME IT OPENS, from the entries it is handed. It is shown at
    -- most once a load and on a button press, so there is nothing to keep painted, and
    -- a rebuild is what lets the same panel be the "new since" list and the history.
    function Cache.showWhatsNew(entries, mode)
        if Cache.WhatsNewUI then pcall(function() Cache.WhatsNewUI:Destroy() end) end
        local ui, frame = buildFrameBase("IVM_WhatsNew",
            UDim2.new(0, 380, 0, 0), UDim2.new(0.5, -190, 0.5, -210))
        frame.AutomaticSize = Enum.AutomaticSize.Y
        local titleBar = addTitleBar(frame, "What's New", C.bar)
        makedraggable(frame, titleBar)
        -- closing is dismissing: a player who closes it has read what they meant to,
        -- and a panel that came back after every close would be the thing they learn
        -- to resent rather than read
        local close = button(titleBar, "×", C.bar, UDim2.new(0, 28, 0, 24))
        close.AnchorPoint = Vector2.new(1, 0.5); close.Position = UDim2.new(1, -6, 0.5, 0)
        close.MouseButton1Click:Connect(dismiss)

        local body = Instance.new("Frame"); body.Name = "Body"
        body.BackgroundTransparency = 1; body.Position = UDim2.new(0, 0, 0, 35)
        body.Size = UDim2.new(1, 0, 0, 0); body.AutomaticSize = Enum.AutomaticSize.Y; body.Parent = frame
        local pad = Instance.new("UIPadding", body)
        pad.PaddingLeft = UDim.new(0, 12); pad.PaddingRight = UDim.new(0, 12)
        pad.PaddingTop = UDim.new(0, 8); pad.PaddingBottom = UDim.new(0, 12)
        local layout = Instance.new("UIListLayout", body)
        layout.SortOrder = Enum.SortOrder.LayoutOrder; layout.Padding = UDim.new(0, 8)

        lbl(body, Cache.changelogSubtitle(mode, #entries), 12, C.dim, false, 1)

        -- the entries scroll inside a box sized to them (up to a cap), so a one-line
        -- welcome is small and a long history stays on the screen
        local scroll = Instance.new("ScrollingFrame"); scroll.Name = "Entries"
        scroll.BackgroundTransparency = 1; scroll.BorderSizePixel = 0
        scroll.Size = UDim2.new(1, 0, 0, Cache.changelogEstimateHeight(entries, 320))
        scroll.CanvasSize = UDim2.new(0, 0, 0, 0); scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
        scroll.ScrollBarThickness = 4; scroll.LayoutOrder = 2; scroll.Parent = body
        local sl = Instance.new("UIListLayout", scroll)
        sl.SortOrder = Enum.SortOrder.LayoutOrder; sl.Padding = UDim.new(0, 6)

        for i, e in ipairs(entries) do
            local card = Instance.new("Frame")
            card.BackgroundColor3 = C.card; card.BorderSizePixel = 0; card.LayoutOrder = i
            card.Size = UDim2.new(1, -8, 0, 0); card.AutomaticSize = Enum.AutomaticSize.Y; card.Parent = scroll
            Instance.new("UICorner", card).CornerRadius = UDim.new(0, 6)
            local cp = Instance.new("UIPadding", card)
            cp.PaddingLeft = UDim.new(0, 10); cp.PaddingRight = UDim.new(0, 10)
            cp.PaddingTop = UDim.new(0, 6); cp.PaddingBottom = UDim.new(0, 8)
            local cl = Instance.new("UIListLayout", card)
            cl.SortOrder = Enum.SortOrder.LayoutOrder; cl.Padding = UDim.new(0, 3)
            local heading, text = Cache.changelogFormat(e)
            lbl(card, heading, 13, C.head, true, 1)
            if text ~= "" then lbl(card, text, 12, C.text, false, 2) end
        end

        local ok = button(body, "Got it", C.ok, UDim2.new(1, 0, 0, 34), 3)
        ok.MouseButton1Click:Connect(dismiss)

        Cache.WhatsNewUI = ui
        return ui
    end

    -- ON LOAD: show what is unseen, once. Skipped on an executor that cannot write
    -- files -- 'Got it' could never be remembered there, and a welcome on every single
    -- load is noise; the Settings button still works for them.
    function Cache.checkWhatsNew()
        if not (writefile and readfile and isfile) then return false end
        local entries, mode = Cache.changelogUnseen(Cache.Changelog, Cache.readWhatsNewSeen())
        if #entries == 0 then return false end
        Cache.showWhatsNew(entries, mode)
        return true
    end

    -- A few seconds after the UI is up, not at once: the window's own intro and the
    -- load notifications arrive in the first seconds, and a panel on top of them is
    -- the one that gets closed unread. By now every part has run, so the premium
    -- entries (249) are registered too. task.delay is a no-op in the tests.
    task.delay(5, function()
        if State.IsCleaningUp then return end
        pcall(Cache.checkWhatsNew)
    end)

    SettingsTab:CreateSection("What's New")
    SettingsTab:CreateNote("What changed in recent updates. It opens by itself once after an update.")
    SettingsTab:CreateButton({ Name="Show What's New", Callback=function()
        local ok = pcall(Cache.showWhatsNew, Cache.changelogSorted(), "all")
        if not ok then
            Cache.notify({Title="What's New", Content="Couldn't build the panel on this executor.", Duration=6})
        end
    end})
end
-- ==== end of WHAT'S NEW ======================================================

-- the fishing board is premium only (208); in the trial the paint is a no-op
if not Cache.paintFishBoard then Cache.paintFishBoard = function() end end

-- visual updates
do
    local renderAccum = 0
    addconn(RunService.RenderStepped:Connect(function(dt)
        renderAccum += dt
        if renderAccum >= 0.033 then
            renderAccum = 0
            -- Skip all visual work when nothing visual is active. Each draw already
            -- early-returns internally, but this avoids paying 5 pcall+call dispatches
            -- every frame while the user isn't using any visual feature. The blueprint
            -- artifact checks keep teardown running for one more frame after a toggle-off.
            local anyVisual = State.CircleEnabled
                or State.SpecificBlockSelectionEnabled
                or State.BlueprintPreviewEnabled
                or State.VendingLabelsEnabled or State.ChestLabelsEnabled
                or State.BlueprintPos1 ~= nil
                or Cache.BlueprintPreviewContainer ~= nil
                or Cache.BlueprintRegionPart ~= nil
            if anyVisual then
                pcall(drawcircle)
                pcall(drawblueprintbox)
                pcall(drawspecificselection)
                pcall(renderblueprintpreview)
                pcall(renderlabels)
            end
        end
    end))
end

-- auto open and labels
addconn(RunService.Heartbeat:Connect(function(dt)
    State.LabelsAccum += dt
    if State.LabelsAccum >= 0.05 then
        State.LabelsAccum = 0
        if State.VendingLabelsEnabled then pcall(scanvendinglabels) end; if State.ChestLabelsEnabled then pcall(scanchestlabels) end
        -- the movement panel's facing readout. The rotation is set from four places
        -- besides its own buttons -- the aligner, a queue entry, a restored session,
        -- Reset -- so it is read here rather than written by each of them, and only
        -- while the panel is actually up.
        if State.ShowMovementUI and Cache.paintMovementRotation then pcall(Cache.paintMovementRotation) end
        -- and the "what is marked" line under the crop/cut buttons, for the same
        -- reason: the corners are set from an input handler over there, and the
        -- readout has to follow them rather than be written by each setter
        if Cache.paintMarkNote then pcall(Cache.paintMarkNote) end
        -- the fishing scoreboard, for the same reason again: its clock moves while the
        -- fishing loop is asleep waiting for a bite, so nothing in that loop is in a
        -- position to keep it current. It rebuilds its text at most once a second.
        if Cache.paintFishBoard then pcall(Cache.paintFishBoard) end
        -- the sign preview, repainted once per settled change rather than once per
        -- callback: a slider drag fires every frame, and forty redraws a second of a
        -- sign nobody has finished choosing is thirty-nine wasted
        if Cache.SignPreviewDirty and State.ShowSignPreview and Cache.repaintSignPreview then
            Cache.SignPreviewDirty = false
            pcall(Cache.repaintSignPreview)
        end
        if Cache.QRPreviewDirty and State.ShowQRPreview and Cache.repaintQRPreview then
            Cache.QRPreviewDirty = false
            pcall(Cache.repaintQRPreview)
        end
    end
    if State.OpeningEnabled then
        State.LastOpeningTime += dt
        if State.LastOpeningTime >= Delay.OpeningSpeed then State.LastOpeningTime = 0; Cache.fireInvoke(Remotes.ClientRequest22, {}) end
    end
end))

-- protect vends (alt+click): toggle a nearby vend into the whitelist so Set Price/Mode
-- skips it. Only affects vending-machine models that the scanner has cached.
addconn(UserInputService.InputBegan:Connect(function(input)
    if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
    if not State.VendWhitelistMode then return end
    -- selection takes priority: if Select Vends Mode is also on, don't ALSO protect the
    -- same click (that produced a vend both selected AND skipped-as-protected)
    if State.SelectionModeEnabled then return end
    if not (UserInputService:IsKeyDown(Enum.KeyCode.LeftAlt) or UserInputService:IsKeyDown(Enum.KeyCode.RightAlt)) then return end
    local block = mouseblock(input.Position)
    if not (block and Cache.VendingMachines[block]) then return end
    Cache.VendWhitelist = Cache.VendWhitelist or {}
    Cache.VendWhitelistHL = Cache.VendWhitelistHL or {}
    if Cache.VendWhitelist[block] then
        Cache.VendWhitelist[block] = nil
        if Cache.VendWhitelistHL[block] then freehighlight(Cache.VendWhitelistHL[block]); Cache.VendWhitelistHL[block] = nil end
        Window:Notify({Title="Vend Unprotected", Content="This vend can be changed again.", Duration=2})
    else
        Cache.VendWhitelist[block] = true
        local hl = gethighlight()
        hl.Adornee = block
        hl.FillColor = Color3.fromRGB(60,200,120); hl.OutlineColor = Color3.fromRGB(120,255,170)
        hl.FillTransparency = 0.6; hl.OutlineTransparency = 0
        Cache.VendWhitelistHL[block] = hl
        Window:Notify({Title="Vend Protected", Content="Set Price/Mode will skip this vend.", Duration=2})
    end
end))

-- vend selection (alt+click): toggle a nearby vend into the action set so Set Price/Mode,
-- deposit, withdraw, restock, etc. hit ONLY the selected vends. Stores the highlight as
-- the value (getvendings checks truthiness; cleanup destroys them).
addconn(UserInputService.InputBegan:Connect(function(input)
    if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
    if not State.SelectionModeEnabled then return end
    if not (UserInputService:IsKeyDown(Enum.KeyCode.LeftAlt) or UserInputService:IsKeyDown(Enum.KeyCode.RightAlt)) then return end
    local block = mouseblock(input.Position)
    if not (block and Cache.VendingMachines[block]) then return end
    if Cache.toggleVendSelected(block) then
        Window:Notify({Title="Vend Selected", Content="Actions will target this vend.", Duration=2})
    else
        Window:Notify({Title="Vend Deselected", Content="Removed from the target set.", Duration=2})
    end
end))

-- block selection (alt+click)
-- Builds without the blueprint transform tools have no preview marker; the corners
-- then come from standing blocks only, exactly as they always did.
if not Cache.previewCellUnderCursor then Cache.previewCellUnderCursor = function() end end
if not Cache.paintMarkNote then Cache.paintMarkNote = function() end end
addconn(UserInputService.InputBegan:Connect(function(input)
    if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
    if not (UserInputService:IsKeyDown(Enum.KeyCode.LeftAlt) or UserInputService:IsKeyDown(Enum.KeyCode.RightAlt)) then return end
    local block = mouseblock(input.Position)
    if State.BlueprintSelectionMode then
        -- THE PREVIEW GETS THE CLICK FIRST. Its parts are CanQuery=false, so a click
        -- aimed at a ghost passes straight through it and lands on whatever is behind
        -- -- the ground under the build -- and the corner you marked was one you were
        -- not looking at. Spawned because working out where the build's cells are is
        -- a walk of the blueprint, and an input handler must not block on that.
        task.spawn(function()
            local pos = Cache.previewCellUnderCursor(input.Position)
            if not pos and block then
                if block:IsA("Model") and block.PrimaryPart then pos = block.PrimaryPart.Position
                elseif block:IsA("BasePart") then pos = block.Position end
            end
            if not pos then return end
            if not State.BlueprintPos1 or State.BlueprintPos2 then
                State.BlueprintPos1 = pos; State.BlueprintPos2 = nil
                Window:Notify({Title="Selection", Content="Position 1 set. Alt+Click for position 2.", Duration=2})
            else
                State.BlueprintPos2 = pos
                Window:Notify({Title="Selection", Content="Selection complete.", Duration=2})
            end
        end)
        return
    end
    if not block then return end
    if State.SpecificBlockSelectionEnabled then
        -- don't let the block-remove selection grab a vend/chest/opener: if Select Vends
        -- Mode is also on, one Alt+Click would queue the vend for destruction by the
        -- block remover. These aren't plain build blocks anyway.
        if Cache.VendingMachines[block] or Cache.Chests[block] or Cache.Openers[block] then return end
        -- ...and never bedrock. Cache.selectRegionBlocks already excludes it, for the
        -- reason that applies just as much here: bedrock cannot be broken, and
        -- removeSelectedBlocks only drops an entry once the block is gone -- so one
        -- stray click on the island floor leaves an entry that never clears, "Auto
        -- Remove Selected (loop)" never finishes, and it burns shared BlockHit slots
        -- for the rest of the session (starving Block Nuke and Tree Aura with it).
        if block.Name == "bedrock" then
            Cache.notify({Title="Selection", Content="That's bedrock — unbreakable, so it's not selectable. The remove loop would never finish with it in the set.", Duration=6})
            return
        end
        if Cache.SpecificSelection[block] then
            local data = Cache.SpecificSelection[block]
            if data.highlight then data.highlight:Destroy() end
            Cache.SpecificSelection[block] = nil
        else
            Cache.SpecificSelection[block] = {}
        end
        return
    end
end))

if not _G.IVM_Instances then _G.IVM_Instances = {} end
local MyInstanceId = HttpService:GenerateGUID(false)

-- ==================== UPDATE NOTICE (Settings) ====================
-- Tells the player when a newer build of their tier is out. In every tier.
--
-- WHERE IT ASKS: Cache.VERSION_URL (031), which build.py fills in per tier from the
-- constants at the top of build.py -- a small PUBLIC JSON the owner hosts, e.g. a gist:
--   { "premium": {"version":"2026.09.27-abc1234","notes":"...","loader":"optional"},
--     "main":    {...} }
-- release.yml writes that file as dist/version.json on every run. Empty URL = the
-- feature is idle and says so.
--
-- WHAT IT DOES WITH THE ANSWER: compares the entry for Cache.BUILD_BRANCH with
-- Cache.BUILD_VERSION (the decision is 095_version_check.lua, tested) and shows a
-- notification. NOTHING DOWNLOADED IS EVER RUN: the file is decoded as JSON and read as
-- text; updating is the player re-running their own loader.
--
-- WHEN: once, ~8 seconds after load (after the window intro and What's New at 5s), if
-- 'Check For Updates On Load' is on -- and only when there IS an update, so a normal
-- load stays quiet. 'Check For Updates' asks now and always answers.
do
    -- game:HttpGet first (every executor has it); the executor's request function as a
    -- fallback, looked up with rawget so the globals checker has nothing to object to
    local function fetch(url)
        local ok, body = pcall(function() return game:HttpGet(url) end)
        if ok and type(body) == "string" and body ~= "" then return body end
        local envs = {}
        pcall(function() envs[#envs + 1] = getfenv(0) end)
        pcall(function() if type(getgenv) == "function" then envs[#envs + 1] = getgenv() end end)
        for _, env in ipairs(envs) do
            local req
            pcall(function()
                req = rawget(env, "request") or rawget(env, "http_request")
                local syn = rawget(env, "syn")
                if not req and type(syn) == "table" then req = syn.request end
            end)
            if type(req) == "function" then
                local okR, res = pcall(req, { Url = url, Method = "GET" })
                if okR and type(res) == "table" and type(res.Body) == "string"
                    and (res.StatusCode == nil or res.StatusCode == 200) then
                    return res.Body
                end
            end
        end
        return nil
    end

    function Cache.checkForUpdates()
        local url = Cache.VERSION_URL
        local data
        if type(url) == "string" and url ~= "" and Cache.BUILD_VERSION ~= "dev" then
            local body = fetch(url)
            if body then
                local ok, decoded = pcall(function() return game:GetService("HttpService"):JSONDecode(body) end)
                data = ok and decoded or false   -- false: fetched, but not JSON
            end
        end
        return Cache.versionVerdict(data, Cache.BUILD_BRANCH, Cache.BUILD_VERSION, url)
    end

    local function show(v, quietUnlessUpdate)
        if quietUnlessUpdate and v.status ~= "update" then return end
        Cache.notify({ Title = v.status == "update" and "Update Available" or "Check For Updates",
            Content = v.message, Duration = v.status == "update" and 15 or 6 })
    end

    task.delay(8, function()
        if State.IsCleaningUp or not Settings.CheckUpdatesOnLoad then return end
        local ok, v = pcall(Cache.checkForUpdates)
        if ok and v then show(v, true) end
    end)

    SettingsTab:CreateSection("Updates")
    SettingsTab:CreateNote("This build: " .. tostring(Cache.BUILD_BRANCH) .. " " .. tostring(Cache.BUILD_VERSION)
        .. ". Checks whether a newer version is out and tells you; to update, re-run your loader. Nothing is downloaded or run by itself.")
    SettingsTab:CreateButton({ Name = "Check For Updates", Callback = function()
        task.spawn(function()
            local ok, v = pcall(Cache.checkForUpdates)
            if ok and v then show(v, false)
            else Cache.notify({ Title = "Check For Updates", Content = "The check failed on this executor.", Duration = 6 }) end
        end)
    end })
    SettingsTab:CreateToggle({ Name = "Check For Updates On Load", CurrentValue = Settings.CheckUpdatesOnLoad ~= false, Callback = function(on)
        Settings.CheckUpdatesOnLoad = on == true
        pcall(Cache.saveHubConfig)
    end })
end
-- ==== end of UPDATE NOTICE ======================================================
-- ==================== SELF-TEST (in game) ====================
-- 'Run Self-Test' on the Settings tab: one press asks the game and the executor what
-- the tests outside the game cannot -- do the remotes exist, is your island found,
-- can your chests be read, which executor functions are there, will a slot switch
-- come back -- and writes the answers to Islands trading hub/self_test.txt and the
-- Required Blocks panel. READ-ONLY: it fires no remote and changes nothing, so it is
-- safe to press at any time, mid-build included. The report layout is 036.
do
    local FILE = "Islands trading hub/self_test.txt"

    local function check(results, name, fn)
        local ok, status, detail = pcall(fn)
        if not ok then
            results[#results + 1] = { name = name, status = "fail", detail = "the check itself errored: " .. tostring(status) }
        else
            results[#results + 1] = { name = name, status = status or "info", detail = detail }
        end
    end

    local function execFn(name)
        local env = getfenv(0)
        local v = rawget(env, name)
        if v == nil and type(getgenv) == "function" then
            pcall(function() v = rawget(getgenv(), name) end)
        end
        return type(v) == "function" and v or nil
    end

    function Cache.runSelfTest()
        local R = {}

        check(R, "Build", function()
            return "info", tostring(Cache.BUILD_BRANCH or "?") .. " " .. tostring(Cache.BUILD_VERSION or "dev")
        end)
        check(R, "Executor", function()
            local f = execFn("identifyexecutor") or execFn("getexecutorname")
            local n, v = "unknown", ""
            if f then local a, b = f(); n = tostring(a or "unknown"); v = b and (" " .. tostring(b)) or "" end
            return "info", n .. v
        end)
        check(R, "Your character", function()
            local ch = LocalPlayer.Character
            local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
            if not hrp then return "fail", "no HumanoidRootPart: respawn and run again" end
            return "ok", "found"
        end)
        check(R, "Your island", function()
            local isl = Cache.myOwnedIslandModel and Cache.myOwnedIslandModel()
            if not isl then return "fail", "not found: go to your own island (building, restock and chests need it)" end
            local blocks = isl:FindFirstChild("Blocks")
            local n = blocks and #blocks:GetChildren() or 0
            return "ok", string.format("%s, %d blocks loaded", isl.Name, n)
        end)
        check(R, "Block templates", function()
            local f = ReplicatedStorage:FindFirstChild("Blocks")
            local n = f and #f:GetChildren() or 0
            if n == 0 then return "fail", "ReplicatedStorage.Blocks is empty: previews, colours and pixel art cannot work" end
            return "ok", n .. " block types"
        end)
        check(R, "Game remotes", function()
            local total, missing = 0, {}
            for name, r in pairs(Remotes) do
                total += 1
                if typeof(r) ~= "Instance" or not (r:IsA("RemoteEvent") or r:IsA("RemoteFunction")) then
                    missing[#missing + 1] = name
                end
            end
            table.sort(missing)
            if #missing == 0 then return "ok", "all " .. total .. " found" end
            -- the feature each missing one carries (036), so the line says what stops
            -- working and not only which obfuscated path moved
            local h = Cache.remoteHealth(Remotes, nil, function(r)
                return typeof(r) == "Instance" and (r:IsA("RemoteEvent") or r:IsA("RemoteFunction"))
            end)
            local dark = Cache.remoteHealthText(h)
            return (#missing > total / 2) and "fail" or "warn",
                string.format("%d of %d missing (the game may have renamed them): %s%s", #missing, total,
                    table.concat(missing, ", ", 1, math.min(#missing, 8)) .. (#missing > 8 and ", ..." or ""),
                    dark ~= "" and (" -- affects " .. dark) or "")
        end)
        check(R, "Place remote", function()
            local rem, meth = Cache.placeRemote()
            if not rem then return "fail", "not found: Auto Build cannot place" end
            return "ok", tostring(meth)
        end)
        check(R, "Vending machines", function()
            local n = 0
            for _ in pairs(Cache.VendingMachines or {}) do n += 1 end
            if n == 0 then return "warn", "none scanned yet (they are found as you move around; open the Vending tab)" end
            return "ok", n .. " seen"
        end)
        check(R, "Chests on your island", function()
            local isl = Cache.myOwnedIslandModel and Cache.myOwnedIslandModel()
            if not isl then return "warn", "your island was not found, so chests were not checked" end
            local seen, readable = 0, 0
            for chest in pairs(Cache.Chests or {}) do
                if typeof(chest) == "Instance" and chest.Parent and chest:IsDescendantOf(isl) then
                    seen += 1
                    if (Cache.chestStacks(chest)) then readable += 1 end
                end
            end
            if seen == 0 then return "warn", "none seen on your island yet (walk past them, or none placed)" end
            if readable == 0 then return "warn", seen .. " seen, but none shows its contents (restock from chests and the materials check cannot see them)" end
            return "ok", string.format("%d seen, %d show their contents", seen, readable)
        end)
        check(R, "Files (writefile / readfile)", function()
            if not (writefile and readfile and isfile) then return "fail", "missing: nothing can be saved (blueprints, settings, progress)" end
            local probe = "Islands trading hub/.selftest_probe"
            local ok = pcall(function() writefile(probe, "ok") end)
            local back = ok and pcall(readfile, probe) and readfile(probe) == "ok"
            if delfile then pcall(delfile, probe) end
            if not back then return "fail", "writing a file did not read back" end
            return "ok", "write and read back"
        end)
        check(R, "listfiles / makefolder", function()
            if not (listfiles and makefolder and isfolder) then return "warn", "missing: the Blueprint Library and folder lists cannot work" end
            return "ok", "present"
        end)
        check(R, "queue_on_teleport", function()
            local q = Cache.findQueueTeleport and Cache.findQueueTeleport()
            if not q then return "warn", "missing: slot switches and rejoins need the Resume Helper (Queue tab)" end
            return "ok", "present"
        end)
        check(R, "Resume after a slot switch", function()
            if not Cache.resumeReport then return "info", "not part of this build" end
            local ok, verdict = Cache.resumeReport()
            return ok and "ok" or "warn", verdict
        end)
        check(R, "Saved queues (queues.json)", function()
            if not Cache.readSavedQueues then return "info", "not part of this build" end
            if not (isfile and readfile) then return "warn", "no file API: queues cannot be saved or loaded" end
            if not isfile(Cache.SAVED_QUEUES_FILE) then return "ok", "none saved yet (the file appears on the first save)" end
            local ok, data = pcall(function() return HttpService:JSONDecode(readfile(Cache.SAVED_QUEUES_FILE)) end)
            if not ok or type(data) ~= "table" then return "warn", "queues.json exists but cannot be read; saving over it will replace it" end
            local n = 0
            for _ in pairs(data) do n += 1 end
            return "ok", n .. " saved queue(s)"
        end)
        check(R, "Tabs", function()
            -- the self-creating tabs: a part that failed to load leaves its tab out,
            -- and a missing sidebar entry is the first thing an owner notices last
            local missing = {}
            if not Cache.QueueTab then missing[#missing + 1] = "Queue" end
            if not Cache.MarketTab then missing[#missing + 1] = "Market" end
            if #missing > 0 then return "fail", table.concat(missing, ", ") .. " did not build: the part that creates it has broken" end
            -- (the admin-only Debug tab is deliberately not asked for here: naming a
            -- cut part's symbol in a kept part is what the tier check exists to stop)
            return "ok", "Queue and Market built"
        end)
        check(R, "Loader line", function()
            local set = false
            pcall(function() set = type(getgenv) == "function" and type(getgenv().ISLANDS_HUB_LOADER) == "string" end)
            if set then return "ok", "ISLANDS_HUB_LOADER is set (a rejoin reloads through your loader)" end
            return "warn", "ISLANDS_HUB_LOADER is not set: a rejoin reloads from the repository URL, which fails if it is private"
        end)
        check(R, "HTTP requests", function()
            local syn = rawget(getfenv(0), "syn")
            local f = execFn("request") or execFn("http_request")
                or (type(syn) == "table" and type(syn.request) == "function" and syn.request) or nil
            if not f then return "warn", "no request function: Discord messages cannot be sent" end
            return "ok", "present"
        end)
        check(R, "Clipboard", function()
            if execFn("setclipboard") or execFn("toclipboard") then return "ok", "present" end
            return "warn", "missing: share codes are saved to a file instead"
        end)
        check(R, "Remote spy (hookmetamethod)", function()
            if execFn("hookmetamethod") and execFn("getnamecallmethod") then return "ok", "present" end
            return "warn", "missing: the Record buttons (slot switch, upgrades, machine inserts) cannot learn a call"
        end)
        check(R, "UI parent", function()
            if execFn("gethui") then return "ok", "gethui" end
            return "info", "CoreGui (no gethui)"
        end)
        check(R, "Frame rate", function()
            local frames, t0 = 0, os.clock()
            local conn = RunService.Heartbeat:Connect(function() frames += 1 end)
            task.wait(1)
            conn:Disconnect()
            local fps = frames / math.max(0.001, os.clock() - t0)
            if fps < 20 then
                return "warn", string.format("%.0f fps -- low: the Original engine and the farms run slower at a low frame rate", fps)
            end
            return "ok", string.format("%.0f fps", fps)
        end)
        check(R, "Ping", function()
            local p
            pcall(function() p = LocalPlayer:GetNetworkPing() end)
            if type(p) ~= "number" then return "info", "not readable" end
            local ms = p * 1000
            if ms > 300 then return "warn", string.format("%.0f ms -- high: every placement waits on it", ms) end
            return "ok", string.format("%.0f ms", ms)
        end)
        return R
    end

    SettingsTab:CreateSection("Self-Test")
    SettingsTab:CreateNote("Checks what only the game can answer: remotes, your island, chests, executor functions, whether a slot switch comes back, frame rate and ping. Read-only -- safe at any time. The report goes to self_test.txt; attach it to a bug report.")
    SettingsTab:CreateButton({ Name = "Run Self-Test", Callback = function()
        task.spawn(function()
            Window:Notify({ Title = "Self-Test", Content = "Checking (about a second)...", Duration = 3 })
            local results = Cache.runSelfTest()
            local lines = Cache.selfTestLines(results, "SELF-TEST -- " .. os.date("%Y-%m-%d %H:%M"))
            local text = table.concat(lines, "\n")
            Cache.SelfTestLast = text
            if writefile then pcall(writefile, FILE, text) end
            -- the Required Blocks panel is the script's one scrolling text box
            pcall(Cache.showRequiredBlocks, text)
            Window:Notify({ Title = "Self-Test", Content = Cache.selfTestVerdict(results) .. " Saved to " .. FILE .. ".", Duration = 10 })
        end)
    end })
end
-- THE REMOTES THAT WERE NOT THERE, said once, shortly after load (030 only records
-- them: it runs before there is a window to say anything in). A feature whose remote
-- is gone fails quietly otherwise, and "quietly" is how a renamed remote turns into
-- a week of "X is broken" reports.
task.delay(8, function()
    if State.IsCleaningUp or #MissingRemotes == 0 then return end
    local shown = {}
    for i = 1, math.min(4, #MissingRemotes) do shown[i] = tostring(MissingRemotes[i]):match("[^/]+$") end
    -- which features go dark (036): the word the owner can act on
    local dark = Cache.remoteHealthText(Cache.remoteHealth(Remotes))
    Cache.notify({Title="Game Remotes Missing", Content=string.format(
        "%d game remote(s) the script expects could not be found (%s%s). The game has probably renamed them in an update; %s will not work until the script is updated. Press 'Check For Updates', and 'Run Self-Test' lists them all.",
        #MissingRemotes, table.concat(shown, ", "), #MissingRemotes > 4 and ", …" or "",
        dark ~= "" and dark or "the features that use them"), Duration=20})
end)
-- ==================== END SELF-TEST (in game) ====================
-- ==================== NOTIFICATION HISTORY (the panel) ====================
-- Every notification, kept: the pure log is 051 (folding repeats, the cap, "3m ago").
--
-- ONE PLACE SEES THEM ALL. Messages reach the screen two ways -- Cache.notify (032)
-- and Window:Notify called directly, hundreds of times over -- and both end in the
-- window's own Notify. Wrapping that one function records every message without
-- touching a single caller, and records it BEFORE showing it, so a notify that errors
-- on the way to the screen is still in the history. Messages from before this part
-- loaded (the first second of a load) are the only ones it cannot see.
--
-- 247's bug report wraps the same function for its own ring, and that is on purpose:
-- it clips and redacts names for a file that may be handed to someone, while this is
-- the player's own readable history with repeats folded. Each wraps the one before,
-- so neither counts the other twice. Loading after 082 and 247, this is the outermost
-- wrapper: a message 082's quiet-build filter keeps off the screen is still recorded.
--
-- Inside one do-block: this part takes none of the main chunk's 200 registers.
do
    Cache.NotifyLog = Cache.NotifyLog or {}
    local repaint            -- forward: the panel, when it is open
    local pending = false

    if Window and type(Window.Notify) == "function" and not Cache.NotifyWrapped then
        Cache.NotifyWrapped = true
        local orig = Window.Notify
        Window.Notify = function(self, props, ...)
            pcall(function()
                if type(props) == "table" then
                    Cache.notifLogAdd(Cache.NotifyLog, props.Title, props.Content, os.time())
                    -- a burst of messages repaints once, on the next frame
                    if repaint and not pending then
                        pending = true
                        task.defer(function() pending = false; if repaint then repaint() end end)
                    end
                end
            end)
            return orig(self, props, ...)
        end
    end

    local function copyText(text)
        local env = getfenv(0)
        local syn = rawget(env, "syn")
        for _, fn in ipairs({ rawget(env, "setclipboard"), rawget(env, "toclipboard"),
                              type(syn) == "table" and syn.write_clipboard or nil }) do
            if type(fn) == "function" and pcall(fn, text) then return true end
        end
        return false
    end

    local function label(parent, text, size, bold, colour)
        local l = Instance.new("TextLabel")
        l.BackgroundTransparency = 1; l.Text = text; l.TextSize = size
        l.Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham
        l.TextColor3 = colour; l.TextXAlignment = Enum.TextXAlignment.Left
        l.TextYAlignment = Enum.TextYAlignment.Top; l.TextWrapped = true
        l.Parent = parent
        return l
    end

    local function build()
        if Cache.NotifyHistoryUI then pcall(function() Cache.NotifyHistoryUI:Destroy() end) end
        local W, H = 420, 470
        local ui, frame = buildFrameBase("IVM_NotifyHistory", UDim2.new(0, W, 0, H), UDim2.new(0.5, -W / 2, 0.5, -H / 2))
        Cache.NotifyHistoryUI = ui
        local bar = addTitleBar(frame, "Notifications", Color3.fromRGB(35, 35, 42), "Notification History")
        makedraggable(frame, bar)

        local list = Instance.new("ScrollingFrame")
        list.Position = UDim2.new(0, 10, 0, 44); list.Size = UDim2.new(1, -20, 1, -44 - 46)
        list.BackgroundTransparency = 1; list.BorderSizePixel = 0
        list.ScrollBarThickness = 4; list.ScrollBarImageColor3 = Color3.fromRGB(70, 70, 80)
        list.AutomaticCanvasSize = Enum.AutomaticSize.Y; list.CanvasSize = UDim2.new(0, 0, 0, 0)
        list.Parent = frame
        local lay = Instance.new("UIListLayout"); lay.Padding = UDim.new(0, 6)
        lay.SortOrder = Enum.SortOrder.LayoutOrder; lay.Parent = list

        local function button(text, x, w)
            local b = Instance.new("TextButton")
            b.Size = UDim2.new(0, w, 0, 28); b.Position = UDim2.new(0, x, 1, -38)
            b.BackgroundColor3 = Color3.fromRGB(45, 45, 55); b.BorderSizePixel = 0
            b.Text = text; b.TextColor3 = Color3.fromRGB(230, 230, 230)
            b.Font = Enum.Font.GothamMedium; b.TextSize = 12; b.AutoButtonColor = true
            b.Parent = frame
            Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
            return b
        end
        local copy = button("Copy All", 10, 100)
        local clear = button("Clear", 118, 80)
        local note = label(frame, "", 11, false, Color3.fromRGB(150, 150, 160))
        note.Position = UDim2.new(0, 210, 1, -38); note.Size = UDim2.new(1, -220, 0, 28)
        note.TextYAlignment = Enum.TextYAlignment.Center; note.TextXAlignment = Enum.TextXAlignment.Right

        repaint = function()
            if not (ui and ui.Parent) then repaint = nil; return end
            for _, c in ipairs(list:GetChildren()) do
                if c:IsA("GuiObject") then c:Destroy() end
            end
            local now = os.time()
            local log = Cache.NotifyLog
            note.Text = #log == 0 and "" or string.format("%d message%s, newest first", #log, #log == 1 and "" or "s")
            if #log == 0 then
                local l = label(list, "Nothing yet. Every message the hub shows from now on is kept here, so one you missed can still be read.", 12, false, Color3.fromRGB(150, 150, 160))
                l.Size = UDim2.new(1, -8, 0, 40)
                return
            end
            for i, e in ipairs(log) do
                local row = Instance.new("Frame")
                row.Size = UDim2.new(1, -6, 0, 0); row.AutomaticSize = Enum.AutomaticSize.Y
                row.BackgroundColor3 = Color3.fromRGB(28, 28, 34); row.BorderSizePixel = 0
                row.LayoutOrder = i; row.Parent = list
                Instance.new("UICorner", row).CornerRadius = UDim.new(0, 8)
                local pad = Instance.new("UIPadding")
                pad.PaddingLeft, pad.PaddingRight = UDim.new(0, 10), UDim.new(0, 10)
                pad.PaddingTop, pad.PaddingBottom = UDim.new(0, 8), UDim.new(0, 8)
                pad.Parent = row
                local inner = Instance.new("UIListLayout"); inner.Padding = UDim.new(0, 3)
                inner.SortOrder = Enum.SortOrder.LayoutOrder; inner.Parent = row

                local head = Instance.new("Frame")
                head.Size = UDim2.new(1, 0, 0, 16); head.BackgroundTransparency = 1
                head.LayoutOrder = 1; head.Parent = row
                local title = label(head, (e.title ~= "" and e.title or "Message")
                    .. ((e.count or 1) > 1 and ("  ×" .. e.count) or ""), 13, true, Color3.fromRGB(235, 235, 235))
                title.Size = UDim2.new(1, -70, 1, 0); title.TextTruncate = Enum.TextTruncate.AtEnd
                title.TextWrapped = false
                local ago = label(head, Cache.notifAgo(now, e.last or e.t), 11, false, Color3.fromRGB(110, 110, 120))
                ago.Size = UDim2.new(0, 70, 1, 0); ago.Position = UDim2.new(1, -70, 0, 0)
                ago.TextXAlignment = Enum.TextXAlignment.Right
                if e.content ~= "" then
                    local body = label(row, e.content, 12, false, Color3.fromRGB(200, 200, 200))
                    body.Size = UDim2.new(1, 0, 0, 0); body.AutomaticSize = Enum.AutomaticSize.Y
                    body.LayoutOrder = 2
                end
            end
        end

        copy.MouseButton1Click:Connect(function()
            local text = Cache.notifLogText(Cache.NotifyLog, os.time())
            if text == "" then note.Text = "Nothing to copy yet."
            elseif copyText(text) then note.Text = "Copied to your clipboard."
            else note.Text = "Your executor has no clipboard." end
        end)
        clear.MouseButton1Click:Connect(function()
            for i = #Cache.NotifyLog, 1, -1 do Cache.NotifyLog[i] = nil end
            repaint()
        end)
        repaint()
        -- "3m ago" goes stale on a panel left open, and a quiet minute brings no new
        -- message to repaint it -- so every half minute, for as long as THIS panel is up
        -- (a rebuilt or closed one has no parent, and the loop ends with it)
        addloop(task.spawn(function()
            while ui.Parent do
                task.wait(30)
                if ui.Parent and repaint then pcall(repaint) end
            end
        end))
    end

    SettingsTab:CreateSection("Notification History")
    SettingsTab:CreateNote("Messages only stay on screen for a few seconds, and they are often the only explanation of why something stopped. The last 50 are kept here.")
    SettingsTab:CreateToggle({ Name="Notification History", CurrentValue=false, Callback=function(v)
        if v then
            local ok, err = pcall(build)
            if not ok then Cache.notify({Title="Notification History", Content="Could not open it: " .. tostring(err), Duration=8}) end
        else
            repaint = nil
            if Cache.NotifyHistoryUI then pcall(function() Cache.NotifyHistoryUI:Destroy() end) end
            Cache.NotifyHistoryUI = nil
        end
    end})
end
-- ==================== END NOTIFICATION HISTORY (the panel) ====================
-- ==================== AUTOMATIC ISLAND BACKUP ====================
-- 'Save Island' on a timer, into a folder of its own, keeping the last few copies --
-- and the way back: 'Load Backup For Repair' makes a backup the selected blueprint,
-- standing exactly where the island stood, so Repair Mode (194) can scan the damage
-- and put back what is missing. The rules (names, pruning, when a backup is refused)
-- are 052_island_backup.lua, pinned by tests/island_backup.test.lua.
--
-- WHY A FOLDER OF ITS OWN. Five copies of the island every couple of hours in the
-- Blueprints folder would be five cards in the library and five rows in Select
-- Blueprint that nobody means to build. A backup only becomes a blueprint when you
-- ask for it back.
--
-- WHERE IT STOOD. A backup is a Save Island, whose blocks are relative to the corner
-- of the island's lowest block. The file also keeps that corner in world space and the
-- island's own origin (Cache.islandBaseOrigin, the reference the Build Queue's resume
-- uses), so on another server -- where the island sits at other coordinates -- the
-- backup is shifted by the same amount and lands on the island, not next to it.
--
-- ONLY YOUR ISLAND. Save Island falls back to every island in the folder when it
-- cannot find yours; a backup does not -- a backup of the neighbours is not a backup.
--
-- Inside one do-block: this part takes none of the main chunk's 200 registers.
-- A FUNCTION, NOT A DO-BLOCK: a function body has its own 200 registers, and a
-- do-block's locals are the main chunk's while it is open. This part held one of
-- the four highest live-local peaks in the file (tools/live_registers.py), a
-- couple of dozen under the limit the executor refused 219 at; 219, 224 and 225
-- are arranged the same way.
function Cache.islandBackupUI()
    local TITLE = "Island Backup"
    local FOLDER = Cache.BACKUP_FOLDER
    local INDEX = FOLDER .. "/last.json"
    local running = false
    local gen = 0         -- one loop at a time: off-and-on again retires the old one
    local busy = false
    local backupDD
    local labelToName = {}
    local picked          -- the label the Backup dropdown shows

    local function say(text, secs)
        Window:Notify({ Title = TITLE, Content = text, Duration = secs or 6 })
    end
    local function canFiles() return writefile and readfile and isfile and isfolder and makefolder and listfiles end
    local function ensureFolder()
        if not isfolder("Islands trading hub") then makefolder("Islands trading hub") end
        if not isfolder(FOLDER) then makefolder(FOLDER) end
    end
    local function listBackups()
        if not canFiles() then return {} end
        local ok, files = pcall(function() ensureFolder(); return listfiles(FOLDER) end)
        return ok and Cache.backupList(files) or {}
    end
    local function readIndex()
        local d
        pcall(function() if isfile(INDEX) then d = HttpService:JSONDecode(readfile(INDEX)) end end)
        return type(d) == "table" and d or nil
    end

    local function refreshPicker(select)
        if not backupDD then return end
        labelToName = {}
        local opts = {}
        for _, b in ipairs(listBackups()) do
            local l = Cache.backupLabel(b)
            labelToName[l] = b.name; opts[#opts + 1] = l
        end
        if #opts == 0 then opts = { "No backups yet" } end
        local pick = opts[1]
        if select then
            for l, n in pairs(labelToName) do if n == select then pick = l end end
        end
        picked = pick     -- whether or not Refresh calls back, this is what it shows
        pcall(function() backupDD:Refresh(opts, pick) end)
    end

    -- one backup; force = the button (writes even after a big drop, and when unchanged)
    local function backupNow(force)
        if busy then return false, "busy" end
        if not canFiles() then return false, "Your executor cannot write files." end
        if not (Cache.buildIslandModel and Cache.buildIslandModel()) then
            return false, "Your own island was not found (stand on it, or wait for it to load)."
        end
        busy = true
        local ok, res, why, count = pcall(function()
            local blocks, originCF = Cache.scanIslandToBlueprint(1500)
            if not blocks then return nil, originCF end
            local sig = Cache.islandSignature(blocks)
            local last = readIndex()
            local go, reason = Cache.backupVerdict(#blocks, sig, last, force)
            if not go then return nil, reason, #blocks end
            local o = Cache.islandBaseOrigin and Cache.islandBaseOrigin()
            local name = Cache.backupName(os.date("*t"), #blocks)
            local encoded = HttpService:JSONEncode({ blocks = blocks, backup = {
                at = os.time(), count = #blocks, sig = sig,
                origin = { originCF.Position.X, originCF.Position.Y, originCF.Position.Z },
                islandOrigin = o and { o.X, o.Y, o.Z } or nil,
            } })
            ensureFolder()
            writefile(FOLDER .. "/" .. name .. ".json", encoded)
            writefile(INDEX, HttpService:JSONEncode({ at = os.time(), count = #blocks, sig = sig, name = name }))
            -- rotate, sparing the biggest (052)
            local dropped = 0
            if delfile then
                for _, n in ipairs(Cache.backupPrune(listBackups(), Settings.IslandBackupKeep)) do
                    if pcall(delfile, FOLDER .. "/" .. n .. ".json") then dropped = dropped + 1 end
                end
            end
            return name, #blocks, dropped
        end)
        busy = false
        if not ok then return false, "Backup failed: " .. tostring(res) end
        if not res then return false, why, count end
        refreshPicker(res)
        return true, res, why
    end
    Cache.islandBackupNow = backupNow

    local function explain(why, count)
        if why == "unchanged" then return nil end      -- quiet: nothing to say
        if why == "dropped" then
            local last = readIndex()
            return string.format("Not backed up: the island has %s blocks, the last backup had %s. That is damage or an island still loading, and backing it up would push out a good copy. Load the last backup and press 'Scan For Damage', or press 'Back Up Island Now' if you emptied it on purpose.",
                tostring(count or "?"), tostring(last and last.count or "?"))
        end
        if why == "empty" then return "Not backed up: no blocks were found on your island." end
        return why
    end

    ToolsTab:CreateSection("Automatic Island Backup")
    ToolsTab:CreateNote("Saves your whole island on a schedule into its own Backups folder and keeps the last few. A copy is skipped when nothing changed, or when a quarter of the island is suddenly gone — so damage never replaces a good backup. To undo damage: pick a backup, press 'Load Backup For Repair', then use Repair Mode on the Build tab.")

    ToolsTab:CreateToggle({ Name = "Automatic Island Backup", CurrentValue = false, Callback = function(v)
        running = v
        gen = gen + 1
        local mine = gen
        if not v then return end
        if not canFiles() then say("Your executor cannot write files, so there is nowhere to keep a backup.", 8); return end
        -- registered, so a teleport's cleanup and 'Unload Script' cancel it (260)
        addloop(task.spawn(function()
            local warned, tried = false, nil
            while running and mine == gen do
                local last = readIndex()
                -- due from the last WRITE or the last attempt, whichever is later: an
                -- unchanged or refused island is not rescanned every minute
                local since = math.max(tonumber(last and last.at) or 0, tried or 0)
                if Cache.backupDue(since > 0 and since or nil, os.time(), Settings.IslandBackupEvery) then
                    tried = os.time()
                    local ok, a, b = backupNow(false)
                    if ok then
                        say(string.format("Backed up %d blocks.", b or 0), 4)
                        warned = false
                    elseif a ~= "busy" then
                        -- a refused backup is said once, not every pass, until one succeeds
                        local text = explain(a, b)
                        if text and not warned then say(text, a == "dropped" and 20 or 8); warned = true end
                    end
                end
                for _ = 1, 60 do
                    if not running or mine ~= gen then break end
                    task.wait(1)
                end
            end
        end))
    end })

    ToolsTab:CreateSlider({ Name = "Back Up Every (minutes)", Step = 5, Range = { 5, 240 }, Increment = 5, Suffix = "m",
        CurrentValue = Settings.IslandBackupEvery, Callback = function(v)
            Settings.IslandBackupEvery = v
            if Cache.saveHubConfig then task.spawn(Cache.saveHubConfig) end
        end })
    ToolsTab:CreateSlider({ Name = "Backups To Keep", Step = 1, Range = { 1, 20 }, Increment = 1, Suffix = "",
        CurrentValue = Settings.IslandBackupKeep, Callback = function(v)
            Settings.IslandBackupKeep = v
            if Cache.saveHubConfig then task.spawn(Cache.saveHubConfig) end
        end })

    ToolsTab:CreateButton({ Name = "Back Up Island Now", Callback = function()
        say("Scanning your island…", 3)
        task.spawn(function()
            local ok, a, b = backupNow(true)
            if ok then say(string.format("Backed up %d blocks as “%s”.", b or 0, a), 6)
            elseif a == "busy" then say("A backup is already being written.", 4)
            else say(explain(a, b) or tostring(a), 8) end
        end)
    end })

    backupDD = ToolsTab:CreateDropdown({ Name = "Backup", Options = { "No backups yet" },
        CurrentOption = { "No backups yet" }, Callback = function(v)
            picked = type(v) == "table" and v[1] or v
        end })
    ToolsTab:CreateButton({ Name = "Refresh Backups", Callback = function() refreshPicker() end })

    -- the load, as a function: 'Load Backup For Repair' is it alone, 'Compare Island
    -- With Backup' is it followed by Repair Mode's scan (after(label) runs once the
    -- backup stands where the island stood; a backup with no position cannot be
    -- compared without a snap first, and the message says so)
    local function loadBackupForRepair(after)
        local label = picked
        local name = label and labelToName[label]
        if not name then say("Pick a backup first (press 'Refresh Backups' if the list is empty).", 6); return end
        task.spawn(function()
            local path = FOLDER .. "/" .. name .. ".json"
            local okR, text = pcall(readfile, path)
            if not okR or type(text) ~= "string" then say("Could not read that backup.", 6); return end
            local okD, data = pcall(function() return HttpService:JSONDecode(text) end)
            if not (okD and type(data) == "table" and type(data.blocks) == "table") then
                say("That backup is not readable.", 6); return
            end
            local okW = pcall(function()
                ensureBlueprintFolder(); writefile("Islands trading hub/Blueprints/" .. name .. ".json", text)
            end)
            if not okW then say("Could not copy it into the Blueprints folder.", 6); return end
            -- select it the way the generators do: the dropdown's own callback loads it
            State.SelectedBlueprint = name
            if BlueprintDD then BlueprintDD:Refresh(refreshblueprints(), name) end
            if Cache.LastLoadedBlueprint ~= name then loadblueprint(name) end
            -- and stand it where the island stood (shifted onto this server's island)
            local meta = type(data.backup) == "table" and data.backup or {}
            local o = meta.origin
            if type(o) == "table" and o[1] then
                local pos = Vector3.new(o[1], o[2], o[3])
                local io, now = meta.islandOrigin, Cache.islandBaseOrigin and Cache.islandBaseOrigin()
                if type(io) == "table" and io[1] and now then pos = pos + (now - Vector3.new(io[1], io[2], io[3])) end
                Cache.BlueprintAnchor = CFrame.new(pos)
                Cache.BlueprintAnchorLocked = true
                State.BlueprintPreviewOffset = Vector3.new(0, 0, 0)
                State.BlueprintPreviewRotationY = 0
                Cache.LastPreviewCFrame = nil
                if after then
                    after(label)
                else
                    say("Loaded “" .. label .. "” as the selected blueprint, standing where your island stood. Now press 'Scan For Damage' on the Build tab to see what is missing, then 'Repair'.", 14)
                end
            else
                say("Loaded “" .. label .. "” as the selected blueprint. It has no saved position, so line it up with 'Snap To Existing Build (search the island)' before 'Scan For Damage'.", 14)
            end
        end)
    end
    ToolsTab:CreateButton({ Name = "Load Backup For Repair", Callback = function() loadBackupForRepair(nil) end })
    -- WHAT CHANGED SINCE THAT BACKUP, one press: the backup becomes the blueprint,
    -- standing where the island stood, and Repair Mode's own scan (194) compares the
    -- island against it -- what went, what was swapped, what is extra -- and draws
    -- the damage map. Nothing is broken: that is 'Repair', a separate press.
    ToolsTab:CreateButton({ Name = "Compare Island With Backup", Callback = function()
        if not Cache.repairScanNow then say("Repair Mode is not in this build, so there is nothing to compare with.", 6); return end
        loadBackupForRepair(function(label)
            say("Comparing the island with “" .. label .. "”: the map shows what went (missing), what was swapped (wrong) and what is new (extra). To put it back, press 'Repair' on the Build tab.", 10)
            task.spawn(Cache.repairScanNow)
        end)
    end })

    -- ---- THE GRIEF CHECK: what changed while someone was here ----------------------
    -- Visitor Alert (224) already knows who is on the island; this listens to its hook.
    -- When the FIRST visitor arrives the island is read (and backed up, so there is a
    -- copy from just before they came); when the LAST one leaves it is read again and
    -- the two are compared in world space (052's islandDiff). One message per visit:
    -- what went, what was swapped, what was added -- and how to put it back. Anything
    -- you changed yourself meanwhile is in it too, and the message says so.
    local grief = { on = false, before = nil, names = {}, busy = false }
    local function snapshot()
        local blocks, originCF = Cache.scanIslandToBlueprint(1500)
        if not blocks then return nil end
        local p = originCF.Position
        return (Cache.islandKeyMap(blocks, p.X, p.Y, p.Z))
    end
    local function onEnter(who)
        local name = tostring(type(who) == "string" and who or (who and who.Name) or "someone")
        if not table.find(grief.names, name) then grief.names[#grief.names + 1] = name end
        if grief.before or grief.busy then return end   -- already watching this visit
        grief.busy = true
        task.spawn(function()
            local ok, map = pcall(snapshot)
            if ok and map then grief.before = map end
            -- a restore point from just before the visit (refused quietly when unchanged)
            pcall(backupNow, false)
            grief.busy = false
        end)
    end
    local function onLeave()
        if not grief.before then return end
        local here = Cache.visitorsNow and Cache.visitorsNow() or {}
        if next(here) ~= nil then return end           -- someone is still here
        local before, names = grief.before, grief.names
        grief.before, grief.names = nil, {}
        task.delay(3, function()
            local ok, after = pcall(snapshot)
            if not (ok and after) then return end
            local d = Cache.islandDiff(before, after)
            local who = table.concat(names, ", ")
            if d.unloaded then
                say("Could not check what " .. who .. " did: most of your island has not loaded here. Stand on it and press 'Scan For Damage' with your latest backup.", 12)
            elseif d.missing + d.replaced == 0 then
                say(who .. " left. Nothing on your island was broken or swapped" ..
                    (d.added > 0 and string.format(" (%d block%s added).", d.added, d.added == 1 and "" or "s") or "."), 6)
            else
                local parts = {}
                if d.missing > 0 then parts[#parts + 1] = string.format("%d block%s gone (%s)", d.missing,
                    d.missing == 1 and "" or "s", Cache.islandDiffTypes(d.missingByType, fixname, 3)) end
                if d.replaced > 0 then parts[#parts + 1] = string.format("%d swapped for another block", d.replaced) end
                if d.added > 0 then parts[#parts + 1] = string.format("%d added", d.added) end
                Window:Notify({ Title = "Island Changed During A Visit", Content = who .. " left — " .. table.concat(parts, ", ")
                    .. ". This counts your own changes too. To put it back: pick the backup from when they arrived in 'Backup', press 'Load Backup For Repair', then 'Scan For Damage' and 'Repair'.", Duration = 30 })
            end
        end)
    end
    do
        local prev = Cache.onVisitor
        Cache.onVisitor = function(event, who, secs)
            if type(prev) == "function" then pcall(prev, event, who, secs) end
            if not grief.on then return end
            if event == "enter" then onEnter(who) elseif event == "leave" then onLeave() end
        end
    end
    ToolsTab:CreateToggle({ Name = "Check For Damage When Visitors Leave", CurrentValue = false, Callback = function(v)
        grief.on = v and true or false
        if not v then grief.before, grief.names = nil, {} end
        if Cache.visitorWant then pcall(Cache.visitorWant, "griefcheck", v) end
    end })

    -- THE ONE AUTOMATION THAT MAY START ITSELF, because the owner asked: neither switch
    -- touches the island, and protection that has to be remembered every session is the
    -- protection that is off on the day it was needed. A little after load, so the
    -- island has streamed in (and a backup of a half-loaded island is refused anyway).
    ToolsTab:CreateToggle({ Name = "Start Island Protection On Load", CurrentValue = Settings.IslandProtectOnLoad == true,
        Callback = function(v)
            Settings.IslandProtectOnLoad = v and true or false
            if Cache.saveHubConfig then task.spawn(Cache.saveHubConfig) end
        end })
    if Settings.IslandProtectOnLoad then
        task.delay(15, function()
            local tf = Cache.ToggleFunctions or {}
            for _, n in ipairs({ "Automatic Island Backup", "Check For Damage When Visitors Leave" }) do
                if tf[n] then pcall(tf[n], true) end
            end
            say("Island protection is on: backups every " .. tostring(Settings.IslandBackupEvery) .. " minutes, and a damage check when visitors leave.", 6)
        end)
    end

    task.defer(refreshPicker)
end
Cache.islandBackupUI()
-- ==================== END AUTOMATIC ISLAND BACKUP ====================
-- ==================== COIN TRIPWIRE (Settings) ====================
-- One switch under the Danger Zone: while it is on, the pocket is read every few
-- seconds, and if it has lost more than the line the owner set inside the window the
-- owner set -- what the script itself deposited on purpose not counted -- every
-- automation is stopped the way 'Stop All' stops it, the owner is told, and the
-- tripwire switches itself OFF so the screen says it tripped. The arithmetic (what
-- is a loss, what is explained, once per arming) is 049_coin_tripwire.lua and is
-- tested; this part reads the balance, keeps the loop and talks. In every tier.
--
-- IT IS NOT AUTOMATION. 073's filter leaves it out of What's Running on purpose:
-- if Stop All stopped the tripwire too, the one time it fired would also be the last
-- time it was armed. Panic still switches it off, with everything else -- the owner
-- pressed Panic. The line and the window are tuning and persist (Settings, 031);
-- the switch starts off after inject like every switch.
--
-- Zero top-level locals: everything is in the do-block.
do
    local POLL = 5

    SettingsTab:CreateSection("Coin Tripwire")
    SettingsTab:CreateNote("If your pocket loses more than the line below inside the window below, every automation is stopped and you are told — a sniper pointed at the wrong price, a game update that turned a deposit into a purchase. Coins the script deposits on purpose (vend and ATM deposits) are not counted as a loss.")

    SettingsTab:CreateInput({ Name="Tripwire Line (coins)", PlaceholderText="1M, 500K, 2.5M",
        CurrentValue=shortnum(tonumber(Settings.TripwireMaxDrop) or Cache.TripwireDefaults.maxDrop), Callback=function(v)
        local n = parsenum(v)
        if n and n >= 1 then
            Settings.TripwireMaxDrop = math.floor(n)
            pcall(Cache.saveHubConfig)
        elseif tostring(v or "") ~= "" then
            Window:Notify({Title="Coin Tripwire", Content="Could not read '" .. tostring(v) .. "' as a coin count (try 500K or 1.5M). Kept " .. shortnum(Settings.TripwireMaxDrop) .. ".", Duration=5})
        end
    end})
    SettingsTab:CreateSlider({ Name="Tripwire Window (minutes)", Step=5, Range={5,240}, Increment=5, Suffix="m",
        CurrentValue=tonumber(Settings.TripwireWindowMin) or Cache.TripwireDefaults.windowMin, Callback=function(v)
        Settings.TripwireWindowMin = math.max(5, math.floor(tonumber(v) or Cache.TripwireDefaults.windowMin))
        pcall(Cache.saveHubConfig)
    end})

    -- what the trip does: 244's Stop All (the same rows, the same words), then the
    -- scheduled things that would switch a step straight back on (242's fallbacks
    -- make these no-ops in a build without them)
    local function trip(t)
        pcall(Cache.stopNightWatch, true)
        pcall(Cache.stopRoutine, true)
        pcall(Cache.stopFarmToShop, true)
        local stopped, stuck = {}, {}
        if Cache.stopAllAutomations then
            local ok, a, b = pcall(Cache.stopAllAutomations)
            if ok then stopped, stuck = a or {}, b or {} end
        end
        local msg = Cache.tripwireMessage(t, shortnum)
        if #stopped > 0 then msg = msg .. " Stopped: " .. table.concat(stopped, ", ") .. "." end
        if #stuck > 0 then msg = msg .. " Would not switch off: " .. table.concat(stuck, ", ") .. "." end
        Window:Notify({Title="Coin Tripwire — Stopped Everything", Content=msg, Duration=30})
        warn("[Coin Tripwire] " .. msg)
    end

    local toggle
    toggle = SettingsTab:CreateToggle({ Name="Coin Tripwire", CurrentValue=false, Callback=function(v)
        State.TripwireEnabled = v == true
        if not v then Cache.TripwireState = nil; return end
        local first = Cache.playerCoins()
        if first == nil then
            State.TripwireEnabled = false
            if toggle then pcall(function() toggle:Set(false, true) end) end
            Window:Notify({Title="Coin Tripwire", Content="Not armed: your coin balance could not be read here, so a loss could not be told from nothing.", Duration=8})
            return
        end
        Cache.TripwireState = Cache.tripwireNew()
        State.TripwireGen = (State.TripwireGen or 0) + 1
        local gen = State.TripwireGen
        Window:Notify({Title="Coin Tripwire", Content=string.format(
            "Armed at %s coins. If the pocket loses more than %s inside %d minutes, everything stops.",
            shortnum(first), shortnum(Settings.TripwireMaxDrop or Cache.TripwireDefaults.maxDrop),
            Settings.TripwireWindowMin or Cache.TripwireDefaults.windowMin), Duration=6})
        addloop(task.spawn(function()
            while State.TripwireEnabled and gen == State.TripwireGen and not State.IsCleaningUp do
                local st = Cache.TripwireState
                if not st then break end
                local ok, t = pcall(Cache.tripwireStep, st, os.clock(), Cache.playerCoins(), {
                    window = (tonumber(Settings.TripwireWindowMin) or Cache.TripwireDefaults.windowMin) * 60,
                    maxDrop = tonumber(Settings.TripwireMaxDrop) or Cache.TripwireDefaults.maxDrop,
                })
                if ok and t then
                    -- off first, so the trip's own Stop All cannot race a second trip
                    State.TripwireEnabled = false
                    Cache.TripwireState = nil
                    if toggle then pcall(function() toggle:Set(false, true) end) end
                    pcall(trip, t)
                    break
                elseif not ok then
                    warn("[Coin Tripwire] " .. tostring(t))
                end
                for _ = 1, POLL do
                    if not State.TripwireEnabled or gen ~= State.TripwireGen or State.IsCleaningUp then break end
                    task.wait(1)
                end
            end
        end))
    end})
end
-- ==================== END COIN TRIPWIRE (Settings) ====================
-- ==================== COLOURS (Settings) ====================
-- One switch: the state colours (053's palette -- the damage map's missing and extra,
-- the crop labels' ready and due) in a form that keeps every pair apart for
-- colour-blind eyes, on a blue/orange axis rather than red/green. It is a tuning
-- value, so it persists (Settings.ColourBlind, 031) and the switch is seeded from
-- what the loader restored. The painters read the palette at draw time, so the next
-- map or label changes without a reload. In every tier. Zero top-level locals.
do
    SettingsTab:CreateSection("Colours")
    SettingsTab:CreateNote("The damage map and the crop labels use red for missing and green for ready. If those two look alike to you, this switches them to blue and orange, which most colour-blind eyes tell apart.")
    SettingsTab:CreateToggle({ Name="Colour-Blind Colours (blue/orange)", CurrentValue=Settings.ColourBlind == true, Callback=function(v)
        Settings.ColourBlind = v == true
        pcall(Cache.saveHubConfig)
        Cache.notify({Title="Colours", Content=v and "Blue and orange from now on: the next damage map and the crop labels use them." or "Back to red and green.", Duration=4})
    end})
end
-- ==================== END COLOURS (Settings) ====================
-- ==================== SECTION: LIFECYCLE (cleanup, instance sweep, watchdog) ====================
-- The flower farm shuts itself down (flowerTeardown, FLOWER FARM ENGINE). The builds
-- that ship without the farm still call it, so they get a no-op to call.
if not Cache.flowerTeardown then Cache.flowerTeardown = function() end end
function DoFullCleanup()
    State.IsCleaningUp = true
    State.ItemLoopGen += 1; State.CoinLoopGen += 1; State.MaintGen += 1
    State.AtmLoopGen += 1; State.ChestLoopGen += 1; State.SniperGen += 1
    State.FarmGen += 1; State.SpawnBossGen += 1; State.HarvestGen += 1
    State.PlantGen += 1; State.EatGen += 1; State.PlowAuraGen += 1; State.UnplowAuraGen += 1
    State.TreeAuraGen += 1; State.BlueprintGen += 1; State.OpenerGen += 1
    State.BlockNukeGen += 1
    State.PlatformFarmGen = (State.PlatformFarmGen or 0) + 1
    State.PlatformFarmEnabled = false
    State.PermKeepGen = (State.PermKeepGen or 0) + 1
    State.PermKeepEnabled = false
    State.SettingsWatchGen = (State.SettingsWatchGen or 0) + 1
    State.SettingsWatch = false
    State.InboundAnnounce = false
    State.PermTrafficGen = (State.PermTrafficGen or 0) + 1
    State.PermTrafficOn = false
    if Cache.inboundStop then Cache.inboundStop() end
    -- the spy's hook outlives the script; a tap left set would keep recording into it
    Cache.RemoteTap = false
    State.RestockGen = (State.RestockGen or 0) + 1
    State.LowStockGen = (State.LowStockGen or 0) + 1; State.LowStockEnabled = false
    if Cache.stopNightWatch then pcall(Cache.stopNightWatch, true) end
    if Cache.stopRoutine then pcall(Cache.stopRoutine, true) end
    if Cache["stopDiscord"] then pcall(Cache["stopDiscord"]) end
    if Cache.stopFarmToShop then pcall(Cache.stopFarmToShop, true) end
    State.DynPriceEnabled = false; State.DynPriceGen = (State.DynPriceGen or 0) + 1
    State.ForecastWarnEnabled = false
    State.RemoveGen = (State.RemoveGen or 0) + 1
    State.RestockLoopEnabled = false; State.VendWhitelistMode = false
    State.RemoveLoopEnabled = false
    State.LoopItemEnabled = false; State.LoopCoinEnabled = false
    State.MaintenanceBypassEnabled = false; State.AtmLoopEnabled = false
    State.ChestLoopEnabled = false; State.VendingSniperEnabled = false
    State.AutoFarmEnabled = false; State.AutoSpawnBosses = false
    State.AutoHarvestEnabled = false; State.AutoPlantEnabled = false
    State.EatLoopEnabled = false; State.PlowAuraEnabled = false; State.UnplowAuraEnabled = false
    State.TreeAuraEnabled = false; State.AutoBlueprintEnabled = false
    State.BlueprintPreviewEnabled = false; State.OpeningEnabled = false
    State.ChestOpenerEnabled = false
    -- Block Nuke's switch is a file-level local in 034, not a State field: bumping its
    -- generation stops the loop, and State.BlockNukeEnabled (which this used to set)
    -- is read by nothing at all. Drive the toggle instead, which sets the real one.
    do local tf = Cache.ToggleFunctions and Cache.ToggleFunctions["Block Nuke"]
       if tf then pcall(tf, false) end end
    State.CircleEnabled = false; State.VendingLabelsEnabled = false
    State.ChestLabelsEnabled = false; State.ShowRequiredBlocksUI = false
    State.ShowFishBoard = false; State.CombatWalk = false
    -- SIX THAT THE HAND-WRITTEN LIST ABOVE HAD MISSED. Every one of them guards a
    -- `while State.X and gen == State.XGen` loop whose generation is not bumped up
    -- there either, so nothing stopped them: the queue runner, both chest loops, the
    -- rabbit farm, Auto Reprice and the totem upgrader all carried on against a
    -- torn-down script. A list of flags maintained by memory is the wrong shape for
    -- this, which is what the cancel below is for -- these are here so the UI switches
    -- read OFF too.
    State.BuildQueueEnabled = false; State.ChestWalkEnabled = false
    State.ChestWithdrawEnabled = false; State.PinkRabbitEnabled = false
    State.PriceBookAutoEnabled = false; State.AutoTotemUpgradeEnabled = false
    -- the farm's own unload, in the farm's part: its loop and its stats panel live on
    -- Cache, not State, and setting the State fields left the water loop and the
    -- flower picker running after a cleanup/re-inject -- two sweeps a second against a
    -- selection the same cleanup had just emptied. A build without the farm has no
    -- loop to stop and no panel to destroy, so it gets the no-op above.
    Cache.flowerTeardown()
    -- EVERY LOOP, NOT THE ONES SOMEONE REMEMBERED. addloop() has registered every
    -- background thread in Cache.Loops since the beginning, and 'Unload Script' has
    -- always cancelled them -- but this function, the one that runs on a teleport and
    -- from the watchdog, only ever bumped a hand-written list of generations. Six
    -- loops were outside that list. Cancelling the registry is the version that cannot
    -- rot: a loop added tomorrow is covered the day it is written, the same way a
    -- symbol in a cut part is.
    for _, t in ipairs(Cache.Loops or {}) do pcall(function() task.cancel(t) end) end
    Cache.Loops = {}
    for _, c in ipairs(Cache.Connections) do pcall(function() c:Disconnect() end) end
    Cache.Connections = {}
    -- MaintenanceConns is a map vend -> ARRAY of connections; ipairs over the map
    -- yielded nothing and leaked every bypass handler on cleanup/re-inject
    for _, conns in pairs(Cache.MaintenanceConns) do
        for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
    end
    Cache.MaintenanceConns = {}
    if Cache.TreeTween then pcall(function() Cache.TreeTween:Cancel() end); Cache.TreeTween = nil end
    if Cache.MobFarmTween then pcall(function() Cache.MobFarmTween:Cancel() end); Cache.MobFarmTween = nil end
    if Cache.NC1 then pcall(function() Cache.NC1:Disconnect() end); Cache.NC1 = nil end
    if Cache.NC2 then pcall(function() Cache.NC2:Disconnect() end); Cache.NC2 = nil end
    if Cache.NoclipConnection then pcall(function() Cache.NoclipConnection:Disconnect() end); Cache.NoclipConnection = nil end
    if Cache.NoclipRespawnConn then pcall(function() Cache.NoclipRespawnConn:Disconnect() end); Cache.NoclipRespawnConn = nil end
    for _, l in pairs(Cache.VendingLabels) do pcall(function() if l.label then l.label:Destroy() end end) end
    Cache.VendingLabels = {}
    for _, l in pairs(Cache.ChestLabels) do pcall(function() if l.label then l.label:Destroy() end end) end
    Cache.ChestLabels = {}
    for _, l in ipairs(Cache.LabelPool) do pcall(function() l:Destroy() end) end
    Cache.LabelPool = {}
    for _, h in pairs(Cache.SelectedVendings) do pcall(function() h:Destroy() end) end
    Cache.SelectedVendings = {}
    for _, h in pairs(Cache.SelectionHighlights) do pcall(function() h:Destroy() end) end
    Cache.SelectionHighlights = {}
    State.VendingHighlightEnabled = false
    for _, h in pairs(Cache.VendingHighlights or {}) do pcall(function() h:Destroy() end) end
    Cache.VendingHighlights = {}
    for _, h in pairs(Cache.VendWhitelistHL or {}) do pcall(function() h:Destroy() end) end
    Cache.VendWhitelistHL = {}; Cache.VendWhitelist = {}
    for _, h in ipairs(Cache.HighlightPool) do pcall(function() h:Destroy() end) end
    Cache.HighlightPool = {}
    for _, l in ipairs(Cache.LinePool) do pcall(function() l:Destroy() end) end
    Cache.LinePool = {}
    for _, l in ipairs(Cache.CircleLines) do pcall(function() l:Destroy() end) end
    Cache.CircleLines = {}
    
    if Cache.BlueprintPreviewContainer then pcall(function() Cache.BlueprintPreviewContainer:Destroy() end); Cache.BlueprintPreviewContainer = nil end
    if Cache.BlueprintRegionHL then pcall(function() Cache.BlueprintRegionHL:Destroy() end); Cache.BlueprintRegionHL = nil end
    if Cache.BlueprintRegionSB then pcall(function() Cache.BlueprintRegionSB:Destroy() end); Cache.BlueprintRegionSB = nil end
    if Cache.BlueprintRegionPart then pcall(function() Cache.BlueprintRegionPart:Destroy() end); Cache.BlueprintRegionPart = nil end
    for b, d in pairs(Cache.SpecificSelection) do
        if d and d.highlight then pcall(function() d.highlight:Destroy() end) end
    end
    Cache.SpecificSelection = {}
    if Cache.RequiredBlocksUI then pcall(function() Cache.RequiredBlocksUI:Destroy() end); Cache.RequiredBlocksUI = nil end
    if Cache.VendScanUI then pcall(function() Cache.VendScanUI:Destroy() end); Cache.VendScanUI = nil end
    if Cache.PriceBookUI then pcall(function() Cache.PriceBookUI:Destroy() end); Cache.PriceBookUI = nil end
    if Cache.VendSelectorUI then pcall(function() Cache.VendSelectorUI:Destroy() end); Cache.VendSelectorUI = nil end
    if Cache.ItemSectionsUI then pcall(function() Cache.ItemSectionsUI:Destroy() end); Cache.ItemSectionsUI = nil end
    if Cache.QueuePanelUI then pcall(function() Cache.QueuePanelUI:Destroy() end); Cache.QueuePanelUI = nil end
    if Cache.FishBoardUI then pcall(function() Cache.FishBoardUI:Destroy() end); Cache.FishBoardUI = nil end
    if Cache.OverviewUI then pcall(function() Cache.OverviewUI:Destroy() end); Cache.OverviewUI = nil end
    if Cache.WhatsNewUI then pcall(function() Cache.WhatsNewUI:Destroy() end); Cache.WhatsNewUI = nil end
    Cache.OverviewShown = false
    -- the ScreenGui, not the Frame inside it: destroying only the Frame left the
    -- IVM_Movement ScreenGui behind in gethui() on every unload
    if Cache.MovementUI then pcall(function() Cache.MovementUI:Destroy() end); Cache.MovementUI = nil end
    Cache.MovementFrame = nil
    if Cache.SignPreviewUI then pcall(function() Cache.SignPreviewUI:Destroy() end); Cache.SignPreviewUI = nil end
    Cache.SignPreviewFrame = nil; Cache.SignPreviewCanvas = nil; Cache.SignPreviewNote = nil
    if Cache.QRPreviewUI then pcall(function() Cache.QRPreviewUI:Destroy() end); Cache.QRPreviewUI = nil end
    if Cache.PixelPreviewUI then pcall(function() Cache.PixelPreviewUI:Destroy() end); Cache.PixelPreviewUI = nil end
    if Cache.BpLibUI then pcall(function() Cache.BpLibUI:Destroy() end); Cache.BpLibUI = nil end
    if Cache.RepairMapUI then pcall(function() Cache.RepairMapUI:Destroy() end); Cache.RepairMapUI = nil end
    if Cache.ProfitReportUI then pcall(function() Cache.ProfitReportUI:Destroy() end); Cache.ProfitReportUI = nil end
    if Cache.SalesReportUI then pcall(function() Cache.SalesReportUI:Destroy() end); Cache.SalesReportUI = nil end
    if Cache.StockForecastUI then pcall(function() Cache.StockForecastUI:Destroy() end); Cache.StockForecastUI = nil end
    if Cache.NotifyHistoryUI then pcall(function() Cache.NotifyHistoryUI:Destroy() end); Cache.NotifyHistoryUI = nil end
    if Cache.BestDealsUI then pcall(function() Cache.BestDealsUI:Destroy() end); Cache.BestDealsUI = nil end
    State.PriceAlertsEnabled = false
    Cache.RepairGen = (Cache.RepairGen or 0) + 1   -- stops a break pass in progress
    Cache.QRPreviewFrame = nil; Cache.QRPreviewCanvas = nil; Cache.QRPreviewNote = nil
    if Cache.setBuildHold then pcall(Cache.setBuildHold, false) end
    if Cache.PerformanceModeConn then pcall(function() Cache.PerformanceModeConn:Disconnect() end); Cache.PerformanceModeConn = nil end
    if Cache.AntiAfkConn then pcall(function() Cache.AntiAfkConn:Disconnect() end); Cache.AntiAfkConn = nil end
    if Cache.DayLockConn then pcall(function() Cache.DayLockConn:Disconnect() end); Cache.DayLockConn = nil end
    Cache.ClockLockHour = nil
    if Cache.DayLockOriginal then
        pcall(function() game:GetService("Lighting").ClockTime = Cache.DayLockOriginal end)
        Cache.DayLockOriginal = nil
    end
    if Cache.AutoPanicConn then pcall(function() Cache.AutoPanicConn:Disconnect() end); Cache.AutoPanicConn = nil end
    -- walk speed: drop the re-apply hooks BEFORE restoring 16, or the property
    -- listener would just write the boosted speed straight back
    State.WalkSpeedEnabled = false
    if Cache.WalkSpeedPropConn then pcall(function() Cache.WalkSpeedPropConn:Disconnect() end); Cache.WalkSpeedPropConn = nil end
    if Cache.WalkSpeedRespawnConn then pcall(function() Cache.WalkSpeedRespawnConn:Disconnect() end); Cache.WalkSpeedRespawnConn = nil end
    pcall(function()
        local char = LocalPlayer.Character
        local hum  = char and char:FindFirstChildWhichIsA("Humanoid")
        if hum then hum.WalkSpeed = 16 end
    end)
    State.FlightEnabled = false
    if Cache.FlightStepConn then pcall(function() Cache.FlightStepConn:Disconnect() end); Cache.FlightStepConn = nil end
    if Cache.FlightRespawnConn then pcall(function() Cache.FlightRespawnConn:Disconnect() end); Cache.FlightRespawnConn = nil end
    -- Freecam teardown (was missing): restore camera/controls, then drop the Shift+P
    -- handler so it can't toggle a broken freecam after unload
    if Cache.stopFreecam then pcall(Cache.stopFreecam) end
    if Cache.FreecamKey then pcall(function() Cache.FreecamKey:Disconnect() end); Cache.FreecamKey = nil end
    pcall(function()
        local char = LocalPlayer.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if hrp then local bv = hrp:FindFirstChild("IVM_FlightBV"); if bv then bv:Destroy() end end
        local hum = char and char:FindFirstChildWhichIsA("Humanoid")
        if hum then hum.PlatformStand = false end
    end)
    for _, a in pairs(Cache.CombatAnims) do pcall(function() a:Stop() end) end
    Cache.CombatAnims = {}
    for _, t in ipairs(Cache.CombatAnimInstances) do pcall(function() t:Stop() end) end
    Cache.CombatAnimInstances = {}
    for name, f in pairs(Cache.ToggleFunctions) do
        -- a safety setting, not a loop: flipping it here only popped its warning
        if name ~= "Only Hit What Can Break (learn the reach)" then pcall(function() f(false) end) end
    end
    pcall(function() Window:Destroy() end)
    if Window.ActiveConnections then
        for _, conn in ipairs(Window.ActiveConnections) do
            pcall(function() conn:Disconnect() end)
        end
    end
    if Window.ActiveLoops then
        for i = #Window.ActiveLoops, 1, -1 do
            Window.ActiveLoops[i] = nil
        end
    end
    for name, _ in pairs(Cache.ToggleFunctions) do
        Cache.ToggleFunctions[name] = nil
    end
    Cache.LoadedBlueprintData = nil
    Cache.BlueprintAnchor = nil
    -- CANCEL IT, don't just drop the handle. Every other teardown of this thread
    -- cancels first; dropping the reference here left the preview loader alive with
    -- nothing left pointing at it, still cloning parts every few milliseconds into a
    -- container cleanup had already destroyed -- and it finishes by writing its own
    -- `Cache.BlueprintLoadThread = nil` over whatever the next instance has put there.
    if Cache.BlueprintLoadThread then pcall(function() task.cancel(Cache.BlueprintLoadThread) end) end
    Cache.BlueprintLoadThread = nil
    Cache.CombatThread = nil
    if _G.IVM_Instances[MyInstanceId] then
        _G.IVM_Instances[MyInstanceId].Active = false
        _G.IVM_Instances[MyInstanceId].Window = nil
    end
    -- leave a no-op stub, NOT nil: straggler threads that wake up after cleanup and
    -- call Window:Notify used to die with "attempt to index nil with 'Notify'" (seen
    -- in user logs) — and when that thread was the build runner, the build silently
    -- stopped. With the stub they just no-op and exit through their gen checks.
    Window = { Notify = function() end, Destroy = function() end, Cleanup = function() end }
    Cache.Win = nil  -- pre-Window functions notify via Cache.notify; nil = silent no-op
end

for id, data in pairs(_G.IVM_Instances or {}) do
    if data.Active then
        -- run the old instance's FULL cleanup, not just Window:Destroy(): destroying
        -- only the window left its build/stats loops running headless — re-injecting
        -- mid-build produced a GHOST builder (two builders fighting, duplicate Build
        -- Stats boxes, doubled request load on the server's rate limiter).
        if data.Window and data.Window.Cleanup then
            pcall(function() data.Window.Cleanup() end)
        elseif data.Window and data.Window.Destroy then
            pcall(function() data.Window:Destroy() end)
        end
        _G.IVM_Instances[id].Active = false
    end
end

_G.IVM_Instances[MyInstanceId] = { Window = Window, Active = true, CreatedAt = tick() }
_G.IVM_Cleanup = DoFullCleanup
_G.IVM_ForceCleanup = DoFullCleanup
Window.Cleanup = DoFullCleanup
task.spawn(function()
    -- watch OUR OWN gui instance, not anything named "IslandsManagerUI": a re-inject
    -- creates a new gui with the same name, which made the old instance's watchdog
    -- believe it was still alive and keep its loops running forever.
    local myGui = Window and Window.ScreenGui
    while true do
        task.wait(5)
        if not (myGui and myGui.Parent) then
            pcall(DoFullCleanup)
            break
        end
    end
end)
-- AUTO-RESUME AFTER A SLOW-SERVER HOP: Cache.slowServerHop wrote a marker right
-- before teleporting, and queue_on_teleport / autoexec re-ran the script on this
-- fresh server. If the marker is fresh (10 min — covers the teleport + join), pick
-- the build back up without a single click. The marker is deleted FIRST so a
-- failed resume can never loop; a marker older than the window is stale (user
-- rejoined manually much later) and is discarded silently.
task.spawn(function()
    if not (isfile and readfile and isfile("Islands trading hub/buildresume.json")) then return end
    local ok, marker = pcall(function() return HttpService:JSONDecode(readfile("Islands trading hub/buildresume.json")) end)
    if delfile then pcall(function() delfile("Islands trading hub/buildresume.json") end) end
    if not (ok and type(marker) == "table" and type(marker.t) == "number") then return end
    if os.time() - marker.t > 600 then return end
    -- let the island stream in before the resume's start scan measures it
    task.wait(8)
    Cache.notify({Title="Auto Rejoin", Content="Fresh server — resuming the build where it left off.", Duration=6})
    local okResume, res = pcall(Cache.coldResumeBuild)
    if not okResume or res == false then
        Cache.notify({Title="Auto Rejoin", Content="Couldn't auto-resume (see the message above) — use Pause/Resume Build to continue by hand.", Duration=10})
    end
end)
